// Core value type for the SQL engine.
#pragma once
#include <cstdint>
#include <string>
#include <vector>
#include <memory>
#include <stdexcept>

enum class VT : uint8_t { Null = 0, Int = 1, Real = 2, Text = 3, Blob = 4 };

// Column affinity
enum class Aff : uint8_t { None = 0, Blob = 0, Text = 1, Numeric = 2, Integer = 3, Real = 4 };

struct Value {
  VT t = VT::Null;
  int64_t i = 0;
  double r = 0.0;
  std::string s;  // text or blob bytes
  // Flags
  uint8_t sub = 0; // subtype

  Value() {}
  static Value Null() { return Value(); }
  static Value Int(int64_t v) { Value x; x.t = VT::Int; x.i = v; return x; }
  static Value Real(double v) { Value x; x.t = VT::Real; x.r = v; return x; }
  static Value Text(std::string v) { Value x; x.t = VT::Text; x.s = std::move(v); return x; }
  static Value Blob(std::string v) { Value x; x.t = VT::Blob; x.s = std::move(v); return x; }
  static Value Bool(bool b) { return Int(b ? 1 : 0); }

  bool isNull() const { return t == VT::Null; }
  bool isInt() const { return t == VT::Int; }
  bool isReal() const { return t == VT::Real; }
  bool isNum() const { return t == VT::Int || t == VT::Real; }
  bool isText() const { return t == VT::Text; }
  bool isBlob() const { return t == VT::Blob; }

  // Conversions following SQLite semantics
  double toReal() const;       // numeric value (prefix parse for text)
  int64_t toInt() const;       // numeric value as integer (truncation, saturation)
  std::string toText() const;  // text rendering (numbers formatted SQLite-style)
  bool truthy(bool* isnull) const; // boolean interpretation

  const char* typeName() const;
};

// Compare two values with SQLite ordering (no affinity applied). collation applies to text.
// Collation: 0=BINARY, 1=NOCASE, 2=RTRIM
int compareValues(const Value& a, const Value& b, int coll = 0);
int compareText(const std::string& a, const std::string& b, int coll);

// Numeric helpers
std::string formatDouble(double d);        // SQLite "%!.15g" with fallback to 17 digits
std::string formatDoubleQuote(double d);   // used by quote()/insert mode
// Parse text as number: returns 0 if not a number, 1 if integer, 2 if real.
// Full string must be consumed (allow leading/trailing whitespace) if strict.
int parseNumber(const std::string& s, int64_t& iv, double& rv, bool strict);
bool looksLikeInt(const std::string& s);
// Apply affinity to a value (used on storage and comparison)
Value applyAffinity(const Value& v, Aff a);
Aff affinityFromType(const std::string& declType);
const char* affName(Aff a);
// Try to convert text to a numeric Value if it is a well-formed number; else unchanged.
Value textToNumericIfPossible(const Value& v, bool integerOnlyIfLossless);

// Convenience
std::string sqlQuoteString(const std::string& s);
std::string blobToHex(const std::string& b);
int utf8Len(const std::string& s);
std::string utf8Lower(const std::string& s);
std::string utf8Upper(const std::string& s);
int utf8Decode(const std::string& s, size_t& pos);
void utf8Append(std::string& out, uint32_t cp);
EOF
echo ok"}

