#include "value.h"
#include <cmath>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <climits>

static inline bool isSp(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r' || c == '\v'; }

const char* Value::typeName() const {
  switch (t) {
    case VT::Null: return "null";
    case VT::Int: return "integer";
    case VT::Real: return "real";
    case VT::Text: return "text";
    case VT::Blob: return "blob";
  }
  return "null";
}

// Parse number per sqlite3AtoF rules. Returns 0 if no numeric prefix at all,
// 1 if integer-looking, 2 if real-looking. If strict, requires whole string consumed
// (allowing surrounding whitespace), else returns based on prefix.
// On return iv/rv hold the parsed values (rv always, iv if integer-looking & in range).
static int parseNumberCore(const char* z, size_t n, int64_t& iv, double& rv, bool strict, bool* intOverflow) {
  size_t p = 0;
  while (p < n && isSp(z[p])) p++;
  bool neg = false;
  if (p < n && (z[p] == '-' || z[p] == '+')) { neg = z[p] == '-'; p++; }
  size_t digStart = p;
  std::string mant;
  int nDigit = 0;
  while (p < n && z[p] >= '0' && z[p] <= '9') { mant.push_back(z[p]); p++; nDigit++; }
  bool hasDot = false, hasExp = false;
  int fracDigits = 0;
  if (p < n && z[p] == '.') {
    hasDot = true; p++;
    while (p < n && z[p] >= '0' && z[p] <= '9') { mant.push_back(z[p]); p++; nDigit++; fracDigits++; }
  }
  if (nDigit == 0) { iv = 0; rv = 0; return 0; }
  int expv = 0; bool expNeg = false;
  if (p < n && (z[p] == 'e' || z[p] == 'E')) {
    size_t q = p + 1;
    if (q < n && (z[q] == '-' || z[q] == '+')) { expNeg = z[q] == '-'; q++; }
    if (q < n && z[q] >= '0' && z[q] <= '9') {
      hasExp = true;
      while (q < n && z[q] >= '0' && z[q] <= '9') { if (expv < 10000) expv = expv * 10 + (z[q] - '0'); q++; }
      p = q;
    }
  }
  size_t endNum = p;
  while (p < n && isSp(z[p])) p++;
  bool complete = (p == n);
  (void)digStart;
  // compute real value using strtod on normalized string
  {
    std::string tmp(z + (neg ? 0 : 0), 0);
    std::string norm;
    if (neg) norm.push_back('-');
    norm.append(z, digStart, endNum - digStart);
    // strtod handles the format
    rv = strtod(norm.c_str(), nullptr);
    if (std::isinf(rv)) { /* keep inf */ }
  }
  bool isIntForm = !hasDot && !hasExp;
  if (intOverflow) *intOverflow = false;
  if (isIntForm) {
    // parse integer with overflow detection
    // strip leading zeros
    size_t k = 0; while (k + 1 < mant.size() && mant[k] == '0') k++;
    std::string d = mant.substr(k);
    bool ovf = false;
    if (d.size() > 19) ovf = true;
    else if (d.size() == 19) {
      const char* lim = neg ? "9223372036854775808" : "9223372036854775807";
      if (d.compare(lim) > 0) ovf = true;
    }
    if (!ovf) {
      uint64_t u = 0;
      for (char c : d) u = u * 10 + (c - '0');
      if (neg) iv = (u == 9223372036854775808ULL) ? INT64_MIN : -(int64_t)u;
      else iv = (int64_t)u;
    } else {
      if (intOverflow) *intOverflow = true;
      iv = neg ? INT64_MIN : INT64_MAX;
    }
    if (strict && !complete) return 0;
    if (ovf) return 2;  // treat as real
    return 1;
  }
  // real form
  if (strict && !complete) return 0;
  // integer value: truncate
  if (rv >= 9223372036854775807.0) iv = INT64_MAX;
  else if (rv <= -9223372036854775808.0) iv = INT64_MIN;
  else iv = (int64_t)rv;
  return 2;
}

int parseNumber(const std::string& s, int64_t& iv, double& rv, bool strict) {
  return parseNumberCore(s.data(), s.size(), iv, rv, strict, nullptr);
}

bool looksLikeInt(const std::string& s) {
  int64_t iv; double rv;
  return parseNumberCore(s.data(), s.size(), iv, rv, true, nullptr) == 1;
}

double Value::toReal() const {
  switch (t) {
    case VT::Null: return 0.0;
    case VT::Int: return (double)i;
    case VT::Real: return r;
    case VT::Text: case VT::Blob: {
      int64_t iv; double rv;
      int k = parseNumberCore(s.data(), s.size(), iv, rv, false, nullptr);
      if (k == 0) return 0.0;
      return rv;
    }
  }
  return 0.0;
}

static int64_t doubleToInt64(double r) {
  if (std::isnan(r)) return 0;
  if (r <= -9223372036854775808.0) return INT64_MIN;
  if (r >= 9223372036854775807.0) return INT64_MAX;
  return (int64_t)r;
}

int64_t Value::toInt() const {
  switch (t) {
    case VT::Null: return 0;
    case VT::Int: return i;
    case VT::Real: return doubleToInt64(r);
    case VT::Text: case VT::Blob: {
      int64_t iv; double rv;
      int k = parseNumberCore(s.data(), s.size(), iv, rv, false, nullptr);
      if (k == 0) return 0;
      if (k == 1) return iv;
      // real-looking text: sqlite converts via real then truncates
      return doubleToInt64(rv);
    }
  }
  return 0;
}

std::string Value::toText() const {
  switch (t) {
    case VT::Null: return "";
    case VT::Int: return std::to_string(i);
    case VT::Real: return formatDouble(r);
    case VT::Text: case VT::Blob: return s;
  }
  return "";
}

bool Value::truthy(bool* isnull) const {
  if (isnull) *isnull = false;
  switch (t) {
    case VT::Null: if (isnull) *isnull = true; return false;
    case VT::Int: return i != 0;
    case VT::Real: return r != 0.0;
    case VT::Text: case VT::Blob: {
      // convert to numeric prefix
      int64_t iv; double rv;
      int k = parseNumberCore(s.data(), s.size(), iv, rv, false, nullptr);
      if (k == 0) return false;
      if (k == 1) return iv != 0;
      return rv != 0.0;
    }
  }
  return false;
}

// Produce decimal digits and decimal-point position for d using precision p (%.{p-1}e)
static void decodeDigits(double d, int prec, std::string& digits, int& iDP) {
  char buf[64];
  snprintf(buf, sizeof buf, "%.*e", prec - 1, d);
  // format: d.ddddde[+-]xx
  const char* p = buf;
  if (*p == '-') p++;
  digits.clear();
  int exp10 = 0;
  while (*p && *p != 'e') { if (*p != '.') digits.push_back(*p); p++; }
  if (*p == 'e') exp10 = atoi(p + 1);
  // strip trailing zeros
  while (digits.size() > 1 && digits.back() == '0') digits.pop_back();
  iDP = exp10 + 1;
}

static std::string formatDoubleDigits(double d, int threshExp) {
  if (std::isnan(d)) return "NaN";
  if (std::isinf(d)) return d < 0 ? "-Inf" : "Inf";
  if (d == 0.0) return "0.0";
  bool neg = d < 0;
  double a = neg ? -d : d;
  std::string digits; int iDP;
  decodeDigits(a, 15, digits, iDP);
  {
    char buf[64]; snprintf(buf, sizeof buf, "%.15g", a);
    double back = strtod(buf, nullptr);
    if (back != a) decodeDigits(a, 17, digits, iDP);
  }
  std::string out;
  if (neg) out.push_back('-');
  int n = (int)digits.size();
  if (iDP <= -4 || iDP > threshExp) {
    out.push_back(digits[0]);
    out.push_back('.');
    if (n > 1) out.append(digits, 1, std::string::npos); else out.push_back('0');
    int e = iDP - 1;
    char eb[16]; snprintf(eb, sizeof eb, "e%c%02d", e < 0 ? '-' : '+', e < 0 ? -e : e);
    out += eb;
  } else if (iDP <= 0) {
    out += "0.";
    for (int k = 0; k < -iDP; k++) out.push_back('0');
    out += digits;
  } else if (iDP >= n) {
    out += digits;
    for (int k = 0; k < iDP - n; k++) out.push_back('0');
    out += ".0";
  } else {
    out.append(digits, 0, iDP);
    out.push_back('.');
    out.append(digits, iDP, std::string::npos);
  }
  return out;
}

std::string formatDouble(double d) { return formatDoubleDigits(d, 17); }
std::string formatDoubleQuote(double d) { return formatDoubleDigits(d, 17); }

int compareText(const std::string& a, const std::string& b, int coll) {
  if (coll == 1) {  // NOCASE: ASCII case folding
    size_t n = std::min(a.size(), b.size());
    for (size_t k = 0; k < n; k++) {
      unsigned char ca = a[k], cb = b[k];
      if (ca >= 'A' && ca <= 'Z') ca += 32;
      if (cb >= 'A' && cb <= 'Z') cb += 32;
      if (ca != cb) return ca < cb ? -1 : 1;
    }
    if (a.size() == b.size()) return 0;
    return a.size() < b.size() ? -1 : 1;
  } else if (coll == 2) {  // RTRIM
    size_t na = a.size(), nb = b.size();
    while (na > 0 && a[na - 1] == ' ') na--;
    while (nb > 0 && b[nb - 1] == ' ') nb--;
    int c = memcmp(a.data(), b.data(), std::min(na, nb));
    if (c != 0) return c < 0 ? -1 : 1;
    if (na == nb) return 0;
    return na < nb ? -1 : 1;
  }
  int c = memcmp(a.data(), b.data(), std::min(a.size(), b.size()));
  if (c != 0) return c < 0 ? -1 : 1;
  if (a.size() == b.size()) return 0;
  return a.size() < b.size() ? -1 : 1;
}

static int intFloatCompare(int64_t i, double r) {
  if (std::isnan(r)) return -1;
  if (r < -9223372036854775808.0) return +1;
  if (r >= 9223372036854775808.0) return -1;
  int64_t y = (int64_t)r;
  if (i < y) return -1;
  if (i > y) return +1;
  double s = (double)i;
  if (s < r) return -1;
  if (s > r) return +1;
  return 0;
}

static int typeClass(VT t) {
  switch (t) {
    case VT::Null: return 0;
    case VT::Int: case VT::Real: return 1;
    case VT::Text: return 2;
    case VT::Blob: return 3;
  }
  return 0;
}

int compareValues(const Value& a, const Value& b, int coll) {
  int ca = typeClass(a.t), cb = typeClass(b.t);
  if (ca != cb) return ca < cb ? -1 : 1;
  switch (ca) {
    case 0: return 0;
    case 1:
      if (a.t == VT::Int && b.t == VT::Int) return a.i < b.i ? -1 : (a.i > b.i ? 1 : 0);
      if (a.t == VT::Real && b.t == VT::Real) return a.r < b.r ? -1 : (a.r > b.r ? 1 : 0);
      if (a.t == VT::Int) return intFloatCompare(a.i, b.r);
      return -intFloatCompare(b.i, a.r);
    case 2: return compareText(a.s, b.s, coll);
    case 3: {
      int c = memcmp(a.s.data(), b.s.data(), std::min(a.s.size(), b.s.size()));
      if (c != 0) return c < 0 ? -1 : 1;
      if (a.s.size() == b.s.size()) return 0;
      return a.s.size() < b.s.size() ? -1 : 1;
    }
  }
  return 0;
}

Aff affinityFromType(const std::string& declType) {
  std::string u;
  for (char c : declType) u.push_back(toupper((unsigned char)c));
  if (u.empty()) return Aff::Blob;
  if (u.find("INT") != std::string::npos) return Aff::Integer;
  if (u.find("CHAR") != std::string::npos || u.find("CLOB") != std::string::npos || u.find("TEXT") != std::string::npos) return Aff::Text;
  if (u.find("BLOB") != std::string::npos) return Aff::Blob;
  if (u.find("REAL") != std::string::npos || u.find("FLOA") != std::string::npos || u.find("DOUB") != std::string::npos) return Aff::Real;
  return Aff::Numeric;
}

const char* affName(Aff a) {
  switch (a) {
    case Aff::Blob: return "BLOB";
    case Aff::Text: return "TEXT";
    case Aff::Numeric: return "NUMERIC";
