// 1 if integer-looking, 2 if real-looking. If strict, requires whole string consumed
// (allowing surrounding whitespace), else returns based on prefix.
// On return iv/rv hold the parsed values (rv always, iv if integer-looking & in range).
static int parseNumberCore(const char* z, size_t n, int64_t& iv, double& rv, bool strict, bool* intOverflow) {
