  return u;
}

std::vector<Token> tokenize(const std::string& sql, bool keepSpace) {
  std::vector<Token> out;
  size_t i = 0, n = sql.size();
  auto push = [&](TT t, size_t s, size_t e) {
    Token tk; tk.type = t; tk.pos = (int)s; tk.len = (int)(e - s); tk.text = sql.substr(s, e - s);
    out.push_back(std::move(tk));
  };
  while (i < n) {
    unsigned char c = sql[i];
    size_t s = i;
    if (isSpaceC(c)) {
      while (i < n && isSpaceC(sql[i])) i++;
      if (keepSpace) push(TT::SPACE, s, i);
      continue;
    }
    if (c == '-' && i + 1 < n && sql[i + 1] == '-') {
      while (i < n && sql[i] != '\n') i++;
      if (keepSpace) push(TT::SPACE, s, i);
      continue;
    }
    if (c == '/' && i + 1 < n && sql[i + 1] == '*') {
      i += 2;
      while (i < n && !(sql[i] == '*' && i + 1 < n && sql[i + 1] == '/')) i++;
      if (i < n) i += 2;
      if (keepSpace) push(TT::SPACE, s, i);
      continue;
    }
    if (c == '\'') {
      // string literal
      i++;
      bool closed = false;
      std::string val;
      while (i < n) {
        if (sql[i] == '\'') {
          if (i + 1 < n && sql[i + 1] == '\'') { val.push_back('\''); i += 2; continue; }
          closed = true; i++; break;
        }
        val.push_back(sql[i]); i++;
      }
      if (!closed) { push(TT::ILLEGAL, s, i); continue; }
      push(TT::STRING, s, i); out.back().kw = val;
      continue;
    }
    if (c == '"' || c == '`' || c == '[') {
      char close = c == '[' ? ']' : c;
      i++;
      bool closed = false; std::string val;
      while (i < n) {
        if (sql[i] == close) {
          if (close != ']' && i + 1 < n && sql[i + 1] == close) { val.push_back(close); i += 2; continue; }
          closed = true; i++; break;
        }
        val.push_back(sql[i]); i++;
      }
      if (!closed) { push(TT::ILLEGAL, s, i); continue; }
      push(TT::ID, s, i); out.back().kw = val; out.back().quoted = true; out.back().quoteChar = (char)c;
      continue;
    }
    if ((c == 'x' || c == 'X') && i + 1 < n && sql[i + 1] == '\'') {
      size_t j = i + 2; bool ok = true; bool closed = false;
      while (j < n) { if (sql[j] == '\'') { closed = true; break; } if (!isxdigit((unsigned char)sql[j])) ok = false; j++; }
      if (!closed) { i = j; push(TT::ILLEGAL, s, i); continue; }
      j++;
      if (!ok || ((j - i - 3) % 2) != 0) { i = j; push(TT::ILLEGAL, s, i); continue; }
      std::string val;
      for (size_t k = i + 2; k + 1 < j - 1; k += 2) {
        auto hv = [](char h) { return isdigit((unsigned char)h) ? h - '0' : (tolower(h) - 'a' + 10); };
        val.push_back((char)(hv(sql[k]) * 16 + hv(sql[k + 1])));
      }
      i = j; push(TT::BLOB, s, i); out.back().kw = val;
      continue;
    }
    if (isdigit(c) || (c == '.' && i + 1 < n && isdigit((unsigned char)sql[i + 1]))) {
      // number
      if (c == '0' && i + 1 < n && (sql[i + 1] == 'x' || sql[i + 1] == 'X')) {
        size_t j = i + 2;
        while (j < n && isxdigit((unsigned char)sql[j])) j++;
        if (j == i + 2 || (j < n && isIdChar(sql[j]))) { while (j < n && isIdChar(sql[j])) j++; i = j; push(TT::ILLEGAL, s, i); continue; }
        i = j; push(TT::INTEGER, s, i); continue;
      }
      size_t j = i; bool isFloat = false;
      while (j < n && isdigit((unsigned char)sql[j])) j++;
      if (j < n && sql[j] == '.') { isFloat = true; j++; while (j < n && isdigit((unsigned char)sql[j])) j++; }
      if (j < n && (sql[j] == 'e' || sql[j] == 'E')) {
        size_t k = j + 1;
        if (k < n && (sql[k] == '+' || sql[k] == '-')) k++;
        if (k < n && isdigit((unsigned char)sql[k])) { isFloat = true; while (k < n && isdigit((unsigned char)sql[k])) k++; j = k; }
        else { while (k < n && isIdChar(sql[k])) k++; i = k; push(TT::ILLEGAL, s, i); continue; }
      }
      if (j < n && isIdChar(sql[j])) { while (j < n && isIdChar(sql[j])) j++; i = j; push(TT::ILLEGAL, s, i); continue; }
      i = j; push(isFloat ? TT::FLOAT : TT::INTEGER, s, i);
      continue;
    }
    if (isIdStart(c)) {
      size_t j = i;
      while (j < n && isIdChar(sql[j])) j++;
      std::string word = sql.substr(i, j - i);
      std::string up = upperStr(word);
      i = j;
      if (kKeywords.count(up)) { push(TT::KW, s, i); out.back().kw = up; }
      else { push(TT::ID, s, i); out.back().kw = word; }
      continue;
    }
    if (c == '?') {
      size_t j = i + 1;
      while (j < n && isdigit((unsigned char)sql[j])) j++;
      i = j; push(TT::VARIABLE, s, i); out.back().kw = sql.substr(s, i - s);
      continue;
    }
    if (c == ':' || c == '@' || c == '$') {
      size_t j = i + 1;
      if (c == '$') {
        while (j < n && (isIdChar(sql[j]) || sql[j] == ':')) {
          if (sql[j] == ':' ) { if (j + 1 < n && sql[j+1] == ':') j += 2; else break; }
          else j++;
        }
        if (j < n && sql[j] == '(') { while (j < n && sql[j] != ')') j++; if (j < n) j++; }
      } else {
        while (j < n && isIdChar(sql[j])) j++;
      }
      if (j == i + 1) { i = j; push(TT::ILLEGAL, s, i); continue; }
      i = j; push(TT::VARIABLE, s, i); out.back().kw = sql.substr(s, i - s);
      continue;
    }
    // operators
    auto op2 = [&](const char* o) { size_t l = strlen(o); return i + l <= n && sql.compare(i, l, o) == 0; };
    const char* ops3[] = {"->>", nullptr};
    const char* ops2[] = {"<=", ">=", "==", "!=", "<>", "<<", ">>", "||", "->", nullptr};
    bool matched = false;
    for (int k = 0; ops3[k]; k++) if (op2(ops3[k])) { i += 3; push(TT::OP, s, i); matched = true; break; }
    if (matched) continue;
    for (int k = 0; ops2[k]; k++) if (op2(ops2[k])) { i += 2; push(TT::OP, s, i); matched = true; break; }
    if (matched) continue;
    if (strchr("-+*/%<>=&|~(),;.", c)) { i++; push(TT::OP, s, i); continue; }
    // illegal character
    i++;
    push(TT::ILLEGAL, s, i);
  }
  Token e; e.type = TT::END; e.pos = (int)n; e.len = 0;
  out.push_back(e);
  return out;
}

bool sqlIsComplete(const std::string& sql) {
  // Complete if last non-space/comment token is ';' and no open string/comments.
  // Also handles CREATE TRIGGER ... END; nesting.
  auto toks = tokenize(sql);
  if (toks.size() < 2) return false;
  // find last real token
  const Token& last = toks[toks.size() - 2];
  if (!(last.type == TT::OP && last.text == ";")) return false;
  if (last.type == TT::ILLEGAL) return false;
  // Trigger handling: if statement starts with CREATE [TEMP] TRIGGER, need END ;
  int state = 0; // simple state machine over statements
  int depth = 0; // inside trigger body
  bool inTrigger = false;
  for (size_t k = 0; k + 1 < toks.size(); k++) {
    const Token& t = toks[k];
    if (t.type == TT::ILLEGAL) return false;
    if (!inTrigger) {
      if (t.type == TT::KW && t.kw == "CREATE") {
        size_t j = k + 1;
        while (j < toks.size() && toks[j].type == TT::KW && (toks[j].kw == "TEMP" || toks[j].kw == "TEMPORARY")) j++;
        if (j < toks.size() && toks[j].type == TT::KW && toks[j].kw == "TRIGGER") { inTrigger = true; depth = 0; }
      }
    } else {
      if (t.type == TT::KW && (t.kw == "CASE")) depth++;
      else if (t.type == TT::KW && t.kw == "END") { if (depth > 0) depth--; else { inTrigger = false; state = 1; } }
    }
  }
  (void)state;
  if (inTrigger) return false;
  return true;
}

std::string ordinalSuffix(int n) {
  int m100 = n % 100, m10 = n % 10;
  if (m100 >= 11 && m100 <= 13) return "th";
  if (m10 == 1) return "st";
  if (m10 == 2) return "nd";
  if (m10 == 3) return "rd";
  return "th";
}

// ---------------- Parser ----------------

Parser::Parser(const std::string& s) : sql(s) { toks = tokenize(sql); }

const Token& Parser::peek(int k) const {
  size_t idx = p + k;
  if (idx >= toks.size()) return toks.back();
  return toks[idx];
}
const Token& Parser::next() {
  const Token& t = peek();
  if (t.type == TT::ILLEGAL) throw SqlError("unrecognized token: \"" + t.text + "\"", t.pos);
  if (p < toks.size() - 1) p++;
  return t;
}
bool Parser::atEnd() { return peek().type == TT::END; }
bool Parser::isKw(const char* kw, int k) const { const Token& t = peek(k); return t.type == TT::KW && t.kw == kw; }
bool Parser::isOp(const char* op, int k) const { const Token& t = peek(k); return t.type == TT::OP && t.text == op; }
bool Parser::acceptKw(const char* kw) { if (isKw(kw)) { next(); return true; } return false; }
bool Parser::acceptOp(const char* op) { if (isOp(op)) { next(); return true; } return false; }
void Parser::expectKw(const char* kw) { if (!isKw(kw)) syntaxErrorHere(); next(); }
void Parser::expectOp(const char* op) { if (!isOp(op)) syntaxErrorHere(); next(); }
int Parser::prevEnd() const { if (p == 0) return 0; return toks[p - 1].pos + toks[p - 1].len; }

void Parser::syntaxError(const Token& t) {
  if (t.type == TT::END) throw SqlError("incomplete input", -1);
  if (t.type == TT::ILLEGAL) throw SqlError("unrecognized token: \"" + t.text + "\"", t.pos);
  throw SqlError("near \"" + t.text + "\": syntax error", t.pos);
}
void Parser::syntaxErrorHere() { syntaxError(peek()); }

bool Parser::isIdent(int k) const {
  const Token& t = peek(k);
  if (t.type == TT::ID) return true;
  if (t.type == TT::KW && kFallback.count(t.kw)) return true;
  return false;
}

std::string Parser::parseName() {
  const Token& t = peek();
  if (t.type == TT::ID) { next(); return t.kw; }
  if (t.type == TT::KW && kFallback.count(t.kw)) { next(); return t.text; }
  if (t.type == TT::STRING) { next(); return t.kw; }
  syntaxErrorHere();
}
std::string Parser::parseNameOrString() { return parseName(); }

std::string Parser::parseTypeName() {
  // type name: one or more identifiers optionally followed by (N) or (N,M)
  std::string type;
  int s = peek().pos;
  bool any = false;
  while (isIdent() || (peek().type == TT::KW && peek().kw != "CONSTRAINT" && peek().kw != "PRIMARY" && peek().kw != "NOT" &&
         peek().kw != "NULL" && peek().kw != "UNIQUE" && peek().kw != "CHECK" && peek().kw != "DEFAULT" && peek().kw != "COLLATE" &&
         peek().kw != "REFERENCES" && peek().kw != "GENERATED" && peek().kw != "AS")) {
    if (peek().type == TT::KW && !kFallback.count(peek().kw) && !any) break;
    if (peek().type == TT::KW && !kFallback.count(peek().kw)) break;
    next(); any = true;
  }
  if (!any) return "";
  if (isOp("(")) {
    next();
    if (!(peek().type == TT::INTEGER || peek().type == TT::FLOAT || isOp("-") || isOp("+"))) syntaxErrorHere();
    if (isOp("-") || isOp("+")) next();
    next();
    if (acceptOp(",")) { if (isOp("-") || isOp("+")) next(); if (!(peek().type == TT::INTEGER || peek().type == TT::FLOAT)) syntaxErrorHere(); next(); }
    expectOp(")");
  }
  int e = prevEnd();
  // normalize whitespace: sqlite keeps the text but collapses internal whitespace to single spaces
  std::string raw = sql.substr(s, e - s);
  std::string norm; bool sp = false;
  for (char c : raw) { if (isSpaceC(c)) { sp = true; } else { if (sp && !norm.empty()) norm.push_back(' '); sp = false; norm.push_back(c); } }
  return norm;
}

std::vector<StmtP> Parser::parseAll() {
  std::vector<StmtP> out;
  while (!atEnd()) {
    StmtP s = parseStatement();
    if (s) out.push_back(s);
  }
  return out;
}

StmtP Parser::parseStatement() {
  while (acceptOp(";")) {}
  if (atEnd()) return nullptr;
  int start = peek().pos;
  StmtP st;
  bool explain = false, eqp = false;
  if (isKw("EXPLAIN")) {
    next(); explain = true;
    if (acceptKw("QUERY")) { expectKw("PLAN"); eqp = true; }
  }
  const Token& t = peek();
  if (t.type == TT::ILLEGAL) next();
  if (t.type == TT::KW) {
    if (t.kw == "SELECT" || t.kw == "VALUES") st = parseSelectStmt(nullptr, false);
    else if (t.kw == "WITH") {
      std::vector<Cte> ctes; bool rec = false;
      parseWith(ctes, rec);
      if (isKw("SELECT") || isKw("VALUES")) st = parseSelectStmt(&ctes, rec);
      else if (isKw("INSERT") || isKw("REPLACE")) st = parseInsert(ctes, rec);
      else if (isKw("UPDATE")) st = parseUpdate(ctes, rec);
      else if (isKw("DELETE")) st = parseDelete(ctes, rec);
      else syntaxErrorHere();
    }
    else if (t.kw == "INSERT" || t.kw == "REPLACE") st = parseInsert({}, false);
    else if (t.kw == "UPDATE") st = parseUpdate({}, false);
    else if (t.kw == "DELETE") st = parseDelete({}, false);
    else if (t.kw == "CREATE") st = parseCreate();
    else if (t.kw == "DROP") st = parseDrop();
    else if (t.kw == "ALTER") st = parseAlter();
    else if (t.kw == "PRAGMA") st = parsePragma();
    else if (t.kw == "BEGIN") {
      next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Begin;
      if (acceptKw("DEFERRED")) st->txType = 0; else if (acceptKw("IMMEDIATE")) st->txType = 1; else if (acceptKw("EXCLUSIVE")) st->txType = 2;
      acceptKw("TRANSACTION");
      if (isIdent()) st->savepoint = parseName();
    }
    else if (t.kw == "COMMIT" || t.kw == "END") {
      next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Commit; acceptKw("TRANSACTION");
      if (isIdent()) parseName();
    }
    else if (t.kw == "ROLLBACK") {
      next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Rollback; acceptKw("TRANSACTION");
      if (isIdent()) parseName();
      if (acceptKw("TO")) { acceptKw("SAVEPOINT"); st->savepoint = parseName(); st->txType = 1; }
    }
    else if (t.kw == "SAVEPOINT") { next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Savepoint; st->savepoint = parseName(); }
    else if (t.kw == "RELEASE") { next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Release; acceptKw("SAVEPOINT"); st->savepoint = parseName(); }
    else if (t.kw == "VACUUM") {
      next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Vacuum;
      if (isIdent()) st->target = parseName();
      if (acceptKw("INTO")) st->attachFile = parseExpr();
    }
    else if (t.kw == "ANALYZE") { next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Analyze; if (isIdent()) { st->target = parseName(); if (acceptOp(".")) st->target = parseName(); } }
    else if (t.kw == "REINDEX") { next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Reindex; if (isIdent()) { st->target = parseName(); if (acceptOp(".")) st->target = parseName(); } }
    else if (t.kw == "ATTACH") {
      next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Attach; acceptKw("DATABASE");
      st->attachFile = parseExpr(); expectKw("AS"); st->attachName = parseExpr();
    }
    else if (t.kw == "DETACH") { next(); st = std::make_shared<Stmt>(); st->kind = Stmt::Detach; acceptKw("DATABASE"); st->attachName = parseExpr(); }
    else syntaxErrorHere();
  } else {
    syntaxErrorHere();
  }
  if (!st) syntaxErrorHere();
  // Statement must end with ; or EOF
  if (!atEnd() && !isOp(";")) syntaxErrorHere();
  int end = prevEnd();
  acceptOp(";");
  st->start = start; st->end = end;
  st->text = sql.substr(start, end - start);
  if (explain) {
    StmtP ex = std::make_shared<Stmt>();
    ex->kind = Stmt::Explain; ex->explainQueryPlan = eqp; ex->inner = st;
    ex->start = start; ex->end = end; ex->text = st->text;
    return ex;
  }
  return st;
}

void Parser::parseWith(std::vector<Cte>& ctes, bool& recursive) {
  expectKw("WITH");
  recursive = acceptKw("RECURSIVE");
  do {
    Cte c;
    c.name = parseName();
    if (acceptOp("(")) {
      do { c.cols.push_back(parseName()); } while (acceptOp(","));
      expectOp(")");
    }
    expectKw("AS");
    if (acceptKw("NOT")) { expectKw("MATERIALIZED"); c.materialized = 2; }
    else if (acceptKw("MATERIALIZED")) c.materialized = 1;
    expectOp("(");
    c.sel = parseSelect(true);
    expectOp(")");
    ctes.push_back(c);
  } while (acceptOp(","));
}

StmtP Parser::parseSelectStmt(std::vector<Cte>* ctes, bool recursive) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Select;
  st->select = parseSelectNoWith(ctes ? *ctes : std::vector<Cte>{}, recursive);
  return st;
}

SelectP Parser::parseSelect(bool allowWith) {
  std::vector<Cte> ctes; bool rec = false;
  if (allowWith && isKw("WITH")) parseWith(ctes, rec);
  return parseSelectNoWith(ctes, rec);
}

SelectP Parser::parseSelectNoWith(std::vector<Cte> ctes, bool recursive) {
  SelectP sel = std::make_shared<Select>();
  sel->ctes = ctes; sel->recursive = recursive;
  sel->start = peek().pos;
  sel->cores.push_back(parseSelectCore());
  while (isKw("UNION") || isKw("INTERSECT") || isKw("EXCEPT")) {
    int op;
    if (acceptKw("UNION")) { if (acceptKw("ALL")) op = 2; else op = 1; }
    else if (acceptKw("INTERSECT")) op = 3;
    else { next(); op = 4; }
    sel->ops.push_back(op);
    if (!(isKw("SELECT") || isKw("VALUES"))) syntaxErrorHere();
    sel->cores.push_back(parseSelectCore());
  }
  if (isKw("ORDER")) sel->orderBy = parseOrderBy();
  if (acceptKw("LIMIT")) {
    sel->limit = parseExpr();
    if (acceptKw("OFFSET")) sel->offset = parseExpr();
    else if (acceptOp(",")) { sel->offset = sel->limit; sel->limit = parseExpr(); }
  }
  sel->end = prevEnd();
  sel->text = sql.substr(sel->start, sel->end - sel->start);
  return sel;
}

std::vector<OrderBy> Parser::parseOrderBy() {
  std::vector<OrderBy> out;
  expectKw("ORDER"); expectKw("BY");
  do {
    OrderBy ob; ob.e = parseExpr();
    if (acceptKw("ASC")) ob.desc = false; else if (acceptKw("DESC")) ob.desc = true;
    if (acceptKw("NULLS")) { if (acceptKw("FIRST")) ob.nulls = 1; else { expectKw("LAST"); ob.nulls = 2; } }
    out.push_back(ob);
  } while (acceptOp(","));
  return out;
}

std::shared_ptr<SelectCore> Parser::parseSelectCore() {
  auto core = std::make_shared<SelectCore>();
  core->start = peek().pos;
  if (acceptKw("VALUES")) {
    core->isValues = true;
    do {
      expectOp("(");
      std::vector<ExprP> row;
      do { row.push_back(parseExpr()); } while (acceptOp(","));
      expectOp(")");
      core->values.push_back(row);
    } while (acceptOp(","));
    core->end = prevEnd();
    return core;
  }
  expectKw("SELECT");
  if (acceptKw("DISTINCT")) core->distinct = true;
  else if (acceptKw("ALL")) core->all = true;
  do {
    ResultColumn rc;
    int s = peek().pos;
    if (isOp("*")) { next(); rc.e = mkExpr(Expr::Star, s, prevEnd()); }
    else if (isIdent() && isOp(".", 1) && isOp("*", 2)) {
      std::string t = parseName(); next(); next();
      rc.e = mkExpr(Expr::TableStar, s, prevEnd()); rc.e->table = t;
    } else {
      rc.e = parseExpr();
      rc.spanText = spanText(rc.e->start, rc.e->end);
      if (acceptKw("AS")) { rc.alias = parseName(); rc.hasAlias = true; }
      else if (isIdent() || peek().type == TT::STRING) { rc.alias = parseName(); rc.hasAlias = true; }
    }
    core->cols.push_back(rc);
  } while (acceptOp(","));
  if (acceptKw("FROM")) parseFrom(core->from);
  if (acceptKw("WHERE")) core->where = parseExpr();
  if (acceptKw("GROUP")) {
    expectKw("BY");
    do { core->groupBy.push_back(parseExpr()); } while (acceptOp(","));
    if (acceptKw("HAVING")) core->having = parseExpr();
  } else if (isKw("HAVING")) {
    next(); core->having = parseExpr();
  }
  if (acceptKw("WINDOW")) {
    do {
      std::string name = parseName();
      expectKw("AS");
      WindowP w = parseWindowDef(false);
      w->name = name;
      core->windows.push_back({name, w});
    } while (acceptOp(","));
  }
  core->end = prevEnd();
  return core;
}

void Parser::parseFrom(std::vector<SrcItem>& from) {
  from.push_back(parseSrcItem());
  while (true) {
    JoinInfo ji;
    if (acceptOp(",")) { ji.type = 0; }
    else if (isKw("JOIN") || isKw("NATURAL") || isKw("LEFT") || isKw("RIGHT") || isKw("FULL") || isKw("INNER") || isKw("CROSS")) {
      ji.type = 1;
      if (acceptKw("NATURAL")) ji.type |= 16;
      if (acceptKw("LEFT")) { ji.type |= 4; acceptKw("OUTER"); }
      else if (acceptKw("RIGHT")) { ji.type |= 8; acceptKw("OUTER"); }
      else if (acceptKw("FULL")) { ji.type |= 32; acceptKw("OUTER"); }
      else if (acceptKw("INNER")) { ji.type |= 1; }
      else if (acceptKw("CROSS")) { ji.type |= 2; }
      expectKw("JOIN");
    } else break;
    SrcItem it = parseSrcItem();
    it.join = ji;
    if (acceptKw("ON")) it.join.on = parseExpr();
    else if (acceptKw("USING")) {
      expectOp("(");
      do { it.join.usingCols.push_back(parseName()); } while (acceptOp(","));
      expectOp(")");
    }
    from.push_back(it);
  }
}

SrcItem Parser::parseSrcItem() {
  SrcItem it;
  if (acceptOp("(")) {
    if (isKw("SELECT") || isKw("VALUES") || isKw("WITH")) {
      it.sub = parseSelect(true); it.isSubquery = true;
      expectOp(")");
    } else {
      // parenthesized join: parse as nested from -> wrap into subquery of SELECT *
      std::vector<SrcItem> inner;
      parseFrom(inner);
      expectOp(")");
      auto core = std::make_shared<SelectCore>();
      ResultColumn rc; rc.e = mkExpr(Expr::Star, 0, 0); core->cols.push_back(rc);
      core->from = inner;
      auto sel = std::make_shared<Select>(); sel->cores.push_back(core);
      it.sub = sel; it.isSubquery = true;
    }
  } else {
    it.name = parseName();
    if (acceptOp(".")) { it.schema = it.name; it.name = parseName(); }
    if (isOp("(")) {
      next(); it.isTvf = true;
      if (!isOp(")")) { do { it.tvfArgs.push_back(parseExpr()); } while (acceptOp(",")); }
      expectOp(")");
    }
  }
  if (acceptKw("AS")) { it.alias = parseName(); it.hasAlias = true; }
  else if (isIdent() && !isKw("ON") && !isKw("USING") && !isKw("WHERE") && !isKw("GROUP") && !isKw("ORDER") && !isKw("LIMIT") && !isKw("JOIN") && !isKw("INDEXED")) {
    // ambiguous keywords used as aliases are disallowed in some positions; allow plain IDs and fallback keywords
    const Token& t = peek();
    if (t.type == TT::ID || (t.type == TT::KW && kFallback.count(t.kw) && t.kw != "WINDOW" && t.kw != "FILTER" && t.kw != "OVER")) { it.alias = parseName(); it.hasAlias = true; }
  }
  if (acceptKw("INDEXED")) { expectKw("BY"); it.indexedBy = parseName(); }
  else if (isKw("NOT") && isKw("INDEXED", 1)) { next(); next(); it.notIndexed = true; }
  return it;
}

WindowP Parser::parseWindowDef(bool allowName) {
  WindowP w = std::make_shared<WindowDef>();
  if (allowName && isIdent()) { w->name = parseName(); return w; }
  expectOp("(");
  if (isIdent() && !isKw("PARTITION") && !isKw("ORDER") && !isKw("RANGE") && !isKw("ROWS") && !isKw("GROUPS")) w->baseName = parseName();
  if (acceptKw("PARTITION")) {
    expectKw("BY");
    do { w->partition.push_back(parseExpr()); } while (acceptOp(","));
  }
  if (isKw("ORDER")) {
    auto ob = parseOrderBy();
    for (auto& o : ob) { WindowDef::OrderTerm t; t.e = o.e; t.desc = o.desc; t.nulls = o.nulls; w->order.push_back(t); }
  }
  if (isKw("RANGE") || isKw("ROWS") || isKw("GROUPS")) {
    w->hasFrame = true;
    if (acceptKw("RANGE")) w->frameType = 0; else if (acceptKw("ROWS")) w->frameType = 1; else { next(); w->frameType = 2; }
    auto parseBound = [&](int& type, ExprP& e) {
      if (acceptKw("UNBOUNDED")) { if (acceptKw("PRECEDING")) type = 0; else { expectKw("FOLLOWING"); type = 4; } }
      else if (acceptKw("CURRENT")) { expectKw("ROW"); type = 2; }
      else { e = parseExpr(); if (acceptKw("PRECEDING")) type = 1; else { expectKw("FOLLOWING"); type = 3; } }
    };
    if (acceptKw("BETWEEN")) {
      parseBound(w->startType, w->startExpr);
      expectKw("AND");
      parseBound(w->endType, w->endExpr);
    } else {
      parseBound(w->startType, w->startExpr);
      w->endType = 2;
    }
    if (acceptKw("EXCLUDE")) {
      if (acceptKw("NO")) { expectKw("OTHERS"); w->exclude = 0; }
      else if (acceptKw("CURRENT")) { expectKw("ROW"); w->exclude = 1; }
      else if (acceptKw("GROUP")) w->exclude = 2;
      else { expectKw("TIES"); w->exclude = 3; }
    }
  }
  expectOp(")");
  return w;
}

int Parser::parseConflictClause() {
  if (acceptKw("ON")) {
    expectKw("CONFLICT");
    if (acceptKw("ROLLBACK")) return 1;
    if (acceptKw("ABORT")) return 2;
    if (acceptKw("FAIL")) return 3;
    if (acceptKw("IGNORE")) return 4;
    if (acceptKw("REPLACE")) return 5;
    syntaxErrorHere();
  }
  return 0;
}

void Parser::parseFkClause(std::string& table, std::vector<std::string>& cols, int& onDel, int& onUpd, bool& deferrable, bool& initDeferred) {
  expectKw("REFERENCES");
  table = parseName();
  if (acceptOp("(")) { do { cols.push_back(parseName()); } while (acceptOp(",")); expectOp(")"); }
  while (true) {
    if (acceptKw("ON")) {
      bool del;
      if (acceptKw("DELETE")) del = true; else { expectKw("UPDATE"); del = false; }
      int act;
      if (acceptKw("SET")) { if (acceptKw("NULL")) act = 1; else { expectKw("DEFAULT"); act = 2; } }
      else if (acceptKw("CASCADE")) act = 3;
      else if (acceptKw("RESTRICT")) act = 4;
      else { expectKw("NO"); expectKw("ACTION"); act = 5; }
      if (del) onDel = act; else onUpd = act;
    } else if (acceptKw("MATCH")) { parseName(); }
    else break;
  }
  if (isKw("NOT") && isKw("DEFERRABLE", 1)) { next(); next(); deferrable = false; if (acceptKw("INITIALLY")) { if (!acceptKw("DEFERRED")) expectKw("IMMEDIATE"); } }
  else if (acceptKw("DEFERRABLE")) { deferrable = true; if (acceptKw("INITIALLY")) { if (acceptKw("DEFERRED")) initDeferred = true; else expectKw("IMMEDIATE"); } }
}

ColumnDef Parser::parseColumnDef() {
  ColumnDef cd;
  cd.name = parseName();
  cd.type = parseTypeName();
  while (true) {
    std::string cname;
    if (acceptKw("CONSTRAINT")) cname = parseName();
    if (acceptKw("PRIMARY")) {
      expectKw("KEY"); cd.pk = true;
      if (acceptKw("ASC")) {} else if (acceptKw("DESC")) cd.pkDesc = true;
      cd.pkConflict = parseConflictClause();
      if (acceptKw("AUTOINCREMENT")) cd.autoincrement = true;
    } else if (acceptKw("NOT")) {
      expectKw("NULL"); cd.notNull = true; cd.notNullConflict = parseConflictClause(); cd.notNullName = cname;
    } else if (acceptKw("NULL")) {
      parseConflictClause();
    } else if (acceptKw("UNIQUE")) {
      cd.unique = true; cd.uniqueConflict = parseConflictClause();
    } else if (acceptKw("CHECK")) {
      expectOp("("); cd.checks.push_back(parseExpr()); expectOp(")");
    } else if (acceptKw("DEFAULT")) {
      int s = peek().pos;
      if (acceptOp("(")) { cd.dflt = parseExpr(); expectOp(")"); }
      else if (isOp("-") || isOp("+")) {
        bool neg = isOp("-"); next();
        const Token& t = peek();
        if (t.type != TT::INTEGER && t.type != TT::FLOAT) syntaxErrorHere();
        ExprP lit = parsePrimary();
        if (neg) { ExprP u = mkExpr(Expr::Unary, s, prevEnd()); u->op = "-"; u->args.push_back(lit); cd.dflt = u; }
        else cd.dflt = lit;
      } else {
        const Token& t = peek();
        if (t.type == TT::INTEGER || t.type == TT::FLOAT || t.type == TT::STRING || t.type == TT::BLOB ||
            (t.type == TT::KW && (t.kw == "NULL" || t.kw == "CURRENT_TIME" || t.kw == "CURRENT_DATE" || t.kw == "CURRENT_TIMESTAMP")) ||
            t.type == TT::ID) {
          cd.dflt = parsePrimary();
        } else syntaxErrorHere();
      }
      cd.hasDefault = true;
      cd.dfltText = sql.substr(s, prevEnd() - s);
    } else if (acceptKw("COLLATE")) {
      cd.collate = parseName();
    } else if (isKw("REFERENCES")) {
      int s = peek().pos;
      bool d = false, id = false;
      parseFkClause(cd.fkTable, cd.fkCols, cd.fkOnDelete, cd.fkOnUpdate, d, id);
      cd.hasFk = true; cd.fkText = sql.substr(s, prevEnd() - s);
    } else if (acceptKw("GENERATED")) {
      expectKw("ALWAYS"); expectKw("AS"); expectOp("("); cd.generated = parseExpr(); expectOp(")");
      cd.isGenerated = true;
      if (acceptKw("STORED")) cd.generatedStored = 1; else if (acceptKw("VIRTUAL")) cd.generatedStored = 0;
    } else if (acceptKw("AS")) {
      expectOp("("); cd.generated = parseExpr(); expectOp(")"); cd.isGenerated = true;
      if (acceptKw("STORED")) cd.generatedStored = 1; else if (acceptKw("VIRTUAL")) cd.generatedStored = 0;
    } else {
      if (!cname.empty()) syntaxErrorHere();
      break;
    }
  }
  return cd;
}

std::vector<IndexedColumn> Parser::parseIndexedColumns() {
  std::vector<IndexedColumn> cols;
  expectOp("(");
  do {
    IndexedColumn ic;
    ic.e = parseExpr();
    if (ic.e->kind == Expr::Column && ic.e->table.empty()) ic.name = ic.e->column;
    if (ic.e->kind == Expr::Collate && ic.e->args[0]->kind == Expr::Column && ic.e->args[0]->table.empty()) { ic.name = ic.e->args[0]->column; ic.collate = ic.e->collate; }
    if (acceptKw("COLLATE")) ic.collate = parseName();
    if (acceptKw("ASC")) {} else if (acceptKw("DESC")) ic.desc = true;
    cols.push_back(ic);
  } while (acceptOp(","));
  expectOp(")");
  return cols;
}

void Parser::parseTableConstraint(Stmt& st) {
  TableConstraint tc;
  if (acceptKw("CONSTRAINT")) tc.name = parseName();
  if (acceptKw("PRIMARY")) {
    expectKw("KEY"); tc.kind = TableConstraint::PK;
    expectOp("(");
    do {
      IndexedColumn ic; ic.e = parseExpr();
      if (ic.e->kind == Expr::Column && ic.e->table.empty()) ic.name = ic.e->column;
      if (acceptKw("COLLATE")) ic.collate = parseName();
      if (acceptKw("ASC")) {} else if (acceptKw("DESC")) ic.desc = true;
      if (acceptKw("AUTOINCREMENT")) tc.autoincrement = true;
      tc.cols.push_back(ic);
    } while (acceptOp(","));
    expectOp(")");
    tc.conflict = parseConflictClause();
  } else if (acceptKw("UNIQUE")) {
    tc.kind = TableConstraint::Unique;
    tc.cols = parseIndexedColumns();
    tc.conflict = parseConflictClause();
  } else if (acceptKw("CHECK")) {
    tc.kind = TableConstraint::Check;
    expectOp("("); tc.check = parseExpr(); expectOp(")");
  } else if (acceptKw("FOREIGN")) {
    expectKw("KEY"); tc.kind = TableConstraint::ForeignKey;
    expectOp("(");
    do { IndexedColumn ic; ic.name = parseName(); tc.cols.push_back(ic); } while (acceptOp(","));
    expectOp(")");
    parseFkClause(tc.fkTable, tc.fkCols, tc.fkOnDelete, tc.fkOnUpdate, tc.deferrable, tc.initiallyDeferred);
  } else syntaxErrorHere();
  st.constraints.push_back(tc);
}

StmtP Parser::parseCreate() {
  int startPos = peek().pos;
  expectKw("CREATE");
  bool temp = false;
  if (acceptKw("TEMP") || acceptKw("TEMPORARY")) temp = true;
  if (acceptKw("TABLE")) return parseCreateTable(temp, startPos);
  if (acceptKw("VIEW")) return parseCreateView(temp, startPos);
  if (acceptKw("TRIGGER")) return parseCreateTrigger(temp, startPos);
  if (acceptKw("UNIQUE")) { expectKw("INDEX"); return parseCreateIndex(true, startPos); }
  if (acceptKw("INDEX")) return parseCreateIndex(false, startPos);
  if (acceptKw("VIRTUAL")) { expectKw("TABLE"); return parseCreateVirtual(startPos); }
  syntaxErrorHere();
}

StmtP Parser::parseCreateTable(bool temp, int startPos) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::CreateTable; st->temp = temp;
  if (acceptKw("IF")) { expectKw("NOT"); expectKw("EXISTS"); st->ifNotExists = true; }
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("AS")) {
    st->asSelect = parseSelect(true);
    return st;
  }
  expectOp("(");
  bool first = true;
  while (true) {
    if (!first) { if (!acceptOp(",")) break; }
    first = false;
    if (isKw("CONSTRAINT") || isKw("PRIMARY") || isKw("UNIQUE") || isKw("CHECK") || isKw("FOREIGN")) {
      parseTableConstraint(*st);
    } else {
      if (!st->constraints.empty()) syntaxErrorHere();
      st->colDefs.push_back(parseColumnDef());
    }
  }
  expectOp(")");
  while (true) {
    if (acceptKw("WITHOUT")) { if (!(peek().type == TT::ID && upperStr(peek().kw) == "ROWID")) syntaxErrorHere(); next(); st->withoutRowid = true; }
    else if (peek().type == TT::ID && upperStr(peek().kw) == "STRICT") { next(); st->strict = true; }
    else break;
    if (!acceptOp(",")) break;
  }
  (void)startPos;
  return st;
}

StmtP Parser::parseCreateIndex(bool unique, int startPos) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::CreateIndex; st->unique = unique;
  if (acceptKw("IF")) { expectKw("NOT"); expectKw("EXISTS"); st->ifNotExists = true; }
  st->indexName = parseName();
  if (acceptOp(".")) { st->schema = st->indexName; st->indexName = parseName(); }
  expectKw("ON");
  st->onTable = parseName();
  st->indexCols = parseIndexedColumns();
  if (acceptKw("WHERE")) st->where = parseExpr();
  (void)startPos;
  return st;
}

StmtP Parser::parseCreateView(bool temp, int startPos) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::CreateView; st->temp = temp;
  if (acceptKw("IF")) { expectKw("NOT"); expectKw("EXISTS"); st->ifNotExists = true; }
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptOp("(")) { do { st->viewCols.push_back(parseName()); } while (acceptOp(",")); expectOp(")"); }
  expectKw("AS");
  st->select = parseSelect(true);
  (void)startPos;
  return st;
}

StmtP Parser::parseCreateTrigger(bool temp, int startPos) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::CreateTrigger; st->temp = temp;
  if (acceptKw("IF")) { expectKw("NOT"); expectKw("EXISTS"); st->ifNotExists = true; }
  st->triggerName = parseName();
  if (acceptOp(".")) { st->schema = st->triggerName; st->triggerName = parseName(); }
  if (acceptKw("BEFORE")) st->trigTime = 1;
  else if (acceptKw("AFTER")) st->trigTime = 2;
  else if (acceptKw("INSTEAD")) { expectKw("OF"); st->trigTime = 3; }
  if (acceptKw("DELETE")) st->trigEvent = 1;
  else if (acceptKw("INSERT")) st->trigEvent = 2;
  else if (acceptKw("UPDATE")) {
    st->trigEvent = 3;
    if (acceptKw("OF")) { do { st->trigCols.push_back(parseName()); } while (acceptOp(",")); }
  } else syntaxErrorHere();
  expectKw("ON");
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("FOR")) { expectKw("EACH"); expectKw("ROW"); st->forEachRow = true; }
  if (acceptKw("WHEN")) st->trigWhen = parseExpr();
  expectKw("BEGIN");
  while (!isKw("END")) {
    if (atEnd()) syntaxErrorHere();
    int s = peek().pos;
    StmtP b;
    if (isKw("SELECT") || isKw("VALUES")) b = parseSelectStmt(nullptr, false);
    else if (isKw("WITH")) {
      std::vector<Cte> ctes; bool rec = false; parseWith(ctes, rec);
      if (isKw("SELECT")) b = parseSelectStmt(&ctes, rec);
      else if (isKw("INSERT") || isKw("REPLACE")) b = parseInsert(ctes, rec);
      else if (isKw("UPDATE")) b = parseUpdate(ctes, rec);
      else if (isKw("DELETE")) b = parseDelete(ctes, rec);
      else syntaxErrorHere();
    }
    else if (isKw("INSERT") || isKw("REPLACE")) b = parseInsert({}, false);
    else if (isKw("UPDATE")) b = parseUpdate({}, false);
    else if (isKw("DELETE")) b = parseDelete({}, false);
    else syntaxErrorHere();
    expectOp(";");
    b->start = s; b->end = prevEnd() - 1; b->text = sql.substr(s, b->end - s);
    st->trigBody.push_back(b);
  }
  expectKw("END");
  (void)startPos;
  return st;
}

StmtP Parser::parseCreateVirtual(int startPos) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::CreateVirtualTable;
  if (acceptKw("IF")) { expectKw("NOT"); expectKw("EXISTS"); st->ifNotExists = true; }
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  expectKw("USING");
  st->moduleName = parseName();
  if (acceptOp("(")) {
    int depth = 0; int s = peek().pos;
    while (!atEnd()) {
      if (isOp("(")) depth++;
      else if (isOp(")")) { if (depth == 0) break; depth--; }
      else if (isOp(",") && depth == 0) { st->moduleArgs.push_back(sql.substr(s, peek().pos - s)); next(); s = peek().pos; continue; }
      next();
    }
    if (peek().pos > s) st->moduleArgs.push_back(sql.substr(s, peek().pos - s));
    expectOp(")");
  }
  (void)startPos;
  return st;
}

StmtP Parser::parseDrop() {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Drop;
  expectKw("DROP");
  if (acceptKw("TABLE")) st->dropKind = 1;
  else if (acceptKw("INDEX")) st->dropKind = 2;
  else if (acceptKw("VIEW")) st->dropKind = 3;
  else if (acceptKw("TRIGGER")) st->dropKind = 4;
  else syntaxErrorHere();
  if (acceptKw("IF")) { expectKw("EXISTS"); st->ifExists = true; }
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  return st;
}

StmtP Parser::parseAlter() {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::AlterTable;
  expectKw("ALTER"); expectKw("TABLE");
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("RENAME")) {
    if (acceptKw("TO")) { st->alterKind = 1; st->newName = parseName(); }
    else {
      acceptKw("COLUMN");
      st->alterKind = 3; st->oldColName = parseName(); expectKw("TO"); st->newColName = parseName();
    }
  } else if (acceptKw("ADD")) {
    acceptKw("COLUMN");
    int s = peek().pos;
    st->alterKind = 2; st->addCol = parseColumnDef();
    st->addColText = sql.substr(s, prevEnd() - s);
  } else if (acceptKw("DROP")) {
    acceptKw("COLUMN");
    st->alterKind = 4; st->oldColName = parseName();
  } else syntaxErrorHere();
  return st;
}

StmtP Parser::parsePragma() {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Pragma;
  expectKw("PRAGMA");
  st->pragmaName = parseName();
  if (acceptOp(".")) { st->schema = st->pragmaName; st->pragmaName = parseName(); }
  if (acceptOp("=")) {
    st->pragmaHasValue = true;
    // pragma value: signed number, name, or string
    if (isOp("-") || isOp("+")) { int s = peek().pos; bool neg = isOp("-"); next(); ExprP lit = parsePrimary(); if (neg) { ExprP u = mkExpr(Expr::Unary, s, prevEnd()); u->op = "-"; u->args.push_back(lit); st->pragmaValue = u; } else st->pragmaValue = lit; }
    else if (peek().type == TT::KW && !kFallback.count(peek().kw)) { Token t = next(); ExprP e = mkExpr(Expr::Literal, t.pos, t.pos + t.len); e->lit = Value::Text(t.text); st->pragmaValue = e; }
    else {
      const Token& t = peek();
      if (t.type == TT::ID || (t.type == TT::KW)) { Token tk = next(); ExprP e = mkExpr(Expr::Literal, tk.pos, tk.pos + tk.len); e->lit = Value::Text(tk.type == TT::ID ? tk.kw : tk.text); st->pragmaValue = e; }
      else st->pragmaValue = parsePrimary();
    }
  } else if (acceptOp("(")) {
    st->pragmaHasValue = true; st->pragmaCall = true;
    if (isOp("-") || isOp("+")) { int s = peek().pos; bool neg = isOp("-"); next(); ExprP lit = parsePrimary(); if (neg) { ExprP u = mkExpr(Expr::Unary, s, prevEnd()); u->op = "-"; u->args.push_back(lit); st->pragmaValue = u; } else st->pragmaValue = lit; }
    else {
      const Token& t = peek();
      if (t.type == TT::ID || t.type == TT::KW) { Token tk = next(); ExprP e = mkExpr(Expr::Literal, tk.pos, tk.pos + tk.len); e->lit = Value::Text(tk.type == TT::ID ? tk.kw : tk.text); st->pragmaValue = e; }
      else st->pragmaValue = parsePrimary();
    }
    expectOp(")");
  }
  return st;
}

void Parser::parseReturning(Stmt& st) {
  if (!acceptKw("RETURNING")) return;
  st.hasReturning = true;
  do {
    ResultColumn rc;
    int s = peek().pos;
    if (isOp("*")) { next(); rc.e = mkExpr(Expr::Star, s, prevEnd()); }
    else {
      rc.e = parseExpr();
      rc.spanText = spanText(rc.e->start, rc.e->end);
      if (acceptKw("AS")) { rc.alias = parseName(); rc.hasAlias = true; }
      else if (isIdent() || peek().type == TT::STRING) { rc.alias = parseName(); rc.hasAlias = true; }
    }
    st.returning.push_back(rc);
  } while (acceptOp(","));
}

void Parser::parseSetList(std::vector<std::pair<std::vector<std::string>, ExprP>>& sets) {
  do {
    std::vector<std::string> cols;
    if (acceptOp("(")) { do { cols.push_back(parseName()); } while (acceptOp(",")); expectOp(")"); }
    else cols.push_back(parseName());
    expectOp("=");
    ExprP e = parseExpr();
    sets.push_back({cols, e});
  } while (acceptOp(","));
}

std::shared_ptr<Upsert> Parser::parseUpsert() {
  auto up = std::make_shared<Upsert>();
  expectKw("ON"); expectKw("CONFLICT");
  if (isOp("(")) {
    up->hasTarget = true;
    up->target = parseIndexedColumns();
    if (acceptKw("WHERE")) up->targetWhere = parseExpr();
  }
  expectKw("DO");
  if (acceptKw("NOTHING")) { up->doNothing = true; }
  else {
    expectKw("UPDATE"); expectKw("SET"); up->doNothing = false;
    parseSetList(up->sets);
    if (acceptKw("WHERE")) up->where = parseExpr();
  }
  return up;
}

StmtP Parser::parseInsert(std::vector<Cte> ctes, bool recursive) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Insert; st->ctes = ctes; st->recursive = recursive;
  if (acceptKw("REPLACE")) { st->isReplace = true; st->orConflict = 5; }
  else {
    expectKw("INSERT");
    if (acceptKw("OR")) {
      if (acceptKw("ROLLBACK")) st->orConflict = 1; else if (acceptKw("ABORT")) st->orConflict = 2; else if (acceptKw("FAIL")) st->orConflict = 3;
      else if (acceptKw("IGNORE")) st->orConflict = 4; else if (acceptKw("REPLACE")) st->orConflict = 5; else syntaxErrorHere();
    }
  }
  expectKw("INTO");
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("AS")) st->alias = parseName();
  if (acceptOp("(")) { do { st->columns.push_back(parseName()); } while (acceptOp(",")); expectOp(")"); }
  if (acceptKw("DEFAULT")) { expectKw("VALUES"); st->defaultValues = true; }
  else {
    st->select = parseSelect(true);
  }
  while (isKw("ON")) st->upserts.push_back(parseUpsert());
  if (!st->upserts.empty()) st->upsert = st->upserts[0];
  parseReturning(*st);
  return st;
}

StmtP Parser::parseUpdate(std::vector<Cte> ctes, bool recursive) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Update; st->ctes = ctes; st->recursive = recursive;
  expectKw("UPDATE");
  if (acceptKw("OR")) {
    if (acceptKw("ROLLBACK")) st->orConflict = 1; else if (acceptKw("ABORT")) st->orConflict = 2; else if (acceptKw("FAIL")) st->orConflict = 3;
    else if (acceptKw("IGNORE")) st->orConflict = 4; else if (acceptKw("REPLACE")) st->orConflict = 5; else syntaxErrorHere();
  }
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("AS")) st->alias = parseName();
  else if (isIdent() && !isKw("SET") && !isKw("INDEXED") && !isKw("NOT")) st->alias = parseName();
  if (acceptKw("INDEXED")) { expectKw("BY"); st->indexedBy = parseName(); }
  else if (isKw("NOT") && isKw("INDEXED", 1)) { next(); next(); st->notIndexed = true; }
  expectKw("SET");
  parseSetList(st->sets);
  if (acceptKw("FROM")) parseFrom(st->from);
  if (acceptKw("WHERE")) st->where = parseExpr();
  parseReturning(*st);
  if (isKw("ORDER")) st->orderBy = parseOrderBy();
  if (acceptKw("LIMIT")) { st->limit = parseExpr(); if (acceptKw("OFFSET")) st->offset = parseExpr(); else if (acceptOp(",")) { st->offset = st->limit; st->limit = parseExpr(); } }
  return st;
}

StmtP Parser::parseDelete(std::vector<Cte> ctes, bool recursive) {
  StmtP st = std::make_shared<Stmt>();
  st->kind = Stmt::Delete; st->ctes = ctes; st->recursive = recursive;
  expectKw("DELETE"); expectKw("FROM");
  st->table = parseName();
  if (acceptOp(".")) { st->schema = st->table; st->table = parseName(); }
  if (acceptKw("AS")) st->alias = parseName();
  else if (isIdent() && !isKw("WHERE") && !isKw("INDEXED") && !isKw("NOT")) st->alias = parseName();
  if (acceptKw("INDEXED")) { expectKw("BY"); st->indexedBy = parseName(); }
  else if (isKw("NOT") && isKw("INDEXED", 1)) { next(); next(); st->notIndexed = true; }
  if (acceptKw("WHERE")) st->where = parseExpr();
  parseReturning(*st);
  if (isKw("ORDER")) st->orderBy = parseOrderBy();
  if (acceptKw("LIMIT")) { st->limit = parseExpr(); if (acceptKw("OFFSET")) st->offset = parseExpr(); else if (acceptOp(",")) { st->offset = st->limit; st->limit = parseExpr(); } }
  return st;
}

// ---------------- Expressions ----------------

ExprP Parser::mkExpr(Expr::Kind k, int start, int end) {
  ExprP e = std::make_shared<Expr>();
  e->kind = k; e->start = start; e->end = end;
  return e;
}

// precedence levels
// 1: OR, 2: AND, 3: NOT (unary, handled), 4: = == != <> IS IN LIKE GLOB MATCH REGEXP BETWEEN ISNULL NOTNULL
// 5: < <= > >=, 6: ESCAPE, 7: & | << >>, 8: + -, 9: * / %, 10: || -> ->>, 11: COLLATE, 12: unary - + ~
static int binPrec(const Token& t) {
  if (t.type == TT::KW) {
    if (t.kw == "OR") return 1;
    if (t.kw == "AND") return 2;
    if (t.kw == "IS" || t.kw == "IN" || t.kw == "LIKE" || t.kw == "GLOB" || t.kw == "MATCH" || t.kw == "REGEXP" ||
        t.kw == "BETWEEN" || t.kw == "ISNULL" || t.kw == "NOTNULL" || t.kw == "NOT") return 4;
    if (t.kw == "COLLATE") return 11;
    return -1;
  }
  if (t.type != TT::OP) return -1;
  const std::string& o = t.text;
  if (o == "=" || o == "==" || o == "!=" || o == "<>") return 4;
  if (o == "<" || o == "<=" || o == ">" || o == ">=") return 5;
  if (o == "&" || o == "|" || o == "<<" || o == ">>") return 7;
  if (o == "+" || o == "-") return 8;
  if (o == "*" || o == "/" || o == "%") return 9;
  if (o == "||" || o == "->" || o == "->>") return 10;
  return -1;
}

ExprP Parser::parseExpr(int minPrec) {
  if (++exprDepth > 1000) { exprDepth--; throw SqlError("Expression tree is too large (maximum depth 1000)"); }
  ExprP left;
  int start = peek().pos;
  if (isKw("NOT") && minPrec <= 3) {
    next();
    ExprP operand = parseExpr(3);
    left = mkExpr(Expr::Not, start, prevEnd());
    left->args.push_back(operand);
  } else {
    left = parseUnary();
  }
  while (true) {
    const Token& t = peek();
    int prec = binPrec(t);
    if (prec < 0 || prec < minPrec) break;
    if (t.type == TT::KW) {
      if (t.kw == "NOT") {
        // NOT IN / NOT LIKE / NOT BETWEEN / NOT NULL / NOT GLOB ...
        const Token& t2 = peek(1);
        if (t2.type == TT::KW && t2.kw == "NULL") {
          next(); next();
          ExprP e = mkExpr(Expr::NotNull, start, prevEnd()); e->args.push_back(left); left = e; continue;
        }
        if (t2.type == TT::KW && (t2.kw == "IN" || t2.kw == "LIKE" || t2.kw == "GLOB" || t2.kw == "MATCH" || t2.kw == "REGEXP" || t2.kw == "BETWEEN")) {
          next();  // consume NOT; fallthrough handled below with negate flag
          const Token& t3 = peek();
          std::string kw = t3.kw; next();
          ExprP e;
          if (kw == "IN") {
            e = mkExpr(Expr::In, start, 0); e->negate = true; e->args.push_back(left);
            if (acceptOp("(")) {
              if (isKw("SELECT") || isKw("VALUES") || isKw("WITH")) { e->sub = parseSelect(true); }
              else if (!isOp(")")) { do { e->args.push_back(parseExpr()); } while (acceptOp(",")); }
              expectOp(")");
            } else {
              std::string n = parseName();
              if (acceptOp(".")) { e->schema = n; n = parseName(); }
              e->table = n;
              if (isOp("(")) { next(); e->op = "tvf"; if (!isOp(")")) { do { e->args.push_back(parseExpr()); } while (acceptOp(",")); } expectOp(")"); }
            }
          } else if (kw == "BETWEEN") {
            e = mkExpr(Expr::Between, start, 0); e->negate = true; e->args.push_back(left);
            e->args.push_back(parseExpr(5)); expectKw("AND"); e->args.push_back(parseExpr(5));
          } else {
            e = mkExpr(Expr::Like, start, 0); e->negate = true; e->op = upperStr(kw);
            e->args.push_back(left); e->args.push_back(parseExpr(5));
            if (acceptKw("ESCAPE")) e->args.push_back(parseExpr(6));
          }
          e->end = prevEnd(); left = e; continue;
        }
        break;
      }
      if (t.kw == "ISNULL") { next(); ExprP e = mkExpr(Expr::IsNull, start, prevEnd()); e->args.push_back(left); left = e; continue; }
      if (t.kw == "NOTNULL") { next(); ExprP e = mkExpr(Expr::NotNull, start, prevEnd()); e->args.push_back(left); left = e; continue; }
      if (t.kw == "IS") {
        next();
        bool isNot = acceptKw("NOT");
        if (acceptKw("DISTINCT")) { expectKw("FROM"); isNot = !isNot; }
        ExprP right = parseExpr(5);
        ExprP e = mkExpr(isNot ? Expr::IsNot : Expr::Is, start, prevEnd());
        e->args.push_back(left); e->args.push_back(right); left = e; continue;
      }
      if (t.kw == "IN") {
        next();
        ExprP e = mkExpr(Expr::In, start, 0); e->args.push_back(left);
        if (acceptOp("(")) {
          if (isKw("SELECT") || isKw("VALUES") || isKw("WITH")) { e->sub = parseSelect(true); }
          else if (!isOp(")")) { do { e->args.push_back(parseExpr()); } while (acceptOp(",")); }
          expectOp(")");
        } else {
          std::string n = parseName();
          if (acceptOp(".")) { e->schema = n; n = parseName(); }
          e->table = n;
          if (isOp("(")) { next(); e->op = "tvf"; if (!isOp(")")) { do { e->args.push_back(parseExpr()); } while (acceptOp(",")); } expectOp(")"); }
        }
        e->end = prevEnd(); left = e; continue;
      }
      if (t.kw == "BETWEEN") {
        next();
        ExprP e = mkExpr(Expr::Between, start, 0); e->args.push_back(left);
        e->args.push_back(parseExpr(5)); expectKw("AND"); e->args.push_back(parseExpr(5));
        e->end = prevEnd(); left = e; continue;
      }
      if (t.kw == "LIKE" || t.kw == "GLOB" || t.kw == "MATCH" || t.kw == "REGEXP") {
        std::string kw = t.kw; next();
        ExprP e = mkExpr(Expr::Like, start, 0); e->op = kw;
        e->args.push_back(left); e->args.push_back(parseExpr(5));
        if (acceptKw("ESCAPE")) e->args.push_back(parseExpr(6));
        e->end = prevEnd(); left = e; continue;
      }
      if (t.kw == "AND") { next(); ExprP r = parseExpr(3); ExprP e = mkExpr(Expr::And, start, prevEnd()); e->args.push_back(left); e->args.push_back(r); left = e; continue; }
      if (t.kw == "OR") { next(); ExprP r = parseExpr(2); ExprP e = mkExpr(Expr::Or, start, prevEnd()); e->args.push_back(left); e->args.push_back(r); left = e; continue; }
      if (t.kw == "COLLATE") { next(); ExprP e = mkExpr(Expr::Collate, start, 0); e->args.push_back(left); e->collate = parseName(); e->end = prevEnd(); left = e; continue; }
      break;
    }
    // binary operator
    std::string op = t.text; next();
    ExprP right = parseExpr(prec + 1);
    ExprP e = mkExpr(Expr::Binary, start, prevEnd());
    e->op = op; e->args.push_back(left); e->args.push_back(right);
    left = e;
  }
  exprDepth--;
  return left;
}

ExprP Parser::parseUnary() {
  int start = peek().pos;
  if (isOp("-") || isOp("+") || isOp("~")) {
    std::string op = next().text;
    ExprP operand = parseUnary();
    // fold negative numeric literals
    ExprP e = mkExpr(Expr::Unary, start, prevEnd());
    e->op = op; e->args.push_back(operand);
    return e;
  }
  ExprP prim = parsePrimary();
  // postfix COLLATE binds tightly
  while (isKw("COLLATE")) {
    next();
    ExprP e = mkExpr(Expr::Collate, start, 0); e->args.push_back(prim); e->collate = parseName(); e->end = prevEnd();
    prim = e;
  }
  return prim;
}

std::string Parser::parseCollationName() { return parseName(); }

ExprP Parser::parsePrimary() {
  const Token& t = peek();
  int start = t.pos;
  switch (t.type) {
    case TT::INTEGER: {
      next();
      ExprP e = mkExpr(Expr::Literal, start, prevEnd());
      const std::string& txt = t.text;
      if (txt.size() > 1 && (txt[1] == 'x' || txt[1] == 'X')) {
        if (txt.size() > 18) throw SqlError("hex literal too big: " + txt, start);
        uint64_t v = strtoull(txt.c_str() + 2, nullptr, 16);
        e->lit = Value::Int((int64_t)v);
      } else {
        int64_t iv; double rv;
        int k = parseNumber(txt, iv, rv, true);
        if (k == 1) e->lit = Value::Int(iv); else e->lit = Value::Real(rv);
      }
      return e;
    }
    case TT::FLOAT: {
      next();
      ExprP e = mkExpr(Expr::Literal, start, prevEnd());
      e->lit = Value::Real(strtod(t.text.c_str(), nullptr));
      return e;
    }
    case TT::STRING: {
      next();
      ExprP e = mkExpr(Expr::Literal, start, prevEnd());
      e->lit = Value::Text(t.kw);
      return e;
    }
    case TT::BLOB: {
      next();
      ExprP e = mkExpr(Expr::Literal, start, prevEnd());
      e->lit = Value::Blob(t.kw);
      return e;
    }
    case TT::VARIABLE: {
      next();
      ExprP e = mkExpr(Expr::Param, start, prevEnd());
      e->paramName = t.kw;
      return e;
    }
    case TT::OP: {
      if (t.text == "(") {
        next();
        if (isKw("SELECT") || isKw("VALUES") || isKw("WITH")) {
          ExprP e = mkExpr(Expr::Subquery, start, 0);
          e->sub = parseSelect(true);
          expectOp(")");
          e->end = prevEnd();
          return e;
        }
        ExprP first = parseExpr();
        if (isOp(",")) {
          ExprP row = mkExpr(Expr::Row, start, 0);
          row->args.push_back(first);
          while (acceptOp(",")) row->args.push_back(parseExpr());
          expectOp(")");
          row->end = prevEnd();
          return row;
        }
        expectOp(")");
        // parenthesized expression: keep inner but extend span
        ExprP e = mkExpr(Expr::Unary, start, prevEnd());
        e->op = "()"; e->args.push_back(first);
        return e;
      }
      syntaxErrorHere();
    }
    case TT::KW: {
      if (t.kw == "NULL") { next(); ExprP e = mkExpr(Expr::Literal, start, prevEnd()); return e; }
      if (t.kw == "CURRENT_TIME" || t.kw == "CURRENT_DATE" || t.kw == "CURRENT_TIMESTAMP") {
        next(); ExprP e = mkExpr(Expr::Func, start, prevEnd()); e->op = utf8Lower(t.kw); return e;
      }
      if (t.kw == "CASE") {
        next();
        ExprP e = mkExpr(Expr::Case, start, 0);
        if (!isKw("WHEN")) e->args.push_back(parseExpr()); else e->args.push_back(nullptr);
        if (!isKw("WHEN")) syntaxErrorHere();
        while (acceptKw("WHEN")) {
          e->args.push_back(parseExpr()); expectKw("THEN"); e->args.push_back(parseExpr());
        }
        if (acceptKw("ELSE")) e->elseExpr = parseExpr();
        expectKw("END");
        e->end = prevEnd();
        return e;
      }
      if (t.kw == "CAST") {
        next(); expectOp("(");
        ExprP e = mkExpr(Expr::Cast, start, 0);
        e->args.push_back(parseExpr());
        expectKw("AS");
        e->castType = parseTypeName();
        expectOp(")");
        e->end = prevEnd();
        return e;
      }
      if (t.kw == "EXISTS") {
        next(); expectOp("(");
        ExprP e = mkExpr(Expr::Exists, start, 0);
        e->sub = parseSelect(true);
        expectOp(")");
        e->end = prevEnd();
        return e;
      }
      if (t.kw == "NOT" ) {
        // NOT EXISTS etc inside primary position
        next();
        ExprP operand = parseExpr(3);
        ExprP e = mkExpr(Expr::Not, start, prevEnd()); e->args.push_back(operand); return e;
      }
      if (t.kw == "RAISE") {
        next(); expectOp("(");
        ExprP e = mkExpr(Expr::Raise, start, 0);
        if (acceptKw("IGNORE")) e->op = "IGNORE";
        else {
          if (acceptKw("ROLLBACK")) e->op = "ROLLBACK"; else if (acceptKw("ABORT")) e->op = "ABORT"; else if (acceptKw("FAIL")) e->op = "FAIL"; else syntaxErrorHere();
          expectOp(",");
          if (peek().type != TT::STRING) syntaxErrorHere();
          e->lit = Value::Text(next().kw);
        }
        expectOp(")");
        e->end = prevEnd();
        return e;
      }
      if (kFallback.count(t.kw)) {
        // identifier-like keyword
        break;
      }
      syntaxErrorHere();
    }
    case TT::ID: break;
    case TT::ILLEGAL: next(); break;
    case TT::END: syntaxErrorHere();
    default: syntaxErrorHere();
  }
  // identifier: column ref or function call
  Token nameTok = next();
  if (isOp("(")) return parseFunctionCall(nameTok);
  ExprP e = mkExpr(Expr::Column, start, 0);
  e->column = nameTok.type == TT::ID ? nameTok.kw : nameTok.text;
  if (nameTok.type == TT::ID && nameTok.quoted && nameTok.quoteChar == '"') e->op = "dq"; // double-quoted identifier (may fall back to string)
  if (isOp(".")) {
    next();
    Token t2 = peek();
    if (!(isIdent() || t2.type == TT::STRING)) syntaxErrorHere();
    std::string n2 = parseName();
    e->table = e->column; e->column = n2; e->op = "";
    if (isOp(".")) {
      next();
      if (!isIdent()) syntaxErrorHere();
      std::string n3 = parseName();
      e->schema = e->table; e->table = e->column; e->column = n3;
    }
  }
  e->end = prevEnd();
  return e;
}

ExprP Parser::parseFunctionCall(const Token& nameTok) {
  int start = nameTok.pos;
  expectOp("(");
  ExprP e = mkExpr(Expr::Func, start, 0);
  e->op = utf8Lower(nameTok.type == TT::ID ? nameTok.kw : nameTok.text);
  if (isOp("*")) { next(); e->op += ""; ExprP star = mkExpr(Expr::Star, prevEnd() - 1, prevEnd()); e->args.push_back(star); }
  else if (!isOp(")")) {
    if (acceptKw("DISTINCT")) e->distinct = true;
    else acceptKw("ALL");
    do { e->args.push_back(parseExpr()); } while (acceptOp(","));
    if (isKw("ORDER")) {
      // aggregate ORDER BY (e.g. group_concat(x ORDER BY y)); parse and store in filter? use elseExpr list
      auto ob = parseOrderBy();
      for (auto& o : ob) { ExprP t = mkExpr(Expr::Unary, 0, 0); t->op = o.desc ? "orderdesc" : "orderasc"; t->args.push_back(o.e); t->paramIdx = o.nulls; e->over = e->over; e->args.push_back(t); e->paramIdx++; }
    }
  }
  expectOp(")");
  e->end = prevEnd();
  parseFilterOver(e);
  return e;
}

void Parser::parseFilterOver(ExprP& fn) {
  if (isKw("FILTER") && isOp("(", 1)) {
    next(); expectOp("("); expectKw("WHERE");
    fn->filter = parseExpr();
    expectOp(")");
    fn->end = prevEnd();
  }
  if (isKw("OVER") && (isOp("(", 1) || isIdent(1))) {
    next();
    fn->over = parseWindowDef(true);
    fn->end = prevEnd();
  }
}

ExprP Parser::parseExprOnly() {
  ExprP e = parseExpr();
  return e;
}
