        if (hasBase) {
          Value w = evalExpr(e->args[k].get(), sc);
          if (base.isNull() || w.isNull()) continue;
          Value a = base, b = w;
          applyCompareAffinity(a, b, affinityOf(e->args[0].get(), sc), affinityOf(e->args[k].get(), sc));
          std::string coll = compareCollation(this, e->args[0].get(), e->args[k].get(), sc);
