      }
      std::vector<Value> args;
      args.reserve(e->args.size());
      for (auto& a : e->args) {
        if (a->kind == Expr::Star) continue;
        args.push_back(evalExpr(a.get(), sc));
      }
      return callFunction(e, e->op, args, sc);
    }
    case Expr::Star: case Expr::TableStar:
      throw SqlError("near \"*\": syntax error", e->start);
  }
  return Value::Null();
}

std::string exprToString(const Expr* e) {
  (void)e;
  return "";
}

std::string quoteValue(const Value& v) {
  switch (v.t) {
    case VT::Null: return "NULL";
    case VT::Int: return std::to_string(v.i);
    case VT::Real: {
      if (std::isinf(v.r)) return v.r > 0 ? "9.0e+999" : "-9.0e+999";
      return formatDoubleQuote(v.r);
    }
    case VT::Text: return sqlQuoteString(v.s);
    case VT::Blob: return "X'" + blobToHex(v.s) + "'";
  }
  return "NULL";
}
