static int collId(const std::string& name) {
  if (name.empty() || nameEq(name, "BINARY")) return 0;
  if (nameEq(name, "NOCASE")) return 1;
  if (nameEq(name, "RTRIM")) return 2;
  return 0;
}

static bool isNumericAff(Aff a) { return a == Aff::Integer || a == Aff::Real || a == Aff::Numeric; }

// Apply comparison affinity conversions
static void applyCompareAffinity(Value& l, Value& r, Aff al, Aff ar) {
  if (isNumericAff(al) && !isNumericAff(ar)) {
    if (r.t == VT::Text) r = textToNumericIfPossible(r, true);
  } else if (isNumericAff(ar) && !isNumericAff(al)) {
    if (l.t == VT::Text) l = textToNumericIfPossible(l, true);
  } else if (al == Aff::Text && ar == Aff::Blob) {
    if (r.t == VT::Int || r.t == VT::Real) r = Value::Text(r.toText());
  } else if (ar == Aff::Text && al == Aff::Blob) {
    if (l.t == VT::Int || l.t == VT::Real) l = Value::Text(l.toText());
  }
}

Aff Engine::affinityOf(Expr* e, Scope* sc) {
  switch (e->kind) {
    case Expr::Column:
      if (!e->resolved) resolveColumn(e, sc);
      if (e->aliasTarget) return affinityOf(e->aliasTarget.get(), sc);
      return e->colAff;
    case Expr::Cast: return affinityFromType(e->castType);
    case Expr::Collate: return affinityOf(e->args[0].get(), sc);
    case Expr::Unary: if (e->op == "()") return affinityOf(e->args[0].get(), sc); return Aff::Blob;
    case Expr::Subquery: {
      // affinity of first result column
      if (e->sub && !e->sub->cores.empty()) {
        auto& core = e->sub->cores[0];
        if (!core->isValues && core->cols.size() == 1 && core->bind) {
          // approximated via bound info in select.cpp
        }
      }
      return Aff::Blob;
    }
    default: return Aff::Blob;
  }
}

std::string Engine::collationFor(Expr* e, Scope* sc) {
  switch (e->kind) {
    case Expr::Collate: return e->collate;
    case Expr::Column:
      if (!e->resolved) resolveColumn(e, sc);
      if (e->aliasTarget) return collationFor(e->aliasTarget.get(), sc);
      return e->colCollate;
    case Expr::Unary: if (e->op == "()") return collationFor(e->args[0].get(), sc); return "";
    case Expr::Func:
      // functions like lower()/upper()/trim/substr propagate collation of first arg? SQLite: no (except for some)
      return "";
    default: return "";
  }
}

static void checkCollation(Engine* eng, const std::string& name, int off) {
  if (name.empty() || nameEq(name, "BINARY") || nameEq(name, "NOCASE") || nameEq(name, "RTRIM")) return;
  if (eng->collationNames.count(lowerStr(name))) return;
  throw SqlError("no such collation sequence: " + name, off);
}

// Determine collation for binary comparison: left explicit COLLATE wins, then right explicit, then left column, then right.
static std::string compareCollation(Engine* eng, Expr* l, Expr* r, Scope* sc) {
  auto explicitColl = [&](Expr* e) -> std::string {
    Expr* x = e;
    while (x) {
      if (x->kind == Expr::Collate) return x->collate;
      if (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
      else break;
    }
    return "";
  };
  std::string c = explicitColl(l);
  if (!c.empty()) return c;
  c = explicitColl(r);
  if (!c.empty()) return c;
  c = eng->collationFor(l, sc);
  if (!c.empty()) return c;
  return eng->collationFor(r, sc);
}

void Engine::resolveColumn(Expr* e, Scope* sc) {
  // Search scopes from innermost outward
  int depth = 0;
  std::string want = e->column;
  bool isRowidName = nameEq(want, "rowid") || nameEq(want, "oid") || nameEq(want, "_rowid_");
  for (Scope* s = sc; s; s = s->parent, depth++) {
    int found = -1, foundCol = -1; bool foundRowid = false; int nFound = 0;
    bool anyTableMatch = false;
    for (size_t ci = 0; ci < s->cursors.size(); ci++) {
      Cursor* c = s->cursors[ci];
      if (!e->table.empty()) {
        if (!nameEq(e->table, c->name)) {
          // also allow matching the underlying table name when no alias was given? SQLite: alias replaces name
          continue;
        }
        if (!e->schema.empty() && !nameEq(e->schema, c->schemaName) && !(nameEq(e->schema, "temp") && c->schemaName == "temp")) continue;
        anyTableMatch = true;
      }
      for (size_t k = 0; k < c->colNames.size(); k++) {
        if (nameEq(c->colNames[k], want)) {
          if (e->table.empty() && k < c->hiddenForStar.size() && c->hiddenForStar[k]) continue;
          if (found == (int)ci && foundCol >= 0) continue;  // duplicate name within same cursor: first wins
          if (found >= 0 && found != (int)ci) { nFound++; }
          else nFound++;
          if (found < 0) { found = (int)ci; foundCol = (int)k; }
          break;
        }
      }
    }
    if (nFound == 0 && isRowidName) {
      for (size_t ci = 0; ci < s->cursors.size(); ci++) {
        Cursor* c = s->cursors[ci];
        if (!e->table.empty() && !nameEq(e->table, c->name)) continue;
        if (c->hasRowid) { if (found < 0) { found = (int)ci; foundRowid = true; } nFound++; }
      }
      if (nFound > 1 && e->table.empty()) nFound = 1;  // ambiguous rowid resolves to first (sqlite behavior)
    }
    if (nFound > 1) {
      std::string nm = e->column;
      if (!e->table.empty()) {
        Cursor* c = s->cursors[found];
        nm = (c->schemaName.empty() ? "main" : c->schemaName) + "." + c->name + "." + e->column;
      }
      throw SqlError("ambiguous column name: " + nm, e->start);
    }
    if (nFound == 1) {
      e->resolved = true; e->depth = depth; e->srcIdx = found;
      Cursor* c = s->cursors[found];
      if (foundRowid) {
        e->isRowid = true; e->colIdx = c->rowidCol; e->colAff = Aff::Integer; e->colCollate = "";
      } else {
        e->colIdx = foundCol;
        e->colAff = foundCol < (int)c->affs.size() ? c->affs[foundCol] : Aff::Blob;
        e->colCollate = foundCol < (int)c->colls.size() ? c->colls[foundCol] : "";
        if (c->rowidCol == foundCol && c->hasRowid && c->table) e->isRowid = true;
      }
      return;
    }
    // alias resolution
    if (s->allowAliases && s->aliases && e->table.empty()) {
      for (size_t k = 0; k < s->aliases->size(); k++) {
        const ResultColumn& rc = (*s->aliases)[k];
        if (rc.hasAlias && nameEq(rc.alias, want)) {
          e->resolved = true; e->depth = depth; e->aliasTarget = rc.e; e->aliasIdx = (int)k;
          return;
        }
      }
    }
    (void)anyTableMatch;
  }
  // TRUE / FALSE literals
  if (e->table.empty() && (nameEq(want, "true") || nameEq(want, "false"))) {
    e->resolved = true; e->isTruthLiteral = true; e->lit = Value::Int(nameEq(want, "true") ? 1 : 0);
    return;
  }
  // double-quoted string fallback
  if (e->op == "dq" && e->table.empty()) {
    throw SqlError("no such column: \"" + e->column + "\" - should this be a string literal in single-quotes?", e->start);
  }
  std::string full = e->column;
  if (!e->table.empty()) full = e->table + "." + full;
  if (!e->schema.empty()) full = e->schema + "." + full;
  throw SqlError("no such column: " + full, e->start);
}

static Scope* scopeAt(Scope* sc, int depth) {
  Scope* s = sc;
  for (int k = 0; k < depth && s; k++) s = s->parent;
  return s;
}

Value Engine::eval(const ExprP& e, Scope* sc) { return evalExpr(e.get(), sc); }

static Value arith(const std::string& op, const Value& a0, const Value& b0, int off) {
  if (a0.isNull() || b0.isNull()) return Value::Null();
  Value a = numericValue(a0), b = numericValue(b0);
  if (op == "%") {
    int64_t ia = a.t == VT::Int ? a.i : a.toInt();
    int64_t ib = b.t == VT::Int ? b.i : b.toInt();
    if (ib == 0) return Value::Null();
    int64_t r;
    if (ib == -1) r = 0; else r = ia % ib;
    if (a.t == VT::Real || b.t == VT::Real) return Value::Real((double)r);
    return Value::Int(r);
  }
  if (a.t == VT::Int && b.t == VT::Int) {
    int64_t x = a.i, y = b.i, r;
    if (op == "+") { if (!__builtin_add_overflow(x, y, &r)) return Value::Int(r); }
    else if (op == "-") { if (!__builtin_sub_overflow(x, y, &r)) return Value::Int(r); }
    else if (op == "*") { if (!__builtin_mul_overflow(x, y, &r)) return Value::Int(r); }
    else if (op == "/") {
      if (y == 0) return Value::Null();
      if (!(x == INT64_MIN && y == -1)) return Value::Int(x / y);
    }
    // overflow: fall through to real
  }
  double x = a.t == VT::Int ? (double)a.i : a.r;
  double y = b.t == VT::Int ? (double)b.i : b.r;
  double r;
  if (op == "+") r = x + y;
  else if (op == "-") r = x - y;
  else if (op == "*") r = x * y;
  else { if (y == 0.0) return Value::Null(); r = x / y; }
  if (std::isnan(r)) return Value::Null();
  return Value::Real(r);
}

static Value bitwise(const std::string& op, const Value& a0, const Value& b0) {
  if (a0.isNull() || b0.isNull()) return Value::Null();
  Value a = numericValue(a0), b = numericValue(b0);
  int64_t x = a.t == VT::Int ? a.i : a.toInt();
  int64_t y = b.t == VT::Int ? b.i : b.toInt();
  if (op == "&") return Value::Int(x & y);
  if (op == "|") return Value::Int(x | y);
  bool left = op == "<<";
  int64_t iB = y;
  if (iB < 0) { left = !left; iB = iB > -64 ? -iB : 64; }
  if (iB >= 64) return Value::Int((x >= 0 || left) ? 0 : -1);
  uint64_t uA; memcpy(&uA, &x, 8);
  if (left) uA <<= iB;
  else { uA >>= iB; if (x < 0) uA |= (~0ULL) << (64 - iB); }
  int64_t r; memcpy(&r, &uA, 8);
  return Value::Int(r);
}

bool patternLike(const std::string& pattern, const std::string& str, int esc, bool caseSensitive) {
  // Standard SQLite LIKE: % matches any sequence, _ matches single char; case-insensitive for ASCII
  size_t pi = 0, si = 0;
  const std::string& P = pattern; const std::string& S = str;
  auto fold = [&](int c) -> int { if (!caseSensitive && c >= 'A' && c <= 'Z') return c + 32; return c; };
  // recursive with memo-less backtracking
  std::function<bool(size_t, size_t)> rec = [&](size_t p, size_t s) -> bool {
    while (p < P.size()) {
      size_t pp = p;
      int pc = utf8Decode(P, pp);
      if (esc >= 0 && pc == esc) {
        if (pp >= P.size()) return false;
        int lit = utf8Decode(P, pp);
        if (s >= S.size()) return false;
        size_t ss = s; int sc = utf8Decode(S, ss);
        if (fold(lit) != fold(sc)) return false;
        p = pp; s = ss; continue;
      }
      if (pc == '%') {
        // collapse multiple % and _
        while (pp < P.size()) {
          size_t q = pp; int c2 = utf8Decode(P, q);
          if (c2 == '%') { pp = q; }
          else if (c2 == '_') { if (s >= S.size()) return false; utf8Decode(S, s); pp = q; }
          else break;
        }
        if (pp >= P.size()) return true;
        // try all positions
        size_t t = s;
        while (true) {
          if (rec(pp, t)) return true;
          if (t >= S.size()) return false;
          utf8Decode(S, t);
        }
      }
      if (pc == '_') {
        if (s >= S.size()) return false;
        utf8Decode(S, s); p = pp; continue;
      }
      if (s >= S.size()) return false;
      size_t ss = s; int sc = utf8Decode(S, ss);
      if (fold(pc) != fold(sc)) return false;
      p = pp; s = ss;
    }
    return s >= S.size();
  };
  (void)pi; (void)si;
  return rec(0, 0);
}

bool patternGlob(const std::string& P, const std::string& S) {
  std::function<bool(size_t, size_t)> rec = [&](size_t p, size_t s) -> bool {
    while (p < P.size()) {
      size_t pp = p;
      int pc = utf8Decode(P, pp);
      if (pc == '*') {
        while (pp < P.size()) {
          size_t q = pp; int c2 = utf8Decode(P, q);
          if (c2 == '*') pp = q;
          else if (c2 == '?') { if (s >= S.size()) return false; utf8Decode(S, s); pp = q; }
          else break;
        }
        if (pp >= P.size()) return true;
        size_t t = s;
        while (true) {
          if (rec(pp, t)) return true;
          if (t >= S.size()) return false;
          utf8Decode(S, t);
        }
      }
      if (pc == '?') { if (s >= S.size()) return false; utf8Decode(S, s); p = pp; continue; }
      if (pc == '[') {
        if (s >= S.size()) return false;
        size_t ss = s; int sc = utf8Decode(S, ss);
        bool invert = false, matched = false;
        size_t q = pp;
        if (q < P.size() && P[q] == '^') { invert = true; q++; }
        int prior = 0; bool first = true;
        if (q < P.size() && P[q] == ']') { if (sc == ']') matched = true; prior = ']'; q++; first = false; }
        while (q < P.size()) {
          size_t q2 = q; int c = utf8Decode(P, q2);
          if (c == ']' ) { q = q2; break; }
          if (c == '-' && !first && q2 < P.size() && P[q2] != ']') {
            size_t q3 = q2; int hi = utf8Decode(P, q3);
            if (sc >= prior && sc <= hi) matched = true;
            q = q3; prior = 0; first = false; continue;
          }
          if (c == sc) matched = true;
          prior = c; q = q2; first = false;
        }
        if (q > P.size()) return false;
        if (matched == invert) return false;
        p = q; s = ss; continue;
      }
      if (s >= S.size()) return false;
      size_t ss = s; int sc = utf8Decode(S, ss);
      if (pc != sc) return false;
      p = pp; s = ss;
    }
    return s >= S.size();
  };
  return rec(0, 0);
}

Value castValue(const Value& v, const std::string& type) {
  if (v.isNull()) return v;
  Aff a = affinityFromType(type);
  switch (a) {
    case Aff::Text:
      if (v.t == VT::Blob) return Value::Text(v.s);
      return Value::Text(v.toText());
    case Aff::Blob:
      if (v.t == VT::Text) return Value::Blob(v.s);
      if (v.t == VT::Blob) return v;
      return Value::Blob(v.toText());
    case Aff::Integer: {
      if (v.t == VT::Int) return v;
      if (v.t == VT::Real) {
        if (std::isnan(v.r)) return Value::Int(0);
        if (v.r <= -9223372036854775808.0) return Value::Int(INT64_MIN);
        if (v.r >= 9223372036854775807.0) return Value::Int(INT64_MAX);
        return Value::Int((int64_t)v.r);
      }
      return Value::Int(v.toInt());
    }
    case Aff::Real: {
      if (v.t == VT::Real) return v;
      if (v.t == VT::Int) return Value::Real((double)v.i);
      return Value::Real(v.toReal());
    }
    case Aff::Numeric:
      return numerifyValue(v);
  }
  return v;
}

static Value compareOp(const std::string& op, int c) {
  bool r;
  if (op == "=" || op == "==") r = c == 0;
  else if (op == "!=" || op == "<>") r = c != 0;
  else if (op == "<") r = c < 0;
  else if (op == "<=") r = c <= 0;
  else if (op == ">") r = c > 0;
  else r = c >= 0;
  return Value::Bool(r);
}

Value Engine::evalExpr(Expr* e, Scope* sc) {
  switch (e->kind) {
    case Expr::Literal: return e->lit;
    case Expr::Param: {
      auto it = params.find(e->paramName);
      if (it != params.end()) return it->second;
      if (e->paramName == "?" ) {
        // positional: use index
        auto it2 = params.find("?" + std::to_string(e->paramIdx));
        if (it2 != params.end()) return it2->second;
      }
      return Value::Null();
    }
    case Expr::Column: {
      if (!e->resolved) resolveColumn(e, sc);
      if (e->isTruthLiteral) return e->lit;
      if (e->aliasTarget) {
        Scope* s = scopeAt(sc, e->depth);
        return evalExpr(e->aliasTarget.get(), s);
      }
      Scope* s = scopeAt(sc, e->depth);
      if (!s || e->srcIdx >= (int)s->cursors.size()) throw SqlError("internal: bad column reference");
      Cursor* c = s->cursors[e->srcIdx];
      if (c->isNullRow) return Value::Null();
      if (e->isRowid) {
        if (c->rowidCol >= 0 && c->row && c->rowidCol < (int)c->row->size() && !c->table) return (*c->row)[c->rowidCol];
        return Value::Int(c->rowid);
      }
      if (!c->row) return Value::Null();
      if (e->colIdx < (int)c->row->size()) return (*c->row)[e->colIdx];
      return Value::Null();
    }
    case Expr::Unary: {
      if (e->op == "()") return evalExpr(e->args[0].get(), sc);
      Value v = evalExpr(e->args[0].get(), sc);
      if (e->op == "+") return v;
      if (v.isNull()) return v;
      if (e->op == "-") {
        Value n = numericValue(v);
        if (n.t == VT::Int) { if (n.i == INT64_MIN) return Value::Real(9223372036854775808.0); return Value::Int(-n.i); }
        return Value::Real(-n.r);
      }
      if (e->op == "~") { Value n = numericValue(v); return Value::Int(~(n.t == VT::Int ? n.i : n.toInt())); }
      throw SqlError("unknown unary operator");
    }
    case Expr::Not: {
      Value v = evalExpr(e->args[0].get(), sc);
      bool isnull; bool t = v.truthy(&isnull);
      if (isnull) return Value::Null();
      return Value::Bool(!t);
    }
    case Expr::And: {
      Value a = evalExpr(e->args[0].get(), sc);
      bool an; bool at = a.truthy(&an);
      if (!an && !at) return Value::Bool(false);
      Value b = evalExpr(e->args[1].get(), sc);
      bool bn; bool bt = b.truthy(&bn);
      if (!bn && !bt) return Value::Bool(false);
      if (an || bn) return Value::Null();
      return Value::Bool(true);
    }
    case Expr::Or: {
      Value a = evalExpr(e->args[0].get(), sc);
      bool an; bool at = a.truthy(&an);
      if (!an && at) return Value::Bool(true);
      Value b = evalExpr(e->args[1].get(), sc);
      bool bn; bool bt = b.truthy(&bn);
      if (!bn && bt) return Value::Bool(true);
      if (an || bn) return Value::Null();
      return Value::Bool(false);
    }
    case Expr::Binary: {
      const std::string& op = e->op;
      if (op == "||") {
        Value a = evalExpr(e->args[0].get(), sc);
        Value b = evalExpr(e->args[1].get(), sc);
        if (a.isNull() || b.isNull()) return Value::Null();
        return Value::Text(a.toText() + b.toText());
      }
      if (op == "+" || op == "-" || op == "*" || op == "/" || op == "%") {
        Value a = evalExpr(e->args[0].get(), sc);
        Value b = evalExpr(e->args[1].get(), sc);
        return arith(op, a, b, e->start);
      }
      if (op == "&" || op == "|" || op == "<<" || op == ">>") {
        Value a = evalExpr(e->args[0].get(), sc);
        Value b = evalExpr(e->args[1].get(), sc);
        return bitwise(op, a, b);
      }
      if (op == "->" || op == "->>") {
        std::vector<Value> args{evalExpr(e->args[0].get(), sc), evalExpr(e->args[1].get(), sc)};
        bool handled = false;
        Value r = callJsonFunction(op == "->" ? "->" : "->>", args, this, handled);
        return r;
      }
      // comparison
      Expr* le = e->args[0].get(); Expr* re = e->args[1].get();
      if (le->kind == Expr::Row || re->kind == Expr::Row || (le->kind == Expr::Subquery && re->kind == Expr::Subquery)) {
        // row value comparison
        std::vector<Value> lv, rv;
        auto getRow = [&](Expr* x, std::vector<Value>& out) {
          if (x->kind == Expr::Row) { for (auto& a : x->args) out.push_back(evalExpr(a.get(), sc)); }
          else if (x->kind == Expr::Subquery) {
            std::vector<Row> rows; std::vector<std::string> names;
            Scope inner; inner.parent = sc;
            materializeSelect(x->sub, sc, rows, names);
            if (rows.empty()) { for (size_t k = 0; k < names.size(); k++) out.push_back(Value::Null()); }
            else out = rows[0];
          } else out.push_back(evalExpr(x, sc));
        };
        getRow(le, lv); getRow(re, rv);
        if (lv.size() != rv.size()) throw SqlError("row value misused", e->start);
        int c = 0; bool anyNull = false;
        for (size_t k = 0; k < lv.size(); k++) {
          if (lv[k].isNull() || rv[k].isNull()) { anyNull = true; if (op == "=" || op == "==" || op == "!=" || op == "<>") return Value::Null(); continue; }
          Value a = lv[k], b = rv[k];
          Aff al = le->kind == Expr::Row ? affinityOf(le->args[k].get(), sc) : Aff::Blob;
          Aff ar = re->kind == Expr::Row ? affinityOf(re->args[k].get(), sc) : Aff::Blob;
          applyCompareAffinity(a, b, al, ar);
          c = compareValues(a, b, 0);
          if (c != 0) break;
          if (anyNull) return Value::Null();
        }
        if (anyNull && c == 0) return Value::Null();
        return compareOp(op, c);
      }
      Value a = evalExpr(le, sc);
      Value b = evalExpr(re, sc);
      if (a.isNull() || b.isNull()) return Value::Null();
      Aff al = affinityOf(le, sc), ar = affinityOf(re, sc);
      applyCompareAffinity(a, b, al, ar);
      std::string coll = compareCollation(this, le, re, sc);
      checkCollation(this, coll, e->start);
      int c = compareValues(a, b, collId(coll));
      return compareOp(op, c);
    }
    case Expr::Is: case Expr::IsNot: {
      Expr* le = e->args[0].get(); Expr* re = e->args[1].get();
      // IS TRUE / IS FALSE
      if (re->kind == Expr::Column && re->table.empty()) {
        if (!re->resolved) { try { resolveColumn(re, sc); } catch (SqlError&) { throw; } }
        if (re->isTruthLiteral) {
          Value a = evalExpr(le, sc);
          bool isnull; bool t = a.truthy(&isnull);
          bool want = re->lit.i != 0;
          bool r = !isnull && t == want;
          if (e->kind == Expr::IsNot) r = !r;
          return Value::Bool(r);
        }
      }
      Value a = evalExpr(le, sc);
      Value b = evalExpr(re, sc);
      bool eq;
      if (a.isNull() || b.isNull()) eq = a.isNull() && b.isNull();
      else {
        Aff al = affinityOf(le, sc), ar = affinityOf(re, sc);
        applyCompareAffinity(a, b, al, ar);
        std::string coll = compareCollation(this, le, re, sc);
        eq = compareValues(a, b, collId(coll)) == 0;
      }
      return Value::Bool(e->kind == Expr::Is ? eq : !eq);
    }
    case Expr::IsNull: { Value a = evalExpr(e->args[0].get(), sc); return Value::Bool(a.isNull()); }
    case Expr::NotNull: { Value a = evalExpr(e->args[0].get(), sc); return Value::Bool(!a.isNull()); }
    case Expr::Between: {
      Value x = evalExpr(e->args[0].get(), sc);
      Value lo = evalExpr(e->args[1].get(), sc);
      Value hi = evalExpr(e->args[2].get(), sc);
      Aff ax = affinityOf(e->args[0].get(), sc);
      std::string coll = compareCollation(this, e->args[0].get(), e->args[1].get(), sc);
      int cid = collId(coll);
      // x >= lo AND x <= hi with NULL semantics
      Value r1, r2;
      if (x.isNull() || lo.isNull()) r1 = Value::Null();
      else { Value a = x, b = lo; applyCompareAffinity(a, b, ax, affinityOf(e->args[1].get(), sc)); r1 = Value::Bool(compareValues(a, b, cid) >= 0); }
      if (x.isNull() || hi.isNull()) r2 = Value::Null();
      else { Value a = x, b = hi; applyCompareAffinity(a, b, ax, affinityOf(e->args[2].get(), sc)); r2 = Value::Bool(compareValues(a, b, cid) <= 0); }
      // AND
      Value res;
      if ((!r1.isNull() && r1.i == 0) || (!r2.isNull() && r2.i == 0)) res = Value::Bool(false);
      else if (r1.isNull() || r2.isNull()) res = Value::Null();
      else res = Value::Bool(true);
      if (e->negate && !res.isNull()) res = Value::Bool(!res.i);
      return res;
    }
    case Expr::In: {
      Expr* le = e->args[0].get();
      std::vector<Value> lv;
      std::vector<Aff> laff;
      if (le->kind == Expr::Row) { for (auto& a : le->args) { lv.push_back(evalExpr(a.get(), sc)); laff.push_back(affinityOf(a.get(), sc)); } }
      else { lv.push_back(evalExpr(le, sc)); laff.push_back(affinityOf(le, sc)); }
      std::vector<Row> items;
      std::vector<Aff> raff(lv.size(), Aff::Blob);
      std::string coll = collationFor(le, sc);
      {
        Expr* x = le; while (x && x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
        if (x && x->kind == Expr::Collate) coll = x->collate;
      }
      if (e->sub) {
        std::vector<std::string> names;
        materializeSelect(e->sub, sc, items, names);
        if (names.size() != lv.size()) throw SqlError("sub-select returns " + std::to_string(names.size()) + " columns - expected " + std::to_string(lv.size()), e->start);
      } else if (!e->table.empty()) {
        // IN table-name
        TableP t = resolveTable(e->schema, e->table, nullptr, e->start);
        if (t->cols.size() != 1 && lv.size() == 1) {
          throw SqlError("sub-select returns " + std::to_string(t->cols.size()) + " columns - expected 1", e->start);
        }
        for (auto& kv : t->rows) items.push_back(kv.second);
        raff[0] = t->cols[0].aff;
      } else {
        if (e->args.size() == 1) return Value::Bool(e->negate ? true : false);
        for (size_t k = 1; k < e->args.size(); k++) items.push_back(Row{evalExpr(e->args[k].get(), sc)});
      }
      int cid = collId(coll);
      bool anyNullRow = false;
      for (auto& lvv : lv) if (lvv.isNull()) anyNullRow = true;
      if (anyNullRow && items.empty()) return Value::Bool(e->negate);
      bool found = false; bool sawNull = false;
      for (auto& it : items) {
        bool eq = true; bool nul = false;
        for (size_t k = 0; k < lv.size(); k++) {
          if (lv[k].isNull() || it[k].isNull()) { nul = true; continue; }
          Value a = lv[k], b = it[k];
          applyCompareAffinity(a, b, laff[k], raff[k]);
          if (compareValues(a, b, cid) != 0) { eq = false; break; }
        }
        if (eq && nul) { sawNull = true; continue; }
        if (eq) { found = true; break; }
      }
      if (found) return Value::Bool(!e->negate);
      if (sawNull) return Value::Null();
      return Value::Bool(e->negate);
    }
    case Expr::Like: {
      Value a = evalExpr(e->args[0].get(), sc);
      Value b = evalExpr(e->args[1].get(), sc);
      if (e->op == "LIKE") {
        int esc = -1;
        if (e->args.size() > 2) {
          Value ev = evalExpr(e->args[2].get(), sc);
          if (ev.isNull()) return Value::Null();
          std::string es = ev.toText();
          if (utf8Len(es) != 1) throw SqlError("ESCAPE expression must be a single character");
          size_t p0 = 0; esc = utf8Decode(es, p0);
        }
        if (a.isNull() || b.isNull()) return Value::Null();
        std::string pat = b.toText(), str = a.toText();
        if (pat.size() > 50000) throw SqlError("LIKE or GLOB pattern too complex");
        bool r = patternLike(pat, str, esc, db.caseSensitiveLike);
        return Value::Bool(e->negate ? !r : r);
      }
      if (e->op == "GLOB") {
        if (a.isNull() || b.isNull()) return Value::Null();
        bool r = patternGlob(b.toText(), a.toText());
        return Value::Bool(e->negate ? !r : r);
      }
      if (e->op == "REGEXP") throw SqlError("no such function: REGEXP", e->start);
      throw SqlError("unable to use function MATCH in the requested context", e->start);
    }
    case Expr::Case: {
      bool hasBase = e->args[0] != nullptr;
      Value base;
      if (hasBase) base = evalExpr(e->args[0].get(), sc);
      for (size_t k = 1; k + 1 < e->args.size(); k += 2) {
        if (hasBase) {
          Value w = evalExpr(e->args[k].get(), sc);
          if (base.isNull() || w.isNull()) continue;
          Value a = base, b = w;
          applyCompareAffinity(a, b, affinityOf(e->args[0].get(), sc), affinityOf(e->args[k].get(), sc));
          std::string coll = compareCollation(this, e->args[0].get(), e->args[k].get(), sc);
          if (compareValues(a, b, collId(coll)) == 0) return evalExpr(e->args[k + 1].get(), sc);
        } else {
          Value w = evalExpr(e->args[k].get(), sc);
          bool nul; if (w.truthy(&nul) && !nul) return evalExpr(e->args[k + 1].get(), sc);
        }
      }
      if (e->elseExpr) return evalExpr(e->elseExpr.get(), sc);
      return Value::Null();
    }
    case Expr::Cast: {
      Value v = evalExpr(e->args[0].get(), sc);
      return castValue(v, e->castType);
    }
    case Expr::Collate: {
      checkCollation(this, e->collate, e->start);
      return evalExpr(e->args[0].get(), sc);
    }
    case Expr::Exists: {
      std::vector<Row> rows; std::vector<std::string> names;
      materializeSelect(e->sub, sc, rows, names);
      return Value::Bool(!rows.empty());
    }
    case Expr::Subquery: {
      std::vector<Row> rows; std::vector<std::string> names;
      // Limit to one row for efficiency: materialize fully for simplicity
      materializeSelect(e->sub, sc, rows, names);
      if (names.size() != 1) throw SqlError("sub-select returns " + std::to_string(names.size()) + " columns - expected 1", e->start);
      if (rows.empty()) return Value::Null();
      return rows[0][0];
    }
    case Expr::Row: {
      if (e->args.size() == 1) return evalExpr(e->args[0].get(), sc);
      throw SqlError("row value misused", e->start);
    }
    case Expr::Raise: {
      if (e->op == "IGNORE") throw IgnoreSignal();
      int code = 19;
      if (e->op == "ROLLBACK") code = 1001; else if (e->op == "FAIL") code = 1003; else code = 1002;
      throw SqlError(e->lit.toText(), -1, code);
    }
    case Expr::Func: {
      // aggregate / window values precomputed?
      if (sc && sc->winValues && e->over) {
        auto it = sc->winValues->find(e);
        if (it != sc->winValues->end()) return it->second;
      }
      if (e->isAggregate && !e->over) {
        // find aggregate value in scope chain
        for (Scope* s = sc; s; s = s->parent) {
          if (s->aggIds) {
            auto it = s->aggIds->find(e);
            if (it != s->aggIds->end() && s->aggValues && it->second < (int)s->aggValues->size()) return (*s->aggValues)[it->second];
          }
        }
        throw SqlError("misuse of aggregate: " + e->op + "()", e->start);
      }
      std::vector<Value> args;
      args.reserve(e->args.size());
      for (auto& a : e->args) {
        if (a->kind == Expr::Star) continue;
        args.push_back(evalExpr(a.get(), sc));
      }
      return callFunction(e, e->op, args, sc);
    }
    case Expr::Star: case Expr::TableStar:
      throw SqlError("near \"*\": syntax error", e->start);
  }
  return Value::Null();
}

std::string exprToString(const Expr* e) {
  (void)e;
  return "";
}

std::string quoteValue(const Value& v) {
  switch (v.t) {
    case VT::Null: return "NULL";
    case VT::Int: return std::to_string(v.i);
    case VT::Real: {
      if (std::isinf(v.r)) return v.r > 0 ? "9.0e+999" : "-9.0e+999";
      return formatDoubleQuote(v.r);
    }
    case VT::Text: return sqlQuoteString(v.s);
    case VT::Blob: return "X'" + blobToHex(v.s) + "'";
  }
  return "NULL";
}
