int64_t Engine::nextRandom() {
  // xorshift128+
  uint64_t s1 = randState[0], s0 = randState[1];
  randState[0] = s0;
  s1 ^= s1 << 23; s1 ^= s1 >> 17; s1 ^= s0; s1 ^= s0 >> 26;
  randState[1] = s1;
  return (int64_t)(randState[0] + randState[1]);
}

static std::string substrUtf8(const std::string& s, int64_t p1, int64_t p2, bool hasLen, bool isBlob) {
  // SQLite semantics
  int64_t len;
  if (isBlob) len = (int64_t)s.size(); else len = utf8Len(s);
  if (p1 < 0) { p1 += len; if (p1 < 0) { if (hasLen) p2 += p1; p1 = 0; } }
  else if (p1 > 0) p1--;
  else if (hasLen) { // p1==0
    p2 -= 1; // (p2 may become negative); sqlite: p1 = 0, p2-- when p1==0? Actually substr(x,0,n) returns n-1 chars
    if (p2 < 0) p2 = 0;
  }
  int64_t end;
  if (!hasLen) { p2 = len; end = len; }
  else if (p2 < 0) { p2 = -p2; if (p1 >= p2) { p1 = p1 - p2; p2 = p2; } else { p2 = p1; p1 = 0; } end = p1 + p2; }
  else end = p1 + p2;
  if (p1 >= len) return "";
  if (end > len) end = len;
  if (end <= p1) return "";
  if (isBlob) return s.substr(p1, end - p1);
  // utf8 char indexes
  size_t bi = 0; int64_t ci = 0;
  while (bi < s.size() && ci < p1) { utf8Decode(s, bi); ci++; }
  size_t bs = bi;
  while (bi < s.size() && ci < end) { utf8Decode(s, bi); ci++; }
  return s.substr(bs, bi - bs);
}

static std::string trimChars(const std::string& s, const std::string& chars, bool left, bool right) {
  // chars: set of UTF-8 characters
  std::vector<std::string> set;
  size_t p = 0;
  while (p < chars.size()) { size_t q = p; utf8Decode(chars, q); set.push_back(chars.substr(p, q - p)); p = q; }
  size_t start = 0, end = s.size();
  auto matchAt = [&](size_t pos, bool fromEnd) -> size_t {
    for (auto& c : set) {
      if (c.empty()) continue;
      if (!fromEnd) { if (s.compare(pos, c.size(), c) == 0) return c.size(); }
      else { if (pos >= c.size() && s.compare(pos - c.size(), c.size(), c) == 0) return c.size(); }
    }
    return 0;
  };
  if (left) { while (start < end) { size_t m = matchAt(start, false); if (!m) break; start += m; } }
  if (right) { while (end > start) { size_t m = matchAt(end, true); if (!m) break; end -= m; } }
  return s.substr(start, end - start);
}

std::string formatPrintf(const std::string& fmt, const std::vector<Value>& args, size_t argStart) {
  std::string out;
  size_t ai = argStart;
  auto nextArg = [&]() -> Value { if (ai < args.size()) return args[ai++]; return Value::Null(); };
  for (size_t i = 0; i < fmt.size(); i++) {
    char c = fmt[i];
    if (c != '%') { out.push_back(c); continue; }
    i++;
    if (i >= fmt.size()) break;
    if (fmt[i] == '%') { out.push_back('%'); continue; }
    bool fMinus = false, fPlus = false, fSpace = false, fZero = false, fAlt = false, fAlt2 = false, fComma = false;
    while (i < fmt.size()) {
      char f = fmt[i];
      if (f == '-') fMinus = true; else if (f == '+') fPlus = true; else if (f == ' ') fSpace = true;
      else if (f == '0') fZero = true; else if (f == '#') fAlt = true; else if (f == '!') fAlt2 = true; else if (f == ',') fComma = true;
      else break;
      i++;
    }
    int width = 0; bool hasWidth = false;
    if (i < fmt.size() && fmt[i] == '*') { Value w = nextArg(); width = (int)w.toInt(); if (width < 0) { fMinus = true; width = -width; } hasWidth = true; i++; }
    else while (i < fmt.size() && isdigit((unsigned char)fmt[i])) { width = width * 10 + (fmt[i] - '0'); hasWidth = true; i++; }
    int prec = -1;
    if (i < fmt.size() && fmt[i] == '.') {
      i++; prec = 0;
      if (i < fmt.size() && fmt[i] == '*') { Value p = nextArg(); prec = (int)p.toInt(); if (prec < 0) prec = -1; i++; }
      else while (i < fmt.size() && isdigit((unsigned char)fmt[i])) { prec = prec * 10 + (fmt[i] - '0'); i++; }
    }
    // length modifiers
    while (i < fmt.size() && (fmt[i] == 'l' || fmt[i] == 'h')) i++;
    if (i >= fmt.size()) break;
    char conv = fmt[i];
    std::string body;
    auto pad = [&](std::string s, bool numeric) {
      if (hasWidth && (int)utf8Len(s) < width) {
        int n = width - utf8Len(s);
        if (fMinus) s.append(n, ' ');
        else if (fZero && numeric) {
          size_t signPos = (!s.empty() && (s[0] == '-' || s[0] == '+' || s[0] == ' ')) ? 1 : 0;
          s.insert(signPos, n, '0');
        } else s.insert(0, n, ' ');
      }
      return s;
    };
    switch (conv) {
      case 'd': case 'i': case 'u': case 'x': case 'X': case 'o': {
        Value v = nextArg();
        Value n = v.isNull() ? Value::Int(0) : numericValue(v);
        int64_t iv = n.t == VT::Int ? n.i : n.toInt();
        std::string digits; bool neg = false;
        if (conv == 'd' || conv == 'i') {
          uint64_t u; if (iv < 0) { neg = true; u = (uint64_t)(-(iv + 1)) + 1; } else u = iv;
          digits = std::to_string(u);
        } else {
          uint64_t u = (uint64_t)iv;
          char buf[40];
          if (conv == 'u') snprintf(buf, sizeof buf, "%llu", (unsigned long long)u);
          else if (conv == 'x') snprintf(buf, sizeof buf, "%llx", (unsigned long long)u);
          else if (conv == 'X') snprintf(buf, sizeof buf, "%llX", (unsigned long long)u);
          else snprintf(buf, sizeof buf, "%llo", (unsigned long long)u);
          digits = buf;
        }
        if (prec >= 0 && (int)digits.size() < prec) digits.insert(0, prec - digits.size(), '0');
        if (fComma && (conv == 'd' || conv == 'i')) {
          std::string g; int cnt = 0;
          for (int k = (int)digits.size() - 1; k >= 0; k--) { g.insert(g.begin(), digits[k]); if (++cnt % 3 == 0 && k > 0) g.insert(g.begin(), ','); }
          digits = g;
        }
        std::string prefix;
        if (neg) prefix = "-"; else if (fPlus && (conv == 'd' || conv == 'i')) prefix = "+"; else if (fSpace && (conv == 'd' || conv == 'i')) prefix = " ";
        if (fAlt && (conv == 'x') && iv != 0) prefix += "0x";
        if (fAlt && (conv == 'X') && iv != 0) prefix += "0X";
        if (fAlt && conv == 'o' && digits[0] != '0') prefix += "0";
        body = pad(prefix + digits, prec < 0);
        break;
      }
      case 'f': case 'e': case 'E': case 'g': case 'G': {
        Value v = nextArg();
        double d = v.isNull() ? 0.0 : (numericValue(v).t == VT::Int ? (double)numericValue(v).i : numericValue(v).r);
        if (prec < 0) prec = 6;
        if (prec > 100000) prec = 100000;
        char fbuf[32];
        std::string flags;
        if (fPlus) flags += "+"; if (fSpace) flags += " "; if (fAlt) flags += "#";
        if (std::isinf(d)) {
          body = d < 0 ? "-Inf" : (fPlus ? "+Inf" : "Inf");
          body = pad(body, false);
          break;
        }
        if (std::isnan(d)) { body = pad("NaN", false); break; }
        if (fAlt2 && (conv == 'g' || conv == 'G')) {
          // alternate: like SQLite's %!g -> shortest-ish representation
          std::string s = formatDouble(d);
          body = pad(s, true);
          break;
        }
        snprintf(fbuf, sizeof fbuf, "%%%s.%d%c", flags.c_str(), prec, conv);
        char buf[512];
        snprintf(buf, sizeof buf, fbuf, d);
        std::string s = buf;
        if (fAlt2 && conv == 'f') {
          // ! flag with %f: strip trailing zeros? keep as is
        }
        body = pad(s, true);
        break;
      }
      case 's': case 'z': {
        Value v = nextArg();
        std::string s = v.isNull() ? "" : v.toText();
        if (prec >= 0 && (int)s.size() > prec) s = s.substr(0, prec);
        body = pad(s, false);
        break;
      }
      case 'q': case 'Q': case 'w': {
        Value v = nextArg();
        std::string s;
        if (v.isNull()) { if (conv == 'Q') s = "NULL"; else s = ""; }
        else {
          std::string t = v.toText();
          if (prec >= 0 && (int)t.size() > prec) t = t.substr(0, prec);
          char q = conv == 'w' ? '"' : '\'';
          if (conv == 'Q') s.push_back('\'');
          for (char ch : t) { if (ch == q) { s.push_back(q); s.push_back(q); } else s.push_back(ch); }
          if (conv == 'Q') s.push_back('\'');
        }
        body = pad(s, false);
        break;
      }
      case 'c': {
        Value v = nextArg();
        std::string s;
        if (v.t == VT::Int || v.t == VT::Real) { utf8Append(s, (uint32_t)v.toInt()); }
        else { std::string t = v.toText(); size_t p = 0; if (!t.empty()) { utf8Decode(t, p); s = t.substr(0, p); } }
        if (prec > 1) { std::string r; for (int k = 0; k < prec; k++) r += s; s = r; }
        body = pad(s, false);
        break;
      }
      case 'n': body = ""; break;
      case 'p': { Value v = nextArg(); body = pad(std::to_string(v.toInt()), false); break; }
      case 'r': {
        Value v = nextArg();
        int64_t n = v.toInt();
        std::string s = std::to_string(n);
        int m = (int)(n % 100); if (m < 0) m = -m;
        if (m >= 11 && m <= 13) s += "th"; else if (m % 10 == 1) s += "st"; else if (m % 10 == 2) s += "nd"; else if (m % 10 == 3) s += "rd"; else s += "th";
        body = pad(s, false);
        break;
      }
      default:
        return out; // unknown conversion: stop
    }
    out += body;
  }
  return out;
}

static Value mathFunc1(const std::string& name, const Value& a) {
  if (a.isNull()) return Value::Null();
  Value n = numericValue(a);
  double x = n.t == VT::Int ? (double)n.i : n.r;
  double r;
  if (name == "acos") { if (x < -1 || x > 1) return Value::Null(); r = acos(x); }
  else if (name == "asin") { if (x < -1 || x > 1) return Value::Null(); r = asin(x); }
  else if (name == "atan") r = atan(x);
  else if (name == "acosh") { if (x < 1) return Value::Null(); r = acosh(x); }
  else if (name == "asinh") r = asinh(x);
  else if (name == "atanh") { if (x <= -1 || x >= 1) return Value::Null(); r = atanh(x); }
  else if (name == "cos") r = cos(x);
  else if (name == "sin") r = sin(x);
  else if (name == "tan") r = tan(x);
  else if (name == "cosh") r = cosh(x);
  else if (name == "sinh") r = sinh(x);
  else if (name == "tanh") r = tanh(x);
  else if (name == "exp") r = exp(x);
  else if (name == "ln") { if (x <= 0) return Value::Null(); r = log(x); }
  else if (name == "log10" || name == "log") { if (x <= 0) return Value::Null(); r = log10(x); }
  else if (name == "log2") { if (x <= 0) return Value::Null(); r = log2(x); }
  else if (name == "radians") r = x * M_PI / 180.0;
  else if (name == "degrees") r = x * 180.0 / M_PI;
  else if (name == "sqrt") { if (x < 0) return Value::Null(); r = sqrt(x); }
  else if (name == "ceil" || name == "ceiling") { if (n.t == VT::Int) return n; r = ceil(x); }
  else if (name == "floor") { if (n.t == VT::Int) return n; r = floor(x); }
  else if (name == "trunc") { if (n.t == VT::Int) return n; r = trunc(x); }
  else return Value::Null();
  if (std::isnan(r) || std::isinf(r)) return Value::Null();
  return Value::Real(r);
}

std::string typeNameOfDecl(const std::string& declType) { return declType; }

Value Engine::callFunction(Expr* e, const std::string& name, std::vector<Value>& args, Scope* sc) {
  (void)sc;
  size_t n = args.size();
  auto nullIfAnyNull = [&]() { for (auto& a : args) if (a.isNull()) return true; return false; };
  if (name == "abs") {
    const Value& a = args[0];
    if (a.isNull()) return a;
    if (a.t == VT::Int) { if (a.i == INT64_MIN) throw SqlError("integer overflow"); return Value::Int(a.i < 0 ? -a.i : a.i); }
    if (a.t == VT::Real) return Value::Real(fabs(a.r));
    double d = a.toReal();
    return Value::Real(fabs(d));
  }
  if (name == "typeof") return Value::Text(args[0].typeName());
  if (name == "subtype") return Value::Int(args[0].sub);
  if (name == "length") {
    const Value& a = args[0];
    switch (a.t) {
      case VT::Null: return a;
      case VT::Blob: return Value::Int((int64_t)a.s.size());
      case VT::Text: { int64_t c = 0; for (size_t k = 0; k < a.s.size(); k++) { if (a.s[k] == 0) break; if ((a.s[k] & 0xC0) != 0x80) c++; } return Value::Int(c); }
      default: return Value::Int((int64_t)a.toText().size());
    }
  }
  if (name == "octet_length") {
    const Value& a = args[0];
    if (a.isNull()) return a;
    if (a.t == VT::Text || a.t == VT::Blob) return Value::Int((int64_t)a.s.size());
    return Value::Int((int64_t)a.toText().size());
  }
  if (name == "upper" || name == "lower") {
    if (args[0].isNull()) return args[0];
    std::string s = args[0].toText();
    return Value::Text(name == "upper" ? utf8Upper(s) : utf8Lower(s));
  }
  if (name == "substr" || name == "substring") {
    const Value& a = args[0];
    if (a.isNull()) return a;
    if (args[1].isNull() || (n > 2 && args[2].isNull())) return Value::Null();
    bool isBlob = a.t == VT::Blob;
    std::string s = a.t == VT::Blob ? a.s : a.toText();
    int64_t p1 = args[1].toInt();
    int64_t p2 = n > 2 ? args[2].toInt() : 0;
    // SQLite substr semantics
    int64_t len = isBlob ? (int64_t)s.size() : utf8Len(s);
    if (p1 < 0) { p1 += len; if (p1 < 0) { if (n > 2) p2 += p1; p1 = 0; } else {} }
    else if (p1 > 0) p1--;
    else if (n > 2) { if (p2 > 0) p2--; }
    int64_t cnt;
    if (n <= 2) cnt = len - p1;
    else if (p2 < 0) { cnt = -p2; if (cnt > p1) cnt = p1; p1 -= cnt; }
    else cnt = p2;
    if (cnt < 0) cnt = 0;
    if (p1 > len) { p1 = len; }
    if (p1 + cnt > len) cnt = len - p1;
    if (cnt <= 0) return isBlob ? Value::Blob("") : Value::Text("");
    if (isBlob) return Value::Blob(s.substr(p1, cnt));
    size_t bi = 0; int64_t ci = 0;
    while (bi < s.size() && ci < p1) { utf8Decode(s, bi); ci++; }
    size_t bs = bi; int64_t taken = 0;
    while (bi < s.size() && taken < cnt) { utf8Decode(s, bi); taken++; }
    return Value::Text(s.substr(bs, bi - bs));
  }
  if (name == "instr") {
    if (args[0].isNull() || args[1].isNull()) return Value::Null();
    bool blob = args[0].t == VT::Blob && args[1].t == VT::Blob;
    std::string h = args[0].toText(), nd = args[1].toText();
    size_t pos = h.find(nd);
    if (pos == std::string::npos) return Value::Int(0);
    if (blob) return Value::Int((int64_t)pos + 1);
    return Value::Int(utf8Len(h.substr(0, pos)) + 1);
  }
  if (name == "replace") {
    if (nullIfAnyNull()) return Value::Null();
    std::string s = args[0].toText(), from = args[1].toText(), to = args[2].toText();
    if (from.empty()) return Value::Text(s);
    std::string out; size_t p = 0;
    while (true) {
      size_t q = s.find(from, p);
      if (q == std::string::npos) { out.append(s, p, std::string::npos); break; }
      out.append(s, p, q - p); out += to; p = q + from.size();
    }
    return Value::Text(out);
  }
  if (name == "trim" || name == "ltrim" || name == "rtrim") {
    if (args[0].isNull()) return Value::Null();
    std::string chars = " ";
    if (n > 1) { if (args[1].isNull()) return Value::Null(); chars = args[1].toText(); }
    std::string s = args[0].toText();
    return Value::Text(trimChars(s, chars, name != "rtrim", name != "ltrim"));
  }
  if (name == "hex") {
    const Value& a = args[0];
    if (a.isNull()) return Value::Text("");
    std::string s = a.toText();
    return Value::Text(blobToHex(s));
  }
  if (name == "unhex") {
    if (args[0].isNull()) return Value::Null();
    std::string s = args[0].toText();
    std::string ignore = n > 1 ? args[1].toText() : "";
    std::string out; int hi = -1;
    size_t p = 0;
    // leading ignore chars
    auto isIgn = [&](char c) { return ignore.find(c) != std::string::npos; };
    while (p < s.size() && isIgn(s[p])) p++;
    size_t endp = s.size();
    while (endp > p && isIgn(s[endp - 1])) endp--;
    for (; p < endp; p++) {
      char c = s[p];
      if (isxdigit((unsigned char)c)) {
        int v = isdigit((unsigned char)c) ? c - '0' : (tolower(c) - 'a' + 10);
        if (hi < 0) hi = v; else { out.push_back((char)(hi * 16 + v)); hi = -1; }
      } else if (isIgn(c) && hi < 0) {
        continue;
      } else return Value::Null();
    }
    if (hi >= 0) return Value::Null();
    return Value::Blob(out);
  }
  if (name == "quote") return Value::Text(quoteValue(args[0]));
  if (name == "coalesce" || name == "ifnull") {
    for (auto& a : args) if (!a.isNull()) return a;
    return Value::Null();
  }
  if (name == "nullif") {
    if (args[0].isNull()) return Value::Null();
    if (args[1].isNull()) return args[0];
    std::string coll = e ? collationFor(e->args[0].get(), sc) : "";
    int cid = coll.empty() ? 0 : (nameEq(coll, "NOCASE") ? 1 : (nameEq(coll, "RTRIM") ? 2 : 0));
    Value a = args[0], b = args[1];
    if (compareValues(a, b, cid) == 0) return Value::Null();
    return args[0];
  }
  if (name == "iif" || name == "if") {
    bool nul; bool t = args[0].truthy(&nul);
    if (t && !nul) return args[1];
    if (n > 2) return args[2];
    return Value::Null();
  }
  if (name == "min" || name == "max") {
    // scalar form
    if (nullIfAnyNull()) return Value::Null();
    int best = 0;
    std::string coll = e ? collationFor(e->args[0].get(), sc) : "";
    int cid = nameEq(coll, "NOCASE") ? 1 : (nameEq(coll, "RTRIM") ? 2 : 0);
    for (size_t k = 1; k < n; k++) {
      int c = compareValues(args[k], args[best], cid);
      if (name == "min" ? c < 0 : c > 0) best = (int)k;
    }
    return args[best];
  }
  if (name == "round") {
    if (args[0].isNull()) return Value::Null();
    int64_t nd = 0;
    if (n > 1) { if (args[1].isNull()) return Value::Null(); nd = args[1].toInt(); if (nd > 30) nd = 30; if (nd < 0) nd = 0; }
    double r = args[0].toReal();
    if (r < -4503599627370496.0 || r > 4503599627370496.0) { /* no rounding */ }
    else if (nd == 0) r = (double)((int64_t)(r + (r < 0 ? -0.5 : 0.5)));
    else {
      char buf[400]; snprintf(buf, sizeof buf, "%.*f", (int)nd, r);
      r = strtod(buf, nullptr);
    }
    return Value::Real(r);
  }
  if (name == "sign") {
    if (args[0].isNull()) return Value::Null();
    Value v = numericValue(args[0]);
    if (args[0].t == VT::Text || args[0].t == VT::Blob) {
      double rv; int rc = sqliteAtoF(args[0].s.data(), args[0].s.size(), rv);
      if (rc <= 0) return Value::Null();
    }
    double x = v.t == VT::Int ? (double)v.i : v.r;
    return Value::Int(x > 0 ? 1 : (x < 0 ? -1 : 0));
  }
  if (name == "random") return Value::Int(nextRandom());
  if (name == "randomblob") {
    int64_t len = args[0].toInt();
    if (len < 1) len = 1;
    std::string out; out.resize(len);
    for (int64_t k = 0; k < len; k++) out[k] = (char)(nextRandom() & 0xFF);
    return Value::Blob(out);
  }
  if (name == "zeroblob") {
    int64_t len = args[0].toInt();
    if (len < 0) len = 0;
    if (len > 1000000000) throw SqlError("string or blob too big", -1, 18);
    return Value::Blob(std::string((size_t)len, '\0'));
  }
  if (name == "char") {
