int64_t Engine::nextRandom() {
  // xorshift128+
  uint64_t s1 = randState[0], s0 = randState[1];
  randState[0] = s0;
  s1 ^= s1 << 23; s1 ^= s1 >> 17; s1 ^= s0; s1 ^= s0 >> 26;
  randState[1] = s1;
  return (int64_t)(randState[0] + randState[1]);
}

static std::string substrUtf8(const std::string& s, int64_t p1, int64_t p2, bool hasLen, bool isBlob) {
  // SQLite semantics
  int64_t len;
  if (isBlob) len = (int64_t)s.size(); else len = utf8Len(s);
  if (p1 < 0) { p1 += len; if (p1 < 0) { if (hasLen) p2 += p1; p1 = 0; } }
  else if (p1 > 0) p1--;
  else if (hasLen) { // p1==0
    p2 -= 1; // (p2 may become negative); sqlite: p1 = 0, p2-- when p1==0? Actually substr(x,0,n) returns n-1 chars
    if (p2 < 0) p2 = 0;
  }
  int64_t end;
  if (!hasLen) { p2 = len; end = len; }
  else if (p2 < 0) { p2 = -p2; if (p1 >= p2) { p1 = p1 - p2; p2 = p2; } else { p2 = p1; p1 = 0; } end = p1 + p2; }
  else end = p1 + p2;
  if (p1 >= len) return "";
  if (end > len) end = len;
  if (end <= p1) return "";
  if (isBlob) return s.substr(p1, end - p1);
  // utf8 char indexes
  size_t bi = 0; int64_t ci = 0;
  while (bi < s.size() && ci < p1) { utf8Decode(s, bi); ci++; }
  size_t bs = bi;
  while (bi < s.size() && ci < end) { utf8Decode(s, bi); ci++; }
  return s.substr(bs, bi - bs);
}

static std::string trimChars(const std::string& s, const std::string& chars, bool left, bool right) {
  // chars: set of UTF-8 characters
  std::vector<std::string> set;
  size_t p = 0;
  while (p < chars.size()) { size_t q = p; utf8Decode(chars, q); set.push_back(chars.substr(p, q - p)); p = q; }
  size_t start = 0, end = s.size();
  auto matchAt = [&](size_t pos, bool fromEnd) -> size_t {
    for (auto& c : set) {
      if (c.empty()) continue;
      if (!fromEnd) { if (s.compare(pos, c.size(), c) == 0) return c.size(); }
      else { if (pos >= c.size() && s.compare(pos - c.size(), c.size(), c) == 0) return c.size(); }
    }
    return 0;
  };
  if (left) { while (start < end) { size_t m = matchAt(start, false); if (!m) break; start += m; } }
  if (right) { while (end > start) { size_t m = matchAt(end, true); if (!m) break; end -= m; } }
  return s.substr(start, end - start);
}

std::string formatPrintf(const std::string& fmt, const std::vector<Value>& args, size_t argStart) {
  std::string out;
  size_t ai = argStart;
  auto nextArg = [&]() -> Value { if (ai < args.size()) return args[ai++]; return Value::Null(); };
  for (size_t i = 0; i < fmt.size(); i++) {
    char c = fmt[i];
    if (c != '%') { out.push_back(c); continue; }
    i++;
    if (i >= fmt.size()) break;
    if (fmt[i] == '%') { out.push_back('%'); continue; }
    bool fMinus = false, fPlus = false, fSpace = false, fZero = false, fAlt = false, fAlt2 = false, fComma = false;
    while (i < fmt.size()) {
      char f = fmt[i];
      if (f == '-') fMinus = true; else if (f == '+') fPlus = true; else if (f == ' ') fSpace = true;
      else if (f == '0') fZero = true; else if (f == '#') fAlt = true; else if (f == '!') fAlt2 = true; else if (f == ',') fComma = true;
      else break;
      i++;
    }
    int width = 0; bool hasWidth = false;
    if (i < fmt.size() && fmt[i] == '*') { Value w = nextArg(); width = (int)w.toInt(); if (width < 0) { fMinus = true; width = -width; } hasWidth = true; i++; }
    else while (i < fmt.size() && isdigit((unsigned char)fmt[i])) { width = width * 10 + (fmt[i] - '0'); hasWidth = true; i++; }
    int prec = -1;
    if (i < fmt.size() && fmt[i] == '.') {
      i++; prec = 0;
      if (i < fmt.size() && fmt[i] == '*') { Value p = nextArg(); prec = (int)p.toInt(); if (prec < 0) prec = -1; i++; }
      else while (i < fmt.size() && isdigit((unsigned char)fmt[i])) { prec = prec * 10 + (fmt[i] - '0'); i++; }
    }
    // length modifiers
    while (i < fmt.size() && (fmt[i] == 'l' || fmt[i] == 'h')) i++;
    if (i >= fmt.size()) break;
    char conv = fmt[i];
    std::string body;
    auto pad = [&](std::string s, bool numeric) {
      if (hasWidth && (int)utf8Len(s) < width) {
        int n = width - utf8Len(s);
        if (fMinus) s.append(n, ' ');
        else if (fZero && numeric) {
          size_t signPos = (!s.empty() && (s[0] == '-' || s[0] == '+' || s[0] == ' ')) ? 1 : 0;
          s.insert(signPos, n, '0');
        } else s.insert(0, n, ' ');
      }
      return s;
    };
    switch (conv) {
      case 'd': case 'i': case 'u': case 'x': case 'X': case 'o': {
        Value v = nextArg();
        Value n = v.isNull() ? Value::Int(0) : numericValue(v);
        int64_t iv = n.t == VT::Int ? n.i : n.toInt();
        std::string digits; bool neg = false;
        if (conv == 'd' || conv == 'i') {
          uint64_t u; if (iv < 0) { neg = true; u = (uint64_t)(-(iv + 1)) + 1; } else u = iv;
          digits = std::to_string(u);
        } else {
          uint64_t u = (uint64_t)iv;
          char buf[40];
          if (conv == 'u') snprintf(buf, sizeof buf, "%llu", (unsigned long long)u);
          else if (conv == 'x') snprintf(buf, sizeof buf, "%llx", (unsigned long long)u);
          else if (conv == 'X') snprintf(buf, sizeof buf, "%llX", (unsigned long long)u);
          else snprintf(buf, sizeof buf, "%llo", (unsigned long long)u);
          digits = buf;
        }
        if (prec >= 0 && (int)digits.size() < prec) digits.insert(0, prec - digits.size(), '0');
        if (fComma && (conv == 'd' || conv == 'i')) {
          std::string g; int cnt = 0;
          for (int k = (int)digits.size() - 1; k >= 0; k--) { g.insert(g.begin(), digits[k]); if (++cnt % 3 == 0 && k > 0) g.insert(g.begin(), ','); }
          digits = g;
        }
        std::string prefix;
        if (neg) prefix = "-"; else if (fPlus && (conv == 'd' || conv == 'i')) prefix = "+"; else if (fSpace && (conv == 'd' || conv == 'i')) prefix = " ";
        if (fAlt && (conv == 'x') && iv != 0) prefix += "0x";
        if (fAlt && (conv == 'X') && iv != 0) prefix += "0X";
        if (fAlt && conv == 'o' && digits[0] != '0') prefix += "0";
        body = pad(prefix + digits, prec < 0);
        break;
      }
      case 'f': case 'e': case 'E': case 'g': case 'G': {
        Value v = nextArg();
        double d = v.isNull() ? 0.0 : (numericValue(v).t == VT::Int ? (double)numericValue(v).i : numericValue(v).r);
        if (prec < 0) prec = 6;
        if (prec > 100000) prec = 100000;
        char fbuf[32];
        std::string flags;
        if (fPlus) flags += "+"; if (fSpace) flags += " "; if (fAlt) flags += "#";
        if (std::isinf(d)) {
          body = d < 0 ? "-Inf" : (fPlus ? "+Inf" : "Inf");
          body = pad(body, false);
          break;
        }
        if (std::isnan(d)) { body = pad("NaN", false); break; }
        if (fAlt2 && (conv == 'g' || conv == 'G')) {
          // alternate: like SQLite's %!g -> shortest-ish representation
          std::string s = formatDouble(d);
          body = pad(s, true);
          break;
        }
        snprintf(fbuf, sizeof fbuf, "%%%s.%d%c", flags.c_str(), prec, conv);
        char buf[512];
        snprintf(buf, sizeof buf, fbuf, d);
        std::string s = buf;
        if (fAlt2 && conv == 'f') {
          // ! flag with %f: strip trailing zeros? keep as is
        }
        body = pad(s, true);
        break;
      }
      case 's': case 'z': {
        Value v = nextArg();
        std::string s = v.isNull() ? "" : v.toText();
        if (prec >= 0 && (int)s.size() > prec) s = s.substr(0, prec);
        body = pad(s, false);
        break;
      }
      case 'q': case 'Q': case 'w': {
        Value v = nextArg();
        std::string s;
        if (v.isNull()) { if (conv == 'Q') s = "NULL"; else s = ""; }
        else {
