cd /workspace && cat > src/select.cpp <<'EOF'
// SELECT binding and execution
#include "engine.h"
#include <algorithm>
#include <cmath>
#include <set>
#include <functional>

bool isAggregateFunction(const std::string& name, int nArgs, bool* arityOk);
bool isWindowFunction(const std::string& name);
int checkScalarFunction(const std::string& name, int nArgs);
std::vector<StmtP> parseSqlAll(const std::string& sql);

struct CoreBind {
  std::vector<std::shared_ptr<Cursor>> cursors;
  std::vector<ResultColumn> cols;      // expanded result columns
  std::vector<std::string> colNames;
  std::vector<Expr*> aggs;
  std::vector<Expr*> wins;
  bool isAggregate = false;
  std::vector<SelectP> subSelects;     // per cursor: subquery select (or null)
  std::vector<std::string> viewSql;
  std::vector<CteDef*> cteRefs;
  std::vector<bool> fromCte;
  bool bound = false;
  std::vector<std::vector<int>> usingPairs; // per cursor list of (leftCursor, leftCol, rightCol) flattened
  std::vector<Aff> colAffs;
  std::vector<std::string> colColls;
  int minMaxAgg = -1;  // index of single min/max aggregate for bare-column rule
};

// ---------- helpers ----------

static int collIdOf(const std::string& name) {
  if (name.empty() || nameEq(name, "BINARY")) return 0;
  if (nameEq(name, "NOCASE")) return 1;
  if (nameEq(name, "RTRIM")) return 2;
  return 0;
}

struct RowState {
  std::vector<const Row*> rows;
  std::vector<int64_t> rowids;
  std::vector<bool> nulls;
};
static RowState saveState(const std::vector<Cursor*>& cs) {
  RowState st;
  st.rows.reserve(cs.size()); st.rowids.reserve(cs.size()); st.nulls.reserve(cs.size());
  for (auto* c : cs) { st.rows.push_back(c->row); st.rowids.push_back(c->rowid); st.nulls.push_back(c->isNullRow); }
  return st;
}
static void restoreState(const std::vector<Cursor*>& cs, const RowState& st) {
  for (size_t k = 0; k < cs.size(); k++) { cs[k]->row = st.rows[k]; cs[k]->rowid = st.rowids[k]; cs[k]->isNullRow = st.nulls[k]; }
}

// Walk expression tree (not descending into subqueries) and call f
static void walkExpr(Expr* e, const std::function<void(Expr*)>& f, bool intoSub = false) {
  if (!e) return;
  f(e);
  for (auto& a : e->args) walkExpr(a.get(), f, intoSub);
  if (e->elseExpr) walkExpr(e->elseExpr.get(), f, intoSub);
  if (e->filter) walkExpr(e->filter.get(), f, intoSub);
  if (e->over) {
    for (auto& p : e->over->partition) walkExpr(p.get(), f, intoSub);
    for (auto& o : e->over->order) walkExpr(o.e.get(), f, intoSub);
    if (e->over->startExpr) walkExpr(e->over->startExpr.get(), f, intoSub);
    if (e->over->endExpr) walkExpr(e->over->endExpr.get(), f, intoSub);
  }
  for (auto& o : e->aggOrder) walkExpr(o.e.get(), f, intoSub);
}

// Resolve all column refs / functions in expression (binder). Throws on error.
static void bindExpr(Engine* eng, Expr* e, Scope* sc, bool allowAgg, std::vector<Expr*>* aggs, std::vector<Expr*>* wins, bool inAggArg = false) {
  if (!e) return;
  switch (e->kind) {
    case Expr::Column:
      if (!e->resolved) eng->resolveColumn(e, sc);
      if (e->aliasTarget) {
        // alias target was bound already in select list
      }
      return;
    case Expr::Func: {
      int nArgs = 0;
      bool star = false;
      for (auto& a : e->args) { if (a->kind == Expr::Star) star = true; else nArgs++; }
      bool arityOk = true;
      bool isAgg = isAggregateFunction(e->op, nArgs, &arityOk);
      bool isWin = isWindowFunction(e->op);
      if (e->op == "count" && star) { isAgg = true; arityOk = (nArgs == 0); }
      if (star && e->op != "count") throw SqlError("near \"*\": syntax error", e->start);
      if (e->over) {
        if (!isAgg && !isWin) {
          int chk = checkScalarFunction(e->op, nArgs);
          if (chk == 0) throw SqlError("no such function: " + e->op, e->start);
          throw SqlError(e->op + "() may not be used as a window function", e->start);
        }
        if (isAgg && !arityOk) throw SqlError("wrong number of arguments to function " + e->op + "()", e->start);
        if (isWin) {
          int mn = 0, mx = 0;
          std::string n = e->op;
          if (n == "row_number" || n == "rank" || n == "dense_rank" || n == "percent_rank" || n == "cume_dist") { mn = 0; mx = 0; }
          else if (n == "ntile" || n == "first_value" || n == "last_value") { mn = 1; mx = 1; }
          else if (n == "lag" || n == "lead") { mn = 1; mx = 3; }
          else if (n == "nth_value") { mn = 2; mx = 2; }
          if (nArgs < mn || nArgs > mx) throw SqlError("wrong number of arguments to function " + e->op + "()", e->start);
        }
        if (!wins) throw SqlError("misuse of window function " + e->op + "()", e->start);
        if (inAggArg) throw SqlError("misuse of window function " + e->op + "()", e->start);
        for (auto& a : e->args) if (a->kind != Expr::Star) bindExpr(eng, a.get(), sc, false, aggs, nullptr, true);
        if (e->filter) bindExpr(eng, e->filter.get(), sc, false, aggs, nullptr, true);
        for (auto& p : e->over->partition) bindExpr(eng, p.get(), sc, false, aggs, nullptr);
        for (auto& o : e->over->order) bindExpr(eng, o.e.get(), sc, false, aggs, nullptr);
        if (e->over->startExpr) bindExpr(eng, e->over->startExpr.get(), sc, false, aggs, nullptr);
        if (e->over->endExpr) bindExpr(eng, e->over->endExpr.get(), sc, false, aggs, nullptr);
        bool dup = false;
        for (auto* w : *wins) if (w == e) dup = true;
        if (!dup) wins->push_back(e);
        return;
      }
      if (isAgg) {
        // also a scalar version exists for min/max
        if (!arityOk) {
          if ((e->op == "min" || e->op == "max") && nArgs >= 2) {
            // scalar min/max
            for (auto& a : e->args) bindExpr(eng, a.get(), sc, allowAgg, aggs, wins, inAggArg);
            return;
          }
          throw SqlError("wrong number of arguments to function " + e->op + "()", e->start);
        }
        if (!allowAgg || !aggs) throw SqlError("misuse of aggregate function " + e->op + "()", e->start);
        if (inAggArg) throw SqlError("misuse of aggregate function " + e->op + "()", e->start);
        e->isAggregate = true;
        for (auto& a : e->args) if (a->kind != Expr::Star) bindExpr(eng, a.get(), sc, false, aggs, nullptr, true);
        if (e->filter) bindExpr(eng, e->filter.get(), sc, false, aggs, nullptr, true);
        for (auto& o : e->aggOrder) bindExpr(eng, o.e.get(), sc, false, aggs, nullptr, true);
        bool dup = false;
        for (auto* a : *aggs) if (a == e) dup = true;
        if (!dup) aggs->push_back(e);
        return;
      }
      if (e->filter) throw SqlError("FILTER clause may only be used with aggregate window functions", e->start);
      {
        int chk = checkScalarFunction(e->op, nArgs);
        if (chk == 0) {
          bool isJson = jsonFunctionExists(e->op);
          if (!isJson) throw SqlError("no such function: " + e->op, e->start);
        } else if (chk == 2) throw SqlError("wrong number of arguments to function " + e->op + "()", e->start);
      }
      if (e->distinct) throw SqlError("DISTINCT aggregates must have exactly one argument", e->start);
      for (auto& a : e->args) bindExpr(eng, a.get(), sc, allowAgg, aggs, wins, inAggArg);
      return;
    }
    case Expr::Subquery: case Expr::Exists: {
      // bind subquery lazily at execution (correlated); but to surface errors early, bind now
      Scope inner; inner.parent = sc;
      eng->selectColumnNames(e->sub, sc);
      return;
    }
    case Expr::In: {
      bindExpr(eng, e->args[0].get(), sc, allowAgg, aggs, wins, inAggArg);
      if (e->sub) { eng->selectColumnNames(e->sub, sc); }
      else if (!e->table.empty()) { eng->resolveTable(e->schema, e->table, nullptr, e->start); }
      for (size_t k = 1; k < e->args.size(); k++) bindExpr(eng, e->args[k].get(), sc, allowAgg, aggs, wins, inAggArg);
      return;
    }
    case Expr::Is: case Expr::IsNot: {
      bindExpr(eng, e->args[0].get(), sc, allowAgg, aggs, wins, inAggArg);
      Expr* re = e->args[1].get();
      if (re->kind == Expr::Column && re->table.empty() && (nameEq(re->column, "true") || nameEq(re->column, "false"))) {
        try { eng->resolveColumn(re, sc); } catch (SqlError&) { re->resolved = true; re->isTruthLiteral = true; re->lit = Value::Int(nameEq(re->column, "true") ? 1 : 0); }
        return;
      }
      bindExpr(eng, re, sc, allowAgg, aggs, wins, inAggArg);
      return;
    }
    case Expr::Collate: {
      std::string c = e->collate;
      if (!(nameEq(c, "BINARY") || nameEq(c, "NOCASE") || nameEq(c, "RTRIM") || eng->collationNames.count(lowerStr(c))))
        throw SqlError("no such collation sequence: " + c, e->start);
      bindExpr(eng, e->args[0].get(), sc, allowAgg, aggs, wins, inAggArg);
      return;
    }
    case Expr::Star: case Expr::TableStar:
      throw SqlError("near \"*\": syntax error", e->start);
    default:
      for (auto& a : e->args) bindExpr(eng, a.get(), sc, allowAgg, aggs, wins, inAggArg);
      if (e->elseExpr) bindExpr(eng, e->elseExpr.get(), sc, allowAgg, aggs, wins, inAggArg);
      return;
  }
}

static std::string exprResultName(Expr* e, Scope* sc, const std::string& span, bool topLevel) {
  Expr* x = e;
  while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
  if (x->kind == Expr::Column && !x->isTruthLiteral && !x->aliasTarget) {
    Scope* s = sc; for (int k = 0; k < x->depth && s; k++) s = s->parent;
    if (s && x->srcIdx >= 0 && x->srcIdx < (int)s->cursors.size()) {
      Cursor* c = s->cursors[x->srcIdx];
      if (x->isRowid) {
        if (c->rowidCol >= 0 && c->rowidCol < (int)c->colNames.size()) return c->colNames[c->rowidCol];
        if (topLevel) return "rowid";
        return span;
      }
      if (x->colIdx >= 0 && x->colIdx < (int)c->colNames.size()) return c->colNames[x->colIdx];
    }
    return x->column;
  }
  return span;
}

// ---------- Cursor construction ----------

static void setupTableCursor(Cursor& c, TableP t, const std::string& alias, const std::string& schemaName) {
  c.table = t;
  c.tableName = t->name;
  c.name = alias.empty() ? t->name : alias;
  c.schemaName = schemaName;
  c.colNames.clear(); c.affs.clear(); c.colls.clear(); c.declTypes.clear();
  for (auto& col : t->cols) { c.colNames.push_back(col.name); c.affs.push_back(col.aff); c.colls.push_back(col.collate); c.declTypes.push_back(col.type); }
  c.hiddenForStar.assign(t->cols.size(), false);
  for (size_t k = 0; k < t->cols.size(); k++) if (t->cols[k].hidden) c.hiddenForStar[k] = true;
  c.hasRowid = !t->withoutRowid && !t->isView;
  c.rowidCol = t->rowidCol;
}

static std::vector<std::string> dedupNames(const std::vector<std::string>& in) {
  std::vector<std::string> out;
  std::set<std::string> seen;
  for (auto n : in) {
    std::string base = n; int cnt = 1;
    std::string key = lowerStr(n);
    while (seen.count(key)) { n = base + ":" + std::to_string(cnt++); key = lowerStr(n); }
    seen.insert(key);
    out.push_back(n);
  }
  return out;
}

static CteDef* findCte(Scope* sc, const std::string& name) {
  for (Scope* s = sc; s; s = s->parent) {
    if (s->ctes) { auto it = s->ctes->find(lowerStr(name)); if (it != s->ctes->end()) return it->second; }
  }
  return nullptr;
}

// Build cursor shells for a core's FROM clause and bind everything.
static void bindCore(Engine* eng, SelectCore* core, Scope* parent, Scope& sc, bool topLevel) {
  if (core->bind && core->bind->bound) {
    // reuse: construct scope cursors from shells
    sc.cursors.clear();
    for (auto& c : core->bind->cursors) sc.cursors.push_back(c.get());
    sc.parent = parent;
    return;
  }
  auto bind = std::make_shared<CoreBind>();
  core->bind = bind;
  sc.parent = parent;
  sc.cursors.clear();
  // FROM items
  for (size_t i = 0; i < core->from.size(); i++) {
    SrcItem& it = core->from[i];
    auto c = std::make_shared<Cursor>();
    c->joinType = it.join.type; c->on = it.join.on; c->usingCols = it.join.usingCols;
    SelectP sub;
    CteDef* cte = nullptr;
    if (it.isSubquery) {
      sub = it.sub;
      c->isSubquery = true;
      c->name = it.hasAlias ? it.alias : "";
      c->tableName = c->name;
    } else if (it.isTvf) {
      std::string fn = lowerStr(it.name);
      c->isSubquery = true; c->name = it.hasAlias ? it.alias : it.name; c->tableName = it.name;
      if (fn == "json_each" || fn == "json_tree") {
        const char* names[] = {"key","value","type","atom","id","parent","fullkey","path","json","root"};
        for (auto n : names) { c->colNames.push_back(n); c->affs.push_back(Aff::Blob); c->colls.push_back(""); }
        c->hiddenForStar.assign(c->colNames.size(), false); c->hiddenForStar[8] = true; c->hiddenForStar[9] = true;
        for (auto& a : it.tvfArgs) bindExpr(eng, a.get(), parent, false, nullptr, nullptr);
      } else if (fn == "generate_series") {
        c->colNames = {"value","start","stop","step"}; c->affs.assign(4, Aff::Blob); c->colls.assign(4, "");
        c->hiddenForStar = {false, true, true, true};
        for (auto& a : it.tvfArgs) bindExpr(eng, a.get(), parent, false, nullptr, nullptr);
      } else if (fn.compare(0, 7, "pragma_") == 0) {
        std::string pn = fn.substr(7);
        std::vector<std::string> cols;
        if (pn == "table_info") cols = {"cid","name","type","notnull","dflt_value","pk","schema","arg"};
        else if (pn == "table_xinfo") cols = {"cid","name","type","notnull","dflt_value","pk","hidden","schema","arg"};
        else if (pn == "index_list") cols = {"seq","name","unique","origin","partial","schema","arg"};
        else if (pn == "index_info") cols = {"seqno","cid","name","schema","arg"};
        else if (pn == "index_xinfo") cols = {"seqno","cid","name","desc","coll","key","schema","arg"};
        else if (pn == "foreign_key_list") cols = {"id","seq","table","from","to","on_update","on_delete","match","schema","arg"};
        else if (pn == "table_list") cols = {"schema","name","type","ncol","wr","strict","schema","arg"};
        else if (pn == "database_list") cols = {"seq","name","file"};
        else if (pn == "function_list") cols = {"name","builtin","type","enc","narg","flags"};
        else if (pn == "collation_list") cols = {"seq","name"};
        else if (pn == "compile_options") cols = {"compile_options"};
        else if (pn == "user_version" || pn == "schema_version" || pn == "application_id" || pn == "page_size" || pn == "page_count" || pn == "freelist_count" || pn == "foreign_keys" || pn == "cache_size" || pn == "journal_mode" || pn == "synchronous" || pn == "encoding" || pn == "auto_vacuum" || pn == "integrity_check" || pn == "quick_check" || pn == "max_page_count" || pn == "mmap_size" || pn == "busy_timeout" || pn == "data_version") cols = {pn};
        else throw SqlError("no such table: " + it.name, it.sub ? 0 : -1);
        for (auto& n : cols) { c->colNames.push_back(n); c->affs.push_back(Aff::Blob); c->colls.push_back(""); }
        c->hiddenForStar.assign(c->colNames.size(), false);
        if (pn != "database_list" && pn != "function_list" && pn != "collation_list" && pn != "compile_options" && cols.size() >= 2 && cols.back() == "arg") {
          c->hiddenForStar[c->colNames.size() - 1] = true; c->hiddenForStar[c->colNames.size() - 2] = true;
        }
        for (auto& a : it.tvfArgs) bindExpr(eng, a.get(), parent, false, nullptr, nullptr);
      } else {
        throw SqlError("no such table: " + it.name, -1);
      }
    } else {
      // CTE?
      cte = it.schema.empty() ? findCte(parent, it.name) : nullptr;
      if (cte) {
        c->isCte = true; c->isSubquery = true;
        c->name = it.hasAlias ? it.alias : it.name; c->tableName = it.name;
      } else {
        Schema* sch = nullptr;
        TableP t = eng->resolveTable(it.schema, it.name, &sch, -1);
        if (t->isView) {
          // parse view definition
          std::string vsql = t->sql;
          auto stmts = parseSqlAll(vsql);
          if (stmts.empty() || stmts[0]->kind != Stmt::CreateView) throw SqlError("malformed view definition");
          sub = stmts[0]->select;
          c->isSubquery = true;
          c->name = it.hasAlias ? it.alias : t->name; c->tableName = t->name;
          c->table = nullptr;
          if (!t->viewCols.empty()) {
            // names overridden below
          }
          c->schemaName = sch ? sch->dbName : "main";
          bind->viewSql.push_back(vsql);
        } else {
          setupTableCursor(*c, t, it.hasAlias ? it.alias : "", sch ? sch->dbName : "main");
          if (it.hasAlias) { c->name = it.alias; }
        }
      }
    }
    if (sub) {
      // bind subquery with parent scope (correlation not allowed in FROM subqueries, but views may reference outer? no)
      std::vector<std::string> names;
      names = eng->selectColumnNames(sub, parent);
      // derive affinity/collation from first core when simple columns
      c->colNames = dedupNames(names);
      c->affs.assign(names.size(), Aff::Blob); c->colls.assign(names.size(), "");
      if (!sub->cores.empty() && sub->cores[0]->bind) {
        auto& b = sub->cores[0]->bind;
        for (size_t k = 0; k < names.size() && k < b->colAffs.size(); k++) { c->affs[k] = b->colAffs[k]; c->colls[k] = b->colColls[k]; }
      }
      c->hiddenForStar.assign(names.size(), false);
      if (!it.isSubquery && !it.isTvf && !cte) {
        // view: apply explicit column names
        Schema* sch = nullptr;
        TableP t = eng->resolveTable(it.schema, it.name, &sch, -1);
        if (!t->viewCols.empty()) {
          if (t->viewCols.size() != names.size()) throw SqlError("expected " + std::to_string(t->viewCols.size()) + " columns for '" + t->name + "' but got " + std::to_string(names.size()));
          c->colNames = t->viewCols;
        }
      }
    } else if (cte) {
      // need CTE column names: bind the CTE select
      if (!cte->def.cols.empty()) { c->colNames = cte->def.cols; }
      else {
        std::vector<std::string> names = eng->selectColumnNames(cte->def.sel, cte->defScope ? cte->defScope : parent);
        c->colNames = dedupNames(names);
      }
      c->affs.assign(c->colNames.size(), Aff::Blob); c->colls.assign(c->colNames.size(), "");
      if (cte->def.sel && !cte->def.sel->cores.empty() && cte->def.sel->cores[0]->bind) {
        auto& b = cte->def.sel->cores[0]->bind;
        for (size_t k = 0; k < c->colNames.size() && k < b->colAffs.size(); k++) { c->affs[k] = b->colAffs[k]; c->colls[k] = b->colColls[k]; }
      }
      c->hiddenForStar.assign(c->colNames.size(), false);
    }
    bind->subSelects.push_back(sub);
    bind->cteRefs.push_back(cte);
    bind->fromCte.push_back(cte != nullptr);
    bind->cursors.push_back(c);
    sc.cursors.push_back(c.get());
    // check duplicate names
    for (size_t j = 0; j + 1 < sc.cursors.size(); j++) {
      if (!c->name.empty() && nameEq(sc.cursors[j]->name, c->name)) {
        // SQLite allows the same table twice without alias but columns become ambiguous; keep both
      }
    }
  }
  // NATURAL / USING processing: mark hidden columns on right side and build ON conditions
  for (size_t i = 1; i < sc.cursors.size(); i++) {
    Cursor* right = sc.cursors[i];
    std::vector<std::string> useCols = right->usingCols;
    if (right->joinType & 16) {
      // natural: all common column names with any left cursor
      for (size_t k = 0; k < right->colNames.size(); k++) {
        for (size_t j = 0; j < i; j++) {
          bool found = false;
          for (size_t m = 0; m < sc.cursors[j]->colNames.size(); m++) if (!sc.cursors[j]->hiddenForStar[m] && nameEq(sc.cursors[j]->colNames[m], right->colNames[k])) found = true;
          if (found) { useCols.push_back(right->colNames[k]); break; }
        }
      }
      if (!right->usingCols.empty() || right->on) throw SqlError("a NATURAL join may not have an ON or USING clause", -1);
    }
    for (auto& uc : useCols) {
      int rc = -1;
      for (size_t k = 0; k < right->colNames.size(); k++) if (nameEq(right->colNames[k], uc)) { rc = (int)k; break; }
      if (rc < 0) throw SqlError("cannot join using column " + uc + " - column not present in both tables", -1);
      int lj = -1, lc = -1;
      for (int j = (int)i - 1; j >= 0 && lj < 0; j--) {
        for (size_t m = 0; m < sc.cursors[j]->colNames.size(); m++) if (!sc.cursors[j]->hiddenForStar[m] && nameEq(sc.cursors[j]->colNames[m], uc)) { lj = j; lc = (int)m; break; }
      }
      if (lj < 0) throw SqlError("cannot join using column " + uc + " - column not present in both tables", -1);
      // build equality expr: left.col = right.col using resolved refs
      ExprP l = std::make_shared<Expr>(); l->kind = Expr::Column; l->resolved = true; l->depth = 0; l->srcIdx = lj; l->colIdx = lc; l->column = uc;
      l->colAff = sc.cursors[lj]->affs[lc]; l->colCollate = sc.cursors[lj]->colls[lc];
      ExprP r = std::make_shared<Expr>(); r->kind = Expr::Column; r->resolved = true; r->depth = 0; r->srcIdx = (int)i; r->colIdx = rc; r->column = uc;
      r->colAff = right->affs[rc]; r->colCollate = right->colls[rc];
      ExprP eq = std::make_shared<Expr>(); eq->kind = Expr::Binary; eq->op = "="; eq->args = {l, r};
      if (right->on) { ExprP a = std::make_shared<Expr>(); a->kind = Expr::And; a->args = {right->on, eq}; right->on = a; }
      else right->on = eq;
      // hide right column for star / unqualified (for RIGHT joins the left is hidden instead)
      if (right->joinType & 8) {
        // RIGHT JOIN: hide left column
        sc.cursors[lj]->hiddenForStar[lc] = true;
      } else right->hiddenForStar[rc] = true;
    }
    if (right->on) {
      // ON clause: bind in scope of all cursors so far (SQLite allows refs to any table in FROM)
      Scope onScope; onScope.cursors = sc.cursors; onScope.parent = parent;
      bindExpr(eng, right->on.get(), &onScope, false, nullptr, nullptr);
      if (right->joinType == 0) {
        // comma join with ON? not possible
      }
    }
  }
  // ON clauses for the first item (shouldn't exist)
  // Expand result columns
  std::vector<ResultColumn> cols;
  std::vector<std::string> names;
  if (core->isValues) {
    size_t ncol = core->values[0].size();
    for (auto& row : core->values) {
      if (row.size() != ncol) throw SqlError("all VALUES must have the same number of terms", -1);
      for (auto& e : row) bindExpr(eng, e.get(), &sc, false, nullptr, nullptr);
    }
    for (size_t k = 0; k < ncol; k++) { ResultColumn rc; rc.e = core->values[0][k]; rc.alias = "column" + std::to_string(k + 1); rc.hasAlias = true; cols.push_back(rc); names.push_back(rc.alias); }
    bind->cols = cols; bind->colNames = names; bind->bound = true;
    bind->colAffs.assign(ncol, Aff::Blob); bind->colColls.assign(ncol, "");
    return;
  }
  for (auto& rc : core->cols) {
    if (rc.e->kind == Expr::Star) {
      if (sc.cursors.empty()) throw SqlError("no tables specified", rc.e->start);
      for (size_t ci = 0; ci < sc.cursors.size(); ci++) {
        Cursor* c = sc.cursors[ci];
        for (size_t k = 0; k < c->colNames.size(); k++) {
          if (c->hiddenForStar[k]) continue;
          ResultColumn n; ExprP e = std::make_shared<Expr>(); e->kind = Expr::Column; e->resolved = true; e->depth = 0; e->srcIdx = (int)ci; e->colIdx = (int)k;
          e->column = c->colNames[k]; e->table = c->name; e->colAff = c->affs[k]; e->colCollate = c->colls[k];
          if (c->table && c->rowidCol == (int)k) e->isRowid = true;
          n.e = e; n.alias = c->colNames[k]; n.hasAlias = false; n.spanText = c->colNames[k];
          cols.push_back(n); names.push_back(c->colNames[k]);
        }
      }
    } else if (rc.e->kind == Expr::TableStar) {
      int found = -1;
      for (size_t ci = 0; ci < sc.cursors.size(); ci++) if (nameEq(sc.cursors[ci]->name, rc.e->table)) { found = (int)ci; break; }
      if (found < 0) throw SqlError("no such table: " + rc.e->table, rc.e->start);
      Cursor* c = sc.cursors[found];
      for (size_t k = 0; k < c->colNames.size(); k++) {
        if (c->table && c->table->cols[k].hidden) continue;
        ResultColumn n; ExprP e = std::make_shared<Expr>(); e->kind = Expr::Column; e->resolved = true; e->depth = 0; e->srcIdx = found; e->colIdx = (int)k;
        e->column = c->colNames[k]; e->table = c->name; e->colAff = c->affs[k]; e->colCollate = c->colls[k];
        if (c->table && c->rowidCol == (int)k) e->isRowid = true;
        n.e = e; n.alias = c->colNames[k]; n.spanText = c->colNames[k];
        cols.push_back(n); names.push_back(c->colNames[k]);
      }
    } else {
      cols.push_back(rc);
      names.push_back("");
    }
  }
  // bind result columns (aggregates allowed)
  std::vector<Expr*> aggs, wins;
  for (size_t k = 0; k < cols.size(); k++) {
    bindExpr(eng, cols[k].e.get(), &sc, true, &aggs, &wins);
    if (names[k].empty()) names[k] = cols[k].hasAlias ? cols[k].alias : exprResultName(cols[k].e.get(), &sc, cols[k].spanText, topLevel);
  }
  // affinities/collations of result columns (for subquery consumers)
  bind->colAffs.clear(); bind->colColls.clear();
  for (auto& c : cols) { bind->colAffs.push_back(eng->affinityOf(c.e.get(), &sc)); bind->colColls.push_back(eng->collationFor(c.e.get(), &sc)); }
  // WHERE (no aggregates)
  sc.aliases = &cols; sc.allowAliases = true;
  if (core->where) {
    std::vector<Expr*> tmp;
    try { bindExpr(eng, core->where.get(), &sc, false, nullptr, &tmp); }
    catch (SqlError& err) { throw; }
    if (!tmp.empty()) throw SqlError("misuse of window function " + tmp[0]->op + "()", tmp[0]->start);
  }
  for (auto& g : core->groupBy) {
    // integer -> result column
    if (g->kind == Expr::Literal && g->lit.t == VT::Int) {
      int64_t idx = g->lit.i;
      if (idx < 1 || idx > (int64_t)cols.size()) throw SqlError("1st GROUP BY term out of range - should be between 1 and " + std::to_string(cols.size()));
      continue;
    }
    std::vector<Expr*> tmpA;
    bindExpr(eng, g.get(), &sc, true, &tmpA, nullptr);
    if (!tmpA.empty()) throw SqlError("aggregate functions are not allowed in the GROUP BY clause", tmpA[0]->start);
  }
  if (core->having) {
    bindExpr(eng, core->having.get(), &sc, true, &aggs, nullptr);
  }
  bind->isAggregate = !aggs.empty() || !core->groupBy.empty();
  if (core->having && !bind->isAggregate) throw SqlError("HAVING clause on a non-aggregate query");
  if (bind->isAggregate && !wins.empty()) {
    // windows over aggregates allowed
  }
  bind->aggs = aggs; bind->wins = wins;
  bind->cols = cols; bind->colNames = names;
  // bare-column min/max rule
  if (aggs.size() == 1 && (aggs[0]->op == "min" || aggs[0]->op == "max") && !aggs[0]->distinct) bind->minMaxAgg = 0;
  bind->bound = true;
}

std::vector<std::string> Engine::selectColumnNames(const SelectP& sel, Scope* parent) {
  // Bind the select (all cores) and return column names of first core
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes;
  std::vector<std::shared_ptr<CteDef>> defs;
  if (!sel->ctes.empty()) {
    for (auto& c : sel->ctes) {
      auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope;
      defs.push_back(d); ctes[lowerStr(c.name)] = d.get();
    }
    cteScope.ctes = &ctes;
  }
  Scope* p = sel->ctes.empty() ? parent : &cteScope;
  std::vector<std::string> names;
  for (size_t i = 0; i < sel->cores.size(); i++) {
    Scope sc;
    if (sel->cores[i]->bind && sel->cores[i]->bind->bound) { if (i == 0) names = sel->cores[i]->bind->colNames; continue; }
    // recursive CTE: binding the recursive core references the CTE itself; defScope lets it resolve
    bindCore(this, sel->cores[i].get(), p, sc, i == 0 && parent == nullptr);
    if (i == 0) names = sel->cores[i]->bind->colNames;
    else if (sel->cores[i]->bind->colNames.size() != names.size())
      throw SqlError("SELECTs to the left and right of " + std::string(sel->ops[i - 1] == 1 ? "UNION" : sel->ops[i - 1] == 2 ? "UNION ALL" : sel->ops[i - 1] == 3 ? "INTERSECT" : "EXCEPT") + " do not have the same number of result columns");
  }
  // keep CteDefs alive for binding only; execution rebuilds
  (void)defs;
  return names;
}

// ---------- Aggregates ----------

struct AggState {
  Expr* e;
  int64_t count = 0;
  bool anyReal = false;
  bool approx = false;
  int64_t isum = 0; double rsum = 0.0; bool overflow = false;
  bool hasVal = false; Value val;
  std::vector<std::pair<Row, Value>> ordered; // for ORDER BY in aggregates
  std::string concat; bool concatStarted = false;
  std::vector<Value> seen;          // DISTINCT tracking
  std::vector<Row> seenRows;
  std::vector<Value> values;        // for median/percentile
  std::vector<Value> jsonVals; std::vector<Value> jsonKeys;
  bool first = true;
  Value sep;
};

static bool valueSeen(std::vector<Value>& seen, const Value& v, int cid) {
  for (auto& s : seen) if (compareValues(s, v, cid) == 0 && s.t == v.t) return true;
  seen.push_back(v);
  return false;
}

static void aggStep(Engine* eng, AggState& st, std::vector<Value>& args, Scope* sc) {
  Expr* e = st.e;
  const std::string& n = e->op;
  if (n == "count") {
    bool star = !e->args.empty() && e->args[0]->kind == Expr::Star;
    if (star || e->args.empty()) { st.count++; return; }
    if (args[0].isNull()) return;
    if (e->distinct) { if (valueSeen(st.seen, args[0], collIdOf(eng->collationFor(e->args[0].get(), sc)))) return; }
    st.count++; return;
  }
  if (!e->args.empty() && e->distinct && n != "group_concat" && n != "string_agg") {
    if (args[0].isNull()) {}
    else if (valueSeen(st.seen, args[0], collIdOf(eng->collationFor(e->args[0].get(), sc)))) return;
  }
  if (n == "sum" || n == "total" || n == "avg") {
    const Value& v = args[0];
    if (v.isNull()) return;
    st.count++;
    Value nv = v;
    if (v.t == VT::Text || v.t == VT::Blob) nv = textToNumericIfPossible(v, false);
    if (nv.t == VT::Int) {
      if (!st.approx) {
        int64_t r;
        if (__builtin_add_overflow(st.isum, nv.i, &r)) { st.overflow = true; st.approx = true; st.rsum = (double)st.isum + (double)nv.i; }
        else st.isum = r;
      } else st.rsum += (double)nv.i;
      st.rsum += 0; // keep
      if (!st.approx) st.rsum = (double)st.isum;
    } else {
      if (!st.approx) { st.rsum = (double)st.isum; st.approx = true; }
      st.anyReal = true;
      double d = nv.t == VT::Real ? nv.r : 0.0;
      st.rsum += d;
    }
    return;
  }
  if (n == "min" || n == "max") {
    const Value& v = args[0];
    if (v.isNull()) return;
    int cid = collIdOf(eng->collationFor(e->args[0].get(), sc));
    if (!st.hasVal) { st.hasVal = true; st.val = v; st.first = false; return; }
    int c = compareValues(v, st.val, cid);
    if (n == "min" ? c < 0 : c > 0) st.val = v;
    return;
  }
  if (n == "group_concat" || n == "string_agg") {
    const Value& v = args[0];
    if (v.isNull()) return;
    if (e->distinct) { if (valueSeen(st.seen, v, collIdOf(eng->collationFor(e->args[0].get(), sc)))) return; }
    if (!e->aggOrder.empty()) {
      Row key; for (auto& o : e->aggOrder) key.push_back(eng->eval(o.e, sc));
      st.ordered.push_back({key, v});
      if (args.size() > 1) st.sep = args[1];
      return;
    }
    if (st.concatStarted) {
      std::string sep = ",";
      if (args.size() > 1) sep = args[1].isNull() ? "" : args[1].toText();
      st.concat += sep;
    }
    st.concat += v.toText(); st.concatStarted = true;
    return;
  }
  if (n == "json_group_array" || n == "jsonb_group_array") { st.jsonVals.push_back(args[0]); return; }
  if (n == "json_group_object" || n == "jsonb_group_object") { st.jsonKeys.push_back(args[0]); st.jsonVals.push_back(args[1]); return; }
  if (n == "median" || n == "percentile" || n == "percentile_cont" || n == "percentile_disc") {
    const Value& v = args[0];
    if (v.isNull()) return;
    if (v.t != VT::Int && v.t != VT::Real) throw SqlError("1st argument to " + n + "() is not numeric");
    if (args.size() > 1) {
      if (!st.hasVal) { st.val = args[1]; st.hasVal = true; }
      else if (compareValues(st.val, args[1]) != 0) throw SqlError("2nd argument to " + n + "() is not the same for all input rows");
    }
    st.values.push_back(v);
    return;
  }
  throw SqlError("no such aggregate: " + n);
}

static Value aggFinal(Engine* eng, AggState& st, Scope* sc) {
  Expr* e = st.e;
  const std::string& n = e->op;
  (void)sc;
  if (n == "count") return Value::Int(st.count);
  if (n == "sum") {
    if (st.count == 0) return Value::Null();
    if (st.overflow) throw SqlError("integer overflow");
    if (st.approx) return Value::Real(st.rsum);
    return Value::Int(st.isum);
  }
  if (n == "total") { if (st.approx) return Value::Real(st.rsum); return Value::Real((double)st.isum); }
  if (n == "avg") {
    if (st.count == 0) return Value::Null();
    double s = st.approx ? st.rsum : (double)st.isum;
    return Value::Real(s / (double)st.count);
  }
  if (n == "min" || n == "max") { if (!st.hasVal) return Value::Null(); return st.val; }
  if (n == "group_concat" || n == "string_agg") {
    if (!e->aggOrder.empty()) {
      if (st.ordered.empty()) return Value::Null();
      std::vector<int> cids;
      for (auto& o : e->aggOrder) cids.push_back(collIdOf(eng->collationFor(o.e.get(), sc)));
      std::stable_sort(st.ordered.begin(), st.ordered.end(), [&](const std::pair<Row, Value>& a, const std::pair<Row, Value>& b) {
        for (size_t k = 0; k < e->aggOrder.size(); k++) {
          int c = compareValues(a.first[k], b.first[k], cids[k]);
          if (e->aggOrder[k].desc) c = -c;
          if (c != 0) return c < 0;
        }
        return false;
      });
      std::string out; std::string sep = ",";
      if (e->args.size() > 1) sep = st.sep.isNull() ? "" : st.sep.toText();
      for (size_t k = 0; k < st.ordered.size(); k++) { if (k) out += sep; out += st.ordered[k].second.toText(); }
      return Value::Text(out);
    }
    if (!st.concatStarted) return Value::Null();
    return Value::Text(st.concat);
  }
  if (n == "json_group_array" || n == "jsonb_group_array" || n == "json_group_object" || n == "jsonb_group_object") {
    std::vector<Value> args;
    bool handled = false;
    if (n.find("array") != std::string::npos) {
      args = st.jsonVals;
      return callJsonFunction("__group_array", args, eng, handled);
    }
    for (size_t k = 0; k < st.jsonVals.size(); k++) { args.push_back(st.jsonKeys[k]); args.push_back(st.jsonVals[k]); }
    return callJsonFunction("__group_object", args, eng, handled);
  }
  if (n == "median" || n == "percentile" || n == "percentile_cont" || n == "percentile_disc") {
    if (st.values.empty()) return Value::Null();
    double p = 0.5;
    if (n == "percentile") { p = st.val.toReal() / 100.0; if (st.val.toReal() < 0 || st.val.toReal() > 100) throw SqlError("2nd argument to percentile() is not between 0.0 and 100.0"); }
    else if (n != "median") { p = st.val.toReal(); if (p < 0 || p > 1) throw SqlError("2nd argument to " + n + "() is not between 0.0 and 1.0"); }
    std::sort(st.values.begin(), st.values.end(), [](const Value& a, const Value& b) { return compareValues(a, b) < 0; });
    double ix = p * (st.values.size() - 1);
    size_t i1 = (size_t)ix;
    if (n == "percentile_disc") { return st.values[i1]; }
    double v1 = st.values[i1].toReal();
    if (i1 + 1 >= st.values.size() || ix == (double)i1) return Value::Real(v1);
    double v2 = st.values[i1 + 1].toReal();
    return Value::Real(v1 + (v2 - v1) * (ix - i1));
  }
  return Value::Null();
}

// ---------- Execution ----------

struct OutRow {
  Row vals;          // result column values
  Row sortKeys;
  RowState state;    // for window functions / later evaluation
  std::vector<Value> aggVals;
  size_t seq = 0;
};

static int compareRows(const Row& a, const Row& b, const std::vector<int>& cids) {
  for (size_t k = 0; k < a.size() && k < b.size(); k++) {
    int c = compareValues(a[k], b[k], k < cids.size() ? cids[k] : 0);
    if (c != 0) return c;
  }
  return 0;
}

// Materialize a table-valued function
static void materializeTvf(Engine* eng, SrcItem& it, Scope* parent, Cursor& c) {
  std::string fn = lowerStr(it.name);
  std::vector<Value> args;
  for (auto& a : it.tvfArgs) args.push_back(eng->eval(a, parent));
  c.mat.clear();
  if (fn == "json_each" || fn == "json_tree") {
    if (args.empty()) throw SqlError("json_each() requires at least one argument");
    jsonEachRows(args[0], args.size() > 1 ? &args[1] : nullptr, fn == "json_tree", c.mat);
    return;
  }
  if (fn == "generate_series") {
    if (args.empty()) throw SqlError("first argument to \"generate_series()\" missing or unusable");
    int64_t start = args[0].toInt();
    int64_t stop = args.size() > 1 ? args[1].toInt() : INT64_MAX;
    int64_t step = args.size() > 2 ? args[2].toInt() : 1;
    if (step == 0) step = 1;
    if (args.size() < 2) throw SqlError("second argument to \"generate_series()\" missing or unusable");
    if (step > 0) for (int64_t v = start; v <= stop; v += step) { c.mat.push_back(Row{Value::Int(v), Value::Int(start), Value::Int(stop), Value::Int(step)}); if (c.mat.size() > 10000000) break; }
    else for (int64_t v = start; v >= stop; v += step) { c.mat.push_back(Row{Value::Int(v), Value::Int(start), Value::Int(stop), Value::Int(step)}); if (c.mat.size() > 10000000) break; }
    return;
  }
  if (fn.compare(0, 7, "pragma_") == 0) {
    // run pragma and collect rows
    StmtP st = std::make_shared<Stmt>(); st->kind = Stmt::Pragma; st->pragmaName = fn.substr(7);
    if (!args.empty()) { st->pragmaHasValue = true; st->pragmaCall = true; ExprP lit = std::make_shared<Expr>(); lit->kind = Expr::Literal; lit->lit = args[0]; st->pragmaValue = lit; }
    if (args.size() > 1) st->schema = args[1].toText();
    std::vector<Row> rows;
    eng->execPragma(st, [](const std::vector<std::string>&) {}, [&](const Row& r) { rows.push_back(r); });
    size_t ncol = c.colNames.size();
    for (auto& r : rows) { Row x = r; while (x.size() < ncol) x.push_back(Value::Null()); c.mat.push_back(x); }
    return;
  }
  throw SqlError("no such table: " + it.name);
}

void Engine::execSelect(const SelectP& sel, Scope* parent, HeaderCallback onHeader, RowCallback onRow, std::vector<std::string>* outNames) {
  if (++depth > 200) { depth--; throw SqlError("too many levels of nesting"); }
  struct DepthGuard { int& d; ~DepthGuard() { d--; } } guard{depth};
  // CTE setup
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes;
  std::vector<std::shared_ptr<CteDef>> defs;
  Scope* p = parent;
  if (!sel->ctes.empty()) {
    for (auto& c : sel->ctes) {
      auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope;
      defs.push_back(d); ctes[lowerStr(c.name)] = d.get();
    }
    cteScope.ctes = &ctes;
    p = &cteScope;
  }
  // bind all cores
  std::vector<std::string> names = selectColumnNames(sel, p);
  if (outNames) *outNames = names;

  bool compound = sel->cores.size() > 1;
  bool hasOrder = !sel->orderBy.empty();
  // LIMIT/OFFSET
  int64_t limit = -1, offset = 0;
  if (sel->limit) {
    Value lv = eval(sel->limit, p);
    if (lv.t == VT::Text || lv.t == VT::Blob) { Value nv = textToNumericIfPossible(lv, true); if (nv.t != VT::Int) throw SqlError("datatype mismatch", -1, 20); lv = nv; }
    if (lv.t == VT::Real) { if (lv.r == (double)(int64_t)lv.r) lv = Value::Int((int64_t)lv.r); else throw SqlError("datatype mismatch", -1, 20); }
    if (lv.isNull()) throw SqlError("datatype mismatch", -1, 20);
    limit = lv.i;
    if (sel->offset) {
      Value ov = eval(sel->offset, p);
      if (ov.t == VT::Text || ov.t == VT::Blob) { Value nv = textToNumericIfPossible(ov, true); if (nv.t != VT::Int) throw SqlError("datatype mismatch", -1, 20); ov = nv; }
      if (ov.t == VT::Real) { if (ov.r == (double)(int64_t)ov.r) ov = Value::Int((int64_t)ov.r); else throw SqlError("datatype mismatch", -1, 20); }
      if (ov.isNull()) throw SqlError("datatype mismatch", -1, 20);
      offset = ov.i; if (offset < 0) offset = 0;
    }
  }
  bool headerDone = false;
  auto emitHeader = [&]() { if (!headerDone) { headerDone = true; if (onHeader) onHeader(names); } };

  if (!compound) {
    SelectCore* core = sel->cores[0].get();
    // single core
    std::vector<OutRow> rows;
    bool stream = !hasOrder && core->bind->wins.empty() && !core->distinct;
    int64_t emitted = 0, skipped = 0;
    bool stop = false;
    auto emitRow = [&](Row& r) {
      if (stop) return;
      if (skipped < offset) { skipped++; return; }
      if (limit >= 0 && emitted >= limit) { stop = true; return; }
      emitHeader();
      emitted++;
      onRow(r);
    };
    std::function<void(OutRow&)> sink;
    if (stream) sink = [&](OutRow& o) { emitRow(o.vals); };
    else sink = [&](OutRow& o) { o.seq = rows.size(); rows.push_back(std::move(o)); };
    // execute core
    extern void execCore(Engine*, SelectCore*, Scope*, const std::vector<OrderBy>*, std::function<void(OutRow&)>&, bool*);
    execCore(this, core, p, hasOrder ? &sel->orderBy : nullptr, sink, &stop);
    if (stream) return;
    // DISTINCT
    if (core->distinct) {
      std::vector<int> cids;
      for (auto& c : core->bind->cols) cids.push_back(collIdOf(collationFor(c.e.get(), nullptr)));
      std::vector<OutRow> uniq;
      // SQLite uses an ephemeral index: order preserved, duplicates dropped
      std::vector<const Row*> seen;
      for (auto& r : rows) {
        bool dup = false;
        for (auto* s : seen) if (compareRows(*s, r.vals, cids) == 0) { dup = true; break; }
        if (dup) continue;
        uniq.push_back(std::move(r));
        seen.push_back(&uniq.back().vals);
        // pointer may invalidate on reallocation; rebuild
        if (seen.size() != uniq.size()) {}
        seen.clear(); for (auto& u : uniq) seen.push_back(&u.vals);
      }
      rows = std::move(uniq);
    }
    if (hasOrder) {
      std::vector<int> cids; std::vector<bool> desc; std::vector<int> nulls;
      for (auto& ob : sel->orderBy) {
        Expr* x = ob.e.get();
        std::string coll;
        if (x->kind == Expr::Collate) coll = x->collate;
        else if (x->kind == Expr::Literal && x->lit.t == VT::Int) {
          int64_t idx = x->lit.i;
          if (idx >= 1 && idx <= (int64_t)core->bind->cols.size()) coll = collationFor(core->bind->cols[idx - 1].e.get(), nullptr);
        } else coll = collationFor(x, nullptr);
        cids.push_back(collIdOf(coll)); desc.push_back(ob.desc); nulls.push_back(ob.nulls);
      }
      std::stable_sort(rows.begin(), rows.end(), [&](const OutRow& a, const OutRow& b) {
        for (size_t k = 0; k < a.sortKeys.size(); k++) {
          const Value& va = a.sortKeys[k]; const Value& vb = b.sortKeys[k];
          int c;
          if (va.isNull() || vb.isNull()) {
            if (va.isNull() && vb.isNull()) c = 0;
            else {
              bool nullsFirst = nulls[k] == 1 || (nulls[k] == 0 && !desc[k]);
              c = va.isNull() ? (nullsFirst ? -1 : 1) : (nullsFirst ? 1 : -1);
              if (c != 0) return c < 0;
              continue;
            }
          } else c = compareValues(va, vb, cids[k]);
          if (desc[k]) c = -c;
          if (c != 0) return c < 0;
        }
        return false;
      });
    }
    for (auto& r : rows) { if (stop) break; emitRow(r.vals); }
    return;
  }
  // Compound select
  std::vector<Row> acc;
  std::vector<int> cids(names.size(), 0);
  {
    auto& b = sel->cores[0]->bind;
    for (size_t k = 0; k < names.size() && k < b->colColls.size(); k++) cids[k] = collIdOf(b->colColls[k]);
  }
  auto rowLess = [&](const Row& a, const Row& b) { return compareRows(a, b, cids) < 0; };
  auto rowEq = [&](const Row& a, const Row& b) { return compareRows(a, b, cids) == 0; };
  for (size_t i = 0; i < sel->cores.size(); i++) {
    std::vector<OutRow> part;
    std::function<void(OutRow&)> sink = [&](OutRow& o) { part.push_back(std::move(o)); };
    bool stop = false;
    extern void execCore(Engine*, SelectCore*, Scope*, const std::vector<OrderBy>*, std::function<void(OutRow&)>&, bool*);
    execCore(this, sel->cores[i].get(), p, nullptr, sink, &stop);
    std::vector<Row> cur;
    for (auto& o : part) cur.push_back(std::move(o.vals));
    if (sel->cores[i]->distinct) {
      std::vector<Row> u;
      for (auto& r : cur) { bool dup = false; for (auto& s : u) if (rowEq(s, r)) { dup = true; break; } if (!dup) u.push_back(r); }
      cur = u;
    }
    if (i == 0) { acc = std::move(cur); continue; }
    int op = sel->ops[i - 1];
    if (op == 2) { for (auto& r : cur) acc.push_back(std::move(r)); continue; }
    // set operations: results sorted (b-tree semantics)
    std::sort(acc.begin(), acc.end(), rowLess);
    acc.erase(std::unique(acc.begin(), acc.end(), rowEq), acc.end());
    std::sort(cur.begin(), cur.end(), rowLess);
    cur.erase(std::unique(cur.begin(), cur.end(), rowEq), cur.end());
    std::vector<Row> out;
    if (op == 1) std::set_union(acc.begin(), acc.end(), cur.begin(), cur.end(), std::back_inserter(out), rowLess);
    else if (op == 3) std::set_intersection(acc.begin(), acc.end(), cur.begin(), cur.end(), std::back_inserter(out), rowLess);
    else std::set_difference(acc.begin(), acc.end(), cur.begin(), cur.end(), std::back_inserter(out), rowLess);
    acc = std::move(out);
  }
  // ORDER BY for compound: terms must be result columns
  if (hasOrder) {
    std::vector<int> idx; std::vector<bool> desc; std::vector<int> nulls; std::vector<int> ocids;
    for (size_t k = 0; k < sel->orderBy.size(); k++) {
      auto& ob = sel->orderBy[k];
      Expr* x = ob.e.get();
      std::string coll;
      if (x->kind == Expr::Collate) { coll = x->collate; x = x->args[0].get(); }
      int found = -1;
      if (x->kind == Expr::Literal && x->lit.t == VT::Int) {
        if (x->lit.i < 1 || x->lit.i > (int64_t)names.size()) throw SqlError(std::to_string(k + 1) + ordinalSuffix(k + 1) + " ORDER BY term out of range - should be between 1 and " + std::to_string(names.size()));
        found = (int)x->lit.i - 1;
      } else if (x->kind == Expr::Column && x->table.empty()) {
        auto& cols0 = sel->cores[0]->bind->cols;
        for (size_t c = 0; c < cols0.size(); c++) {
          if (cols0[c].hasAlias && nameEq(cols0[c].alias, x->column)) { found = (int)c; break; }
        }
        if (found < 0) for (size_t c = 0; c < names.size(); c++) if (nameEq(names[c], x->column)) { found = (int)c; break; }
      } else {
        // match by expression text against the first core's columns
        auto& cols0 = sel->cores[0]->bind->cols;
        for (size_t c = 0; c < cols0.size(); c++) {
          if (!cols0[c].spanText.empty() && sel->text.size() >= (size_t)(x->end) && x->end > x->start) {
            std::string sp = sel->text.substr(x->start - sel->start, x->end - x->start);
            if (sp == cols0[c].spanText) { found = (int)c; break; }
          }
        }
      }
      if (found < 0) throw SqlError(std::to_string(k + 1) + ordinalSuffix(k + 1) + " ORDER BY term does not match any column in the result set", -1);
      idx.push_back(found); desc.push_back(ob.desc); nulls.push_back(ob.nulls);
      ocids.push_back(coll.empty() ? cids[found] : collIdOf(coll));
    }
    std::stable_sort(acc.begin(), acc.end(), [&](const Row& a, const Row& b) {
      for (size_t k = 0; k < idx.size(); k++) {
        const Value& va = a[idx[k]]; const Value& vb = b[idx[k]];
        int c;
        if (va.isNull() || vb.isNull()) {
          if (va.isNull() && vb.isNull()) continue;
          bool nullsFirst = nulls[k] == 1 || (nulls[k] == 0 && !desc[k]);
          c = va.isNull() ? (nullsFirst ? -1 : 1) : (nullsFirst ? 1 : -1);
          return c < 0;
        }
        c = compareValues(va, vb, ocids[k]);
        if (desc[k]) c = -c;
        if (c != 0) return c < 0;
      }
      return false;
    });
  }
  int64_t emitted = 0;
  for (size_t k = (size_t)std::min<int64_t>(offset, (int64_t)acc.size()); k < acc.size(); k++) {
    if (limit >= 0 && emitted >= limit) break;
    emitHeader(); emitted++;
    onRow(acc[k]);
  }
}

void Engine::materializeSelect(const SelectP& sel, Scope* parent, std::vector<Row>& rows, std::vector<std::string>& names, std::vector<std::string>* declTypes) {
  (void)declTypes;
  rows.clear();
  execSelect(sel, parent, [&](const std::vector<std::string>& n) { names = n; }, [&](const Row& r) { rows.push_back(r); }, &names);
}

// Window function evaluation
static void computeWindows(Engine* eng, SelectCore* core, Scope& sc, std::vector<OutRow>& rows, std::vector<std::unordered_map<const Expr*, Value>>& winVals);

// Execute a single core, producing OutRows via sink. If orderBy given, computes sort keys.
void execCore(Engine* eng, SelectCore* core, Scope* parent, const std::vector<OrderBy>* orderBy, std::function<void(OutRow&)>& sink, bool* stop) {
  Scope sc;
  bindCore(eng, core, parent, sc, false);
  CoreBind& b = *core->bind;
  // Prepare runtime cursors: copy shells so that nested/recursive use doesn't clash
  std::vector<std::shared_ptr<Cursor>> live;
  for (size_t i = 0; i < b.cursors.size(); i++) {
    auto c = std::make_shared<Cursor>(*b.cursors[i]);
    c->mat.clear(); c->matRowids.clear();
    live.push_back(c);
  }
  sc.cursors.clear();
  for (auto& c : live) sc.cursors.push_back(c.get());
  sc.parent = parent;
  sc.aliases = &b.cols; sc.allowAliases = true;
  // Materialize subqueries / CTEs / TVFs
  for (size_t i = 0; i < live.size(); i++) {
    Cursor& c = *live[i];
    if (core->isValues) break;
    SrcItem& it = core->from[i];
    if (b.cteRefs[i]) {
      CteDef* d = b.cteRefs[i];
      if (d->computing) {
        // recursive reference: rows provided via recursiveQueue
        if (d->recursiveQueue) { c.mat = *d->recursiveQueue; }
        continue;
      }
      if (!d->materialized) {
        d->computing = true;
        std::vector<std::string> nm;
        // recursive CTE?
        SelectP cs = d->def.sel;
        bool isRecursive = false;
        if (cs->cores.size() >= 2) {
          // check if any core after the first references the CTE itself
          for (size_t k = 1; k < cs->cores.size(); k++) for (auto& f : cs->cores[k]->from) if (!f.isSubquery && nameEq(f.name, d->def.name)) isRecursive = true;
        }
        if (isRecursive) {
          // evaluate: initial cores (all before the recursive one(s)) then iterate
          std::vector<Row> result; std::vector<Row> queue;
          size_t recStart = 1;
          for (size_t k = 1; k < cs->cores.size(); k++) { bool refs = false; for (auto& f : cs->cores[k]->from) if (!f.isSubquery && nameEq(f.name, d->def.name)) refs = true; if (refs) { recStart = k; break; } }
          bool unionAll = cs->ops[recStart - 1] == 2;
          std::vector<int> cids;
          // initial select: cores [0, recStart)
          {
            auto init = std::make_shared<Select>();
            for (size_t k = 0; k < recStart; k++) init->cores.push_back(cs->cores[k]);
            for (size_t k = 0; k + 1 < recStart; k++) init->ops.push_back(cs->ops[k]);
            std::vector<Row> r0;
            d->recursiveQueue = &queue;
            eng->materializeSelect(init, d->defScope, r0, nm);
            if (!d->def.cols.empty()) nm = d->def.cols;
            cids.assign(nm.size(), 0);
            for (auto& r : r0) {
              if (!unionAll) { bool dup = false; for (auto& x : result) if (compareRows(x, r, cids) == 0) { dup = true; break; } if (dup) continue; }
              result.push_back(r); queue.push_back(r);
            }
          }
          // LIMIT on recursive CTE
          int64_t lim = -1;
          if (cs->limit) lim = eng->eval(cs->limit, d->defScope).toInt();
          int iter = 0;
          while (!queue.empty()) {
            if (lim >= 0 && (int64_t)result.size() >= lim) break;
            std::vector<Row> cur = queue; queue.clear();
            // Process rows one at a time (SQLite semantics: queue), but evaluating the recursive core per row is slow.
            // Use the whole batch at once when ORDER BY absent, which gives identical results for most queries.
            std::vector<Row> batch = cur;
            d->recursiveQueue = &batch;
            for (size_t k = recStart; k < cs->cores.size(); k++) {
              auto one = std::make_shared<Select>(); one->cores.push_back(cs->cores[k]);
              std::vector<Row> rr; std::vector<std::string> nn;
              eng->materializeSelect(one, d->defScope, rr, nn);
              for (auto& r : rr) {
                if (!unionAll) { bool dup = false; for (auto& x : result) if (compareRows(x, r, cids) == 0) { dup = true; break; } if (dup) continue; }
                result.push_back(r); queue.push_back(r);
                if (lim >= 0 && (int64_t)result.size() >= lim) break;
              }
            }
            if (++iter > 10000000) break;
          }
          if (!cs->orderBy.empty()) {
            // sort result by ORDER BY (column indexes / names)
            std::vector<int> idx; std::vector<bool> desc;
            for (auto& ob : cs->orderBy) {
              int f = -1;
              if (ob.e->kind == Expr::Literal && ob.e->lit.t == VT::Int) f = (int)ob.e->lit.i - 1;
              else if (ob.e->kind == Expr::Column) for (size_t q = 0; q < nm.size(); q++) if (nameEq(nm[q], ob.e->column)) f = (int)q;
              if (f < 0) throw SqlError("1st ORDER BY term does not match any column in the result set");
              idx.push_back(f); desc.push_back(ob.desc);
            }
            std::stable_sort(result.begin(), result.end(), [&](const Row& a, const Row& bb) {
              for (size_t k = 0; k < idx.size(); k++) { int c = compareValues(a[idx[k]], bb[idx[k]]); if (desc[k]) c = -c; if (c) return c < 0; }
              return false;
            });
          }
          if (lim >= 0 && (int64_t)result.size() > lim) result.resize(lim);
          d->rows = result;
          d->recursiveQueue = nullptr;
        } else {
          eng->materializeSelect(d->def.sel, d->defScope, d->rows, nm);
        }
        d->materialized = true; d->computing = false;
      }
      c.mat = d->rows;
      continue;
    }
    if (b.subSelects[i]) {
      std::vector<std::string> nm;
      eng->materializeSelect(b.subSelects[i], parent, c.mat, nm);
      continue;
    }
    if (it.isTvf) { materializeTvf(eng, it, parent, c); continue; }
  }

  // Aggregation structures
  bool isAgg = b.isAggregate;
  struct Group { Row key; std::vector<AggState> aggs; RowState rep; bool hasRep = false; size_t firstSeq; };
  std::vector<Group> groups;
  std::map<std::vector<std::string>, size_t> groupIndex; // not used (we sort later)
  std::vector<int> gcids;
  // GROUP BY expressions: integer literal -> result column
  std::vector<ExprP> groupExprs;
  for (auto& g : core->groupBy) {
    if (g->kind == Expr::Literal && g->lit.t == VT::Int) groupExprs.push_back(b.cols[g->lit.i - 1].e);
    else groupExprs.push_back(g);
  }
  for (auto& g : groupExprs) gcids.push_back(collIdOf(eng->collationFor(g.get(), &sc)));
  auto newAggStates = [&]() { std::vector<AggState> v; for (auto* a : b.aggs) { AggState s; s.e = a; v.push_back(s); } return v; };
  size_t seqCounter = 0;
  std::vector<std::unordered_map<const Expr*, Value>> winVals;
  std::vector<OutRow> pending;  // rows awaiting window computation
  bool hasWins = !b.wins.empty();
  std::unordered_map<const Expr*, int> aggIds;
  for (size_t k = 0; k < b.aggs.size(); k++) aggIds[b.aggs[k]] = (int)k;

  auto evalOutput = [&](std::vector<Value>* aggValues, OutRow& o) {
    sc.aggValues = aggValues; sc.aggIds = aggValues ? &aggIds : nullptr;
    o.vals.clear();
    for (auto& rc : b.cols) o.vals.push_back(eng->eval(rc.e, &sc));
    if (orderBy) {
      for (auto& ob : *orderBy) {
        Expr* x = ob.e.get();
        if (x->kind == Expr::Collate) x = x->args[0].get();
        if (x->kind == Expr::Literal && x->lit.t == VT::Int) {
          int64_t idx = x->lit.i;
          if (idx < 1 || idx > (int64_t)b.cols.size()) throw SqlError("1st ORDER BY term out of range - should be between 1 and " + std::to_string(b.cols.size()));
          o.sortKeys.push_back(o.vals[idx - 1]);
        } else {
          // alias to result column?
          bool done = false;
          if (x->kind == Expr::Column && x->table.empty()) {
            for (size_t c = 0; c < b.cols.size(); c++) if (b.cols[c].hasAlias && nameEq(b.cols[c].alias, x->column)) { o.sortKeys.push_back(o.vals[c]); done = true; break; }
          }
          if (!done) o.sortKeys.push_back(eng->eval(ob.e, &sc));
        }
      }
    }
    sc.aggValues = nullptr; sc.aggIds = nullptr;
  };

  // bind ORDER BY expressions (so errors surface before output)
  if (orderBy) {
    std::vector<Expr*> oaggs = b.aggs, owins;
    for (size_t k = 0; k < orderBy->size(); k++) {
      Expr* x = (*orderBy)[k].e.get();
      Expr* y = x; if (y->kind == Expr::Collate) y = y->args[0].get();
      if (y->kind == Expr::Literal && y->lit.t == VT::Int) {
        if (y->lit.i < 1 || y->lit.i > (int64_t)b.cols.size()) throw SqlError(std::to_string(k + 1) + ordinalSuffix(k + 1) + " ORDER BY term out of range - should be between 1 and " + std::to_string(b.cols.size()));
        continue;
      }
      bindExpr(eng, x, &sc, true, &oaggs, &owins);
      if (oaggs.size() != b.aggs.size()) {
        if (!isAgg) throw SqlError("misuse of aggregate: " + oaggs.back()->op + "()", oaggs.back()->start);
        b.aggs = oaggs; aggIds.clear(); for (size_t q = 0; q < b.aggs.size(); q++) aggIds[b.aggs[q]] = (int)q;
      }
      for (auto* w : owins) { bool dup = false; for (auto* z : b.wins) if (z == w) dup = true; if (!dup) b.wins.push_back(w); }
    }
    hasWins = !b.wins.empty();
  }

  auto produce = [&](std::vector<Value>* aggValues) {
    OutRow o;
    o.seq = seqCounter++;
    if (hasWins) {
      o.state = saveState(sc.cursors);
      if (aggValues) o.aggVals = *aggValues;
      pending.push_back(std::move(o));
      return;
    }
    evalOutput(aggValues, o);
    sink(o);
  };

  auto processRow = [&]() {
    if (*stop) return;
    if (core->where) {
      Value w = eng->eval(core->where, &sc);
      bool nul; if (!w.truthy(&nul) || nul) return;
    }
    if (!isAgg) { produce(nullptr); return; }
    // group key
    Row key;
    for (auto& g : groupExprs) key.push_back(eng->eval(g, &sc));
    Group* grp = nullptr;
    for (auto& g : groups) if (compareRows(g.key, key, gcids) == 0 && g.key.size() == key.size()) { grp = &g; break; }
    if (!grp) {
      Group g; g.key = key; g.aggs = newAggStates(); g.rep = saveState(sc.cursors); g.hasRep = true; g.firstSeq = seqCounter++;
      groups.push_back(std::move(g)); grp = &groups.back();
    }
    for (size_t k = 0; k < grp->aggs.size(); k++) {
      AggState& st = grp->aggs[k];
      Expr* ae = st.e;
      if (ae->filter) { Value f = eng->eval(ae->filter, &sc); bool nul; if (!f.truthy(&nul) || nul) continue; }
      std::vector<Value> args;
      for (auto& a : ae->args) { if (a->kind == Expr::Star) continue; args.push_back(eng->eval(a, &sc)); }
      if (b.minMaxAgg == (int)k && !args.empty() && !args[0].isNull()) {
        bool before = st.hasVal; Value prev = st.val;
        aggStep(eng, st, args, &sc);
        if (!before || compareValues(st.val, prev, collIdOf(eng->collationFor(ae->args[0].get(), &sc))) != 0) grp->rep = saveState(sc.cursors);
      } else aggStep(eng, st, args, &sc);
    }
  };

  // Join loop
  size_t n = live.size();
  if (core->isValues) {
    for (auto& row : core->values) {
      OutRow o; o.seq = seqCounter++;
      for (auto& e : row) o.vals.push_back(eng->eval(e, &sc));
      sink(o);
      if (*stop) break;
    }
    return;
  }
  if (n == 0) {
    processRow();
  } else {
    // RIGHT/FULL join support: track matched rows of right tables
    std::vector<std::vector<bool>> rightMatched(n);
    std::vector<bool> needRight(n, false);
    for (size_t i = 1; i < n; i++) if (live[i]->joinType & (8 | 32)) { needRight[i] = true; }
    std::function<void(size_t)> loop = [&](size_t level) {
      if (*stop) return;
      if (level == n) { processRow(); return; }
      Cursor& c = *live[level];
      bool isLeft = (c.joinType & (4 | 32)) != 0;
      bool matched = false;
      auto tryRow = [&](size_t idx) {
        if (c.on) {
          Value v = eng->eval(c.on, &sc);
          bool nul; if (!v.truthy(&nul) || nul) return;
        }
        matched = true;
        if (needRight[level]) { if (rightMatched[level].size() <= idx) rightMatched[level].resize(idx + 1, false); rightMatched[level][idx] = true; }
        loop(level + 1);
      };
      c.isNullRow = false;
      if (c.table) {
        // iterate table rows in rowid order; copy keys to allow safe iteration
        auto& rows = c.table->rows;
        size_t idx = 0;
        for (auto it = rows.begin(); it != rows.end() && !*stop; ++it, ++idx) {
          c.row = &it->second; c.rowid = it->first;
          tryRow(idx);
        }
      } else {
        for (size_t idx = 0; idx < c.mat.size() && !*stop; idx++) {
          c.row = &c.mat[idx]; c.rowid = (int64_t)idx + 1;
          tryRow(idx);
        }
      }
      if (!matched && isLeft) {
        c.isNullRow = true; c.row = nullptr;
        loop(level + 1);
        c.isNullRow = false;
      }
    };
    loop(0);
    // RIGHT / FULL join: emit unmatched right rows with left side NULL
    for (size_t i = 1; i < n && !*stop; i++) {
      if (!needRight[i]) continue;
      Cursor& c = *live[i];
      size_t cnt = c.table ? c.table->rows.size() : c.mat.size();
      for (size_t j = 0; j < i; j++) { live[j]->isNullRow = true; live[j]->row = nullptr; }
      for (size_t j = i + 1; j < n; j++) { live[j]->isNullRow = true; live[j]->row = nullptr; }
      size_t idx = 0;
      auto emitUnmatched = [&](size_t id) {
        if (id < rightMatched[i].size() && rightMatched[i][id]) return;
        processRow();
      };
      if (c.table) { for (auto it = c.table->rows.begin(); it != c.table->rows.end(); ++it, ++idx) { c.row = &it->second; c.rowid = it->first; emitUnmatched(idx); } }
      else { for (idx = 0; idx < cnt; idx++) { c.row = &c.mat[idx]; emitUnmatched(idx); } }
      for (size_t j = 0; j < n; j++) live[j]->isNullRow = false;
    }
  }
  if (isAgg) {
    if (groups.empty() && core->groupBy.empty()) {
      // single group with no rows: aggregates over empty set
      Group g; g.aggs = newAggStates(); g.hasRep = false;
      for (auto* c : sc.cursors) { c->isNullRow = true; c->row = nullptr; }
      groups.push_back(std::move(g));
    }
    // sort groups by key
    if (!core->groupBy.empty()) {
      std::stable_sort(groups.begin(), groups.end(), [&](const Group& a, const Group& bb) { return compareRows(a.key, bb.key, gcids) < 0; });
    }
    for (auto& g : groups) {
      if (*stop) break;
      if (g.hasRep) restoreState(sc.cursors, g.rep);
      std::vector<Value> vals;
      for (auto& st : g.aggs) vals.push_back(aggFinal(eng, st, &sc));
      if (core->having) {
        sc.aggValues = &vals; sc.aggIds = &aggIds;
        Value h = eng->eval(core->having, &sc);
        sc.aggValues = nullptr; sc.aggIds = nullptr;
        bool nul; if (!h.truthy(&nul) || nul) continue;
      }
      produce(&vals);
    }
  }
  if (hasWins) {
    computeWindows(eng, core, sc, pending, winVals);
    for (size_t k = 0; k < pending.size(); k++) {
      if (*stop) break;
      OutRow& o = pending[k];
      restoreState(sc.cursors, o.state);
      sc.winValues = &winVals[k];
      std::vector<Value>* av = isAgg ? &o.aggVals : nullptr;
      evalOutput(av, o);
      sc.winValues = nullptr;
      sink(o);
    }
  }
}

// ---------- Window functions ----------

static void computeWindows(Engine* eng, SelectCore* core, Scope& sc, std::vector<OutRow>& rows, std::vector<std::unordered_map<const Expr*, Value>>& winVals) {
  CoreBind& b = *core->bind;
  winVals.assign(rows.size(), {});
  std::unordered_map<const Expr*, int> aggIds;
  for (size_t k = 0; k < b.aggs.size(); k++) aggIds[b.aggs[k]] = (int)k;
  auto setRow = [&](size_t i) {
    restoreState(sc.cursors, rows[i].state);
    if (b.isAggregate) { sc.aggValues = &rows[i].aggVals; sc.aggIds = &aggIds; }
  };
  for (Expr* w : b.wins) {
    // resolve window definition (named windows)
    WindowP def = w->over;
    if (def && !def->name.empty() && def->partition.empty() && def->order.empty() && !def->hasFrame) {
      bool found = false;
      for (auto& nw : core->windows) if (nameEq(nw.first, def->name)) { def = nw.second; found = true; }
      if (!found) throw SqlError("no such window: " + def->name);
    }
    if (def && !def->baseName.empty()) {
      WindowP base;
      for (auto& nw : core->windows) if (nameEq(nw.first, def->baseName)) base = nw.second;
      if (!base) throw SqlError("no such window: " + def->baseName);
      auto merged = std::make_shared<WindowDef>(*def);
      merged->partition = base->partition;
      if (merged->order.empty()) merged->order = base->order;
      def = merged;
    }
    // bind partition/order in sc
    for (auto& p : def->partition) bindExpr(eng, p.get(), &sc, true, &b.aggs, nullptr);
    for (auto& o : def->order) bindExpr(eng, o.e.get(), &sc, true, &b.aggs, nullptr);
    size_t n = rows.size();
    // compute partition keys and order keys per row
    std::vector<Row> pkeys(n), okeys(n);
    std::vector<int> pcids, ocids;
    for (auto& p : def->partition) pcids.push_back(collIdOf(eng->collationFor(p.get(), &sc)));
    for (auto& o : def->order) ocids.push_back(collIdOf(eng->collationFor(o.e.get(), &sc)));
    for (size_t i = 0; i < n; i++) {
      setRow(i);
      for (auto& p : def->partition) pkeys[i].push_back(eng->eval(p, &sc));
      for (auto& o : def->order) okeys[i].push_back(eng->eval(o.e, &sc));
    }
    sc.aggValues = nullptr; sc.aggIds = nullptr;
    std::vector<size_t> order(n);
    for (size_t i = 0; i < n; i++) order[i] = i;
    auto cmpOrder = [&](size_t a, size_t c) -> int {
      for (size_t k = 0; k < def->order.size(); k++) {
        const Value& va = okeys[a][k]; const Value& vb = okeys[c][k];
        int r;
        if (va.isNull() || vb.isNull()) {
          if (va.isNull() && vb.isNull()) continue;
          bool nullsFirst = def->order[k].nulls == 1 || (def->order[k].nulls == 0 && !def->order[k].desc);
          r = va.isNull() ? (nullsFirst ? -1 : 1) : (nullsFirst ? 1 : -1);
          return r;
        }
        r = compareValues(va, vb, ocids[k]);
        if (def->order[k].desc) r = -r;
        if (r) return r;
      }
      return 0;
    };
    std::stable_sort(order.begin(), order.end(), [&](size_t a, size_t c) {
      int r = compareRows(pkeys[a], pkeys[c], pcids);
      if (r) return r < 0;
      return cmpOrder(a, c) < 0;
    });
    // iterate partitions
    size_t ps = 0;
    const std::string& fn = w->op;
    bool isAggFn = isAggregateFunction(fn, 0, nullptr) || fn == "count";
    while (ps < n) {
      size_t pe = ps;
      while (pe < n && compareRows(pkeys[order[ps]], pkeys[order[pe]], pcids) == 0) pe++;
      size_t psize = pe - ps;
      // peer groups
      std::vector<size_t> peerStart(psize), peerEnd(psize);
      for (size_t i = 0; i < psize;) {
        size_t j = i;
        while (j < psize && cmpOrder(order[ps + i], order[ps + j]) == 0) j++;
        for (size_t k = i; k < j; k++) { peerStart[k] = i; peerEnd[k] = j; }
        i = j;
      }
      // evaluate args per row in partition
      auto evalArgs = [&](size_t idxInPart) {
        std::vector<Value> args;
        setRow(order[ps + idxInPart]);
        for (auto& a : w->args) if (a->kind != Expr::Star) args.push_back(eng->eval(a, &sc));
        sc.aggValues = nullptr; sc.aggIds = nullptr;
        return args;
      };
      auto filterOk = [&](size_t idxInPart) {
        if (!w->filter) return true;
        setRow(order[ps + idxInPart]);
        Value f = eng->eval(w->filter, &sc);
        sc.aggValues = nullptr; sc.aggIds = nullptr;
        bool nul; return f.truthy(&nul) && !nul;
      };
      // frame computation
      auto frameBounds = [&](size_t i, size_t& fs, size_t& fe) {
        int ft = def->hasFrame ? def->frameType : 0;
        int stType = def->hasFrame ? def->startType : 0;
        int enType = def->hasFrame ? def->endType : 2;
        if (def->order.empty() && !def->hasFrame) { fs = 0; fe = psize; return; }
        auto boundRows = [&](int type, ExprP ex, bool isStart) -> int64_t {
          switch (type) {
            case 0: return 0;
            case 4: return (int64_t)psize;
            case 2: return isStart ? (int64_t)i : (int64_t)i + 1;
            case 1: case 3: {
              Value v = eng->eval(ex, &sc);
              if (v.isNull() || (v.t != VT::Int && !(v.t == VT::Real && v.r == (double)(int64_t)v.r)) || v.toInt() < 0) throw SqlError("frame starting offset must be a non-negative integer");
              int64_t k = v.toInt();
              int64_t pos = (int64_t)i + (type == 1 ? -k : k);
              if (!isStart) pos += 1;
              if (pos < 0) pos = 0; if (pos > (int64_t)psize) pos = psize;
              return pos;
            }
          }
          return 0;
        };
        if (ft == 1) { fs = (size_t)boundRows(stType, def->startExpr, true); fe = (size_t)boundRows(enType, def->endExpr, false); if (fe < fs) fe = fs; return; }
        if (ft == 2) {
          // GROUPS: offsets count peer groups
          auto groupBound = [&](int type, ExprP ex, bool isStart) -> size_t {
            if (type == 0) return 0;
            if (type == 4) return psize;
            if (type == 2) return isStart ? peerStart[i] : peerEnd[i];
            Value v = eng->eval(ex, &sc);
            if (v.isNull() || v.toInt() < 0) throw SqlError("frame starting offset must be a non-negative integer");
            int64_t k = v.toInt();
            size_t pos = i;
            if (type == 1) { for (int64_t q = 0; q < k; q++) { if (peerStart[pos] == 0) { return 0; } pos = peerStart[pos] - 1; } return isStart ? peerStart[pos] : peerEnd[pos]; }
            for (int64_t q = 0; q < k; q++) { if (peerEnd[pos] >= psize) return psize; pos = peerEnd[pos]; }
            return isStart ? peerStart[pos] : peerEnd[pos];
          };
          fs = groupBound(stType, def->startExpr, true); fe = groupBound(enType, def->endExpr, false); if (fe < fs) fe = fs; return;
        }
        // RANGE
        auto rangeBound = [&](int type, ExprP ex, bool isStart) -> size_t {
          if (type == 0) return 0;
          if (type == 4) return psize;
          if (type == 2) return isStart ? peerStart[i] : peerEnd[i];
          if (def->order.size() != 1) throw SqlError("RANGE with offset PRECEDING/FOLLOWING requires one ORDER BY expression");
          Value v = eng->eval(ex, &sc);
          if (v.isNull() || (!v.isNum()) || v.toReal() < 0) throw SqlError("frame starting offset must be a non-negative integer");
          const Value& cur = okeys[order[ps + i]][0];
          bool desc = def->order[0].desc;
          if (cur.isNull()) return isStart ? peerStart[i] : peerEnd[i];
          // target = cur -/+ v
          double delta = v.toReal(); if (type == 1) delta = -delta;
          if (desc) delta = -delta;
          Value target;
          if (cur.t == VT::Int && v.t == VT::Int) { target = Value::Int(cur.i + (int64_t)delta); }
          else target = Value::Real(cur.toReal() + delta);
          // find first row (for start) whose key >= target (asc) / <= target (desc); for end, first row > target
          size_t pos = 0;
          for (pos = 0; pos < psize; pos++) {
            const Value& k = okeys[order[ps + pos]][0];
            if (k.isNull()) { if (isStart && type == 1) continue; else continue; }
            int c = compareValues(k, target);
            if (desc) c = -c;
            if (isStart ? c >= 0 : c > 0) break;
          }
          return pos;
        };
        fs = rangeBound(stType, def->startExpr, true); fe = rangeBound(enType, def->endExpr, false);
        if (fe < fs) fe = fs;
      };
      std::vector<Value> results(psize);
      if (fn == "row_number") { for (size_t i = 0; i < psize; i++) results[i] = Value::Int((int64_t)i + 1); }
      else if (fn == "rank") { for (size_t i = 0; i < psize; i++) results[i] = Value::Int((int64_t)peerStart[i] + 1); }
      else if (fn == "dense_rank") { int64_t r = 0; for (size_t i = 0; i < psize; i++) { if (i == 0 || peerStart[i] != peerStart[i - 1]) r++; results[i] = Value::Int(r); } }
      else if (fn == "percent_rank") { for (size_t i = 0; i < psize; i++) results[i] = Value::Real(psize > 1 ? (double)peerStart[i] / (double)(psize - 1) : 0.0); }
      else if (fn == "cume_dist") { for (size_t i = 0; i < psize; i++) results[i] = Value::Real((double)peerEnd[i] / (double)psize); }
      else if (fn == "ntile") {
        auto a = evalArgs(0);
        if (a[0].isNull() || a[0].toInt() <= 0 || a[0].t != VT::Int) throw SqlError("argument of ntile must be a positive integer");
        int64_t nb = a[0].toInt();
        int64_t sz = psize / nb, extra = psize % nb;
        size_t i = 0;
        for (int64_t bk = 1; bk <= nb && i < psize; bk++) { int64_t cnt = sz + (bk <= extra ? 1 : 0); for (int64_t q = 0; q < cnt && i < psize; q++) results[i++] = Value::Int(bk); }
      }
      else if (fn == "lag" || fn == "lead") {
        for (size_t i = 0; i < psize; i++) {
          auto a = evalArgs(i);
          int64_t off = a.size() > 1 ? a[1].toInt() : 1;
          Value dflt = a.size() > 2 ? a[2] : Value::Null();
          int64_t j = fn == "lag" ? (int64_t)i - off : (int64_t)i + off;
          if (j < 0 || j >= (int64_t)psize) results[i] = dflt;
          else { auto aj = evalArgs((size_t)j); results[i] = aj[0]; }
        }
      }
      else if (fn == "first_value" || fn == "last_value" || fn == "nth_value") {
        for (size_t i = 0; i < psize; i++) {
          setRow(order[ps + i]);
          size_t fs, fe; frameBounds(i, fs, fe);
          sc.aggValues = nullptr; sc.aggIds = nullptr;
          // exclude handling
          std::vector<size_t> idxs;
          for (size_t q = fs; q < fe; q++) {
            if (def->exclude == 1 && q == i) continue;
            if (def->exclude == 2 && peerStart[q] == peerStart[i]) continue;
            if (def->exclude == 3 && peerStart[q] == peerStart[i] && q != i) continue;
            idxs.push_back(q);
          }
          if (idxs.empty()) { results[i] = Value::Null(); continue; }
          size_t pick;
          if (fn == "first_value") pick = idxs.front();
          else if (fn == "last_value") pick = idxs.back();
          else {
            auto a = evalArgs(i);
            if (a[1].isNull() || a[1].t != VT::Int || a[1].i <= 0) throw SqlError("second argument to nth_value must be a positive integer");
            int64_t nth = a[1].i;
            if (nth > (int64_t)idxs.size()) { results[i] = Value::Null(); continue; }
            pick = idxs[nth - 1];
          }
          auto ap = evalArgs(pick);
          results[i] = ap[0];
        }
      }
      else if (isAggFn) {
        for (size_t i = 0; i < psize; i++) {
          setRow(order[ps + i]);
          size_t fs, fe; frameBounds(i, fs, fe);
          sc.aggValues = nullptr; sc.aggIds = nullptr;
          AggState st; st.e = w;
          for (size_t q = fs; q < fe; q++) {
            if (def->exclude == 1 && q == i) continue;
            if (def->exclude == 2 && peerStart[q] == peerStart[i]) continue;
            if (def->exclude == 3 && peerStart[q] == peerStart[i] && q != i) continue;
            if (!filterOk(q)) continue;
            auto a = evalArgs(q);
            setRow(order[ps + q]);
            aggStep(eng, st, a, &sc);
            sc.aggValues = nullptr; sc.aggIds = nullptr;
          }
          results[i] = aggFinal(eng, st, &sc);
        }
      } else throw SqlError("no such function: " + fn);
      for (size_t i = 0; i < psize; i++) winVals[order[ps + i]][w] = results[i];
      ps = pe;
    }
  }
  sc.aggValues = nullptr; sc.aggIds = nullptr;
}
