  if (mx < INT64_MAX) return mx + 1;
  throw SqlError("database or disk is full", -1, 13);
}

TableP Schema::findTable(const std::string& name) const { auto it = tables.find(lowerStr(name)); return it == tables.end() ? nullptr : it->second; }
IndexP Schema::findIndex(const std::string& name) const { auto it = indexes.find(lowerStr(name)); return it == indexes.end() ? nullptr : it->second; }
TriggerP Schema::findTrigger(const std::string& name) const { auto it = triggers.find(lowerStr(name)); return it == triggers.end() ? nullptr : it->second; }
std::vector<IndexP> Schema::indexesOf(const std::string& table) const {
  std::vector<IndexP> out;
  for (auto& e : entries) if (e.type == "index" && nameEq(e.tblName, table)) { auto ix = findIndex(e.name); if (ix) out.push_back(ix); }
  return out;
}
std::vector<TriggerP> Schema::triggersOf(const std::string& table) const {
  std::vector<TriggerP> out;
  for (auto& e : entries) if (e.type == "trigger" && nameEq(e.tblName, table)) { auto t = findTrigger(e.name); if (t) out.push_back(t); }
  return out;
}
void Schema::addEntry(const SchemaEntry& e) { entries.push_back(e); }
void Schema::removeEntry(const std::string& name) {
  for (size_t i = 0; i < entries.size(); i++) if (nameEq(entries[i].name, name)) { entries.erase(entries.begin() + i); return; }
}
void Schema::renameEntriesTable(const std::string& oldName, const std::string& newName) {
  for (auto& e : entries) if (nameEq(e.tblName, oldName)) e.tblName = newName;
}

Schema* Database::schemaByName(const std::string& n) {
  if (n.empty() || nameEq(n, "main")) return &main;
  if (nameEq(n, "temp")) return &temp;
  auto it = attached.find(lowerStr(n));
  if (it != attached.end()) return &it->second;
  return nullptr;
}
TableP Database::findTable(const std::string& schema, const std::string& name, Schema** out) {
  if (!schema.empty()) {
    Schema* s = schemaByName(schema);
    if (!s) return nullptr;
    TableP t = s->findTable(name);
    if (t && out) *out = s;
    return t;
  }
  TableP t = temp.findTable(name);
  if (t) { if (out) *out = &temp; return t; }
  t = main.findTable(name);
  if (t) { if (out) *out = &main; return t; }
  for (auto& kv : attached) { t = kv.second.findTable(name); if (t) { if (out) *out = &kv.second; return t; } }
  return nullptr;
}
IndexP Database::findIndex(const std::string& schema, const std::string& name, Schema** out) {
  if (!schema.empty()) { Schema* s = schemaByName(schema); if (!s) return nullptr; IndexP i = s->findIndex(name); if (i && out) *out = s; return i; }
  IndexP i = temp.findIndex(name); if (i) { if (out) *out = &temp; return i; }
  i = main.findIndex(name); if (i) { if (out) *out = &main; return i; }
  for (auto& kv : attached) { i = kv.second.findIndex(name); if (i) { if (out) *out = &kv.second; return i; } }
  return nullptr;
}
TriggerP Database::findTrigger(const std::string& schema, const std::string& name, Schema** out) {
  if (!schema.empty()) { Schema* s = schemaByName(schema); if (!s) return nullptr; TriggerP t = s->findTrigger(name); if (t && out) *out = s; return t; }
  TriggerP t = temp.findTrigger(name); if (t) { if (out) *out = &temp; return t; }
  t = main.findTrigger(name); if (t) { if (out) *out = &main; return t; }
  return nullptr;
}
std::vector<IndexP> Database::indexesOf(const std::string& table, Schema* sch) {
  if (sch) return sch->indexesOf(table);
  auto v = main.indexesOf(table);
  auto w = temp.indexesOf(table);
  v.insert(v.end(), w.begin(), w.end());
  return v;
}
std::vector<TriggerP> Database::triggersOf(const std::string& table) {
  auto v = main.triggersOf(table);
  auto w = temp.triggersOf(table);
  v.insert(v.end(), w.begin(), w.end());
  return v;
}
void Database::flush() {
  if (dirty && !isMemory && !filename.empty()) { std::string err; save(err); dirty = false; }
}

static std::string normalizeCreateSql(const std::string& text, const std::string& kind, size_t nameStartOff) {
  // "CREATE <kind> " + text from the object name onward (trailing whitespace trimmed)
  std::string rest = text.substr(nameStartOff);
  while (!rest.empty() && isspace((unsigned char)rest.back())) rest.pop_back();
  return "CREATE " + kind + " " + rest;
}

// Find offset of object name within statement text: skip CREATE [TEMP] [UNIQUE] kind [IF NOT EXISTS]
static size_t nameOffset(const std::string& text) {
  auto toks = tokenize(text);
  size_t i = 0;
  // skip until after TABLE/INDEX/VIEW/TRIGGER keyword, then optional IF NOT EXISTS
  while (i < toks.size() && toks[i].type != TT::END) {
    if (toks[i].type == TT::KW && (toks[i].kw == "TABLE" || toks[i].kw == "INDEX" || toks[i].kw == "VIEW" || toks[i].kw == "TRIGGER")) { i++; break; }
    i++;
  }
  if (i < toks.size() && toks[i].type == TT::KW && toks[i].kw == "IF") i += 3;
  if (i < toks.size()) return toks[i].pos;
  return 0;
}

static std::string stripSchemaPrefix(const std::string& text, size_t nameOff, const std::string& schema) {
  // if the name is schema-qualified (schema.name), remove "schema." from the stored text
  if (schema.empty()) return text.substr(nameOff);
  auto toks = tokenize(text.substr(nameOff));
  if (toks.size() > 2 && toks[1].type == TT::OP && toks[1].text == ".") return text.substr(nameOff + toks[2].pos);
  return text.substr(nameOff);
}

TableP buildTable(const Stmt& st, const std::string& sqlText, Database& db) {
  (void)db;
  auto t = std::make_shared<Table>();
  t->name = st.table;
  t->withoutRowid = st.withoutRowid;
  t->strict = st.strict;
  t->sql = sqlText;
  t->temp = st.temp;
  std::set<std::string> seen;
  int pkCount = 0;
  for (auto& cd : st.colDefs) {
    Column c;
    c.name = cd.name; c.type = cd.type; c.aff = affinityFromType(cd.type);
    if (st.strict) {
      std::string u; for (char ch : cd.type) u.push_back(toupper((unsigned char)ch));
      if (!(u == "INT" || u == "INTEGER" || u == "REAL" || u == "TEXT" || u == "BLOB" || u == "ANY"))
        throw SqlError(u.empty() ? "missing datatype for " + st.table + "." + cd.name : "unknown datatype for " + st.table + "." + cd.name + ": \"" + cd.type + "\"");
      if (u == "ANY") c.aff = Aff::Blob;
    }
    c.notNull = cd.notNull; c.notNullConflict = cd.notNullConflict;
    c.pk = cd.pk; c.autoinc = cd.autoincrement; c.unique = cd.unique;
    c.hasDefault = cd.hasDefault; c.dflt = cd.dflt; c.dfltText = cd.dfltText;
    c.collate = cd.collate; c.checks = cd.checks;
    c.isGenerated = cd.isGenerated; c.generated = cd.generated; c.genStored = cd.generatedStored == 1;
    if (seen.count(lowerStr(c.name))) throw SqlError("duplicate column name: " + c.name);
    seen.insert(lowerStr(c.name));
    if (cd.pk) pkCount++;
    t->cols.push_back(c);
  }
  // table constraints
  for (auto& tc : st.constraints) {
    if (tc.kind == TableConstraint::PK) {
      pkCount++;
      for (auto& ic : tc.cols) {
        int ci = ic.name.empty() ? -1 : t->colIndex(ic.name);
        if (ci < 0) throw SqlError("no such column: " + (ic.name.empty() ? std::string("?") : ic.name));
      }
    }
    if (tc.kind == TableConstraint::Unique || tc.kind == TableConstraint::PK) {
      for (auto& ic : tc.cols) if (!ic.name.empty() && t->colIndex(ic.name) < 0) throw SqlError("no such column: " + ic.name);
    }
    if (tc.kind == TableConstraint::ForeignKey) {
      for (auto& ic : tc.cols) if (t->colIndex(ic.name) < 0) throw SqlError("unknown column \"" + ic.name + "\" in foreign key definition");
    }
  }
  if (pkCount > 1) throw SqlError("table \"" + st.table + "\" has more than one primary key");
  t->constraints = st.constraints;
  // Determine rowid alias / pk columns
  for (size_t i = 0; i < t->cols.size(); i++) {
    if (t->cols[i].pk) {
      t->pkCols.push_back((int)i);
      std::string u; for (char ch : t->cols[i].type) u.push_back(toupper((unsigned char)ch));
      bool desc = false;
      for (auto& cd : st.colDefs) if (nameEq(cd.name, t->cols[i].name)) desc = cd.pkDesc;
      if (u == "INTEGER" && !t->withoutRowid && !desc) t->rowidCol = (int)i;
      if (t->cols[i].autoinc) t->autoinc = true;
    }
  }
  for (auto& tc : st.constraints) {
    if (tc.kind == TableConstraint::PK) {
      for (auto& ic : tc.cols) t->pkCols.push_back(t->colIndex(ic.name));
      if (tc.cols.size() == 1) {
        int ci = t->colIndex(tc.cols[0].name);
        std::string u; for (char ch : t->cols[ci].type) u.push_back(toupper((unsigned char)ch));
        if (u == "INTEGER" && !t->withoutRowid) t->rowidCol = ci;
        if (tc.autoincrement) t->autoinc = true;
      }
    }
  }
  if (t->autoinc && t->rowidCol < 0) throw SqlError("AUTOINCREMENT is only allowed on an INTEGER PRIMARY KEY");
  if (t->withoutRowid) {
    if (t->pkCols.empty()) throw SqlError("PRIMARY KEY missing on table " + st.table);
    for (int ci : t->pkCols) t->cols[ci].notNull = true;
  }
  // PRIMARY KEY columns on WITHOUT ROWID tables are NOT NULL; on rowid tables PK (non-integer) columns allow NULL (legacy)
  return t;
}

// ---------- Engine::execute ----------

size_t Engine::stmtBegin() { return db.undo.size(); }
void Engine::stmtCommit(size_t mark) {
  (void)mark;
  if (!db.inTransaction) { db.undo.clear(); db.dirty = true; }
}
void Engine::stmtRollback(size_t mark) { db.undoTo(mark); }

void Engine::begin(int type) {
  (void)type;
  if (db.inTransaction) throw SqlError("cannot start a transaction within a transaction");
  db.inTransaction = true;
  db.undo.clear();
  db.savepoints.clear();
}
void Engine::commit() {
  if (!db.inTransaction) throw SqlError("cannot commit - no transaction is active");
  db.inTransaction = false;
  db.undo.clear(); db.savepoints.clear();
  db.flush();
}
void Engine::rollback() {
  if (!db.inTransaction) throw SqlError("cannot rollback - no transaction is active");
  db.undoTo(0);
  db.inTransaction = false; db.savepoints.clear();
}
void Engine::savepoint(const std::string& name) {
  if (!db.inTransaction) { db.inTransaction = true; db.undo.clear(); db.savepoints.clear(); db.savepointAutoDepth = 1; }
  db.savepoints.push_back({lowerStr(name), db.undo.size()});
}
void Engine::release(const std::string& name) {
  std::string n = lowerStr(name);
  int idx = -1;
  for (int i = (int)db.savepoints.size() - 1; i >= 0; i--) if (db.savepoints[i].first == n) { idx = i; break; }
  if (idx < 0) throw SqlError("no such savepoint: " + name);
  db.savepoints.resize(idx);
  if (db.savepoints.empty() && db.savepointAutoDepth) { db.savepointAutoDepth = 0; db.inTransaction = false; db.undo.clear(); db.flush(); }
}
void Engine::rollbackTo(const std::string& name) {
  std::string n = lowerStr(name);
  int idx = -1;
  for (int i = (int)db.savepoints.size() - 1; i >= 0; i--) if (db.savepoints[i].first == n) { idx = i; break; }
  if (idx < 0) throw SqlError("no such savepoint: " + name);
  db.undoTo(db.savepoints[idx].second);
  db.savepoints.resize(idx + 1);
}

TableP Engine::resolveTable(const std::string& schema, const std::string& name, Schema** outSchema, int errOffset) {
  if (!schema.empty() && !db.schemaByName(schema)) throw SqlError("unknown database " + schema, errOffset);
  // sqlite_master / sqlite_schema virtual tables are materialized on access
  std::string ln = lowerStr(name);
  if (ln == "sqlite_master" || ln == "sqlite_schema" || ln == "sqlite_temp_master" || ln == "sqlite_temp_schema") {
    Schema* s = (ln.find("temp") != std::string::npos || nameEq(schema, "temp")) ? &db.temp : (schema.empty() ? &db.main : db.schemaByName(schema));
    auto t = std::make_shared<Table>();
    t->name = (ln.find("temp") != std::string::npos) ? (ln == "sqlite_temp_master" ? "sqlite_temp_master" : "sqlite_temp_schema") : (ln == "sqlite_master" ? "sqlite_master" : "sqlite_schema");
    const char* names[] = {"type", "name", "tbl_name", "rootpage", "sql"};
    const char* types[] = {"text", "text", "text", "int", "text"};
    for (int i = 0; i < 5; i++) { Column c; c.name = names[i]; c.type = types[i]; c.aff = affinityFromType(c.type); t->cols.push_back(c); }
    int64_t rid = 1;
    for (auto& e : s->entries) {
      Row r{Value::Text(e.type), Value::Text(e.name), Value::Text(e.tblName), Value::Int(e.rootpage), e.sqlNull ? Value::Null() : Value::Text(e.sql)};
      t->rows[rid++] = r;
    }
    if (outSchema) *outSchema = s;
    return t;
  }
  Schema* sch = nullptr;
  TableP t = db.findTable(schema, name, &sch);
  if (!t) throw SqlError("no such table: " + (schema.empty() ? "" : schema + ".") + name, errOffset);
  if (outSchema) *outSchema = sch;
  return t;
}

Value Engine::applyColumnAffinity(const Value& v, const Column& c) { return applyAffinity(v, c.aff); }

bool Engine::hasTriggers(TableP t, int event) {
  for (auto& tr : db.triggersOf(t->name)) if (tr->event == event) return true;
  return false;
}

static std::string checkExprText(const Expr* e, const std::string& sql) {
  if (e->end > e->start && e->end <= (int)sql.size()) return sql.substr(e->start, e->end - e->start);
  return "";
}

void Engine::deleteRowRaw(TableP t, int64_t rowid) {
  auto it = t->rows.find(rowid);
  if (it == t->rows.end()) return;
  Row old = it->second;
  t->rows.erase(it);
  db.logUndo([t, rowid, old]() { t->rows[rowid] = old; });
}

// Compute generated columns in a row
static void computeGenerated(Engine* eng, TableP t, Row& vals) {
  bool any = false;
  for (auto& c : t->cols) if (c.isGenerated) any = true;
  if (!any) return;
  Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
  for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
  cur.hiddenForStar.assign(t->cols.size(), false);
  cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
  cur.row = &vals;
  Scope sc; sc.cursors.push_back(&cur);
  for (int pass = 0; pass < 2; pass++) {
    for (size_t i = 0; i < t->cols.size(); i++) {
      if (!t->cols[i].isGenerated) continue;
      ExprP g = t->cols[i].generated;
      // clone-free evaluation: reset resolution each time since scope structure constant
      Value v = eng->eval(g, &sc);
      vals[i] = applyAffinity(v, t->cols[i].aff);
    }
  }
}

// Check constraints; returns conflicts to delete (for REPLACE). Throws on violation.
void Engine::checkConstraints(TableP t, Schema* sch, const Row& vals, int64_t rowid, int64_t ignoreRowid, int conflict, std::vector<int64_t>& toDelete, bool& skip, Scope* sc) {
  skip = false;
  auto conflictError = [&](const std::string& msg, int colConflict) {
    int c = colConflict ? colConflict : conflict;
    if (c == 0) c = 2;
    if (c == 4) { skip = true; return true; }  // IGNORE
    int code = 19;
    if (c == 1) code = 1001; else if (c == 3) code = 1003;  // rollback / fail
    throw SqlError(msg, -1, code);
  };
  // NOT NULL
  for (size_t i = 0; i < t->cols.size(); i++) {
    const Column& c = t->cols[i];
    if (c.notNull && vals[i].isNull()) {
      int cc = c.notNullConflict ? c.notNullConflict : conflict;
      if (cc == 5) {
        // REPLACE: use default; handled by caller (we throw if no default)
        if (!c.hasDefault) cc = 2;
        else { throw SqlError("__replace_default__" + std::to_string(i), -1, -5); }
      }
      if (conflictError("NOT NULL constraint failed: " + t->name + "." + c.name, cc == 5 ? 2 : cc)) return;
    }
  }
  // STRICT type checks
  if (t->strict) {
    for (size_t i = 0; i < t->cols.size(); i++) {
      const Column& c = t->cols[i];
      std::string u; for (char ch : c.type) u.push_back(toupper((unsigned char)ch));
      const Value& v = vals[i];
      if (v.isNull() || u == "ANY") continue;
      bool ok = true;
      if (u == "INT" || u == "INTEGER") ok = v.t == VT::Int;
      else if (u == "REAL") ok = v.t == VT::Real;
      else if (u == "TEXT") ok = v.t == VT::Text;
      else if (u == "BLOB") ok = v.t == VT::Blob;
      if (!ok) throw SqlError("cannot store " + std::string(v.typeName()) + " value in " + u + " column " + t->name + "." + c.name, -1, 19);
    }
  }
  // CHECK constraints
  {
    Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
    for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
    cur.hiddenForStar.assign(t->cols.size(), false);
    cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
    cur.row = &vals; cur.rowid = rowid;
    Scope csc; csc.cursors.push_back(&cur); csc.parent = nullptr;
    for (size_t i = 0; i < t->cols.size(); i++) {
      for (auto& chk : t->cols[i].checks) {
        Value v = eval(chk, &csc);
        bool nul; if (!v.truthy(&nul) && !nul) {
          if (conflictError("CHECK constraint failed: " + checkExprText(chk.get(), t->sql), conflict == 5 ? 2 : 0)) return;
        }
      }
    }
    for (auto& tc : t->constraints) {
      if (tc.kind != TableConstraint::Check) continue;
      Value v = eval(tc.check, &csc);
      bool nul; if (!v.truthy(&nul) && !nul) {
        std::string nm = tc.name.empty() ? checkExprText(tc.check.get(), t->sql) : tc.name;
        if (conflictError("CHECK constraint failed: " + nm, conflict == 5 ? 2 : 0)) return;
      }
    }
  }
  // rowid uniqueness
  if (!t->withoutRowid) {
    auto it = t->rows.find(rowid);
    if (it != t->rows.end() && rowid != ignoreRowid) {
      int c = conflict ? conflict : 2;
      if (c == 5) toDelete.push_back(rowid);
      else {
        std::string cn = t->rowidCol >= 0 ? t->cols[t->rowidCol].name : "rowid";
        if (conflictError("UNIQUE constraint failed: " + t->name + "." + cn, 0)) return;
      }
    }
  }
  // UNIQUE / PK indexes
  std::vector<IndexP> idxs = db.indexesOf(t->name, sch);
  for (auto& ix : idxs) {
    if (!ix->unique) continue;
    // compute key for new row
    std::vector<Value> key;
    bool anyNull = false;
    Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
    for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
    cur.hiddenForStar.assign(t->cols.size(), false); cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
    Scope isc; isc.cursors.push_back(&cur);
    auto keyFor = [&](const Row& r, int64_t rid, std::vector<Value>& out) {
      cur.row = &r; cur.rowid = rid;
      for (auto& ic : ix->cols) {
        if (ic.col >= 0) out.push_back(r[ic.col]);
        else if (ic.col == -2) out.push_back(Value::Int(rid));
        else out.push_back(eval(ic.expr, &isc));
      }
    };
    if (ix->where) { cur.row = &vals; cur.rowid = rowid; Value w = eval(ix->where, &isc); bool nul; if (!w.truthy(&nul) || nul) continue; }
    keyFor(vals, rowid, key);
    for (auto& k : key) if (k.isNull()) anyNull = true;
    if (anyNull && !t->withoutRowid) continue;
    if (anyNull && t->withoutRowid && !ix->isPk) continue;
    std::vector<int> cids;
    for (size_t k = 0; k < ix->cols.size(); k++) {
      std::string coll = ix->cols[k].collate;
      if (coll.empty() && ix->cols[k].col >= 0) coll = t->cols[ix->cols[k].col].collate;
      cids.push_back(nameEq(coll, "NOCASE") ? 1 : (nameEq(coll, "RTRIM") ? 2 : 0));
    }
    for (auto& kv : t->rows) {
      if (kv.first == ignoreRowid) continue;
      if (ix->where) { cur.row = &kv.second; cur.rowid = kv.first; Value w = eval(ix->where, &isc); bool nul; if (!w.truthy(&nul) || nul) continue; }
      std::vector<Value> k2; keyFor(kv.second, kv.first, k2);
      bool eq = true;
      for (size_t k = 0; k < key.size(); k++) { if (k2[k].isNull()) { eq = false; break; } if (compareValues(key[k], k2[k], cids[k]) != 0 || (key[k].isText() != k2[k].isText())) { eq = false; break; } }
      if (eq) {
        int c = conflict ? conflict : (ix->conflict ? ix->conflict : 2);
        if (conflict == 0 && ix->conflict) c = ix->conflict;
        if (c == 5) { if (std::find(toDelete.begin(), toDelete.end(), kv.first) == toDelete.end()) toDelete.push_back(kv.first); }
        else {
          std::string msg = "UNIQUE constraint failed: ";
          bool first = true;
          for (auto& ic : ix->cols) {
            if (!first) msg += ", "; first = false;
            msg += t->name + "." + (ic.col >= 0 ? t->cols[ic.col].name : (ic.col == -2 ? "rowid" : "<expr>"));
          }
          if (conflictError(msg, 0)) return;
          break;
        }
      }
    }
  }
}

void Engine::fireTriggers(TableP t, int time, int event, const std::vector<std::string>* updCols, const Row* oldRow, int64_t oldRowid, const Row* newRow, int64_t newRowid, Scope* sc) {
  (void)sc;
  auto trigs = db.triggersOf(t->name);
  for (auto& tr : trigs) {
    if (tr->time != time || tr->event != event) continue;
    if (event == 3 && !tr->cols.empty() && updCols) {
      bool any = false;
      for (auto& c : tr->cols) for (auto& u : *updCols) if (nameEq(c, u)) any = true;
      if (!any) continue;
    }
    // recursion guard
    static thread_local std::vector<Trigger*> active;
    if (!db.recursiveTriggers && std::find(active.begin(), active.end(), tr.get()) != active.end()) continue;
    if (active.size() > 1000) throw SqlError("too many levels of trigger recursion");
    Cursor newC, oldC;
    auto setupPseudo = [&](Cursor& c, const char* nm, const Row* r, int64_t rid) {
      c.name = nm; c.tableName = t->name;
      for (auto& col : t->cols) { c.colNames.push_back(col.name); c.affs.push_back(col.aff); c.colls.push_back(col.collate); }
      c.hiddenForStar.assign(t->cols.size(), false);
      c.hasRowid = !t->withoutRowid; c.rowidCol = t->rowidCol;
      c.row = r; c.rowid = rid; c.isNullRow = (r == nullptr);
    };
    Scope tsc;
    if (newRow) { setupPseudo(newC, "new", newRow, newRowid); tsc.cursors.push_back(&newC); }
    if (oldRow) { setupPseudo(oldC, "old", oldRow, oldRowid); tsc.cursors.push_back(&oldC); }
    // WHEN
    if (tr->when) {
      Value w = eval(tr->when, &tsc);
      bool nul; if (!w.truthy(&nul) || nul) continue;
    }
    active.push_back(tr.get());
    struct Pop { std::vector<Trigger*>& a; ~Pop() { a.pop_back(); } } pop{active};
    bool savedInTrigger = inTrigger; inTrigger = true;
    int64_t savedChanges = db.changes;
    try {
      for (auto& body : tr->body) {
        // execute body statement with trigger scope; results discarded
        StmtP b = body;
        auto noHdr = [](const std::vector<std::string>&) {};
        auto noRow = [](const Row&) {};
        switch (b->kind) {
          case Stmt::Select: { Scope s2 = tsc; execSelect(b->select, &s2, noHdr, noRow); break; }
          case Stmt::Insert: execInsert(b, &tsc, noRow, noHdr); break;
          case Stmt::Update: execUpdate(b, &tsc, noRow, noHdr); break;
          case Stmt::Delete: execDelete(b, &tsc, noRow, noHdr); break;
          default: break;
        }
      }
    } catch (...) { inTrigger = savedInTrigger; db.changes = savedChanges; throw; }
    inTrigger = savedInTrigger;
    db.changes = savedChanges;
  }
}

static Cursor makeTableCursor(TableP t, const std::string& alias, const std::string& schemaName) {
  Cursor c;
  c.table = t; c.name = alias.empty() ? t->name : alias; c.tableName = t->name; c.schemaName = schemaName;
  for (auto& col : t->cols) { c.colNames.push_back(col.name); c.affs.push_back(col.aff); c.colls.push_back(col.collate); c.declTypes.push_back(col.type); }
  c.hiddenForStar.assign(t->cols.size(), false);
  for (size_t k = 0; k < t->cols.size(); k++) if (t->cols[k].hidden) c.hiddenForStar[k] = true;
  c.hasRowid = !t->withoutRowid; c.rowidCol = t->rowidCol;
  return c;
}

void Engine::runReturning(const StmtP& st, TableP t, const Row& row, int64_t rowid, Scope* sc, RowCallback onRow, HeaderCallback onHeader, bool& headerDone) {
  (void)sc;
  Cursor c = makeTableCursor(t, st->alias, "main");
  c.row = &row; c.rowid = rowid;
  Scope rs; rs.cursors.push_back(&c);
  std::vector<std::string> names; Row out;
  for (auto& rc : st->returning) {
    if (rc.e->kind == Expr::Star) {
      for (size_t k = 0; k < t->cols.size(); k++) { if (t->cols[k].hidden) continue; names.push_back(t->cols[k].name); out.push_back(row[k]); }
    } else {
      Value v = eval(rc.e, &rs);
      std::string nm;
      if (rc.hasAlias) nm = rc.alias;
      else {
        Expr* x = rc.e.get();
        while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
        if (x->kind == Expr::Column && x->resolved && !x->isRowid && x->colIdx >= 0) nm = t->cols[x->colIdx].name;
        else if (x->kind == Expr::Column && x->isRowid) nm = t->rowidCol >= 0 ? t->cols[t->rowidCol].name : "rowid";
        else nm = rc.spanText;
      }
      names.push_back(nm); out.push_back(v);
    }
  }
  if (!headerDone) { headerDone = true; onHeader(names); }
  onRow(out);
}

static void bindReturning(Engine* eng, const StmtP& st, TableP t) {
  Cursor c = makeTableCursor(t, st->alias, "main");
  Scope rs; rs.cursors.push_back(&c);
  for (auto& rc : st->returning) {
    if (rc.e->kind == Expr::Star) continue;
    // simple bind via eval on null row (resolves columns)
    std::function<void(Expr*)> walk = [&](Expr* e) {
      if (!e) return;
      if (e->kind == Expr::Column && !e->resolved) eng->resolveColumn(e, &rs);
      if (e->kind == Expr::Func) {
        int nArgs = 0; for (auto& a : e->args) if (a->kind != Expr::Star) nArgs++;
        extern int checkScalarFunction(const std::string&, int);
        extern bool isAggregateFunction(const std::string&, int, bool*);
        if (isAggregateFunction(e->op, nArgs, nullptr)) throw SqlError("misuse of aggregate function " + e->op + "()", e->start);
        int chk = checkScalarFunction(e->op, nArgs);
        if (chk == 0 && !jsonFunctionExists(e->op)) throw SqlError("no such function: " + e->op, e->start);
        if (chk == 2) throw SqlError("wrong number of arguments to function " + e->op + "()", e->start);
      }
      for (auto& a : e->args) walk(a.get());
      if (e->elseExpr) walk(e->elseExpr.get());
    };
    walk(rc.e.get());
  }
}

// ---------- INSERT ----------

void Engine::insertRow(TableP t, Schema* sch, Row& vals, int64_t* rowidIn, int conflict, Scope* sc, bool fromReplace) {
  (void)fromReplace;
  // rowid
  int64_t rowid;
  bool explicitRowid = false;
  if (!t->withoutRowid) {
    if (t->rowidCol >= 0 && !vals[t->rowidCol].isNull()) {
      Value v = vals[t->rowidCol];
      if (v.t == VT::Text) v = textToNumericIfPossible(v, true);
      if (v.t == VT::Real && v.r == (double)(int64_t)v.r && v.r < 9223372036854775808.0 && v.r >= -9223372036854775808.0) v = Value::Int((int64_t)v.r);
      if (v.t != VT::Int) throw SqlError("datatype mismatch", -1, 20);
      rowid = v.i; explicitRowid = true;
      vals[t->rowidCol] = v;
    } else if (rowidIn && *rowidIn != INT64_MIN) {
      rowid = *rowidIn; explicitRowid = true;
    } else {
      rowid = t->newRowid();
      if (t->autoinc) {
        TableP seq = db.main.findTable("sqlite_sequence");
        int64_t prev = 0; bool found = false;
        if (seq) for (auto& kv : seq->rows) if (kv.second.size() >= 2 && kv.second[0].isText() && kv.second[0].s == t->name) { prev = kv.second[1].toInt(); found = true; }
        (void)found;
        if (prev >= INT64_MAX) throw SqlError("database or disk is full", -1, 13);
        if (prev + 1 > rowid) rowid = prev + 1;
      }
      if (t->rowidCol >= 0) vals[t->rowidCol] = Value::Int(rowid);
    }
  } else {
    rowid = t->newRowid();
  }
  (void)explicitRowid;
  // constraints
  std::vector<int64_t> toDelete; bool skip = false;
  try {
    checkConstraints(t, sch, vals, rowid, INT64_MIN, conflict, toDelete, skip, sc);
  } catch (SqlError& err) {
    if (err.code == -5) {
      // REPLACE on NOT NULL: substitute default and retry
      int ci = atoi(err.what() + strlen("__replace_default__"));
      Scope dsc; vals[ci] = applyAffinity(eval(t->cols[ci].dflt, &dsc), t->cols[ci].aff);
      insertRow(t, sch, vals, rowidIn, conflict, sc, fromReplace);
      return;
    }
    throw;
  }
  if (skip) return;
  for (int64_t rid : toDelete) {
    // REPLACE: delete conflicting rows (fire delete triggers only when recursive triggers enabled)
    auto it = t->rows.find(rid);
    if (it == t->rows.end()) continue;
    Row old = it->second;
    if (db.recursiveTriggers) fireTriggers(t, 1, 1, nullptr, &old, rid, nullptr, 0, sc);
    deleteRowRaw(t, rid);
    if (db.recursiveTriggers) fireTriggers(t, 2, 1, nullptr, &old, rid, nullptr, 0, sc);
  }
  t->rows[rowid] = vals;
  db.logUndo([t, rowid]() { t->rows.erase(rowid); });
  if (t->autoinc) {
    TableP seq = db.main.findTable("sqlite_sequence");
    if (seq) {
      bool found = false;
      for (auto& kv : seq->rows) {
        if (kv.second.size() >= 2 && kv.second[0].isText() && kv.second[0].s == t->name) {
          found = true;
          if (kv.second[1].toInt() < rowid) {
            int64_t rid = kv.first; Row old = kv.second;
            kv.second[1] = Value::Int(rowid);
            db.logUndo([seq, rid, old]() { seq->rows[rid] = old; });
          }
        }
      }
      if (!found) {
        int64_t rid = seq->newRowid();
        seq->rows[rid] = Row{Value::Text(t->name), Value::Int(rowid)};
        db.logUndo([seq, rid]() { seq->rows.erase(rid); });
      }
    }
  }
  db.lastInsertRowid = rowid;
  db.changes++;
  db.totalChanges++;
}

void Engine::execInsert(const StmtP& st, Scope* parent, RowCallback onRow, HeaderCallback onHeader) {
  Schema* sch = nullptr;
  TableP t = resolveTable(st->schema, st->table, &sch, -1);
  if (t->isView) {
    // INSTEAD OF triggers
    auto trigs = db.triggersOf(t->name);
    bool has = false; for (auto& tr : trigs) if (tr->time == 3 && tr->event == 2) has = true;
    if (!has) throw SqlError("cannot modify " + t->name + " because it is a view");
  }
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0 && !db.writableSchema && lowerStr(t->name) != "sqlite_sequence") throw SqlError("table " + t->name + " may not be modified");
  if (db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  if (db.readOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  // CTE scope
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes; std::vector<std::shared_ptr<CteDef>> defs;
  Scope* p = parent;
  if (!st->ctes.empty()) {
    for (auto& c : st->ctes) { auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope; defs.push_back(d); ctes[lowerStr(c.name)] = d.get(); }
    cteScope.ctes = &ctes; p = &cteScope;
  }
  // target columns
  std::vector<int> targetCols;
  int nVisible = 0;
  for (auto& c : t->cols) if (!c.isGenerated && !c.hidden) nVisible++;
  if (!st->columns.empty()) {
    for (auto& cn : st->columns) {
      int ci = t->colIndex(cn);
      if (ci < 0) {
        if (nameEq(cn, "rowid") || nameEq(cn, "oid") || nameEq(cn, "_rowid_")) { if (!t->withoutRowid) { targetCols.push_back(-1); continue; } }
        throw SqlError("table " + t->name + " has no column named " + cn);
      }
      if (t->cols[ci].isGenerated) throw SqlError("cannot INSERT into generated column \"" + t->cols[ci].name + "\"");
      targetCols.push_back(ci);
    }
  } else {
    for (size_t i = 0; i < t->cols.size(); i++) if (!t->cols[i].isGenerated && !t->cols[i].hidden) targetCols.push_back((int)i);
  }
  // Source rows
  std::vector<Row> src;
  if (st->defaultValues) {
    src.push_back(Row{});
  } else {
    // check column count at bind time for VALUES
    std::vector<std::string> names;
    if (st->select->cores.size() == 1 && st->select->cores[0]->isValues && st->select->ctes.empty()) {
      auto& core = st->select->cores[0];
      // VALUES: evaluate rows directly (allows per-row column count checks)
      size_t nv = core->values[0].size();
      if (nv != targetCols.size()) {
        if (st->columns.empty()) throw SqlError("table " + t->name + " has " + std::to_string(nVisible) + " columns but " + std::to_string(nv) + " values were supplied");
        throw SqlError(std::to_string(nv) + " values for " + std::to_string(targetCols.size()) + " columns");
      }
      for (auto& row : core->values) if (row.size() != nv) throw SqlError("all VALUES must have the same number of terms");
      if (st->upsert && !st->hasReturning) {}
      // bind expressions
      for (auto& row : core->values) for (auto& e : row) {
        std::function<void(Expr*)> walk = [&](Expr* x) {
          if (!x) return;
          if (x->kind == Expr::Column && !x->resolved) resolveColumn(x, p);
          if (x->kind == Expr::Subquery || x->kind == Expr::Exists || (x->kind == Expr::In && x->sub)) { selectColumnNames(x->sub, p); return; }
          if (x->kind == Expr::Func) {
            int nArgs = 0; for (auto& a : x->args) if (a->kind != Expr::Star) nArgs++;
            extern int checkScalarFunction(const std::string&, int); extern bool isAggregateFunction(const std::string&, int, bool*);
            if (isAggregateFunction(x->op, nArgs, nullptr) && !(nArgs >= 2 && (x->op == "min" || x->op == "max"))) throw SqlError("misuse of aggregate function " + x->op + "()", x->start);
            int chk = checkScalarFunction(x->op, nArgs);
            if (chk == 0 && !jsonFunctionExists(x->op)) throw SqlError("no such function: " + x->op, x->start);
            if (chk == 2) throw SqlError("wrong number of arguments to function " + x->op + "()", x->start);
          }
          for (auto& a : x->args) walk(a.get());
          if (x->elseExpr) walk(x->elseExpr.get());
        };
        walk(e.get());
      }
      if (st->hasReturning) bindReturning(this, st, t);
      for (auto& row : core->values) {
        Row r; for (auto& e : row) r.push_back(eval(e, p));
        src.push_back(r);
      }
    } else {
      names = selectColumnNames(st->select, p);
      if (names.size() != targetCols.size()) {
        if (st->columns.empty()) throw SqlError("table " + t->name + " has " + std::to_string(nVisible) + " columns but " + std::to_string(names.size()) + " values were supplied");
        throw SqlError(std::to_string(names.size()) + " values for " + std::to_string(targetCols.size()) + " columns");
      }
      if (st->hasReturning) bindReturning(this, st, t);
      materializeSelect(st->select, p, src, names);
    }
  }
  bool headerDone = false;
  std::vector<std::pair<Row, int64_t>> returningRows;
  int conflict = st->orConflict;
  bool isView = t->isView;
  for (auto& srow : src) {
    Row vals(t->cols.size());
    // defaults
    Scope dsc;
    for (size_t i = 0; i < t->cols.size(); i++) {
      if (t->cols[i].hasDefault && t->cols[i].dflt) vals[i] = applyAffinity(eval(t->cols[i].dflt, &dsc), t->cols[i].aff);
      else vals[i] = Value::Null();
    }
    int64_t explicitRowid = INT64_MIN;
    for (size_t k = 0; k < targetCols.size(); k++) {
      int ci = targetCols[k];
      if (ci < 0) { Value v = srow[k]; if (v.t == VT::Text) v = textToNumericIfPossible(v, true); if (v.t != VT::Int && !v.isNull()) throw SqlError("datatype mismatch", -1, 20); if (!v.isNull()) explicitRowid = v.i; continue; }
      vals[ci] = applyAffinity(srow[k], t->cols[ci].aff);
    }
    if (isView) {
      // INSTEAD OF INSERT triggers
      size_t nvals = vals.size();
      (void)nvals;
      Row newRow = vals;
      fireTriggers(t, 3, 2, nullptr, nullptr, 0, &newRow, 0, p);
      continue;
    }
    computeGenerated(this, t, vals);
    // BEFORE triggers
    bool before = hasTriggers(t, 2);
    int64_t preRowid = explicitRowid;
    if (before) {
      if (preRowid == INT64_MIN && !t->withoutRowid) {
        if (t->rowidCol >= 0 && !vals[t->rowidCol].isNull()) preRowid = vals[t->rowidCol].toInt();
        else { preRowid = t->newRowid(); if (t->rowidCol >= 0) vals[t->rowidCol] = Value::Int(preRowid); }
      }
      try { fireTriggers(t, 1, 2, nullptr, nullptr, 0, &vals, preRowid, p); }
      catch (IgnoreSignal&) { continue; }
    }
    // UPSERT handling
    if (!st->upserts.empty()) {
      std::vector<int64_t> conf; bool skip = false;
      bool conflictFound = false;
      try { checkConstraints(t, sch, vals, (t->rowidCol >= 0 && !vals[t->rowidCol].isNull()) ? vals[t->rowidCol].toInt() : (explicitRowid != INT64_MIN ? explicitRowid : t->newRowid()), INT64_MIN, 5, conf, skip, p); }
      catch (SqlError& err) { if (err.code == -5) throw SqlError("NOT NULL constraint failed: " + t->name + "." + t->cols[atoi(err.what() + 19)].name, -1, 19); throw; }
      if (!conf.empty()) conflictFound = true;
      if (conflictFound) {
        // pick the upsert clause: first matching target or the catch-all
        std::shared_ptr<Upsert> up;
        for (auto& u : st->upserts) {
          if (!u->hasTarget) { up = u; break; }
          // match target columns against unique index on the conflicting row
          up = u; break;  // simplified: use first
        }
        if (!up) throw SqlError("UNIQUE constraint failed");
        if (up->doNothing) continue;
        int64_t crid = conf[0];
        Row oldRow = t->rows[crid];
        // scope: excluded + table
        Cursor tc = makeTableCursor(t, st->alias, "main"); tc.row = &oldRow; tc.rowid = crid;
        Cursor exc = makeTableCursor(t, "excluded", "main"); exc.row = &vals; exc.rowid = crid;
        Scope usc; usc.cursors.push_back(&tc); usc.cursors.push_back(&exc); usc.parent = p;
        if (up->where) { Value w = eval(up->where, &usc); bool nul; if (!w.truthy(&nul) || nul) continue; }
        Row newRow = oldRow;
        for (auto& set : up->sets) {
          Value v = eval(set.second, &usc);
          if (set.first.size() == 1) {
            int ci = t->colIndex(set.first[0]);
            if (ci < 0) throw SqlError("no such column: " + set.first[0]);
            newRow[ci] = applyAffinity(v, t->cols[ci].aff);
          }
        }
        computeGenerated(this, t, newRow);
        int64_t newRid = crid;
        if (t->rowidCol >= 0 && !newRow[t->rowidCol].isNull()) newRid = newRow[t->rowidCol].toInt();
        std::vector<int64_t> del; bool sk = false;
        checkConstraints(t, sch, newRow, newRid, crid, 2, del, sk, p);
        fireTriggers(t, 1, 3, nullptr, &oldRow, crid, &newRow, newRid, p);
        if (newRid != crid) deleteRowRaw(t, crid);
        Row prev = t->rows.count(newRid) ? t->rows[newRid] : Row{}; bool existed = t->rows.count(newRid) > 0;
        t->rows[newRid] = newRow;
        db.logUndo([t, newRid, prev, existed]() { if (existed) t->rows[newRid] = prev; else t->rows.erase(newRid); });
        db.changes++; db.totalChanges++;
        fireTriggers(t, 2, 3, nullptr, &oldRow, crid, &newRow, newRid, p);
        if (st->hasReturning) returningRows.push_back({newRow, newRid});
        continue;
      }
    }
    try {
      size_t before_n = t->rows.size(); (void)before_n;
      int64_t rin = explicitRowid;
      int64_t* rp = (rin != INT64_MIN) ? &rin : nullptr;
      int64_t sentinel = INT64_MIN;
      if (!rp) { sentinel = INT64_MIN; rp = &sentinel; }
      int64_t changesBefore = db.changes;
      insertRow(t, sch, vals, rp, conflict, p);
      if (db.changes == changesBefore) continue;  // ignored
    } catch (SqlError& err) {
      if (err.code == 1003) { throw SqlError(err.what(), -1, 19); } // FAIL: propagate without statement rollback marker
      throw;
    }
    int64_t rid = db.lastInsertRowid;
    if (hasTriggers(t, 2)) {
      Row inserted = t->rows[rid];
      try { fireTriggers(t, 2, 2, nullptr, nullptr, 0, &inserted, rid, p); } catch (IgnoreSignal&) {}
    }
    if (st->hasReturning) returningRows.push_back({t->rows[rid], rid});
  }
  if (st->hasReturning) {
    for (auto& rr : returningRows) runReturning(st, t, rr.first, rr.second, p, onRow, onHeader, headerDone);
  }
}

// ---------- UPDATE ----------

void Engine::execUpdate(const StmtP& st, Scope* parent, RowCallback onRow, HeaderCallback onHeader) {
  Schema* sch = nullptr;
  TableP t = resolveTable(st->schema, st->table, &sch, -1);
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0 && !db.writableSchema && lowerStr(t->name) != "sqlite_sequence") throw SqlError("table " + t->name + " may not be modified");
  if (db.queryOnly || db.readOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  bool isView = t->isView;
  if (isView) {
    auto trigs = db.triggersOf(t->name);
    bool has = false; for (auto& tr : trigs) if (tr->time == 3 && tr->event == 3) has = true;
    if (!has) throw SqlError("cannot modify " + t->name + " because it is a view");
  }
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes; std::vector<std::shared_ptr<CteDef>> defs;
  Scope* p = parent;
  if (!st->ctes.empty()) {
    for (auto& c : st->ctes) { auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope; defs.push_back(d); ctes[lowerStr(c.name)] = d.get(); }
    cteScope.ctes = &cteScope.ctes ? ctes : ctes; cteScope.ctes = &ctes; p = &cteScope;
  }
  // Build a SELECT to find matching rows: SELECT rowid FROM t [, from...] WHERE ...
  // Resolve SET columns
  std::vector<std::pair<std::vector<int>, ExprP>> sets;
  std::vector<std::string> updCols;
  for (auto& s : st->sets) {
    std::vector<int> cis;
    for (auto& cn : s.first) {
      int ci = t->colIndex(cn);
      if (ci < 0) {
        if (!t->withoutRowid && (nameEq(cn, "rowid") || nameEq(cn, "oid") || nameEq(cn, "_rowid_"))) ci = -1;
        else throw SqlError("no such column: " + cn, s.second ? -1 : -1);
      }
      if (ci >= 0 && t->cols[ci].isGenerated) throw SqlError("cannot UPDATE generated column \"" + t->cols[ci].name + "\"");
      cis.push_back(ci);
      updCols.push_back(ci >= 0 ? t->cols[ci].name : "rowid");
    }
    sets.push_back({cis, s.second});
  }
  // Set up scope: target cursor + FROM cursors
  Cursor tc = makeTableCursor(t, st->alias, sch ? sch->dbName : "main");
  if (isView) {
    // view: materialize rows
    std::string vsql = t->sql; auto stmts = parseSqlAll(vsql);
    std::vector<std::string> nm;
    materializeSelect(stmts[0]->select, p, tc.mat, nm);
    tc.table = nullptr; tc.hasRowid = false;
  }
  // FROM clause: build a core with target + from items (materialize via join loop reuse: simpler to bind manually)
  std::vector<Cursor> fromCursors;
  std::vector<SelectP> fromSubs;
  for (auto& it : st->from) {
    Cursor c;
    if (it.isSubquery) {
      std::vector<std::string> nm; materializeSelect(it.sub, p, c.mat, nm);
      c.colNames = nm; c.affs.assign(nm.size(), Aff::Blob); c.colls.assign(nm.size(), ""); c.hiddenForStar.assign(nm.size(), false);
      c.name = it.hasAlias ? it.alias : ""; c.isSubquery = true;
    } else {
      Schema* s2 = nullptr; TableP ft = resolveTable(it.schema, it.name, &s2, -1);
      if (ft->isView) {
        auto stmts = parseSqlAll(ft->sql); std::vector<std::string> nm; materializeSelect(stmts[0]->select, p, c.mat, nm);
        c.colNames = nm; c.affs.assign(nm.size(), Aff::Blob); c.colls.assign(nm.size(), ""); c.hiddenForStar.assign(nm.size(), false);
        c.name = it.hasAlias ? it.alias : ft->name; c.isSubquery = true;
      } else {
        c = makeTableCursor(ft, it.hasAlias ? it.alias : "", s2 ? s2->dbName : "main");
      }
    }
    c.on = it.join.on; c.joinType = it.join.type;
    fromCursors.push_back(c);
  }
  Scope sc; sc.parent = p; sc.cursors.push_back(&tc);
  for (auto& c : fromCursors) sc.cursors.push_back(&c);
  // bind
  for (auto& s : sets) {
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->resolved) resolveColumn(x, &sc);
      if (x->kind == Expr::Subquery || x->kind == Expr::Exists || (x->kind == Expr::In && x->sub)) { selectColumnNames(x->sub, &sc); return; }
      if (x->kind == Expr::Func) {
        int nArgs = 0; for (auto& a : x->args) if (a->kind != Expr::Star) nArgs++;
        extern int checkScalarFunction(const std::string&, int); extern bool isAggregateFunction(const std::string&, int, bool*);
        if (isAggregateFunction(x->op, nArgs, nullptr) && !(nArgs >= 2 && (x->op == "min" || x->op == "max"))) throw SqlError("misuse of aggregate function " + x->op + "()", x->start);
        int chk = checkScalarFunction(x->op, nArgs);
        if (chk == 0 && !jsonFunctionExists(x->op)) throw SqlError("no such function: " + x->op, x->start);
        if (chk == 2) throw SqlError("wrong number of arguments to function " + x->op + "()", x->start);
      }
      for (auto& a : x->args) walk(a.get());
      if (x->elseExpr) walk(x->elseExpr.get());
    };
    walk(s.second.get());
    if (st->where) walk(st->where.get());
    for (auto& c : fromCursors) if (c.on) walk(c.on.get());
  }
  if (st->where) {
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->resolved) resolveColumn(x, &sc);
      if (x->kind == Expr::Subquery || x->kind == Expr::Exists || (x->kind == Expr::In && x->sub)) { selectColumnNames(x->sub, &sc); return; }
      if (x->kind == Expr::Func) {
        int nArgs = 0; for (auto& a : x->args) if (a->kind != Expr::Star) nArgs++;
        extern int checkScalarFunction(const std::string&, int); extern bool isAggregateFunction(const std::string&, int, bool*);
        if (isAggregateFunction(x->op, nArgs, nullptr) && !(nArgs >= 2 && (x->op == "min" || x->op == "max"))) throw SqlError("misuse of aggregate function " + x->op + "()", x->start);
        int chk = checkScalarFunction(x->op, nArgs);
        if (chk == 0 && !jsonFunctionExists(x->op)) throw SqlError("no such function: " + x->op, x->start);
        if (chk == 2) throw SqlError("wrong number of arguments to function " + x->op + "()", x->start);
      }
      for (auto& a : x->args) walk(a.get());
      if (x->elseExpr) walk(x->elseExpr.get());
    };
    walk(st->where.get());
  }
  if (st->hasReturning) bindReturning(this, st, t);
  // Collect matching rows: (rowid, from-row-state)
  struct Match { int64_t rowid; std::vector<const Row*> fromRows; std::vector<int64_t> fromRowids; Row viewRow; };
  std::vector<Match> matches;
  auto evalWhere = [&]() -> bool {
    if (!st->where) return true;
    Value w = eval(st->where, &sc);
    bool nul; return w.truthy(&nul) && !nul;
  };
  std::function<void(size_t, Match&)> fromLoop = [&](size_t level, Match& m) {
    if (level == fromCursors.size()) {
      if (evalWhere()) {
        for (auto& c : fromCursors) { m.fromRows.push_back(c.row); m.fromRowids.push_back(c.rowid); }
        matches.push_back(m); m.fromRows.clear(); m.fromRowids.clear();
        throw 1;  // first match only
      }
      return;
    }
    Cursor& c = fromCursors[level];
    auto tryRow = [&]() {
      if (c.on) { Value v = eval(c.on, &sc); bool nul; if (!v.truthy(&nul) || nul) return; }
      fromLoop(level + 1, m);
    };
    if (c.table) { for (auto& kv : c.table->rows) { c.row = &kv.second; c.rowid = kv.first; tryRow(); } }
    else { for (size_t i = 0; i < c.mat.size(); i++) { c.row = &c.mat[i]; c.rowid = (int64_t)i + 1; tryRow(); } }
  };
  if (isView) {
    for (size_t i = 0; i < tc.mat.size(); i++) {
      tc.row = &tc.mat[i]; tc.rowid = (int64_t)i + 1;
      Match m; m.rowid = tc.rowid; m.viewRow = tc.mat[i];
      if (fromCursors.empty()) { if (evalWhere()) matches.push_back(m); }
      else { try { fromLoop(0, m); } catch (int) {} }
    }
  } else {
    for (auto& kv : t->rows) {
      tc.row = &kv.second; tc.rowid = kv.first;
      Match m; m.rowid = kv.first;
      if (fromCursors.empty()) { if (evalWhere()) matches.push_back(m); }
      else { try { fromLoop(0, m); } catch (int) {} }
    }
  }
  bool headerDone = false;
  std::vector<std::pair<Row, int64_t>> returningRows;
  int conflict = st->orConflict;
  for (auto& m : matches) {
    Row oldRow;
    if (isView) oldRow = m.viewRow;
    else { auto it = t->rows.find(m.rowid); if (it == t->rows.end()) continue; oldRow = it->second; }
    tc.row = isView ? &m.viewRow : &t->rows[m.rowid]; tc.rowid = m.rowid;
    for (size_t k = 0; k < fromCursors.size(); k++) { fromCursors[k].row = m.fromRows[k]; fromCursors[k].rowid = m.fromRowids[k]; }
    Row newRow = oldRow;
    int64_t newRowid = m.rowid;
    for (auto& s : sets) {
      Value v = eval(s.second, &sc);
      if (s.first.size() == 1) {
        int ci = s.first[0];
        if (ci < 0) { Value nv = v; if (nv.t == VT::Text) nv = textToNumericIfPossible(nv, true); if (nv.t != VT::Int) throw SqlError("datatype mismatch", -1, 20); newRowid = nv.i; }
        else newRow[ci] = applyAffinity(v, t->cols[ci].aff);
      } else {
        // row value assignment: v must be a Row expr evaluated -> evaluate args separately
        Expr* re = s.second.get();
        std::vector<Value> vals;
        if (re->kind == Expr::Row) for (auto& a : re->args) vals.push_back(eval(a, &sc));
        else if (re->kind == Expr::Subquery) { std::vector<Row> rows; std::vector<std::string> nm; materializeSelect(re->sub, &sc, rows, nm); if (!rows.empty()) vals = rows[0]; else vals.assign(s.first.size(), Value::Null()); }
        if (vals.size() != s.first.size()) throw SqlError(std::to_string(s.first.size()) + " columns assigned " + std::to_string(vals.size()) + " values");
        for (size_t k = 0; k < s.first.size(); k++) { int ci = s.first[k]; if (ci >= 0) newRow[ci] = applyAffinity(vals[k], t->cols[ci].aff); }
      }
    }
    if (isView) {
      fireTriggers(t, 3, 3, &updCols, &oldRow, m.rowid, &newRow, m.rowid, p);
      continue;
    }
    if (t->rowidCol >= 0) {
      Value v = newRow[t->rowidCol];
      if (v.isNull()) throw SqlError("datatype mismatch", -1, 20);
      if (v.t == VT::Text) v = textToNumericIfPossible(v, true);
      if (v.t == VT::Real && v.r == (double)(int64_t)v.r) v = Value::Int((int64_t)v.r);
      if (v.t != VT::Int) throw SqlError("datatype mismatch", -1, 20);
      newRow[t->rowidCol] = v; newRowid = v.i;
    }
    computeGenerated(this, t, newRow);
    try { fireTriggers(t, 1, 3, &updCols, &oldRow, m.rowid, &newRow, newRowid, p); }
    catch (IgnoreSignal&) { continue; }
    std::vector<int64_t> toDelete; bool skip = false;
    try {
      checkConstraints(t, sch, newRow, newRowid, m.rowid, conflict, toDelete, skip, p);
    } catch (SqlError& err) {
      if (err.code == -5) {
        int ci = atoi(err.what() + 19);
        Scope dsc; newRow[ci] = applyAffinity(eval(t->cols[ci].dflt, &dsc), t->cols[ci].aff);
        checkConstraints(t, sch, newRow, newRowid, m.rowid, conflict, toDelete, skip, p);
      } else throw;
    }
    if (skip) continue;
    for (int64_t rid : toDelete) { if (rid != m.rowid) deleteRowRaw(t, rid); }
    if (newRowid != m.rowid) {
      deleteRowRaw(t, m.rowid);
      bool existed = t->rows.count(newRowid) > 0; Row prev = existed ? t->rows[newRowid] : Row{};
      t->rows[newRowid] = newRow;
      db.logUndo([t, newRowid, prev, existed]() { if (existed) t->rows[newRowid] = prev; else t->rows.erase(newRowid); });
    } else {
      t->rows[m.rowid] = newRow;
      db.logUndo([t, m, oldRow]() { t->rows[m.rowid] = oldRow; });
    }
    db.changes++; db.totalChanges++;
    try { fireTriggers(t, 2, 3, &updCols, &oldRow, m.rowid, &newRow, newRowid, p); } catch (IgnoreSignal&) {}
    if (st->hasReturning) returningRows.push_back({newRow, newRowid});
  }
  if (st->hasReturning) for (auto& rr : returningRows) runReturning(st, t, rr.first, rr.second, p, onRow, onHeader, headerDone);
}

// ---------- DELETE ----------

void Engine::execDelete(const StmtP& st, Scope* parent, RowCallback onRow, HeaderCallback onHeader) {
  Schema* sch = nullptr;
  TableP t = resolveTable(st->schema, st->table, &sch, -1);
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0 && !db.writableSchema && lowerStr(t->name) != "sqlite_sequence") throw SqlError("table " + t->name + " may not be modified");
  if (db.queryOnly || db.readOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  bool isView = t->isView;
  if (isView) {
    auto trigs = db.triggersOf(t->name);
    bool has = false; for (auto& tr : trigs) if (tr->time == 3 && tr->event == 1) has = true;
    if (!has) throw SqlError("cannot modify " + t->name + " because it is a view");
  }
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes; std::vector<std::shared_ptr<CteDef>> defs;
  Scope* p = parent;
  if (!st->ctes.empty()) {
    for (auto& c : st->ctes) { auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope; defs.push_back(d); ctes[lowerStr(c.name)] = d.get(); }
    cteScope.ctes = &ctes; p = &cteScope;
  }
  Cursor tc = makeTableCursor(t, st->alias, sch ? sch->dbName : "main");
  if (isView) { auto stmts = parseSqlAll(t->sql); std::vector<std::string> nm; materializeSelect(stmts[0]->select, p, tc.mat, nm); tc.table = nullptr; tc.hasRowid = false; }
  Scope sc; sc.parent = p; sc.cursors.push_back(&tc);
  if (st->where) {
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->resolved) resolveColumn(x, &sc);
      if (x->kind == Expr::Subquery || x->kind == Expr::Exists || (x->kind == Expr::In && x->sub)) { selectColumnNames(x->sub, &sc); return; }
      if (x->kind == Expr::Func) {
        int nArgs = 0; for (auto& a : x->args) if (a->kind != Expr::Star) nArgs++;
        extern int checkScalarFunction(const std::string&, int); extern bool isAggregateFunction(const std::string&, int, bool*);
        if (isAggregateFunction(x->op, nArgs, nullptr) && !(nArgs >= 2 && (x->op == "min" || x->op == "max"))) throw SqlError("misuse of aggregate function " + x->op + "()", x->start);
        int chk = checkScalarFunction(x->op, nArgs);
        if (chk == 0 && !jsonFunctionExists(x->op)) throw SqlError("no such function: " + x->op, x->start);
        if (chk == 2) throw SqlError("wrong number of arguments to function " + x->op + "()", x->start);
      }
      for (auto& a : x->args) walk(a.get());
      if (x->elseExpr) walk(x->elseExpr.get());
    };
    walk(st->where.get());
  }
  if (st->hasReturning) bindReturning(this, st, t);
  std::vector<int64_t> targets;
  std::vector<Row> viewRows;
  if (isView) {
    for (size_t i = 0; i < tc.mat.size(); i++) {
      tc.row = &tc.mat[i]; tc.rowid = (int64_t)i + 1;
      bool ok = true;
      if (st->where) { Value w = eval(st->where, &sc); bool nul; ok = w.truthy(&nul) && !nul; }
      if (ok) viewRows.push_back(tc.mat[i]);
    }
    for (auto& r : viewRows) fireTriggers(t, 3, 1, nullptr, &r, 0, nullptr, 0, p);
    return;
  }
  for (auto& kv : t->rows) {
    tc.row = &kv.second; tc.rowid = kv.first;
    bool ok = true;
    if (st->where) { Value w = eval(st->where, &sc); bool nul; ok = w.truthy(&nul) && !nul; }
    if (ok) targets.push_back(kv.first);
  }
  bool headerDone = false;
  std::vector<std::pair<Row, int64_t>> returningRows;
  for (int64_t rid : targets) {
    auto it = t->rows.find(rid);
    if (it == t->rows.end()) continue;
    Row old = it->second;
    try { fireTriggers(t, 1, 1, nullptr, &old, rid, nullptr, 0, p); } catch (IgnoreSignal&) { continue; }
    if (t->rows.find(rid) == t->rows.end()) continue;
    deleteRowRaw(t, rid);
    db.changes++; db.totalChanges++;
    try { fireTriggers(t, 2, 1, nullptr, &old, rid, nullptr, 0, p); } catch (IgnoreSignal&) {}
    if (st->hasReturning) returningRows.push_back({old, rid});
  }
  if (st->hasReturning) for (auto& rr : returningRows) runReturning(st, t, rr.first, rr.second, p, onRow, onHeader, headerDone);
}
