cd /workspace && cat > src/ddl.cpp <<'EOF'
// DDL, transactions dispatch, PRAGMA
#include "engine.h"
#include "parser.h"
#include <algorithm>
#include <set>
#include <cstring>

const char** compileOptions();

static int nextRootPage(Schema& s) {
  int mx = 1;
  for (auto& e : s.entries) if (e.rootpage > mx) mx = e.rootpage;
  return mx + 1;
}

static size_t findNameOffset(const std::string& text) {
  auto toks = tokenize(text);
  size_t i = 0;
  while (i < toks.size() && toks[i].type != TT::END) {
    if (toks[i].type == TT::KW && (toks[i].kw == "TABLE" || toks[i].kw == "INDEX" || toks[i].kw == "VIEW" || toks[i].kw == "TRIGGER")) { i++; break; }
    i++;
  }
  if (i < toks.size() && toks[i].type == TT::KW && toks[i].kw == "IF") i += 3;
  if (i < toks.size()) {
    // skip schema prefix
    if (i + 2 < toks.size() && toks[i + 1].type == TT::OP && toks[i + 1].text == ".") return toks[i + 2].pos;
    return toks[i].pos;
  }
  return 0;
}

static std::string makeCreateSql(const std::string& text, const std::string& kind) {
  size_t off = findNameOffset(text);
  std::string rest = text.substr(off);
  while (!rest.empty() && isspace((unsigned char)rest.back())) rest.pop_back();
  return "CREATE " + kind + " " + rest;
}

static void checkReservedName(const std::string& name, const std::string& what) {
  if (lowerStr(name).compare(0, 7, "sqlite_") == 0) throw SqlError("object name reserved for internal use: " + name);
  (void)what;
}

void Engine::execCreateTable(const StmtP& st) {
  Schema* sch = st->temp ? &db.temp : (st->schema.empty() ? &db.main : db.schemaByName(st->schema));
  if (!sch) throw SqlError("unknown database " + st->schema);
  if (st->temp && !st->schema.empty() && !nameEq(st->schema, "temp")) throw SqlError("temporary table name must be unqualified");
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  // existence check
  TableP existing = db.findTable(st->schema.empty() && !st->temp ? "" : (st->temp ? "temp" : st->schema), st->table);
  if (!existing && st->schema.empty() && !st->temp) existing = db.main.findTable(st->table) ? db.main.findTable(st->table) : db.temp.findTable(st->table);
  if (st->temp) existing = db.temp.findTable(st->table);
  else if (st->schema.empty()) existing = db.main.findTable(st->table) ? db.main.findTable(st->table) : db.temp.findTable(st->table);
  if (existing) {
    if (st->ifNotExists) return;
    int off = (int)findNameOffset(st->text) + st->start;
    throw SqlError((existing->isView ? "view " : "table ") + st->table + " already exists", off);
  }
  if (db.findIndex(st->temp ? "temp" : st->schema, st->table)) throw SqlError("there is already an index named " + st->table);
  checkReservedName(st->table, "table");
  TableP t;
  std::string sqlText;
  if (st->asSelect) {
    // CREATE TABLE AS SELECT
    std::vector<Row> rows; std::vector<std::string> names;
    materializeSelect(st->asSelect, nullptr, rows, names);
    t = std::make_shared<Table>();
    t->name = st->table;
    auto& bind = st->asSelect->cores[0]->bind;
    std::set<std::string> seen;
    for (size_t i = 0; i < names.size(); i++) {
      Column c; c.name = names[i];
      std::string key = lowerStr(c.name); int k = 1;
      while (seen.count(key)) { c.name = names[i] + ":" + std::to_string(k++); key = lowerStr(c.name); }
      seen.insert(key);
      // declared type from expression affinity
      Aff a = (bind && i < bind->colAffs.size()) ? bind->colAffs[i] : Aff::Blob;
      // for column refs use the declared type
      Expr* x = bind ? bind->cols[i].e.get() : nullptr;
      std::string decl;
      if (x) {
        while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
        if (x->kind == Expr::Column && x->resolved && !x->aliasTarget) {
          // find declared type via cursor
          Scope dummy;
          auto& cur = bind->cursors[x->srcIdx];
          if (cur->table && x->colIdx >= 0 && x->colIdx < (int)cur->table->cols.size()) decl = cur->table->cols[x->colIdx].type;
          else if (x->colIdx >= 0 && x->colIdx < (int)cur->declTypes.size()) decl = cur->declTypes[x->colIdx];
        }
      }
      if (decl.empty()) {
        switch (a) { case Aff::Text: decl = "TEXT"; break; case Aff::Integer: decl = "INT"; break; case Aff::Real: decl = "REAL"; break; case Aff::Numeric: decl = "NUM"; break; default: decl = ""; }
      }
      c.type = decl; c.aff = affinityFromType(decl);
      t->cols.push_back(c);
    }
    sqlText = "CREATE TABLE " + (st->table.find_first_of(" \t") != std::string::npos ? "\"" + st->table + "\"" : st->table) + "(";
    for (size_t i = 0; i < t->cols.size(); i++) {
      if (i) sqlText += ",";
      std::string nm = t->cols[i].name;
      bool needQuote = nm.empty();
      for (char ch : nm) if (!(isalnum((unsigned char)ch) || ch == '_' || (unsigned char)ch >= 0x80)) needQuote = true;
      if (!needQuote && isdigit((unsigned char)nm[0])) needQuote = true;
      if (!needQuote) { std::string up; for (char ch : nm) up.push_back(toupper((unsigned char)ch)); if (isKeyword(up)) needQuote = true; }
      if (needQuote) { sqlText += "\""; for (char ch : nm) { if (ch == '"') sqlText += "\"\""; else sqlText.push_back(ch); } sqlText += "\""; }
      else sqlText += nm;
      if (!t->cols[i].type.empty()) sqlText += " " + t->cols[i].type;
    }
    sqlText += ")";
    t->sql = sqlText;
    t->rootpage = nextRootPage(*sch);
    SchemaEntry e; e.type = "table"; e.name = t->name; e.tblName = t->name; e.rootpage = t->rootpage; e.sql = sqlText;
    sch->addEntry(e); sch->tables[lowerStr(t->name)] = t;
    TableP tp = t;
    Schema* sp = sch;
    db.logUndo([sp, tp]() { sp->removeEntry(tp->name); sp->tables.erase(lowerStr(tp->name)); });
    for (auto& r : rows) {
      Row vals(t->cols.size());
      for (size_t i = 0; i < t->cols.size(); i++) vals[i] = applyAffinity(r[i], t->cols[i].aff);
      int64_t rid = t->newRowid();
      t->rows[rid] = vals;
    }
    db.changes = 0;
    sch->schemaCookie++;
    return;
  }
  sqlText = makeCreateSql(st->text, "TABLE");
  t = buildTable(*st, sqlText, db);
  t->temp = st->temp;
  // validate defaults are constant etc; validate CHECK/generated expressions
  {
    Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
    for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
    cur.hiddenForStar.assign(t->cols.size(), false); cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
    Scope sc; sc.cursors.push_back(&cur);
    Row dummy(t->cols.size());
    cur.row = &dummy;
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->resolved) resolveColumn(x, &sc);
      if (x->kind == Expr::Subquery || x->kind == Expr::Exists) throw SqlError("subqueries prohibited in CHECK constraints");
      for (auto& a : x->args) walk(a.get());
      if (x->elseExpr) walk(x->elseExpr.get());
    };
    for (auto& c : t->cols) {
      for (auto& chk : c.checks) walk(chk.get());
      if (c.isGenerated) walk(c.generated.get());
      if (c.hasDefault && c.dflt) {
        // default must be constant
        bool constant = true;
        std::function<void(Expr*)> cw = [&](Expr* x) { if (!x) return; if (x->kind == Expr::Column || x->kind == Expr::Param || x->kind == Expr::Subquery) constant = false; for (auto& a : x->args) cw(a.get()); };
        cw(c.dflt.get());
        if (!constant) throw SqlError("default value of column [" + c.name + "] is not constant");
      }
    }
    for (auto& tc : t->constraints) if (tc.kind == TableConstraint::Check) walk(tc.check.get());
  }
  // sqlite_sequence
  if (t->autoinc && !sch->findTable("sqlite_sequence") && sch == &db.main) {
    // created after the table entry in sqlite
  }
  t->rootpage = nextRootPage(*sch);
  SchemaEntry e; e.type = "table"; e.name = t->name; e.tblName = t->name; e.rootpage = t->rootpage; e.sql = sqlText;
  sch->addEntry(e);
  sch->tables[lowerStr(t->name)] = t;
  // autoindexes for UNIQUE / PK
  int autoN = 1;
  std::vector<IndexP> created;
  auto addAuto = [&](const std::vector<IndexedColumn>& cols, bool isPk, int conflict) {
    auto ix = std::make_shared<Index>();
    ix->name = "sqlite_autoindex_" + t->name + "_" + std::to_string(autoN++);
    ix->tableName = t->name; ix->unique = true; ix->isPk = isPk; ix->autoIndex = true; ix->conflict = conflict;
    for (auto& ic : cols) {
      IndexCol c; c.col = t->colIndex(ic.name); c.collate = ic.collate; c.desc = ic.desc;
      if (c.col < 0 && ic.e) { c.expr = ic.e; }
      if (c.collate.empty() && c.col >= 0) c.collate = t->cols[c.col].collate;
      ix->cols.push_back(c);
    }
    ix->rootpage = (t->withoutRowid && isPk) ? t->rootpage : nextRootPage(*sch);
    SchemaEntry ie; ie.type = "index"; ie.name = ix->name; ie.tblName = t->name; ie.rootpage = ix->rootpage; ie.sqlNull = true;
    sch->addEntry(ie); sch->indexes[lowerStr(ix->name)] = ix;
    created.push_back(ix);
  };
  // column constraints in order
  for (auto& cd : st->colDefs) {
    if (cd.pk) {
      IndexedColumn ic; ic.name = cd.name; ic.desc = cd.pkDesc;
      if (t->rowidCol >= 0 && nameEq(t->cols[t->rowidCol].name, cd.name)) { /* rowid alias: no index */ }
      else addAuto({ic}, true, cd.pkConflict);
    }
    if (cd.unique) { IndexedColumn ic; ic.name = cd.name; addAuto({ic}, false, cd.uniqueConflict); }
  }
  for (auto& tc : st->constraints) {
    if (tc.kind == TableConstraint::PK) {
      bool isRowid = tc.cols.size() == 1 && t->rowidCol >= 0 && nameEq(t->cols[t->rowidCol].name, tc.cols[0].name);
      if (!isRowid) addAuto(tc.cols, true, tc.conflict);
    } else if (tc.kind == TableConstraint::Unique) addAuto(tc.cols, false, tc.conflict);
  }
  if (t->autoinc && !db.main.findTable("sqlite_sequence")) {
    auto sq = std::make_shared<Table>();
    sq->name = "sqlite_sequence";
    Column c1; c1.name = "name"; c1.aff = Aff::Blob; Column c2; c2.name = "seq"; c2.aff = Aff::Blob;
    sq->cols = {c1, c2};
    sq->sql = "CREATE TABLE sqlite_sequence(name,seq)";
    sq->rootpage = nextRootPage(db.main);
    SchemaEntry se; se.type = "table"; se.name = sq->name; se.tblName = sq->name; se.rootpage = sq->rootpage; se.sql = sq->sql;
    db.main.addEntry(se); db.main.tables["sqlite_sequence"] = sq;
    Database* dbp = &db;
    db.logUndo([dbp, sq]() { dbp->main.removeEntry(sq->name); dbp->main.tables.erase("sqlite_sequence"); });
  }
  Schema* sp = sch; TableP tp = t;
  db.logUndo([sp, tp, created]() {
    sp->removeEntry(tp->name); sp->tables.erase(lowerStr(tp->name));
    for (auto& ix : created) { sp->removeEntry(ix->name); sp->indexes.erase(lowerStr(ix->name)); }
  });
  sch->schemaCookie++;
}

void Engine::execCreateIndex(const StmtP& st) {
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  Schema* sch = nullptr;
  TableP t = db.findTable(st->schema, st->onTable, &sch);
  if (!t) throw SqlError("no such table: " + (st->schema.empty() ? "" : st->schema + ".") + st->onTable);
  if (t->isView) throw SqlError("views may not be indexed");
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0) throw SqlError("table " + t->name + " may not be indexed");
  if (db.findIndex("", st->indexName) || sch->findIndex(st->indexName)) {
    if (st->ifNotExists) return;
    throw SqlError("index " + st->indexName + " already exists", -1);
  }
  if (db.findTable("", st->indexName)) throw SqlError("there is already a table named " + st->indexName);
  checkReservedName(st->indexName, "index");
  auto ix = std::make_shared<Index>();
  ix->name = st->indexName; ix->tableName = t->name; ix->unique = st->unique; ix->where = st->where;
  ix->sql = makeCreateSql(st->text, st->unique ? "UNIQUE INDEX" : "INDEX");
  Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
  for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
  cur.hiddenForStar.assign(t->cols.size(), false); cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
  Scope sc; sc.cursors.push_back(&cur);
  for (auto& ic : st->indexCols) {
    IndexCol c; c.collate = ic.collate; c.desc = ic.desc;
    Expr* x = ic.e.get();
    while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
    if (x->kind == Expr::Column && x->table.empty()) {
      int ci = t->colIndex(x->column);
      if (ci < 0) {
        if (!t->withoutRowid && (nameEq(x->column, "rowid") || nameEq(x->column, "oid") || nameEq(x->column, "_rowid_"))) c.col = -2;
        else throw SqlError("no such column: " + x->column, x->start);
      } else c.col = ci;
      if (c.collate.empty() && c.col >= 0) c.collate = t->cols[c.col].collate;
    } else {
      std::function<void(Expr*)> walk = [&](Expr* e) {
        if (!e) return;
        if (e->kind == Expr::Column && !e->resolved) resolveColumn(e, &sc);
        if (e->kind == Expr::Subquery || e->kind == Expr::Exists) throw SqlError("subqueries prohibited in index expressions");
        for (auto& a : e->args) walk(a.get());
        if (e->elseExpr) walk(e->elseExpr.get());
      };
      walk(x);
      c.col = -1; c.expr = ic.e;
    }
    ix->cols.push_back(c);
  }
  if (ix->where) {
    std::function<void(Expr*)> walk = [&](Expr* e) {
      if (!e) return;
      if (e->kind == Expr::Column && !e->resolved) resolveColumn(e, &sc);
      for (auto& a : e->args) walk(a.get());
    };
    walk(ix->where.get());
  }
  // check uniqueness of existing rows
  if (ix->unique) {
    std::vector<std::pair<std::vector<Value>, int64_t>> keys;
    std::vector<int> cids;
    for (auto& c : ix->cols) cids.push_back(nameEq(c.collate, "NOCASE") ? 1 : (nameEq(c.collate, "RTRIM") ? 2 : 0));
    for (auto& kv : t->rows) {
      cur.row = &kv.second; cur.rowid = kv.first;
      if (ix->where) { Value w = eval(ix->where, &sc); bool nul; if (!w.truthy(&nul) || nul) continue; }
      std::vector<Value> key; bool anyNull = false;
      for (auto& c : ix->cols) { Value v = c.col >= 0 ? kv.second[c.col] : (c.col == -2 ? Value::Int(kv.first) : eval(c.expr, &sc)); if (v.isNull()) anyNull = true; key.push_back(v); }
      if (anyNull) continue;
      for (auto& k : keys) {
        bool eq = true;
        for (size_t i = 0; i < key.size(); i++) if (compareValues(k.first[i], key[i], cids[i]) != 0 || k.first[i].isText() != key[i].isText()) { eq = false; break; }
        if (eq) {
          std::string msg = "UNIQUE constraint failed: ";
          for (size_t i = 0; i < ix->cols.size(); i++) { if (i) msg += ", "; msg += t->name + "." + (ix->cols[i].col >= 0 ? t->cols[ix->cols[i].col].name : "rowid"); }
          throw SqlError(msg, -1, 19);
        }
      }
      keys.push_back({key, kv.first});
    }
  }
  ix->rootpage = nextRootPage(*sch);
  SchemaEntry e; e.type = "index"; e.name = ix->name; e.tblName = t->name; e.rootpage = ix->rootpage; e.sql = ix->sql;
  sch->addEntry(e); sch->indexes[lowerStr(ix->name)] = ix;
  Schema* sp = sch; IndexP ip = ix;
  db.logUndo([sp, ip]() { sp->removeEntry(ip->name); sp->indexes.erase(lowerStr(ip->name)); });
  sch->schemaCookie++;
}

void Engine::execCreateView(const StmtP& st) {
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  Schema* sch = st->temp ? &db.temp : (st->schema.empty() ? &db.main : db.schemaByName(st->schema));
  if (!sch) throw SqlError("unknown database " + st->schema);
  TableP existing = st->temp ? db.temp.findTable(st->table) : (st->schema.empty() ? (db.main.findTable(st->table) ? db.main.findTable(st->table) : db.temp.findTable(st->table)) : sch->findTable(st->table));
  if (existing) {
    if (st->ifNotExists) return;
    int off = (int)findNameOffset(st->text) + st->start;
    throw SqlError((existing->isView ? "view " : "table ") + st->table + " already exists", off);
  }
  checkReservedName(st->table, "view");
  // validate the select by binding
  std::vector<std::string> names = selectColumnNames(st->select, nullptr);
  if (!st->viewCols.empty() && st->viewCols.size() != names.size()) throw SqlError("expected " + std::to_string(st->viewCols.size()) + " columns for '" + st->table + "' but got " + std::to_string(names.size()));
  auto t = std::make_shared<Table>();
  t->name = st->table; t->isView = true; t->viewSelect = st->select; t->viewCols = st->viewCols; t->temp = st->temp;
  t->sql = makeCreateSql(st->text, "VIEW");
  std::vector<std::string> finalNames = st->viewCols.empty() ? names : st->viewCols;
  std::set<std::string> seen;
  for (size_t i = 0; i < finalNames.size(); i++) {
    Column c; c.name = finalNames[i];
    std::string key = lowerStr(c.name); int k = 1;
    while (seen.count(key)) { c.name = finalNames[i] + ":" + std::to_string(k++); key = lowerStr(c.name); }
    seen.insert(key);
    auto& bind = st->select->cores[0]->bind;
    c.aff = (bind && i < bind->colAffs.size()) ? bind->colAffs[i] : Aff::Blob;
    if (bind && i < bind->cols.size()) {
      Expr* x = bind->cols[i].e.get();
      while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
      if (x->kind == Expr::Column && x->resolved && !x->aliasTarget && x->srcIdx < (int)bind->cursors.size()) {
        auto& cur = bind->cursors[x->srcIdx];
        if (cur->table && x->colIdx >= 0 && x->colIdx < (int)cur->table->cols.size()) c.type = cur->table->cols[x->colIdx].type;
        else if (x->colIdx >= 0 && x->colIdx < (int)cur->declTypes.size()) c.type = cur->declTypes[x->colIdx];
      }
    }
    t->cols.push_back(c);
  }
  SchemaEntry e; e.type = "view"; e.name = t->name; e.tblName = t->name; e.rootpage = 0; e.sql = t->sql;
  sch->addEntry(e); sch->tables[lowerStr(t->name)] = t;
  Schema* sp = sch; TableP tp = t;
  db.logUndo([sp, tp]() { sp->removeEntry(tp->name); sp->tables.erase(lowerStr(tp->name)); });
  sch->schemaCookie++;
}

void Engine::execCreateTrigger(const StmtP& st) {
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  Schema* tsch = nullptr;
  TableP t = db.findTable(st->schema, st->table, &tsch);
  if (!t) throw SqlError("no such table: " + (st->schema.empty() ? "" : st->schema + ".") + st->table);
  Schema* sch = st->temp ? &db.temp : tsch;
  if (db.findTrigger("", st->triggerName)) {
    if (st->ifNotExists) return;
    throw SqlError("trigger " + st->triggerName + " already exists");
  }
  checkReservedName(st->triggerName, "trigger");
  if (t->isView && st->trigTime != 3) throw SqlError("cannot create " + std::string(st->trigTime == 2 ? "AFTER" : "BEFORE") + " trigger on view: " + t->name);
  if (!t->isView && st->trigTime == 3) throw SqlError("cannot create INSTEAD OF trigger on table: " + t->name);
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0) throw SqlError("cannot create trigger on system table");
  auto tr = std::make_shared<Trigger>();
  tr->name = st->triggerName; tr->tableName = t->name;
  tr->time = st->trigTime == 0 ? 1 : st->trigTime; tr->event = st->trigEvent; tr->cols = st->trigCols;
  tr->when = st->trigWhen; tr->body = st->trigBody; tr->temp = st->temp;
  tr->sql = makeCreateSql(st->text, "TRIGGER");
  for (auto& c : tr->cols) if (t->colIndex(c) < 0) throw SqlError("no such column: " + c);
  // validate body: NEW/OLD usage
  for (auto& b : tr->body) {
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->table.empty()) {
        if (nameEq(x->table, "new") && (tr->event == 1)) throw SqlError("no such column: " + x->table + "." + x->column);
        if (nameEq(x->table, "old") && (tr->event == 2)) throw SqlError("no such column: " + x->table + "." + x->column);
        if ((nameEq(x->table, "new") || nameEq(x->table, "old")) && t->colIndex(x->column) < 0 && !nameEq(x->column, "rowid")) throw SqlError("no such column: " + x->table + "." + x->column);
      }
      for (auto& a : x->args) walk(a.get());
      if (x->elseExpr) walk(x->elseExpr.get());
    };
    if (b->where) walk(b->where.get());
    for (auto& s : b->sets) walk(s.second.get());
    if (b->kind == Stmt::Insert || b->kind == Stmt::Update || b->kind == Stmt::Delete) {
      TableP bt = db.findTable(b->schema, b->table);
      if (!bt) throw SqlError("no such table: " + (b->schema.empty() ? "" : b->schema + ".") + b->table);
    }
  }
  if (tr->when) {
    std::function<void(Expr*)> walk = [&](Expr* x) {
      if (!x) return;
      if (x->kind == Expr::Column && !x->table.empty()) {
        if (nameEq(x->table, "new") && (tr->event == 1)) throw SqlError("no such column: " + x->table + "." + x->column);
        if (nameEq(x->table, "old") && (tr->event == 2)) throw SqlError("no such column: " + x->table + "." + x->column);
      }
      for (auto& a : x->args) walk(a.get());
    };
    walk(tr->when.get());
  }
  SchemaEntry e; e.type = "trigger"; e.name = tr->name; e.tblName = t->name; e.rootpage = 0; e.sql = tr->sql;
  sch->addEntry(e); sch->triggers[lowerStr(tr->name)] = tr;
  Schema* sp = sch; TriggerP tp = tr;
  db.logUndo([sp, tp]() { sp->removeEntry(tp->name); sp->triggers.erase(lowerStr(tp->name)); });
  sch->schemaCookie++;
}

void Engine::execDrop(const StmtP& st) {
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  Schema* sch = nullptr;
  if (st->dropKind == 1 || st->dropKind == 3) {
    TableP t = db.findTable(st->schema, st->table, &sch);
    if (!t) {
      if (st->ifExists) return;
      throw SqlError(std::string("no such ") + (st->dropKind == 1 ? "table" : "view") + ": " + (st->schema.empty() ? "" : st->schema + ".") + st->table);
    }
    if (st->dropKind == 1 && t->isView) throw SqlError("use DROP VIEW to delete view " + st->table);
    if (st->dropKind == 3 && !t->isView) throw SqlError("use DROP TABLE to delete table " + st->table);
    if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0) throw SqlError("table " + t->name + " may not be dropped");
    // remove indexes and triggers
    std::vector<SchemaEntry> savedEntries = sch->entries;
    std::map<std::string, IndexP> savedIdx = sch->indexes;
    std::map<std::string, TriggerP> savedTrg = sch->triggers;
    std::map<std::string, TriggerP> savedTempTrg = db.temp.triggers;
    std::vector<SchemaEntry> savedTempEntries = db.temp.entries;
    std::vector<std::string> toRemove;
    for (auto& e : sch->entries) if ((e.type == "index" || e.type == "trigger") && nameEq(e.tblName, t->name)) toRemove.push_back(e.name);
    for (auto& n : toRemove) { sch->removeEntry(n); sch->indexes.erase(lowerStr(n)); sch->triggers.erase(lowerStr(n)); }
    if (sch != &db.temp) {
      std::vector<std::string> tr2;
      for (auto& e : db.temp.entries) if (e.type == "trigger" && nameEq(e.tblName, t->name)) tr2.push_back(e.name);
      for (auto& n : tr2) { db.temp.removeEntry(n); db.temp.triggers.erase(lowerStr(n)); }
    }
    sch->removeEntry(t->name);
    sch->tables.erase(lowerStr(t->name));
    int64_t nrows = t->isView ? 0 : (int64_t)t->rows.size();
    // sqlite_sequence cleanup
    if (t->autoinc) {
      TableP seq = db.main.findTable("sqlite_sequence");
      if (seq) for (auto it = seq->rows.begin(); it != seq->rows.end();) { if (it->second[0].isText() && it->second[0].s == t->name) { Row old = it->second; int64_t rid = it->first; it = seq->rows.erase(it); db.logUndo([seq, rid, old]() { seq->rows[rid] = old; }); } else ++it; }
    }
    Schema* sp = sch; TableP tp = t; Database* dbp = &db;
    db.logUndo([sp, tp, savedEntries, savedIdx, savedTrg, savedTempTrg, savedTempEntries, dbp]() {
      sp->entries = savedEntries; sp->indexes = savedIdx; sp->triggers = savedTrg; sp->tables[lowerStr(tp->name)] = tp;
      if (sp != &dbp->temp) { dbp->temp.triggers = savedTempTrg; dbp->temp.entries = savedTempEntries; }
    });
    db.changes = nrows;  // sqlite reports rows deleted? Actually changes() unchanged by DROP; keep 0
    db.changes = 0;
    sch->schemaCookie++;
    return;
  }
  if (st->dropKind == 2) {
    IndexP ix = db.findIndex(st->schema, st->table, &sch);
    if (!ix) { if (st->ifExists) return; throw SqlError("no such index: " + (st->schema.empty() ? "" : st->schema + ".") + st->table); }
    if (ix->autoIndex) throw SqlError("index associated with UNIQUE or PRIMARY KEY constraint cannot be dropped");
    std::vector<SchemaEntry> saved = sch->entries;
    sch->removeEntry(ix->name); sch->indexes.erase(lowerStr(ix->name));
    Schema* sp = sch; IndexP ip = ix;
    db.logUndo([sp, ip, saved]() { sp->entries = saved; sp->indexes[lowerStr(ip->name)] = ip; });
    sch->schemaCookie++;
    return;
  }
  if (st->dropKind == 4) {
    TriggerP tr = db.findTrigger(st->schema, st->table, &sch);
    if (!tr) { if (st->ifExists) return; throw SqlError("no such trigger: " + (st->schema.empty() ? "" : st->schema + ".") + st->table); }
    std::vector<SchemaEntry> saved = sch->entries;
    sch->removeEntry(tr->name); sch->triggers.erase(lowerStr(tr->name));
    Schema* sp = sch; TriggerP tp = tr;
    db.logUndo([sp, tp, saved]() { sp->entries = saved; sp->triggers[lowerStr(tp->name)] = tp; });
    sch->schemaCookie++;
    return;
  }
}

// Replace an identifier token in SQL text (used by ALTER TABLE RENAME)
static std::string renameIdentInSql(const std::string& sql, const std::string& oldName, const std::string& newName, bool tableNameOnly, int occurrenceLimit) {
  auto toks = tokenize(sql, true);
  std::string out;
  int count = 0;
  for (size_t i = 0; i < toks.size(); i++) {
    const Token& t = toks[i];
    if (t.type == TT::END) break;
    bool isName = (t.type == TT::ID && nameEq(t.kw, oldName)) || (t.type == TT::KW && nameEq(t.text, oldName)) || (t.type == TT::STRING && nameEq(t.kw, oldName));
    if (isName && (occurrenceLimit < 0 || count < occurrenceLimit)) {
      count++;
      bool needQuote = false;
      for (char ch : newName) if (!(isalnum((unsigned char)ch) || ch == '_')) needQuote = true;
      std::string up; for (char ch : newName) up.push_back(toupper((unsigned char)ch));
      if (isKeyword(up)) needQuote = true;
      if (t.quoted || needQuote) { out += "\""; for (char ch : newName) { if (ch == '"') out += "\"\""; else out.push_back(ch); } out += "\""; }
      else out += newName;
      (void)tableNameOnly;
    } else out += t.text;
  }
  return out;
}

void Engine::execAlter(const StmtP& st) {
  if (db.readOnly || db.queryOnly) throw SqlError("attempt to write a readonly database", -1, 8);
  Schema* sch = nullptr;
  TableP t = db.findTable(st->schema, st->table, &sch);
  if (!t) throw SqlError("no such table: " + (st->schema.empty() ? "" : st->schema + ".") + st->table);
  if (t->isView && st->alterKind != 1) throw SqlError("cannot " + std::string(st->alterKind == 2 ? "add a column to" : st->alterKind == 3 ? "rename columns of" : "drop a column from") + " a view");
  if (lowerStr(t->name).compare(0, 7, "sqlite_") == 0) throw SqlError("table " + t->name + " may not be altered");
  if (st->alterKind == 1) {
    // RENAME TO
    if (db.findTable("", st->newName) || db.findIndex("", st->newName)) throw SqlError("there is already another table or index with this name: " + st->newName);
    std::string oldName = t->name;
    std::vector<SchemaEntry> saved = sch->entries;
    std::string savedSql = t->sql;
    TableP tp = t; Schema* sp = sch;
    auto savedTables = sch->tables;
    sch->tables.erase(lowerStr(oldName));
    t->name = st->newName;
    sch->tables[lowerStr(t->name)] = t;
    // rewrite CREATE statement text: replace table name token (first occurrence after CREATE TABLE/VIEW)
    {
      auto toks = tokenize(t->sql, true);
      std::string out; bool done = false; int kwSeen = 0;
      for (auto& tk : toks) {
        if (tk.type == TT::END) break;
        if (!done && kwSeen >= 1 && (tk.type == TT::ID || tk.type == TT::KW || tk.type == TT::STRING)) {
          if (tk.type == TT::KW && kwSeen == 1 && (tk.kw == "IF")) { out += tk.text; continue; }
          bool needQuote = false;
          for (char ch : t->name) if (!(isalnum((unsigned char)ch) || ch == '_')) needQuote = true;
          std::string up; for (char ch : t->name) up.push_back(toupper((unsigned char)ch));
          if (isKeyword(up) || needQuote || tk.quoted) { out += "\"" + t->name + "\""; }
          else out += t->name;
          done = true; continue;
        }
        if (tk.type == TT::KW && (tk.kw == "TABLE" || tk.kw == "VIEW")) kwSeen = 1;
        out += tk.text;
      }
      t->sql = out;
    }
    for (auto& e : sch->entries) {
      if (nameEq(e.name, oldName) && (e.type == "table" || e.type == "view")) { e.name = t->name; e.sql = t->sql; }
      if (nameEq(e.tblName, oldName)) e.tblName = t->name;
    }
    // indexes: update table name and sql
    for (auto& kv : sch->indexes) if (nameEq(kv.second->tableName, oldName)) {
      kv.second->tableName = t->name;
      if (!kv.second->sql.empty()) {
        // replace "ON oldname"
        auto toks = tokenize(kv.second->sql, true);
        std::string out; bool afterOn = false;
        for (auto& tk : toks) { if (tk.type == TT::END) break; if (afterOn && (tk.type == TT::ID || tk.type == TT::KW || tk.type == TT::STRING)) { out += (tk.quoted ? "\"" + t->name + "\"" : t->name); afterOn = false; continue; } if (tk.type == TT::KW && tk.kw == "ON") afterOn = true; out += tk.text; }
        kv.second->sql = out;
        for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = out;
      }
      // rename autoindex names
      if (kv.second->autoIndex) {
        std::string prefix = "sqlite_autoindex_" + oldName + "_";
        if (kv.second->name.compare(0, prefix.size(), prefix) == 0) {
          std::string nn = "sqlite_autoindex_" + t->name + "_" + kv.second->name.substr(prefix.size());
          for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.name = nn;
          kv.second->name = nn;
        }
      }
    }
    {
      std::map<std::string, IndexP> re;
      for (auto& kv : sch->indexes) re[lowerStr(kv.second->name)] = kv.second;
      sch->indexes = re;
    }
    // triggers on this table
    for (auto& kv : sch->triggers) if (nameEq(kv.second->tableName, oldName)) {
      kv.second->tableName = t->name;
      kv.second->sql = renameIdentInSql(kv.second->sql, oldName, t->name, true, -1);
      for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = kv.second->sql;
      // re-parse body
      auto stmts = parseSqlAll(kv.second->sql);
      if (!stmts.empty() && stmts[0]->kind == Stmt::CreateTrigger) { kv.second->body = stmts[0]->trigBody; kv.second->when = stmts[0]->trigWhen; }
    }
    // views referencing the table: rewrite sql
    for (auto& kv : sch->tables) if (kv.second->isView && kv.second != t) {
      std::string ns = renameIdentInSql(kv.second->sql, oldName, t->name, true, -1);
      if (ns != kv.second->sql) { kv.second->sql = ns; for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = ns; }
    }
    // FK references in other tables
    for (auto& kv : sch->tables) if (!kv.second->isView && kv.second != t) {
      bool changed = false;
      for (auto& c : kv.second->constraints) if (c.kind == TableConstraint::ForeignKey && nameEq(c.fkTable, oldName)) { c.fkTable = t->name; changed = true; }
      if (changed) { /* rewrite sql REFERENCES oldName */ 
        auto toks = tokenize(kv.second->sql, true); std::string out; bool afterRef = false;
        for (auto& tk : toks) { if (tk.type == TT::END) break; if (afterRef && (tk.type == TT::ID || tk.type == TT::KW || tk.type == TT::STRING) && nameEq(tk.type == TT::ID ? tk.kw : tk.text, oldName)) { out += (tk.quoted ? "\"" + t->name + "\"" : t->name); afterRef = false; continue; } afterRef = (tk.type == TT::KW && tk.kw == "REFERENCES") || (afterRef && tk.type == TT::SPACE); out += tk.text; }
        kv.second->sql = out; for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = out;
      }
    }
    auto newTables = sch->tables;
    db.logUndo([sp, tp, saved, savedSql, oldName, savedTables]() { tp->name = oldName; tp->sql = savedSql; sp->entries = saved; sp->tables = savedTables; });
    sch->schemaCookie++;
    return;
  }
  if (st->alterKind == 2) {
    // ADD COLUMN
    const ColumnDef& cd = st->addCol;
    if (t->colIndex(cd.name) >= 0) throw SqlError("duplicate column name: " + cd.name);
    if (cd.pk) throw SqlError("Cannot add a PRIMARY KEY column");
    if (cd.unique) throw SqlError("Cannot add a UNIQUE column");
    if (cd.notNull && !cd.hasDefault && !cd.isGenerated) throw SqlError("Cannot add a NOT NULL column with default value NULL");
    if (cd.hasDefault && cd.dflt) {
      bool constant = true;
      std::function<void(Expr*)> cw = [&](Expr* x) { if (!x) return; if (x->kind == Expr::Column || x->kind == Expr::Param || x->kind == Expr::Subquery || (x->kind == Expr::Func && (x->op == "current_time" || x->op == "current_date" || x->op == "current_timestamp"))) constant = false; for (auto& a : x->args) cw(a.get()); };
      cw(cd.dflt.get());
      if (!constant) throw SqlError("Cannot add a column with non-constant default");
      Scope dsc; Value dv = eval(cd.dflt, &dsc);
      if (cd.notNull && dv.isNull()) throw SqlError("Cannot add a NOT NULL column with default value NULL");
    }
    if (cd.isGenerated && cd.generatedStored == 1) throw SqlError("cannot add a STORED column");
    Column c;
    c.name = cd.name; c.type = cd.type; c.aff = affinityFromType(cd.type);
    c.notNull = cd.notNull; c.notNullConflict = cd.notNullConflict; c.hasDefault = cd.hasDefault; c.dflt = cd.dflt; c.dfltText = cd.dfltText;
    c.collate = cd.collate; c.checks = cd.checks; c.isGenerated = cd.isGenerated; c.generated = cd.generated; c.genStored = false;
    if (t->strict) {
      std::string u; for (char ch : cd.type) u.push_back(toupper((unsigned char)ch));
      if (!(u == "INT" || u == "INTEGER" || u == "REAL" || u == "TEXT" || u == "BLOB" || u == "ANY")) throw SqlError(u.empty() ? "missing datatype for " + t->name + "." + cd.name : "unknown datatype for " + t->name + "." + cd.name + ": \"" + cd.type + "\"");
    }
    std::string savedSql = t->sql;
    auto savedCols = t->cols;
    auto savedRows = t->rows;
    t->cols.push_back(c);
    Scope dsc;
    Value dv = c.hasDefault && c.dflt ? applyAffinity(eval(c.dflt, &dsc), c.aff) : Value::Null();
    for (auto& kv : t->rows) kv.second.push_back(dv);
    if (c.isGenerated) {
      Cursor cur; cur.table = t; cur.name = t->name; cur.tableName = t->name;
      for (auto& cc : t->cols) { cur.colNames.push_back(cc.name); cur.affs.push_back(cc.aff); cur.colls.push_back(cc.collate); }
      cur.hiddenForStar.assign(t->cols.size(), false); cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
      Scope sc; sc.cursors.push_back(&cur);
      for (auto& kv : t->rows) { cur.row = &kv.second; cur.rowid = kv.first; kv.second.back() = applyAffinity(eval(c.generated, &sc), c.aff); }
    }
    // modify sql: insert ", <coldef>" before the closing paren (and before WITHOUT ROWID/STRICT)
    {
      std::string s = t->sql;
      // find the matching close paren of the column list
      int depth = 0; size_t closePos = std::string::npos; size_t openPos = std::string::npos;
      auto toks = tokenize(s);
      for (auto& tk : toks) {
        if (tk.type == TT::OP && tk.text == "(") { if (depth == 0 && openPos == std::string::npos) openPos = tk.pos; depth++; }
        else if (tk.type == TT::OP && tk.text == ")") { depth--; if (depth == 0) { closePos = tk.pos; break; } }
      }
      if (closePos != std::string::npos) {
        std::string colText = st->addColText;
        while (!colText.empty() && isspace((unsigned char)colText.back())) colText.pop_back();
        s = s.substr(0, closePos) + ", " + colText + s.substr(closePos);
      }
      t->sql = s;
      for (auto& e : sch->entries) if (nameEq(e.name, t->name)) e.sql = s;
    }
    TableP tp = t; Schema* sp = sch;
    db.logUndo([tp, sp, savedSql, savedCols, savedRows]() { tp->sql = savedSql; tp->cols = savedCols; tp->rows = savedRows; for (auto& e : sp->entries) if (nameEq(e.name, tp->name)) e.sql = savedSql; });
    sch->schemaCookie++;
    return;
  }
  if (st->alterKind == 3) {
    // RENAME COLUMN
    int ci = t->colIndex(st->oldColName);
    if (ci < 0) throw SqlError("no such column: \"" + st->oldColName + "\"");
    if (t->colIndex(st->newColName) >= 0 && !nameEq(st->oldColName, st->newColName)) throw SqlError("duplicate column name: " + st->newColName);
    std::string savedSql = t->sql; auto savedCols = t->cols;
    std::string oldName = t->cols[ci].name;
    t->cols[ci].name = st->newColName;
    // rewrite sql: rename identifier tokens matching the column name within the CREATE TABLE text (skip table name)
    {
      auto toks = tokenize(t->sql, true);
      std::string out; int nameSeen = 0;
      for (auto& tk : toks) {
        if (tk.type == TT::END) break;
        bool isId = tk.type == TT::ID || (tk.type == TT::KW) || tk.type == TT::STRING;
        std::string nm = tk.type == TT::ID ? tk.kw : (tk.type == TT::STRING ? tk.kw : tk.text);
        if (isId && nameSeen == 0 && tk.type != TT::KW) { nameSeen = 1; out += tk.text; continue; }
        if (isId && nameSeen == 0 && tk.type == TT::KW && tk.kw != "TABLE" && tk.kw != "CREATE" && tk.kw != "TEMP" && tk.kw != "TEMPORARY" && tk.kw != "IF" && tk.kw != "NOT" && tk.kw != "EXISTS") { nameSeen = 1; out += tk.text; continue; }
        if (isId && nameSeen && nameEq(nm, oldName)) {
          bool needQuote = tk.quoted;
          for (char ch : st->newColName) if (!(isalnum((unsigned char)ch) || ch == '_')) needQuote = true;
          std::string up; for (char ch : st->newColName) up.push_back(toupper((unsigned char)ch));
          if (isKeyword(up)) needQuote = true;
          if (needQuote) out += "\"" + st->newColName + "\""; else out += st->newColName;
          continue;
        }
        out += tk.text;
      }
      t->sql = out;
      for (auto& e : sch->entries) if (nameEq(e.name, t->name)) e.sql = out;
    }
    // indexes referencing column
    for (auto& kv : sch->indexes) if (nameEq(kv.second->tableName, t->name) && !kv.second->sql.empty()) {
      auto toks = tokenize(kv.second->sql, true); std::string out; bool inParen = false;
      for (auto& tk : toks) { if (tk.type == TT::END) break; if (tk.type == TT::OP && tk.text == "(") inParen = true; if (inParen && (tk.type == TT::ID || tk.type == TT::STRING || tk.type == TT::KW) && nameEq(tk.type == TT::ID ? tk.kw : (tk.type == TT::STRING ? tk.kw : tk.text), oldName)) { out += (tk.quoted ? "\"" + st->newColName + "\"" : st->newColName); continue; } out += tk.text; }
      kv.second->sql = out; for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = out;
    }
    // triggers / views: rename occurrences (approximation)
    for (auto& kv : sch->triggers) if (nameEq(kv.second->tableName, t->name)) {
      std::string ns = renameIdentInSql(kv.second->sql, oldName, st->newColName, false, -1);
      if (ns != kv.second->sql) { kv.second->sql = ns; for (auto& e : sch->entries) if (nameEq(e.name, kv.second->name)) e.sql = ns; auto stmts = parseSqlAll(ns); if (!stmts.empty()) { kv.second->body = stmts[0]->trigBody; kv.second->when = stmts[0]->trigWhen; } }
    }
    TableP tp = t; Schema* sp = sch;
    db.logUndo([tp, sp, savedSql, savedCols]() { tp->sql = savedSql; tp->cols = savedCols; for (auto& e : sp->entries) if (nameEq(e.name, tp->name)) e.sql = savedSql; });
    sch->schemaCookie++;
    return;
  }
  if (st->alterKind == 4) {
    int ci = t->colIndex(st->oldColName);
    if (ci < 0) throw SqlError("no such column: \"" + st->oldColName + "\"");
    const Column& c = t->cols[ci];
    if (c.pk || (t->rowidCol == ci)) throw SqlError("cannot drop PRIMARY KEY column: \"" + c.name + "\"");
    if (c.unique) throw SqlError("cannot drop UNIQUE column: \"" + c.name + "\"");
    for (auto& ix : db.indexesOf(t->name, sch)) for (auto& icol : ix->cols) if (icol.col == ci) throw SqlError("error in index " + ix->name + " after drop column: no such column: " + c.name);
    for (auto& tc : t->constraints) {
      if (tc.kind == TableConstraint::PK || tc.kind == TableConstraint::Unique) for (auto& icol : tc.cols) if (nameEq(icol.name, c.name)) throw SqlError(std::string("cannot drop ") + (tc.kind == TableConstraint::PK ? "PRIMARY KEY" : "UNIQUE") + " column: \"" + c.name + "\"");
    }
    std::string savedSql = t->sql; auto savedCols = t->cols; auto savedRows = t->rows; int savedRowidCol = t->rowidCol;
    // rewrite sql: remove the column definition
    {
      auto toks = tokenize(t->sql, true);
      // locate column list; find the column def token range
      size_t open = 0; int depth = 0; std::vector<std::pair<size_t, size_t>> defs; size_t defStart = 0; bool inList = false;
      for (size_t i = 0; i < toks.size(); i++) {
        auto& tk = toks[i];
        if (tk.type == TT::OP && tk.text == "(") { if (depth == 0 && !inList) { inList = true; open = i; defStart = i + 1; } depth++; continue; }
        if (tk.type == TT::OP && tk.text == ")") { depth--; if (depth == 0 && inList) { defs.push_back({defStart, i}); break; } continue; }
        if (tk.type == TT::OP && tk.text == "," && depth == 1 && inList) { defs.push_back({defStart, i}); defStart = i + 1; }
      }
      (void)open;
      if (ci < (int)defs.size()) {
        auto d = defs[ci];
        std::string out;
        for (size_t i = 0; i < toks.size(); i++) {
          if (toks[i].type == TT::END) break;
          if (i >= d.first && i < d.second) continue;
          // remove the separating comma
          if (ci > 0 && i == d.first - 1 && toks[i].type == TT::OP && toks[i].text == ",") continue;
          if (ci == 0 && i == d.second && toks[i].type == TT::OP && toks[i].text == ",") continue;
          out += toks[i].text;
        }
        t->sql = out;
        for (auto& e : sch->entries) if (nameEq(e.name, t->name)) e.sql = out;
      }
    }
    t->cols.erase(t->cols.begin() + ci);
    if (t->rowidCol > ci) t->rowidCol--;
    for (auto& kv : t->rows) kv.second.erase(kv.second.begin() + ci);
    for (auto& ix : sch->indexes) for (auto& icol : ix.second->cols) if (nameEq(ix.second->tableName, t->name) && icol.col > ci) icol.col--;
    TableP tp = t; Schema* sp = sch;
    db.logUndo([tp, sp, savedSql, savedCols, savedRows, savedRowidCol]() { tp->sql = savedSql; tp->cols = savedCols; tp->rows = savedRows; tp->rowidCol = savedRowidCol; for (auto& e : sp->entries) if (nameEq(e.name, tp->name)) e.sql = savedSql; });
    sch->schemaCookie++;
    return;
  }
}

// ---------- PRAGMA ----------

static bool boolArg(const Value& v, bool& out) {
  std::string s = lowerStr(v.toText());
  if (v.t == VT::Int) { out = v.i != 0; return true; }
  if (s == "on" || s == "yes" || s == "true" || s == "1") { out = true; return true; }
  if (s == "off" || s == "no" || s == "false" || s == "0") { out = false; return true; }
  if (v.t == VT::Real) { out = v.r != 0; return true; }
  return false;
}

void Engine::execPragma(const StmtP& st, HeaderCallback onHeader, RowCallback onRow) {
  std::string name = lowerStr(st->pragmaName);
  Value arg;
  if (st->pragmaHasValue && st->pragmaValue) { Scope sc; arg = eval(st->pragmaValue, &sc); }
  Schema* sch = st->schema.empty() ? &db.main : db.schemaByName(st->schema);
  if (!sch) throw SqlError("unknown database " + st->schema);
  auto single = [&](const std::string& col, const Value& v) { onHeader({col}); onRow(Row{v}); };
  auto boolPragma = [&](bool& flag) {
    if (st->pragmaHasValue) { bool b; if (boolArg(arg, b)) flag = b; return; }
    single(name, Value::Int(flag ? 1 : 0));
  };
  if (name == "table_info" || name == "table_xinfo") {
    if (!st->pragmaHasValue) return;
    TableP t;
    try { t = resolveTable(st->schema, arg.toText(), nullptr, -1); } catch (SqlError&) { return; }
    bool x = name == "table_xinfo";
    if (x) onHeader({"cid","name","type","notnull","dflt_value","pk","hidden"}); else onHeader({"cid","name","type","notnull","dflt_value","pk"});
    int pkSeq = 0;
    std::vector<int> pkOrder(t->cols.size(), 0);
    for (int ci : t->pkCols) pkOrder[ci] = ++pkSeq;
    int cid = 0;
    for (size_t i = 0; i < t->cols.size(); i++) {
      const Column& c = t->cols[i];
      int hidden = c.isGenerated ? (c.genStored ? 3 : 2) : (c.hidden ? 1 : 0);
      if (!x && c.isGenerated) continue;
      Row r{Value::Int(cid++), Value::Text(c.name), Value::Text(c.type), Value::Int(c.notNull ? 1 : 0), c.hasDefault ? Value::Text(c.dfltText) : Value::Null(), Value::Int(pkOrder[i])};
      if (x) r.push_back(Value::Int(hidden));
      onRow(r);
    }
    return;
  }
  if (name == "index_list") {
    if (!st->pragmaHasValue) return;
    TableP t = db.findTable(st->schema, arg.toText());
    if (!t) return;
    onHeader({"seq","name","unique","origin","partial"});
    auto idxs = db.indexesOf(t->name);
    // sqlite lists most recently created first
    int seq = 0;
    for (int i = (int)idxs.size() - 1; i >= 0; i--) {
      auto& ix = idxs[i];
      onRow(Row{Value::Int(seq++), Value::Text(ix->name), Value::Int(ix->unique ? 1 : 0), Value::Text(ix->isPk ? "pk" : (ix->autoIndex ? "u" : "c")), Value::Int(ix->where ? 1 : 0)});
    }
    return;
  }
  if (name == "index_info" || name == "index_xinfo") {
    if (!st->pragmaHasValue) return;
    IndexP ix = db.findIndex(st->schema, arg.toText());
    if (!ix) return;
    TableP t = db.findTable("", ix->tableName);
    bool x = name == "index_xinfo";
    if (x) onHeader({"seqno","cid","name","desc","coll","key"}); else onHeader({"seqno","cid","name"});
    int seq = 0;
    for (auto& c : ix->cols) {
      Row r{Value::Int(seq++), Value::Int(c.col == -1 ? -2 : c.col), c.col >= 0 && t ? Value::Text(t->cols[c.col].name) : Value::Null()};
      if (x) { r.push_back(Value::Int(c.desc ? 1 : 0)); r.push_back(Value::Text(c.collate.empty() ? "BINARY" : c.collate)); r.push_back(Value::Int(1)); }
      onRow(r);
    }
    if (x && !(t && t->withoutRowid)) onRow(Row{Value::Int(seq), Value::Int(-1), Value::Null(), Value::Int(0), Value::Text("BINARY"), Value::Int(0)});
    return;
  }
  if (name == "foreign_key_list") {
    if (!st->pragmaHasValue) return;
    TableP t = db.findTable(st->schema, arg.toText());
    if (!t) return;
    onHeader({"id","seq","table","from","to","on_update","on_delete","match"});
    auto actName = [](int a) { switch (a) { case 1: return "SET NULL"; case 2: return "SET DEFAULT"; case 3: return "CASCADE"; case 4: return "RESTRICT"; default: return "NO ACTION"; } };
    int id = 0;
    std::vector<std::pair<int, const TableConstraint*>> fks;
    // column-level FKs are stored? We only stored table constraints; also parse column fks from sql
    auto stmts = parseSqlAll(t->sql);
    if (!stmts.empty() && stmts[0]->kind == Stmt::CreateTable) {
      std::vector<std::tuple<std::string, std::vector<std::string>, std::vector<std::string>, int, int>> all;
      // SQLite numbers FKs in reverse order of definition
      for (auto& cd : stmts[0]->colDefs) if (cd.hasFk) all.push_back({cd.fkTable, {cd.name}, cd.fkCols, cd.fkOnUpdate, cd.fkOnDelete});
      for (auto& tc : stmts[0]->constraints) if (tc.kind == TableConstraint::ForeignKey) { std::vector<std::string> from; for (auto& ic : tc.cols) from.push_back(ic.name); all.push_back({tc.fkTable, from, tc.fkCols, tc.fkOnUpdate, tc.fkOnDelete}); }
      for (int i = (int)all.size() - 1; i >= 0; i--) {
        auto& fk = all[i];
        for (size_t k = 0; k < std::get<1>(fk).size(); k++) {
          onRow(Row{Value::Int(id), Value::Int((int64_t)k), Value::Text(std::get<0>(fk)), Value::Text(std::get<1>(fk)[k]), k < std::get<2>(fk).size() ? Value::Text(std::get<2>(fk)[k]) : Value::Null(), Value::Text(actName(std::get<3>(fk))), Value::Text(actName(std::get<4>(fk))), Value::Text("NONE")});
        }
        id++;
      }
    }
    (void)fks;
    return;
  }
  if (name == "table_list") {
    onHeader({"schema","name","type","ncol","wr","strict"});
    auto emit = [&](Schema& s, const std::string& sname) {
      for (int i = (int)s.entries.size() - 1; i >= 0; i--) {
        auto& e = s.entries[i];
        if (e.type != "table" && e.type != "view") continue;
        TableP t = s.findTable(e.name);
        if (!t) continue;
        if (st->pragmaHasValue && !nameEq(arg.toText(), t->name)) continue;
        onRow(Row{Value::Text(sname), Value::Text(t->name), Value::Text(t->isView ? "view" : (t->isVirtual ? "virtual" : "table")), Value::Int((int64_t)t->cols.size()), Value::Int(t->withoutRowid ? 1 : 0), Value::Int(t->strict ? 1 : 0)});
      }
      if (!st->pragmaHasValue || nameEq(arg.toText(), sname == "temp" ? "sqlite_temp_schema" : "sqlite_schema"))
        onRow(Row{Value::Text(sname), Value::Text(sname == "temp" ? "sqlite_temp_schema" : "sqlite_schema"), Value::Text("table"), Value::Int(5), Value::Int(0), Value::Int(0)});
    };
    if (st->schema.empty()) { emit(db.main, "main"); emit(db.temp, "temp"); for (auto& kv : db.attached) emit(kv.second, kv.second.dbName); }
    else emit(*sch, sch->dbName);
    return;
  }
  if (name == "database_list") {
    onHeader({"seq","name","file"});
    onRow(Row{Value::Int(0), Value::Text("main"), Value::Text(db.isMemory ? "" : db.filename)});
    int seq = 2;
    for (auto& kv : db.attached) onRow(Row{Value::Int(seq++), Value::Text(kv.second.dbName), Value::Text("")});
    return;
  }
  if (name == "collation_list") {
    onHeader({"seq","name"});
    onRow(Row{Value::Int(0), Value::Text("decimal")}); onRow(Row{Value::Int(1), Value::Text("BINARY")}); onRow(Row{Value::Int(2), Value::Text("NOCASE")}); onRow(Row{Value::Int(3), Value::Text("RTRIM")}); onRow(Row{Value::Int(4), Value::Text("uint")});
    return;
  }
  if (name == "compile_options") {
    onHeader({"compile_options"});
    const char** o = compileOptions();
    for (int i = 0; o[i]; i++) onRow(Row{Value::Text(o[i])});
    return;
  }
  if (name == "function_list") {
    onHeader({"name","builtin","type","enc","narg","flags"});
    return;
  }
  if (name == "page_size") { if (st->pragmaHasValue) { int64_t v = arg.toInt(); if (v >= 512 && v <= 65536 && (v & (v - 1)) == 0) db.pageSize = (int)v; return; } single("page_size", Value::Int(db.pageSize)); return; }
  if (name == "page_count") {
    int pc = 1;
    for (auto& e : sch->entries) if (e.rootpage > pc) pc = e.rootpage;
    // tables with rows need more pages; approximate with rootpages
    if (sch->entries.empty()) pc = db.isMemory ? 0 : 1;
    extern int estimatePageCount(Database&, Schema&);
    pc = estimatePageCount(db, *sch);
    single("page_count", Value::Int(pc)); return;
  }
  if (name == "freelist_count") { single("freelist_count", Value::Int(db.freelistCount)); return; }
  if (name == "user_version") { if (st->pragmaHasValue) { sch->userVersion = (int)arg.toInt(); db.dirty = true; return; } single("user_version", Value::Int(sch->userVersion)); return; }
  if (name == "schema_version") { if (st->pragmaHasValue) { sch->schemaCookie = (int)arg.toInt(); return; } single("schema_version", Value::Int(sch->schemaCookie)); return; }
  if (name == "application_id") { if (st->pragmaHasValue) { sch->applicationId = (int)arg.toInt(); db.dirty = true; return; } single("application_id", Value::Int(sch->applicationId)); return; }
  if (name == "data_version") { single("data_version", Value::Int(1)); return; }
  if (name == "journal_mode") {
    std::string mode = db.isMemory ? "memory" : "delete";
    if (st->pragmaHasValue) {
      std::string m = lowerStr(arg.toText());
      if (!db.isMemory && (m == "delete" || m == "truncate" || m == "persist" || m == "wal" || m == "off" || m == "memory")) mode = m;
      else if (db.isMemory && (m == "off")) mode = "off";
    }
    single("journal_mode", Value::Text(mode)); return;
  }
  if (name == "synchronous") { if (st->pragmaHasValue) { std::string m = lowerStr(arg.toText()); if (m == "off" || m == "0") db.synchronous = 0; else if (m == "normal" || m == "1") db.synchronous = 1; else if (m == "full" || m == "2") db.synchronous = 2; else if (m == "extra" || m == "3") db.synchronous = 3; return; } single("synchronous", Value::Int(db.synchronous)); return; }
  if (name == "foreign_keys") { boolPragma(db.foreignKeys); return; }
  if (name == "encoding") { if (st->pragmaHasValue) return; single("encoding", Value::Text("UTF-8")); return; }
