        onRow(Row{Value::Int(id++), Value::Int(0), Value::Int(0), Value::Text(d)});
      }
      if (!in->select->orderBy.empty()) onRow(Row{Value::Int(id++), Value::Int(0), Value::Int(0), Value::Text("USE TEMP B-TREE FOR ORDER BY")});
    }
