void Engine::execute(const StmtP& st, HeaderCallback onHeader, RowCallback onRow) {
  currentStmtText = st->text;
  switch (st->kind) {
    case Stmt::Empty: return;
    case Stmt::Explain: execExplain(st, onHeader, onRow); return;
    case Stmt::Select: {
      Scope sc;
      // Headers for SELECT with zero rows: sqlite does not call the callback; we send header on first row only
      execSelect(st->select, nullptr, onHeader, onRow);
      return;
    }
    case Stmt::Begin: begin(st->txType); return;
    case Stmt::Commit: commit(); return;
    case Stmt::Rollback: if (st->txType == 1) rollbackTo(st->savepoint); else rollback(); return;
    case Stmt::Savepoint: savepoint(st->savepoint); return;
    case Stmt::Release: release(st->savepoint); return;
    case Stmt::Pragma: execPragma(st, onHeader, onRow); return;
    case Stmt::Vacuum: case Stmt::Analyze: case Stmt::Reindex: db.changes = 0; return;
    case Stmt::Attach: {
      Scope sc; Value f = eval(st->attachFile, &sc); Value n = eval(st->attachName, &sc);
      std::string nm = n.toText();
      if (db.attached.size() >= 10) throw SqlError("too many attached databases - max 10");
      if (db.schemaByName(nm)) throw SqlError("database " + nm + " is already in use");
      Schema s; s.dbName = nm;
      db.attached[lowerStr(nm)] = s;
      return;
    }
    case Stmt::Detach: {
      Scope sc; Value n = eval(st->attachName, &sc);
      std::string nm = lowerStr(n.toText());
      if (!db.attached.count(nm)) throw SqlError("no such database: " + n.toText());
      db.attached.erase(nm);
      return;
    }
    default: break;
  }
  // Modifying statements: statement-level atomicity
  size_t mark = stmtBegin();
  int64_t savedChanges = db.changes;
  if (st->kind == Stmt::Insert || st->kind == Stmt::Update || st->kind == Stmt::Delete) db.changes = 0;
  try {
    switch (st->kind) {
      case Stmt::Insert: execInsert(st, nullptr, onRow, onHeader); break;
      case Stmt::Update: execUpdate(st, nullptr, onRow, onHeader); break;
      case Stmt::Delete: execDelete(st, nullptr, onRow, onHeader); break;
      case Stmt::CreateTable: execCreateTable(st); break;
      case Stmt::CreateIndex: execCreateIndex(st); break;
      case Stmt::CreateView: execCreateView(st); break;
      case Stmt::CreateTrigger: execCreateTrigger(st); break;
      case Stmt::CreateVirtualTable: throw SqlError("no such module: " + st->moduleName);
      case Stmt::Drop: execDrop(st); break;
      case Stmt::AlterTable: execAlter(st); break;
      default: break;
    }
  } catch (SqlError& err) {
    if (err.code == 1001) {
      // ROLLBACK conflict resolution: roll back entire transaction
      if (db.inTransaction) { db.undoTo(0); db.inTransaction = false; db.savepoints.clear(); }
      else stmtRollback(mark);
      db.changes = savedChanges;
      throw SqlError(err.what(), err.offset, 19);
    }
    if (err.code == 1003) {
      // FAIL: keep changes so far
      db.changes = db.changes; // partial changes remain
      if (!db.inTransaction) { db.undo.clear(); db.dirty = true; }
      throw SqlError(err.what(), err.offset, 19);
    }
    stmtRollback(mark);
    db.changes = savedChanges;
    throw;
  } catch (IgnoreSignal&) {
    stmtCommit(mark);
    return;
  }
  stmtCommit(mark);
}
