        computeYMD_HMS(p);
        p->tz = 0; p->validJD = false;
        computeJD(p);
        Z = ((p->iJD + 129600000) / 86400000) % 7;
        if (Z > nn) Z -= 7;
        p->iJD += (nn - Z) * 86400000;
        rc = 0;
      }
      break;
    }
    case 's': {
      if (strncasecmp(z, "start of ", 9) != 0) {
        if (strcasecmp(z, "subsec") == 0 || strcasecmp(z, "subsecond") == 0) { p->useSubsec = true; rc = 0; }
        break;
      }
      if (!p->validJD && !p->validYMD && !p->validHMS) break;
      z += 9;
      computeYMD(p);
      p->validHMS = true; p->h = p->m = 0; p->s = 0.0; p->rawS = false; p->tz = 0; p->validJD = false;
      if (strcasecmp(z, "month") == 0) { p->D = 1; rc = 0; }
      else if (strcasecmp(z, "year") == 0) { p->M = 1; p->D = 1; rc = 0; }
      else if (strcasecmp(z, "day") == 0) rc = 0;
      break;
    }
    case '+': case '-': case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9': {
      double rRounder;
      int i;
      int Y, M, D, h, m, x;
      const char* z2 = z;
      char z0 = z[0];
      for (n = 1; z[n]; n++) {
        if (z[n] == ':') break;
        if (isspace((unsigned char)z[n])) break;
        if (z[n] == '-') {
          if (n == 5 && getDigits(&z[1], "40f", &Y) == 1) break;
