        if (parseHhMmSs(z3, &tx)) break;
        computeJD(&tx);
        tx.iJD -= 43200000;
        day = tx.iJD / 86400000;
        tx.iJD -= day * 86400000;
        if (z0 == '-') tx.iJD = -tx.iJD;
        computeJD(p);
        clearYMD_HMS_TZ(p);
        p->iJD += tx.iJD;
        rc = 0;
        break;
      }
      z += n;
      while (isspace((unsigned char)*z)) z++;
      n = (int)strlen(z);
      if (n < 3 || n > 10) break;
      if (tolower((unsigned char)z[n - 1]) == 's') n--;
      computeJD(p);
      rRounder = r < 0 ? -0.5 : +0.5;
      p->nFloor = 0;
      for (i = 0; i < 6; i++) {
        if (aXformType[i].nName == n && strncasecmp(aXformType[i].zName, z, n) == 0 && r > -aXformType[i].rLimit && r < aXformType[i].rLimit) {
