// Date/time functions (modeled on SQLite date.c)
#include "engine.h"
#include <cmath>
#include <cstring>
#include <ctime>
#include <sys/time.h>

struct DateTime {
  int64_t iJD = 0;
  int Y = 0, M = 0, D = 0, h = 0, m = 0;
  int tz = 0;
  double s = 0;
  bool validJD = false, validYMD = false, validHMS = false;
  bool rawS = false, isError = false, useSubsec = false, isUtc = false, isLocal = false, tzSet = false;
  int nFloor = 0;
};

static void datetimeError(DateTime* p) { *p = DateTime(); p->isError = true; }
static bool validJulianDay(int64_t iJD) { return iJD >= 0 && iJD <= 464269060799999LL; }

static void computeJD(DateTime* p) {
  int Y, M, D, A, B, X1, X2;
  if (p->validJD) return;
  if (p->validYMD) { Y = p->Y; M = p->M; D = p->D; } else { Y = 2000; M = 1; D = 1; }
  if (Y < -4713 || Y > 9999 || p->rawS) { datetimeError(p); return; }
  if (M <= 2) { Y--; M += 12; }
  A = (Y < 0 ? (Y - 99) / 100 : Y / 100);
  A = Y / 100;
  B = 2 - A + (A / 4);
  X1 = 36525 * (Y + 4716) / 100;
  X2 = 306001 * (M + 1) / 10000;
  p->iJD = (int64_t)((X1 + X2 + D + B - 1524.5) * 86400000);
  p->validJD = true;
  if (p->validHMS) {
    p->iJD += p->h * 3600000 + p->m * 60000 + (int64_t)(p->s * 1000 + 0.5);
    if (p->tz) { p->iJD -= p->tz * 60000; p->validYMD = false; p->validHMS = false; p->tz = 0; p->isUtc = true; p->isLocal = false; }
  }
}

static void computeYMD(DateTime* p) {
  int Z, alpha, A, B, C, D, E, X1;
  if (p->validYMD) return;
  if (!p->validJD) { p->Y = 2000; p->M = 1; p->D = 1; }
  else if (!validJulianDay(p->iJD)) { datetimeError(p); return; }
  else {
    Z = (int)((p->iJD + 43200000) / 86400000);
    alpha = (int)((Z + 32044.75) / 36524.25) - 52;
    A = Z + 1 + alpha - ((alpha + 100) / 4) + 25;
    B = A + 1524;
    C = (int)((B - 122.1) / 365.25);
    D = (36525 * (C & 32767)) / 100;
    E = (int)((B - D) / 30.6001);
    X1 = (int)(30.6001 * E);
    p->D = B - D - X1;
    p->M = E < 14 ? E - 1 : E - 13;
    p->Y = p->M > 2 ? C - 4716 : C - 4715;
  }
  p->validYMD = true;
}

static void computeHMS(DateTime* p) {
  int day_ms, day_min;
  if (p->validHMS) return;
  computeJD(p);
  day_ms = (int)((p->iJD + 43200000) % 86400000);
  p->s = (day_ms % 60000) / 1000.0;
  day_min = day_ms / 60000;
  p->m = day_min % 60;
  p->h = day_min / 60;
  p->rawS = false;
  p->validHMS = true;
}
static void computeYMD_HMS(DateTime* p) { computeYMD(p); computeHMS(p); }
static void clearYMD_HMS_TZ(DateTime* p) { p->validYMD = false; p->validHMS = false; p->tz = 0; }

static int getDigits(const char* zDate, const char* zFormat, ...) {
  static const uint16_t aMx[] = {12, 14, 24, 31, 59, 14712};
  va_list ap;
  int cnt = 0;
  char nextC;
  va_start(ap, zFormat);
  do {
    char N = zFormat[0] - '0';
    char min = zFormat[1] - '0';
    int val = 0;
    uint16_t max;
    max = aMx[zFormat[2] - 'a'];
    nextC = zFormat[3];
    val = 0;
    while (N--) {
      if (!isdigit((unsigned char)*zDate)) goto end_getDigits;
      val = val * 10 + *zDate - '0';
      zDate++;
    }
    if (val < (int)min || val > (int)max || (nextC != 0 && nextC != *zDate)) goto end_getDigits;
    *va_arg(ap, int*) = val;
    zDate++;
    cnt++;
    zFormat += 4;
  } while (nextC);
end_getDigits:
  va_end(ap);
  return cnt;
}

static int parseTimezone(const char* zDate, DateTime* p) {
  int sgn = 0, nHr, nMn; int c;
  while (isspace((unsigned char)*zDate)) zDate++;
  p->tz = 0;
  c = *zDate;
  if (c == '-') sgn = -1;
  else if (c == '+') sgn = +1;
  else if (c == 'Z' || c == 'z') { zDate++; p->isLocal = false; p->isUtc = true; goto zulu_time; }
  else return c != 0;
  zDate++;
  if (getDigits(zDate, "20b:20e", &nHr, &nMn) != 2) return 1;
  zDate += 5;
  p->tz = sgn * (nMn + nHr * 60);
zulu_time:
  while (isspace((unsigned char)*zDate)) zDate++;
  p->tzSet = true;
  return *zDate != 0;
}

static int parseHhMmSs(const char* zDate, DateTime* p) {
  int h, m, s; double ms = 0.0;
  if (getDigits(zDate, "20c:20e", &h, &m) != 2) return 1;
  zDate += 5;
  if (*zDate == ':') {
    zDate++;
    if (getDigits(zDate, "20e", &s) != 1) return 1;
    zDate += 2;
    if (*zDate == '.' && isdigit((unsigned char)zDate[1])) {
      double rScale = 1.0;
      zDate++;
      while (isdigit((unsigned char)*zDate)) { ms = ms * 10.0 + *zDate - '0'; rScale *= 10.0; zDate++; }
      ms /= rScale;
    }
  } else s = 0;
  p->validJD = false; p->rawS = false; p->validHMS = true;
  p->h = h; p->m = m; p->s = s + ms;
  if (parseTimezone(zDate, p)) return 1;
  return 0;
}

static int parseYyyyMmDd(const char* zDate, DateTime* p) {
  int Y, M, D, neg;
  if (zDate[0] == '-') { zDate++; neg = 1; } else neg = 0;
  if (getDigits(zDate, "40f-21a-21d", &Y, &M, &D) != 3) return 1;
  zDate += 10;
  while (isspace((unsigned char)*zDate) || 'T' == *zDate) zDate++;
  if (parseHhMmSs(zDate, p) == 0) { /* ok */ }
  else if (*zDate == 0) p->validHMS = false;
  else return 1;
  p->validJD = false; p->validYMD = true;
  p->Y = neg ? -Y : Y; p->M = M; p->D = D;
  if (p->tz) computeJD(p);
  return 0;
}

static int64_t g_nowCacheKey = 0;
static int64_t g_nowCacheVal = 0;
int64_t currentTimeMs() {
  struct timeval tv; gettimeofday(&tv, nullptr);
  return (int64_t)tv.tv_sec * 1000 + tv.tv_usec / 1000;
}
static void setDateTimeToCurrent(DateTime* p, Engine* eng) {
  (void)eng;
  int64_t key = (int64_t)(intptr_t)eng;
  (void)key;
  int64_t ms = currentTimeMs();
  p->iJD = ms + 210866760000000LL;
  p->validJD = true;
}

static void setRawDateNumber(DateTime* p, double r) {
  p->s = r; p->rawS = true;
  if (r >= 0.0 && r < 5373484.5) { p->iJD = (int64_t)(r * 86400000.0 + 0.5); p->validJD = true; }
}

static int parseDateOrTime(Engine* eng, const char* zDate, DateTime* p) {
  double r;
  if (parseYyyyMmDd(zDate, p) == 0) return 0;
  if (parseHhMmSs(zDate, p) == 0) return 0;
  if (strcasecmp(zDate, "now") == 0) { setDateTimeToCurrent(p, eng); return 0; }
  if (sqliteAtoF(zDate, strlen(zDate), r) > 0) { setRawDateNumber(p, r); return 0; }
  if (strcasecmp(zDate, "subsec") == 0 || strcasecmp(zDate, "subsecond") == 0) { p->useSubsec = true; return 0; }
