}

static int toLocaltime(DateTime* p) {
  time_t t;
  struct tm sLocal;
  int iYearDiff;
  if (p->iJD < 21086676 * (int64_t)10000 || p->iJD > 25340230 * (int64_t)10000 + 799) {
    // approximate for out of range
    DateTime x = *p;
    computeYMD_HMS(&x);
    iYearDiff = (2000 + x.Y % 4) - x.Y;
    x.Y += iYearDiff; x.validJD = false; computeJD(&x);
    t = (time_t)(x.iJD / 1000 - 21086676 * (int64_t)10000);
  } else { iYearDiff = 0; t = (time_t)(p->iJD / 1000 - 21086676 * (int64_t)10000); }
  memset(&sLocal, 0, sizeof sLocal);
  localtime_r(&t, &sLocal);
  p->Y = sLocal.tm_year + 1900 - iYearDiff;
  p->M = sLocal.tm_mon + 1;
  p->D = sLocal.tm_mday;
  p->h = sLocal.tm_hour;
  p->m = sLocal.tm_min;
  p->s = sLocal.tm_sec + (p->iJD % 1000) * 0.001;
  p->validYMD = true; p->validHMS = true; p->validJD = false; p->rawS = false; p->tz = 0; p->isError = false;
  return 0;
}

struct XformType { const char* zName; int nName; double rLimit; double rXform; };
static const XformType aXformType[] = {
  {"second", 6, 4.6427e+14, 1.0}, {"minute", 6, 7.7379e+12, 60.0}, {"hour", 4, 1.2897e+11, 3600.0},
  {"day", 3, 5373485.0, 86400.0}, {"month", 5, 176546.0, 2592000.0}, {"year", 4, 14713.0, 31536000.0},
};

static int daysAfterMonth(DateTime* p) {
  // days in month M of year Y
  static const int d[] = {31,28,31,30,31,30,31,31,30,31,30,31};
  int Y = p->Y, M = p->M;
  int n = d[(M - 1 + 1200) % 12];
  if (M == 2 && ((Y % 4 == 0 && Y % 100 != 0) || Y % 400 == 0)) n = 29;
  return n;
}

static int parseModifier(Engine* eng, const char* z, int n, DateTime* p, int idx) {
  int rc = 1;
  double r;
  switch (tolower((unsigned char)z[0])) {
    case 'a': {
      if (strcasecmp(z, "auto") == 0) {
        if (idx > 1) return 1;
        if (!p->rawS || p->validJD) { rc = 0; p->rawS = false; }
        else if (p->s >= -21086676 * (int64_t)10000 && p->s <= (25340230 * (int64_t)10000) + 799) {
          r = p->s * 1000.0 + 210866760000000.0;
          clearYMD_HMS_TZ(p);
          p->iJD = (int64_t)(r + 0.5); p->validJD = true; p->rawS = false; rc = 0;
        }
      }
      break;
    }
    case 'c': {
      if (strcasecmp(z, "ceiling") == 0) { computeJD(p); clearYMD_HMS_TZ(p); rc = 0; p->nFloor = 0; }
      break;
    }
    case 'f': {
      if (strcasecmp(z, "floor") == 0) {
        computeJD(p);
        p->iJD -= p->nFloor * 86400000;
        clearYMD_HMS_TZ(p); rc = 0;
      }
      break;
    }
    case 'j': {
      if (strcasecmp(z, "julianday") == 0) {
        if (idx > 1) return 1;
        if (p->validJD && p->rawS) { rc = 0; p->rawS = false; }
      }
      break;
    }
    case 'l': {
      if (strcasecmp(z, "localtime") == 0 && !p->tzSet) {
        computeJD(p);
        rc = toLocaltime(p);
        p->isUtc = false; p->isLocal = true; p->tzSet = true;
      }
      break;
    }
    case 'u': {
      if (strcasecmp(z, "unixepoch") == 0 && p->rawS) {
        if (idx > 1) return 1;
        r = p->s * 1000.0 + 210866760000000.0;
        if (r >= 0.0 && r < 464269060800000.0) { clearYMD_HMS_TZ(p); p->iJD = (int64_t)(r + 0.5); p->validJD = true; p->rawS = false; rc = 0; }
      } else if (strcasecmp(z, "utc") == 0 && !p->tzSet) {
        if (!p->isUtc) {
          int64_t iOrigJD, iGuess; int cnt = 0; int64_t iErr;
          computeJD(p);
          iGuess = iOrigJD = p->iJD;
          iErr = 0;
          do {
            DateTime new_ = DateTime();
            iGuess -= iErr;
            new_.iJD = iGuess; new_.validJD = true;
            rc = toLocaltime(&new_);
            if (rc) return rc;
            computeJD(&new_);
            iErr = new_.iJD - iOrigJD;
          } while (iErr && cnt++ < 3);
          p->iJD = iGuess;
          p->validJD = true; p->isUtc = true; p->isLocal = false;
        }
        rc = 0; p->tzSet = true;
      }
      break;
    }
    case 'w': {
      int nn;
      if (strncasecmp(z, "weekday ", 8) == 0 && sqliteAtoF(&z[8], strlen(&z[8]), r) > 0 && r >= 0.0 && r < 7.0 && (nn = (int)r) == r) {
        int64_t Z;
        computeYMD_HMS(p);
        p->tz = 0; p->validJD = false;
        computeJD(p);
        Z = ((p->iJD + 129600000) / 86400000) % 7;
        if (Z > nn) Z -= 7;
        p->iJD += (nn - Z) * 86400000;
        rc = 0;
      }
      break;
    }
    case 's': {
      if (strncasecmp(z, "start of ", 9) != 0) {
        if (strcasecmp(z, "subsec") == 0 || strcasecmp(z, "subsecond") == 0) { p->useSubsec = true; rc = 0; }
        break;
      }
      if (!p->validJD && !p->validYMD && !p->validHMS) break;
      z += 9;
      computeYMD(p);
      p->validHMS = true; p->h = p->m = 0; p->s = 0.0; p->rawS = false; p->tz = 0; p->validJD = false;
      if (strcasecmp(z, "month") == 0) { p->D = 1; rc = 0; }
      else if (strcasecmp(z, "year") == 0) { p->M = 1; p->D = 1; rc = 0; }
      else if (strcasecmp(z, "day") == 0) rc = 0;
      break;
    }
    case '+': case '-': case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9': {
      double rRounder;
      int i;
      int Y, M, D, h, m, x;
      const char* z2 = z;
      char z0 = z[0];
      for (n = 1; z[n]; n++) {
        if (z[n] == ':') break;
        if (isspace((unsigned char)z[n])) break;
