        if (*z2) {
          DateTime tx; memset(&tx, 0, sizeof tx);
          if (parseHhMmSs(z2, &tx)) break;
          h = tx.h; m = tx.m; sec = tx.s;
        }
        computeYMD_HMS(p);
        if (z0 == '-') { Y = -Y; M = -M; D = -D; h = -h; m = -m; sec = -sec; }
        p->Y += Y; p->M += M;
        x = p->M > 0 ? (p->M - 1) / 12 : (p->M - 12) / 12;
        p->Y += x; p->M -= x * 12;
        p->validJD = false;
        computeJD(p);
        p->iJD += (int64_t)D * 86400000 + (int64_t)h * 3600000 + (int64_t)m * 60000 + (int64_t)(sec * 1000 + (sec < 0 ? -0.5 : 0.5));
        clearYMD_HMS_TZ(p);
        rc = 0;
        break;
      }
      if (z[n] == ':') {
        const char* z3 = z;
        DateTime tx; int64_t day;
        if (!isdigit((unsigned char)*z3)) z3++;
        memset(&tx, 0, sizeof tx);
