          rc = 0;
          break;
        }
      }
      clearYMD_HMS_TZ(p);
      break;
    }
    default: break;
  }
  return rc;
}

// returns 1 on error (NULL result)
static int isDate(Engine* eng, const std::vector<Value>& args, DateTime* p) {
  *p = DateTime();
  if (args.empty()) { if (!eng->deterministicMode) { setDateTimeToCurrent(p, eng); return 0; } }
  if (args.empty()) { setDateTimeToCurrent(p, eng); return 0; }
  const Value& a0 = args[0];
  if (a0.isNull()) return 1;
  if (a0.t == VT::Int || a0.t == VT::Real) setRawDateNumber(p, a0.toReal());
  else {
    std::string s = a0.toText();
    if (parseDateOrTime(eng, s.c_str(), p)) return 1;
  }
  for (size_t i = 1; i < args.size(); i++) {
    const Value& a = args[i];
    if (a.isNull()) return 1;
    std::string z = a.toText();
    int n = (int)z.size();
    if (parseModifier(eng, z.c_str(), n, p, (int)i)) return 1;
  }
  computeJD(p);
  if (p->isError || !validJulianDay(p->iJD)) return 1;
  if (args.size() == 1 && p->validYMD && p->D > 28) {
    // check for day overflow -> treat as error? sqlite normalizes; keep
  }
  return 0;
}

static std::string fmtYear(int Y) {
  char buf[32];
  if (Y < 0) snprintf(buf, sizeof buf, "-%04d", -Y); else snprintf(buf, sizeof buf, "%04d", Y);
  return buf;
}

static std::string dateStr(DateTime& x) { computeYMD(&x); char b[64]; snprintf(b, sizeof b, "%s-%02d-%02d", fmtYear(x.Y).c_str(), x.M, x.D); return b; }
static std::string timeStr(DateTime& x) {
  computeHMS(&x); char b[64];
  if (x.useSubsec) snprintf(b, sizeof b, "%02d:%02d:%06.3f", x.h, x.m, x.s);
  else snprintf(b, sizeof b, "%02d:%02d:%02d", x.h, x.m, (int)x.s);
  return b;
}

Value evalDateFunc(const std::string& name, const std::vector<Value>& args, Engine* eng, bool* ok) {
  *ok = true;
  if (name == "current_time" || name == "current_date" || name == "current_timestamp") {
    DateTime x; setDateTimeToCurrent(&x, eng);
    if (name == "current_date") return Value::Text(dateStr(x));
    if (name == "current_time") return Value::Text(timeStr(x));
    computeYMD_HMS(&x);
    return Value::Text(dateStr(x) + " " + timeStr(x));
  }
  if (name == "date" || name == "time" || name == "datetime" || name == "julianday" || name == "unixepoch") {
    DateTime x;
    if (isDate(eng, args, &x)) return Value::Null();
    if (name == "julianday") return Value::Real(x.iJD / 86400000.0);
    if (name == "unixepoch") {
      if (x.useSubsec) return Value::Real((x.iJD - 210866760000000LL) / 1000.0);
      return Value::Int(x.iJD / 1000 - 21086676 * (int64_t)10000);
    }
    computeYMD_HMS(&x);
    if (x.isError) return Value::Null();
    if (name == "date") return Value::Text(dateStr(x));
    if (name == "time") return Value::Text(timeStr(x));
    return Value::Text(dateStr(x) + " " + timeStr(x));
  }
  if (name == "strftime") {
    if (args.empty() || args[0].isNull()) return Value::Null();
    std::string fmt = args[0].toText();
    std::vector<Value> rest(args.begin() + 1, args.end());
    DateTime x;
    if (isDate(eng, rest, &x)) return Value::Null();
    computeJD(&x); computeYMD_HMS(&x);
    if (x.isError) return Value::Null();
    std::string out;
    char buf[64];
    for (size_t i = 0; i < fmt.size(); i++) {
      if (fmt[i] != '%') { out.push_back(fmt[i]); continue; }
      i++;
      if (i >= fmt.size()) break;
      char cf = fmt[i];
      switch (cf) {
        case 'd': snprintf(buf, sizeof buf, "%02d", x.D); out += buf; break;
        case 'e': snprintf(buf, sizeof buf, "%2d", x.D); out += buf; break;
        case 'f': { double s = x.s; if (s > 59.999) s = 59.999; snprintf(buf, sizeof buf, "%06.3f", s); out += buf; break; }
        case 'F': snprintf(buf, sizeof buf, "%s-%02d-%02d", fmtYear(x.Y).c_str(), x.M, x.D); out += buf; break;
        case 'H': snprintf(buf, sizeof buf, "%02d", x.h); out += buf; break;
        case 'k': snprintf(buf, sizeof buf, "%2d", x.h); out += buf; break;
        case 'I': case 'l': { int h12 = x.h % 12; if (h12 == 0) h12 = 12; snprintf(buf, sizeof buf, cf == 'I' ? "%02d" : "%2d", h12); out += buf; break; }
        case 'W': case 'j': case 'U': case 'V': case 'G': case 'g': case 'u': case 'w': {
          DateTime y = x; y.validJD = false; y.M = 1; y.D = 1; computeJD(&y);
          int nDay = (int)((x.iJD - y.iJD + 43200000) / 86400000);  // day of year 0-based
          int wd = (int)(((x.iJD + 129600000) / 86400000) % 7);     // 0=Sunday
          if (cf == 'j') { snprintf(buf, sizeof buf, "%03d", nDay + 1); out += buf; }
          else if (cf == 'w') { snprintf(buf, sizeof buf, "%d", wd); out += buf; }
          else if (cf == 'u') { snprintf(buf, sizeof buf, "%d", wd == 0 ? 7 : wd); out += buf; }
          else if (cf == 'W') { int wdM = (wd + 6) % 7; snprintf(buf, sizeof buf, "%02d", (nDay + 7 - wdM) / 7); out += buf; }
          else if (cf == 'U') { snprintf(buf, sizeof buf, "%02d", (nDay + 7 - wd) / 7); out += buf; }
          else {
            // ISO 8601 week
            DateTime z = x;
            z.validJD = false; computeJD(&z);
            int wdIso = (wd + 6) % 7; // Monday=0
            // Thursday of this week
            int64_t thursJD = z.iJD + (int64_t)(3 - wdIso) * 86400000;
            DateTime th; th.iJD = thursJD; th.validJD = true; computeYMD(&th);
            int isoYear = th.Y;
            DateTime jan1; jan1.Y = isoYear; jan1.M = 1; jan1.D = 1; jan1.validYMD = true; computeJD(&jan1);
            int dayOfYearThurs = (int)((thursJD - jan1.iJD + 43200000) / 86400000);
            int week = dayOfYearThurs / 7 + 1;
            if (cf == 'V') { snprintf(buf, sizeof buf, "%02d", week); out += buf; }
            else if (cf == 'G') { out += fmtYear(isoYear); }
            else { snprintf(buf, sizeof buf, "%02d", ((isoYear % 100) + 100) % 100); out += buf; }
          }
          break;
        }
        case 'J': { char b2[64]; snprintf(b2, sizeof b2, "%.16g", x.iJD / 86400000.0); out += b2; break; }
        case 'm': snprintf(buf, sizeof buf, "%02d", x.M); out += buf; break;
        case 'M': snprintf(buf, sizeof buf, "%02d", x.m); out += buf; break;
        case 'p': out += x.h >= 12 ? "PM" : "AM"; break;
        case 'P': out += x.h >= 12 ? "pm" : "am"; break;
        case 'R': snprintf(buf, sizeof buf, "%02d:%02d", x.h, x.m); out += buf; break;
        case 's': { if (x.useSubsec) snprintf(buf, sizeof buf, "%.3f", (x.iJD - 210866760000000LL) / 1000.0); else snprintf(buf, sizeof buf, "%lld", (long long)(x.iJD / 1000 - 21086676 * (int64_t)10000)); out += buf; break; }
        case 'S': snprintf(buf, sizeof buf, "%02d", (int)x.s); out += buf; break;
        case 'T': snprintf(buf, sizeof buf, "%02d:%02d:%02d", x.h, x.m, (int)x.s); out += buf; break;
        case 'Y': out += fmtYear(x.Y); break;
        case '%': out.push_back('%'); break;
        default: return Value::Null();
      }
    }
    return Value::Text(out);
  }
  if (name == "timediff") {
    DateTime d1, d2;
    if (isDate(eng, {args[0]}, &d1)) return Value::Null();
    if (isDate(eng, {args[1]}, &d2)) return Value::Null();
    computeYMD_HMS(&d1); computeYMD_HMS(&d2);
    char sign; int Y, M;
    if (d1.iJD >= d2.iJD) {
      sign = '+';
      Y = d1.Y - d2.Y;
      if (Y) { d2.Y = d1.Y; d2.validJD = false; computeJD(&d2); }
      M = d1.M - d2.M;
      if (M < 0) { Y--; M += 12; }
