      d1.iJD -= d2.iJD;
      d1.iJD += (int64_t)1486995408 * (int64_t)100000;
    } else {
      sign = '-';
      Y = d2.Y - d1.Y;
      if (Y) { d1.Y = d2.Y; d1.validJD = false; computeJD(&d1); }
      M = d2.M - d1.M;
      if (M < 0) { Y--; M += 12; }
      if (M != 0) { d1.M = d2.M; d1.validJD = false; computeJD(&d1); }
      while (d1.iJD > d2.iJD) { M--; if (M < 0) { M = 11; Y--; } d1.M--; if (d1.M < 1) { d1.M = 12; d1.Y--; } d1.validJD = false; computeJD(&d1); }
      d1.iJD = d2.iJD - d1.iJD;
      d1.iJD += (int64_t)1486995408 * (int64_t)100000;
    }
    clearYMD_HMS_TZ(&d1);
    computeYMD_HMS(&d1);
    char buf[100];
    snprintf(buf, sizeof buf, "%c%04d-%02d-%02d %02d:%02d:%06.3f", sign, Y, M, d1.D - 1, d1.h, d1.m, d1.s);
    return Value::Text(buf);
  }
  *ok = false;
  return Value::Null();
}
