// JSON functions
#include "engine.h"
#include <cmath>
#include <cstring>
#include <algorithm>

struct JNode {
  enum T { Null, True, False, Int, Real, Str, Arr, Obj } t = Null;
  std::string s;          // string value (decoded) or number text
  std::vector<JNode> kids;
  std::vector<std::string> keys;
  int64_t iv = 0; double rv = 0;
  bool numText = false;   // keep original number text in s
  size_t off = 0;         // offset in source
};

struct JParser {
  const std::string& src; size_t p = 0; bool ok = true; size_t errPos = 0;
  JParser(const std::string& s) : src(s) {}
  void ws() { while (p < src.size() && (src[p] == ' ' || src[p] == '\t' || src[p] == '\n' || src[p] == '\r')) p++; if (p + 1 < src.size() && src[p] == '/' && src[p+1] == '*') { size_t q = src.find("*/", p + 2); if (q == std::string::npos) { fail(); return; } p = q + 2; ws(); } else if (p + 1 < src.size() && src[p] == '/' && src[p+1] == '/') { while (p < src.size() && src[p] != '\n') p++; ws(); } }
  void fail() { if (ok) { ok = false; errPos = p; } }
  bool parseString(std::string& out) {
    char q = src[p];
    if (q != '"' && q != '\'') { fail(); return false; }
    p++;
    while (p < src.size()) {
      char c = src[p];
      if (c == q) { p++; return true; }
      if (c == '\\') {
        p++;
        if (p >= src.size()) { fail(); return false; }
        char e = src[p++];
        switch (e) {
          case '"': out.push_back('"'); break; case '\\': out.push_back('\\'); break; case '/': out.push_back('/'); break;
          case 'b': out.push_back('\b'); break; case 'f': out.push_back('\f'); break; case 'n': out.push_back('\n'); break;
          case 'r': out.push_back('\r'); break; case 't': out.push_back('\t'); break; case '0': out.push_back('\0'); break;
          case '\'': out.push_back('\''); break; case 'v': out.push_back('\v'); break; case '\n': break;
          case 'x': { if (p + 2 > src.size()) { fail(); return false; } uint32_t v = strtoul(src.substr(p, 2).c_str(), nullptr, 16); p += 2; utf8Append(out, v); break; }
          case 'u': {
            if (p + 4 > src.size()) { fail(); return false; }
            uint32_t v = 0;
            for (int k = 0; k < 4; k++) { char h = src[p + k]; if (!isxdigit((unsigned char)h)) { fail(); return false; } v = v * 16 + (isdigit((unsigned char)h) ? h - '0' : (tolower(h) - 'a' + 10)); }
            p += 4;
            if (v >= 0xD800 && v <= 0xDBFF && p + 6 <= src.size() && src[p] == '\\' && src[p + 1] == 'u') {
              uint32_t lo = strtoul(src.substr(p + 2, 4).c_str(), nullptr, 16);
              if (lo >= 0xDC00 && lo <= 0xDFFF) { v = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00); p += 6; }
            }
            if (v == 0) out.push_back('\0'); else utf8Append(out, v);
            break;
          }
          default: fail(); return false;
        }
        continue;
      }
      if ((unsigned char)c < 0x20 && c != '\t' && c != '\n' && c != '\r') { fail(); return false; }
      out.push_back(c); p++;
    }
    fail(); return false;
  }
  JNode parseValue(int depth = 0) {
    JNode n;
    ws();
    if (!ok || p >= src.size()) { fail(); return n; }
    n.off = p;
    char c = src[p];
    if (depth > 1000) { fail(); return n; }
    if (c == '{') {
      p++; n.t = JNode::Obj;
      ws();
      if (p < src.size() && src[p] == '}') { p++; return n; }
      while (ok) {
        ws();
        if (p < src.size() && src[p] == '}') { p++; return n; }  // trailing comma
        std::string key;
        if (p < src.size() && (src[p] == '"' || src[p] == '\'')) { if (!parseString(key)) return n; }
        else { size_t s = p; while (p < src.size() && (isalnum((unsigned char)src[p]) || src[p] == '_' || src[p] == '$')) p++; if (p == s) { fail(); return n; } key = src.substr(s, p - s); }
        ws();
        if (p >= src.size() || src[p] != ':') { fail(); return n; }
        p++;
        JNode v = parseValue(depth + 1);
        if (!ok) return n;
        n.keys.push_back(key); n.kids.push_back(std::move(v));
        ws();
        if (p < src.size() && src[p] == ',') { p++; continue; }
        if (p < src.size() && src[p] == '}') { p++; return n; }
        fail(); return n;
      }
      return n;
    }
    if (c == '[') {
      p++; n.t = JNode::Arr;
      ws();
      if (p < src.size() && src[p] == ']') { p++; return n; }
      while (ok) {
        ws();
        if (p < src.size() && src[p] == ']') { p++; return n; }
        JNode v = parseValue(depth + 1);
        if (!ok) return n;
        n.kids.push_back(std::move(v));
        ws();
        if (p < src.size() && src[p] == ',') { p++; continue; }
        if (p < src.size() && src[p] == ']') { p++; return n; }
        fail(); return n;
      }
      return n;
    }
    if (c == '"' || c == '\'') { n.t = JNode::Str; if (!parseString(n.s)) return n; return n; }
    if (src.compare(p, 4, "true") == 0) { p += 4; n.t = JNode::True; return n; }
    if (src.compare(p, 5, "false") == 0) { p += 5; n.t = JNode::False; return n; }
    if (src.compare(p, 4, "null") == 0) { p += 4; n.t = JNode::Null; return n; }
    if (c == '-' || c == '+' || isdigit((unsigned char)c) || c == '.' || c == 'I' || c == 'N') {
      size_t s = p;
      if (src.compare(p, 8, "Infinity") == 0 || src.compare(p, 9, "+Infinity") == 0 || src.compare(p, 9, "-Infinity") == 0) {
        bool neg = c == '-'; p += (c == 'I') ? 8 : 9;
        n.t = JNode::Real; n.rv = neg ? -INFINITY : INFINITY; n.numText = true; n.s = neg ? "-9.0e+999" : "9.0e+999"; return n;
      }
      if (src.compare(p, 3, "NaN") == 0) { p += 3; n.t = JNode::Null; return n; }
      if (c == '-' || c == '+') p++;
      if (p + 1 < src.size() && src[p] == '0' && (src[p + 1] == 'x' || src[p + 1] == 'X')) {
        p += 2; size_t hs = p; while (p < src.size() && isxdigit((unsigned char)src[p])) p++;
        if (p == hs) { fail(); return n; }
        n.t = JNode::Int; n.iv = (int64_t)strtoull(src.substr(hs, p - hs).c_str(), nullptr, 16); if (c == '-') n.iv = -n.iv; n.s = std::to_string(n.iv); n.numText = true; return n;
      }
      bool isReal = false;
      while (p < src.size() && isdigit((unsigned char)src[p])) p++;
      if (p < src.size() && src[p] == '.') { isReal = true; p++; while (p < src.size() && isdigit((unsigned char)src[p])) p++; }
      if (p < src.size() && (src[p] == 'e' || src[p] == 'E')) { isReal = true; p++; if (p < src.size() && (src[p] == '+' || src[p] == '-')) p++; size_t es = p; while (p < src.size() && isdigit((unsigned char)src[p])) p++; if (p == es) { fail(); return n; } }
      std::string txt = src.substr(s, p - s);
      if (txt == "-" || txt == "+" || txt == "." || txt == "-." ) { fail(); return n; }
      n.numText = true; n.s = txt;
      if (!txt.empty() && txt[0] == '+') n.s = txt.substr(1);
      if (!isReal) {
        int64_t iv; double rv; int k = parseNumber(txt, iv, rv, true);
        if (k == 1) { n.t = JNode::Int; n.iv = iv; } else { n.t = JNode::Real; n.rv = rv; }
      } else { n.t = JNode::Real; n.rv = strtod(txt.c_str(), nullptr); }
      return n;
    }
    fail();
    return n;
  }
};

static bool parseJson(const std::string& s, JNode& out, size_t* errPos = nullptr) {
  JParser jp(s);
  out = jp.parseValue();
  jp.ws();
  if (jp.ok && jp.p != s.size()) { jp.fail(); }
  if (errPos) *errPos = jp.errPos;
  return jp.ok;
}

static void jsonQuoteStr(const std::string& s, std::string& out) {
  out.push_back('"');
  for (unsigned char c : s) {
    switch (c) {
      case '"': out += "\\\""; break;
      case '\\': out += "\\\\"; break;
      case '\n': out += "\\n"; break;
      case '\r': out += "\\r"; break;
      case '\t': out += "\\t"; break;
      case '\b': out += "\\b"; break;
      case '\f': out += "\\f"; break;
      default:
        if (c < 0x20) { char b[8]; snprintf(b, sizeof b, "\\u%04x", c); out += b; }
        else out.push_back((char)c);
    }
  }
  out.push_back('"');
}

static std::string jsonRealText(double r) {
  if (std::isinf(r)) return r > 0 ? "9.0e+999" : "-9.0e+999";
  if (std::isnan(r)) return "null";
  return formatDouble15(r);
}

static void serialize(const JNode& n, std::string& out) {
  switch (n.t) {
    case JNode::Null: out += "null"; break;
    case JNode::True: out += "true"; break;
    case JNode::False: out += "false"; break;
    case JNode::Int: out += n.numText ? n.s : std::to_string(n.iv); break;
    case JNode::Real: out += n.numText ? n.s : jsonRealText(n.rv); break;
    case JNode::Str: jsonQuoteStr(n.s, out); break;
    case JNode::Arr: out.push_back('['); for (size_t i = 0; i < n.kids.size(); i++) { if (i) out.push_back(','); serialize(n.kids[i], out); } out.push_back(']'); break;
    case JNode::Obj: out.push_back('{'); for (size_t i = 0; i < n.kids.size(); i++) { if (i) out.push_back(','); jsonQuoteStr(n.keys[i], out); out.push_back(':'); serialize(n.kids[i], out); } out.push_back('}'); break;
  }
}

static void serializePretty(const JNode& n, std::string& out, const std::string& indent, int level) {
  auto pad = [&](int l) { for (int i = 0; i < l; i++) out += indent; };
  switch (n.t) {
    case JNode::Arr:
      if (n.kids.empty()) { out += "[]"; return; }
      out += "[\n";
      for (size_t i = 0; i < n.kids.size(); i++) { pad(level + 1); serializePretty(n.kids[i], out, indent, level + 1); if (i + 1 < n.kids.size()) out += ","; out += "\n"; }
      pad(level); out += "]"; return;
    case JNode::Obj:
      if (n.kids.empty()) { out += "{}"; return; }
      out += "{\n";
      for (size_t i = 0; i < n.kids.size(); i++) { pad(level + 1); jsonQuoteStr(n.keys[i], out); out += ": "; serializePretty(n.kids[i], out, indent, level + 1); if (i + 1 < n.kids.size()) out += ","; out += "\n"; }
      pad(level); out += "}"; return;
    default: serialize(n, out);
  }
}

static std::string jsonMini(const JNode& n) { std::string s; serialize(n, s); return s; }

std::string jsonMinify(const std::string& s, bool& ok) {
  JNode n; ok = parseJson(s, n);
  if (!ok) return "";
  return jsonMini(n);
}

static JNode valueToJNode(const Value& v, bool& err) {
  JNode n;
  switch (v.t) {
    case VT::Null: n.t = JNode::Null; break;
    case VT::Int: n.t = JNode::Int; n.iv = v.i; break;
    case VT::Real: n.t = JNode::Real; n.rv = v.r; break;
    case VT::Text:
      if (v.sub == 'J') { JNode j; if (parseJson(v.s, j)) return j; }
      n.t = JNode::Str; n.s = v.s; break;
    case VT::Blob: {
      // treat as JSONB-ish: try parse text
      JNode j; if (parseJson(v.s, j)) return j;
      err = true; break;
    }
  }
  return n;
}

static Value jsonResult(const std::string& text) { Value v = Value::Text(text); v.sub = 'J'; return v; }

// Convert JSON node to SQL value (for ->> and json_extract)
static Value nodeToSql(const JNode& n, bool jsonForm) {
  if (jsonForm) return jsonResult(jsonMini(n));
  switch (n.t) {
    case JNode::Null: return Value::Null();
    case JNode::True: return Value::Int(1);
    case JNode::False: return Value::Int(0);
    case JNode::Int: return Value::Int(n.iv);
    case JNode::Real: return Value::Real(n.rv);
    case JNode::Str: return Value::Text(n.s);
    default: return jsonResult(jsonMini(n));
  }
}

// Path lookup. Returns pointer to node or null. Path like $.a.b[1]
static JNode* lookupPath(JNode* root, const std::string& path, bool& pathErr, std::string& errTok, bool create = false, JNode** parent = nullptr, int* parentIdx = nullptr) {
  pathErr = false;
  if (path.empty() || path[0] != '$') { pathErr = true; errTok = path; return nullptr; }
  size_t p = 1;
  JNode* cur = root;
  JNode* par = nullptr; int pidx = -1;
  while (p < path.size()) {
    if (!cur) return nullptr;
    if (path[p] == '.') {
      p++;
      std::string key;
      if (p < path.size() && path[p] == '"') {
        p++; while (p < path.size() && path[p] != '"') key.push_back(path[p++]);
        if (p >= path.size()) { pathErr = true; errTok = path.substr(p > 20 ? p - 20 : 0); return nullptr; }
        p++;
      } else {
        while (p < path.size() && path[p] != '.' && path[p] != '[') key.push_back(path[p++]);
      }
      if (cur->t != JNode::Obj) {
        if (create && cur->t == JNode::Null && false) {}
        return nullptr;
      }
      int found = -1;
      for (size_t i = 0; i < cur->keys.size(); i++) if (cur->keys[i] == key) { found = (int)i; break; }
      if (found < 0) {
        if (create) { cur->keys.push_back(key); cur->kids.push_back(JNode()); found = (int)cur->kids.size() - 1; }
        else return nullptr;
      }
      par = cur; pidx = found; cur = &cur->kids[found];
      continue;
    }
    if (path[p] == '[') {
      p++;
      size_t s = p;
      while (p < path.size() && path[p] != ']') p++;
      if (p >= path.size()) { pathErr = true; errTok = path.substr(s - 1); return nullptr; }
      std::string idxs = path.substr(s, p - s);
      p++;
      if (cur->t != JNode::Arr) return nullptr;
      int64_t idx;
      if (!idxs.empty() && idxs[0] == '#') {
        idx = (int64_t)cur->kids.size();
        if (idxs.size() > 1) { if (idxs[1] != '-') { pathErr = true; errTok = idxs; return nullptr; } idx += atoll(idxs.c_str() + 1); }
      } else {
        for (char c : idxs) if (!isdigit((unsigned char)c)) { pathErr = true; errTok = idxs; return nullptr; }
        if (idxs.empty()) { pathErr = true; errTok = "]"; return nullptr; }
        idx = atoll(idxs.c_str());
      }
      if (idx < 0 || idx >= (int64_t)cur->kids.size()) {
        if (create && idx == (int64_t)cur->kids.size()) { cur->kids.push_back(JNode()); }
        else return nullptr;
      }
      par = cur; pidx = (int)idx; cur = &cur->kids[idx];
      continue;
    }
    pathErr = true; errTok = path.substr(p); return nullptr;
  }
  if (parent) *parent = par;
  if (parentIdx) *parentIdx = pidx;
  return cur;
}

static const char* jtypeName(const JNode& n) {
  switch (n.t) {
    case JNode::Null: return "null"; case JNode::True: return "true"; case JNode::False: return "false";
    case JNode::Int: return "integer"; case JNode::Real: return "real"; case JNode::Str: return "text";
    case JNode::Arr: return "array"; case JNode::Obj: return "object";
  }
  return "null";
}

bool jsonFunctionExists(const std::string& name) {
  static const char* names[] = {"json","jsonb","json_array","jsonb_array","json_array_length","json_error_position","json_extract","jsonb_extract","json_insert","jsonb_insert","json_object","jsonb_object","json_patch","jsonb_patch","json_pretty","json_remove","jsonb_remove","json_replace","jsonb_replace","json_set","jsonb_set","json_type","json_valid","json_quote","json_group_array","json_group_object","jsonb_group_array","jsonb_group_object",nullptr};
  for (int i = 0; names[i]; i++) if (name == names[i]) return true;
  return false;
}

static JNode parseArgJson(const Value& v, const char* fname) {
  (void)fname;
  JNode n;
  if (v.t == VT::Text || v.t == VT::Blob) {
    if (!parseJson(v.s, n)) throw SqlError("malformed JSON");
    return n;
  }
  bool err = false;
  n = valueToJNode(v, err);
  if (err) throw SqlError("malformed JSON");
  return n;
}

Value callJsonFunction(const std::string& name, std::vector<Value>& args, Engine* eng, bool& handled) {
  (void)eng;
  handled = true;
  bool jsonb = name.compare(0, 5, "jsonb") == 0;
  std::string base = jsonb ? "json" + name.substr(5) : name;
  auto result = [&](const JNode& n) -> Value {
    std::string s = jsonMini(n);
    if (jsonb) return Value::Blob(s);
    return jsonResult(s);
  };
  if (name == "->" || name == "->>") {
    if (args[0].isNull() || args[1].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], name.c_str());
    std::string path;
    if (args[1].t == VT::Int) path = "$[" + std::to_string(args[1].i) + "]";
    else { path = args[1].toText(); if (path.empty() || path[0] != '$') path = "$." + path; }
    bool perr; std::string tok;
    JNode* n = lookupPath(&root, path, perr, tok);
    if (perr) throw SqlError("JSON path error near '" + tok + "'");
    if (!n) return Value::Null();
    return nodeToSql(*n, name == "->");
  }
  if (base == "json") {
    if (args[0].isNull()) return Value::Null();
    JNode n = parseArgJson(args[0], "json");
    return result(n);
  }
  if (base == "json_valid") {
    if (args[0].isNull()) return Value::Null();
    JNode n;
    if (args[0].t == VT::Blob) return Value::Int(0);
    return Value::Int(parseJson(args[0].toText(), n) ? 1 : 0);
  }
  if (base == "json_error_position") {
    if (args[0].isNull()) return Value::Null();
    JNode n; size_t ep = 0;
    if (parseJson(args[0].toText(), n, &ep)) return Value::Int(0);
    return Value::Int((int64_t)ep + 1);
  }
  if (base == "json_quote") {
    bool err = false;
    JNode n = valueToJNode(args[0], err);
    if (args[0].t == VT::Text && args[0].sub != 'J') { n = JNode(); n.t = JNode::Str; n.s = args[0].s; }
    if (args[0].t == VT::Blob) throw SqlError("JSON cannot hold BLOB values");
    return jsonResult(jsonMini(n));
  }
  if (base == "json_array") {
    JNode arr; arr.t = JNode::Arr;
    for (auto& a : args) {
      bool err = false;
      if (a.t == VT::Blob) { JNode j; if (!parseJson(a.s, j)) throw SqlError("JSON cannot hold BLOB values"); arr.kids.push_back(j); continue; }
      arr.kids.push_back(valueToJNode(a, err));
    }
    return result(arr);
  }
  if (base == "json_object") {
    if (args.size() % 2) throw SqlError("json_object() requires an even number of arguments");
    JNode obj; obj.t = JNode::Obj;
    for (size_t i = 0; i < args.size(); i += 2) {
      if (args[i].t != VT::Text && !(args[i].t == VT::Int || args[i].t == VT::Real)) throw SqlError("json_object() labels must be TEXT");
      bool err = false;
      obj.keys.push_back(args[i].toText());
      if (args[i + 1].t == VT::Blob) { JNode j; if (!parseJson(args[i + 1].s, j)) throw SqlError("JSON cannot hold BLOB values"); obj.kids.push_back(j); continue; }
      obj.kids.push_back(valueToJNode(args[i + 1], err));
    }
    return result(obj);
  }
  if (base == "__group_array") {
    JNode arr; arr.t = JNode::Arr;
    for (auto& a : args) { bool err = false; arr.kids.push_back(valueToJNode(a, err)); }
    return jsonResult(jsonMini(arr));
  }
  if (base == "__group_object") {
    JNode obj; obj.t = JNode::Obj;
    for (size_t i = 0; i + 1 < args.size(); i += 2) { bool err = false; obj.keys.push_back(args[i].toText()); obj.kids.push_back(valueToJNode(args[i + 1], err)); }
    return jsonResult(jsonMini(obj));
  }
  if (base == "json_type") {
    if (args[0].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], "json_type");
    if (args.size() > 1) {
      if (args[1].isNull()) return Value::Null();
      bool perr; std::string tok;
      JNode* n = lookupPath(&root, args[1].toText(), perr, tok);
      if (perr) throw SqlError("bad JSON path: '" + args[1].toText() + "'");
      if (!n) return Value::Null();
      return Value::Text(jtypeName(*n));
    }
    return Value::Text(jtypeName(root));
  }
  if (base == "json_array_length") {
    if (args[0].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], "json_array_length");
    JNode* n = &root;
    if (args.size() > 1) {
      if (args[1].isNull()) return Value::Null();
      bool perr; std::string tok;
      n = lookupPath(&root, args[1].toText(), perr, tok);
      if (perr) throw SqlError("bad JSON path: '" + args[1].toText() + "'");
      if (!n) return Value::Null();
    }
    if (n->t != JNode::Arr) return Value::Int(0);
    return Value::Int((int64_t)n->kids.size());
  }
  if (base == "json_extract") {
    if (args[0].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], "json_extract");
    if (args.size() == 1) return Value::Null();
    if (args.size() == 2) {
      if (args[1].isNull()) return Value::Null();
      bool perr; std::string tok;
      JNode* n = lookupPath(&root, args[1].toText(), perr, tok);
      if (perr) throw SqlError("bad JSON path: '" + args[1].toText() + "'");
      if (!n) return Value::Null();
      if (jsonb) return Value::Blob(jsonMini(*n));
      return nodeToSql(*n, false);
    }
    JNode arr; arr.t = JNode::Arr;
    for (size_t i = 1; i < args.size(); i++) {
      if (args[i].isNull()) return Value::Null();
      bool perr; std::string tok;
      JNode* n = lookupPath(&root, args[i].toText(), perr, tok);
      if (perr) throw SqlError("bad JSON path: '" + args[i].toText() + "'");
      if (!n) arr.kids.push_back(JNode()); else arr.kids.push_back(*n);
    }
    return result(arr);
  }
  if (base == "json_insert" || base == "json_replace" || base == "json_set") {
    if (args[0].isNull()) return Value::Null();
    if ((args.size() - 1) % 2) throw SqlError(base + "() needs an odd number of arguments");
    JNode root = parseArgJson(args[0], base.c_str());
    for (size_t i = 1; i + 1 < args.size(); i += 2) {
      if (args[i].isNull()) return Value::Null();
      std::string path = args[i].toText();
      bool perr; std::string tok;
      JNode* existing = lookupPath(&root, path, perr, tok);
      if (perr) throw SqlError("bad JSON path: '" + path + "'");
      bool err = false;
      JNode nv = args[i + 1].t == VT::Blob ? parseArgJson(args[i + 1], "") : valueToJNode(args[i + 1], err);
      if (existing) {
        if (base == "json_insert") continue;
        *existing = nv;
      } else {
        if (base == "json_replace") continue;
        // create: only if parent exists
        JNode* par = nullptr; int pidx = -1;
        JNode* created = lookupPath(&root, path, perr, tok, true, &par, &pidx);
        if (created) *created = nv;
      }
    }
    return result(root);
  }
  if (base == "json_remove") {
    if (args[0].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], "json_remove");
    for (size_t i = 1; i < args.size(); i++) {
      if (args[i].isNull()) return Value::Null();
      std::string path = args[i].toText();
      bool perr; std::string tok;
      JNode* par = nullptr; int pidx = -1;
      JNode* n = lookupPath(&root, path, perr, tok, false, &par, &pidx);
      if (perr) throw SqlError("bad JSON path: '" + path + "'");
      if (!n) continue;
      if (!par) { return Value::Null(); }
      par->kids.erase(par->kids.begin() + pidx);
      if (par->t == JNode::Obj) par->keys.erase(par->keys.begin() + pidx);
    }
    return result(root);
  }
  if (base == "json_patch") {
    if (args[0].isNull() || args[1].isNull()) return Value::Null();
    JNode target = parseArgJson(args[0], "json_patch");
    JNode patch = parseArgJson(args[1], "json_patch");
    std::function<void(JNode&, const JNode&)> merge = [&](JNode& t, const JNode& p) {
      if (p.t != JNode::Obj) { t = p; return; }
      if (t.t != JNode::Obj) { t = JNode(); t.t = JNode::Obj; }
      for (size_t i = 0; i < p.kids.size(); i++) {
        int found = -1;
        for (size_t k = 0; k < t.keys.size(); k++) if (t.keys[k] == p.keys[i]) { found = (int)k; break; }
        if (p.kids[i].t == JNode::Null) { if (found >= 0) { t.kids.erase(t.kids.begin() + found); t.keys.erase(t.keys.begin() + found); } continue; }
        if (found < 0) { t.keys.push_back(p.keys[i]); JNode nn; merge(nn, p.kids[i]); t.kids.push_back(nn); }
        else merge(t.kids[found], p.kids[i]);
      }
    };
    merge(target, patch);
    return result(target);
  }
  if (base == "json_pretty") {
    if (args[0].isNull()) return Value::Null();
    JNode root = parseArgJson(args[0], "json_pretty");
    std::string indent = "    ";
    if (args.size() > 1 && !args[1].isNull()) indent = args[1].toText();
    std::string out; serializePretty(root, out, indent, 0);
    return Value::Text(out);
  }
  handled = false;
  return Value::Null();
}

// json_each / json_tree rows: key, value, type, atom, id, parent, fullkey, path, json, root
void jsonEachRows(const Value& json, const Value* pathV, bool tree, std::vector<Row>& out) {
  if (json.isNull()) return;
  JNode root;
  if (!parseJson(json.toText(), root)) throw SqlError("malformed JSON");
  std::string path = pathV && !pathV->isNull() ? pathV->toText() : "$";
  bool perr; std::string tok;
  JNode* start = lookupPath(&root, path, perr, tok);
  if (perr) throw SqlError("bad JSON path: '" + path + "'");
  if (!start) return;
  int64_t idCounter = 0;
  Value jsonText = Value::Text(json.toText());
  Value rootV = pathV && !pathV->isNull() ? Value::Text(path) : Value::Null();
  std::function<void(const JNode&, const Value&, const std::string&, const std::string&, int64_t, bool)> emit;
  emit = [&](const JNode& n, const Value& key, const std::string& fullkey, const std::string& parentPath, int64_t parentId, bool isRoot) {
    int64_t id = isRoot ? 0 : (int64_t)n.off;
    (void)idCounter;
    Value atom;
    bool container = n.t == JNode::Arr || n.t == JNode::Obj;
    if (!container) atom = nodeToSql(n, false);
    Value val = container ? jsonResult(jsonMini(n)) : nodeToSql(n, false);
    if (tree || !container || !isRoot) {
      if (!(isRoot && !tree)) {
        Row r{key, val, Value::Text(jtypeName(n)), atom, Value::Int(id), isRoot ? Value::Null() : Value::Int(parentId), Value::Text(fullkey), Value::Text(parentPath), jsonText, rootV};
        out.push_back(r);
      }
    }
    if (container && (tree || isRoot)) {
      for (size_t i = 0; i < n.kids.size(); i++) {
        Value k; std::string fk;
        if (n.t == JNode::Arr) { k = Value::Int((int64_t)i); fk = fullkey + "[" + std::to_string(i) + "]"; }
        else {
          k = Value::Text(n.keys[i]);
          bool simple = !n.keys[i].empty();
          for (char c : n.keys[i]) if (!(isalnum((unsigned char)c) || c == '_')) simple = false;
          fk = fullkey + (simple ? "." + n.keys[i] : ".\"" + n.keys[i] + "\"");
        }
        emit(n.kids[i], k, fk, fullkey, id, false);
      }
    }
  };
  if (!tree && !(start->t == JNode::Arr || start->t == JNode::Obj)) {
    // json_each on a scalar: single row
    Row r{Value::Null(), nodeToSql(*start, false), Value::Text(jtypeName(*start)), nodeToSql(*start, false), Value::Int(0), Value::Null(), Value::Text(path), Value::Text(path), jsonText, rootV};
    out.push_back(r);
    return;
  }
  emit(*start, Value::Null(), path, path, 0, true);
}
