static int getVarint(const unsigned char* p, const unsigned char* end, uint64_t& v) {
  v = 0;
  for (int i = 0; i < 8; i++) {
    if (p + i >= end) return 0;
    v = (v << 7) | (p[i] & 0x7f);
    if (!(p[i] & 0x80)) return i + 1;
