static void putVarint(std::string& out, uint64_t v) {
  if (v <= 0x7f) { out.push_back((char)v); return; }
  if (v > 0x00ffffffffffffffULL) {
    // 9 bytes
    unsigned char buf[9];
    buf[8] = (unsigned char)(v & 0xff); v >>= 8;
    for (int i = 7; i >= 0; i--) { buf[i] = (unsigned char)((v & 0x7f) | 0x80); v >>= 7; }
    out.append((char*)buf, 9); return;
