static std::string encodeRecord(const std::vector<Value>& vals) {
  std::string hdr, body;
  for (auto& v : vals) {
    switch (v.t) {
      case VT::Null: putVarint(hdr, 0); break;
      case VT::Int: {
        int64_t i = v.i;
        if (i == 0) { putVarint(hdr, 8); }
        else if (i == 1) { putVarint(hdr, 9); }
        else {
          int st; int n;
          if (i >= -128 && i <= 127) { st = 1; n = 1; }
          else if (i >= -32768 && i <= 32767) { st = 2; n = 2; }
          else if (i >= -8388608 && i <= 8388607) { st = 3; n = 3; }
          else if (i >= -2147483648LL && i <= 2147483647LL) { st = 4; n = 4; }
          else if (i >= -140737488355328LL && i <= 140737488355327LL) { st = 5; n = 6; }
          else { st = 6; n = 8; }
          putVarint(hdr, st);
          for (int k = n - 1; k >= 0; k--) body.push_back((char)((uint64_t)i >> (8 * k)));
        }
        break;
      }
      case VT::Real: {
        putVarint(hdr, 7);
        uint64_t u; memcpy(&u, &v.r, 8);
        for (int k = 7; k >= 0; k--) body.push_back((char)(u >> (8 * k)));
        break;
      }
      case VT::Text: putVarint(hdr, 13 + 2 * (uint64_t)v.s.size()); body += v.s; break;
      case VT::Blob: putVarint(hdr, 12 + 2 * (uint64_t)v.s.size()); body += v.s; break;
    }
  }
  std::string hl; putVarint(hl, hdr.size() + 1);
  if (hl.size() + hdr.size() != (size_t)(hdr.size() + 1)) { hl.clear(); putVarint(hl, hdr.size() + hl.size()); }
  // header length includes itself
  std::string out;
  std::string tmp; putVarint(tmp, hdr.size() + 1);
  if (tmp.size() > 1) { tmp.clear(); putVarint(tmp, hdr.size() + 2); if (tmp.size() == 1) { tmp.clear(); putVarint(tmp, hdr.size() + 1); } }
  out = tmp + hdr + body;
  return out;
}

static bool decodeRecord(const unsigned char* p, size_t n, std::vector<Value>& out) {
