    uint64_t st; int kk = getVarint(h, hend, st);
    if (!kk) return false;
    h += kk;
    Value v;
    switch (st) {
      case 0: break;
      case 1: case 2: case 3: case 4: case 5: case 6: {
        int len = st <= 4 ? (int)st : (st == 5 ? 6 : 8);
        if (d + len > end) return false;
        int64_t iv = (d[0] & 0x80) ? -1 : 0;
        for (int i = 0; i < len; i++) iv = (iv << 8) | d[i];
        v = Value::Int(iv); d += len; break;
      }
      case 7: { if (d + 8 > end) return false; uint64_t u = 0; for (int i = 0; i < 8; i++) u = (u << 8) | d[i]; double r; memcpy(&r, &u, 8); v = Value::Real(r); d += 8; break; }
      case 8: v = Value::Int(0); break;
      case 9: v = Value::Int(1); break;
      case 10: case 11: return false;
      default: {
        uint64_t len = (st - 12) / 2;
        if (d + len > end) return false;
        if (st % 2) v = Value::Text(std::string((const char*)d, len)); else v = Value::Blob(std::string((const char*)d, len));
        d += len;
      }
    }
    out.push_back(v);
  }
  return true;
}

// ---------- Reader ----------

struct Reader {
  const std::string& data;
  int pageSize = 4096, usable = 4096;
  size_t nPages = 0;
  Reader(const std::string& d) : data(d) {}
  const unsigned char* page(uint32_t pgno) {
    if (pgno == 0 || (size_t)(pgno - 1) * pageSize + pageSize > data.size()) return nullptr;
    return (const unsigned char*)data.data() + (size_t)(pgno - 1) * pageSize;
  }
  std::string readPayload(const unsigned char* p, const unsigned char* pageEnd, uint64_t payloadLen, bool isIndex, size_t& cellBytes) {
    int U = usable;
    int maxLocal = isIndex ? ((U - 12) * 64 / 255 - 23) : (U - 35);
    int minLocal = (U - 12) * 32 / 255 - 23;
    uint64_t local;
    if (payloadLen <= (uint64_t)maxLocal) local = payloadLen;
    else {
      uint64_t surplus = minLocal + (payloadLen - minLocal) % (U - 4);
      local = surplus <= (uint64_t)maxLocal ? surplus : (uint64_t)minLocal;
    }
    std::string out;
    if (p + local > pageEnd) local = pageEnd > p ? pageEnd - p : 0;
    out.append((const char*)p, local);
    cellBytes = local;
    if (local < payloadLen) {
      if (p + local + 4 > pageEnd) return out;
      uint32_t ovfl = be32(p + local);
      cellBytes += 4;
      uint64_t remaining = payloadLen - local;
      int guard = 0;
      while (ovfl && remaining > 0 && guard++ < 1000000) {
        const unsigned char* op = page(ovfl);
        if (!op) break;
        uint32_t next = be32(op);
        uint64_t take = std::min<uint64_t>(remaining, U - 4);
        out.append((const char*)op + 4, take);
        remaining -= take;
        ovfl = next;
      }
    }
    return out;
  }
  // Walk a b-tree; callback(rowid, payload) for table trees; for index trees rowid=0
  void walk(uint32_t pgno, bool isIndex, const std::function<void(int64_t, const std::string&)>& cb, int depth = 0) {
    if (depth > 100) return;
    const unsigned char* pg = page(pgno);
    if (!pg) return;
    const unsigned char* hdr = pg + (pgno == 1 ? 100 : 0);
    const unsigned char* pageEnd = pg + pageSize;
    int type = hdr[0];
    int nCell = be16(hdr + 3);
    int hdrSize = (type == 0x02 || type == 0x05) ? 12 : 8;
    const unsigned char* ptrs = hdr + hdrSize;
    if (type == 0x05) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        if (c + 4 > pageEnd) continue;
        walk(be32(c), isIndex, cb, depth + 1);
      }
      walk(be32(hdr + 8), isIndex, cb, depth + 1);
      return;
    }
    if (type == 0x0D) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        uint64_t plen, rowid;
        int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        k = getVarint(c, pageEnd, rowid); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, false, cb2);
        cb((int64_t)rowid, payload);
      }
      return;
    }
    if (type == 0x02) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        if (c + 4 > pageEnd) continue;
        uint32_t child = be32(c); c += 4;
        walk(child, isIndex, cb, depth + 1);
        uint64_t plen; int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, true, cb2);
        cb(0, payload);
      }
      walk(be32(hdr + 8), isIndex, cb, depth + 1);
      return;
    }
    if (type == 0x0A) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        uint64_t plen; int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, true, cb2);
        cb(0, payload);
      }
    }
  }
};

static bool readFileAll(const std::string& fn, std::string& out) {
  std::ifstream f(fn, std::ios::binary);
  if (!f) return false;
  out.assign((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  return true;
}

bool Database::load(std::string& err) {
  main = Schema(); main.dbName = "main";
  loaded = true;
  if (isMemory || filename.empty()) return true;
  std::string data;
  struct stat stt;
  if (stat(filename.c_str(), &stt) != 0) { fileExistedAtOpen = false; return true; }
  fileExistedAtOpen = true;
  if (!readFileAll(filename, data)) { err = "unable to open database file"; return false; }
  if (data.empty()) return true;
  if (data.size() < 100 || data.compare(0, 16, std::string("SQLite format 3\0", 16)) != 0) { err = "file is not a database"; return false; }
  const unsigned char* h = (const unsigned char*)data.data();
  int ps = be16(h + 16); if (ps == 1) ps = 65536;
  Reader rd(data);
  rd.pageSize = ps; rd.usable = ps - h[20];
  pageSize = ps;
  fileChangeCounter = (int)be32(h + 24);
  freelistCount = (int)be32(h + 36);
  main.schemaCookie = (int)be32(h + 40);
  main.userVersion = (int)be32(h + 60);
  main.applicationId = (int)be32(h + 68);
  pageCount = (int)be32(h + 28);
  // schema
  struct Ent { SchemaEntry e; };
  std::vector<SchemaEntry> ents;
  rd.walk(1, false, [&](int64_t rowid, const std::string& payload) {
    (void)rowid;
    std::vector<Value> vals;
    if (!decodeRecord((const unsigned char*)payload.data(), payload.size(), vals) || vals.size() < 5) return;
    SchemaEntry e;
    e.type = vals[0].toText(); e.name = vals[1].toText(); e.tblName = vals[2].toText(); e.rootpage = (int)vals[3].toInt();
    if (vals[4].isNull()) e.sqlNull = true; else e.sql = vals[4].toText();
    ents.push_back(e);
  });
  // first pass: tables
  for (auto& e : ents) {
    main.addEntry(e);
    if (e.type == "table") {
      TableP t;
      if (!e.sqlNull) {
        try {
          auto stmts = parseSqlAll(e.sql);
          if (!stmts.empty() && stmts[0]->kind == Stmt::CreateTable && !stmts[0]->asSelect) t = buildTable(*stmts[0], e.sql, *this);
          else if (!stmts.empty() && stmts[0]->kind == Stmt::CreateVirtualTable) { t = std::make_shared<Table>(); t->name = e.name; t->isVirtual = true; t->sql = e.sql; }
        } catch (...) {}
      }
      if (!t) { t = std::make_shared<Table>(); t->name = e.name; t->sql = e.sql; }
      t->rootpage = e.rootpage;
      main.tables[lowerStr(t->name)] = t;
      if (t->isVirtual) continue;
      // read rows
      std::vector<int> colOrder;  // for WITHOUT ROWID: record column order -> table column index
      int nStored = 0;
      std::vector<int> storedIdx;
      for (size_t i = 0; i < t->cols.size(); i++) if (!(t->cols[i].isGenerated && !t->cols[i].genStored)) storedIdx.push_back((int)i);
      nStored = (int)storedIdx.size();
      if (t->withoutRowid) {
        std::vector<int> order;
        for (int pk : t->pkCols) order.push_back(pk);
        for (int ci : storedIdx) if (std::find(order.begin(), order.end(), ci) == order.end()) order.push_back(ci);
        colOrder = order;
      } else colOrder = storedIdx;
      int64_t seq = 0;
      rd.walk(e.rootpage, t->withoutRowid, [&](int64_t rowid, const std::string& payload) {
        std::vector<Value> vals;
        if (!decodeRecord((const unsigned char*)payload.data(), payload.size(), vals)) return;
        Row row(t->cols.size());
        for (size_t k = 0; k < colOrder.size(); k++) {
          int ci = colOrder[k];
          if (k < vals.size()) row[ci] = vals[k];
          else if (t->cols[ci].hasDefault && t->cols[ci].dflt) {
            // default for columns added by ALTER TABLE
            Engine eng(*this); Scope sc;
            try { row[ci] = applyAffinity(eng.eval(t->cols[ci].dflt, &sc), t->cols[ci].aff); } catch (...) {}
          }
        }
        if (!t->withoutRowid) {
          if (t->rowidCol >= 0) row[t->rowidCol] = Value::Int(rowid);
          t->rows[rowid] = row;
        } else t->rows[++seq] = row;
      });
      (void)nStored;
      if (t->autoinc) autoinc_dummy: ;
    }
  }
  // second pass: indexes, views, triggers
  for (auto& e : ents) {
    if (e.type == "index") {
      auto ix = std::make_shared<Index>();
      ix->name = e.name; ix->tableName = e.tblName; ix->rootpage = e.rootpage;
      TableP t = main.findTable(e.tblName);
      if (e.sqlNull) {
        ix->autoIndex = true; ix->unique = true; ix->sql = "";
        // reconstruct from table definition: nth autoindex
        if (t) {
          int n = 0; size_t us = e.name.rfind('_'); if (us != std::string::npos) n = atoi(e.name.c_str() + us + 1);
          auto stmts = parseSqlAll(t->sql);
          int cnt = 0;
          if (!stmts.empty() && stmts[0]->kind == Stmt::CreateTable) {
            auto& st = *stmts[0];
            bool done = false;
            for (auto& cd : st.colDefs) {
              if (cd.pk && !(t->rowidCol >= 0 && nameEq(t->cols[t->rowidCol].name, cd.name))) { if (++cnt == n) { IndexCol c; c.col = t->colIndex(cd.name); c.collate = t->cols[c.col].collate; c.desc = cd.pkDesc; ix->cols.push_back(c); ix->isPk = true; ix->conflict = cd.pkConflict; done = true; break; } }
              if (cd.unique) { if (++cnt == n) { IndexCol c; c.col = t->colIndex(cd.name); c.collate = t->cols[c.col].collate; ix->cols.push_back(c); ix->conflict = cd.uniqueConflict; done = true; break; } }
            }
            if (!done) for (auto& tc : st.constraints) {
              if (tc.kind == TableConstraint::PK) {
                bool isRowid = tc.cols.size() == 1 && t->rowidCol >= 0 && nameEq(t->cols[t->rowidCol].name, tc.cols[0].name);
                if (isRowid) continue;
                if (++cnt == n) { for (auto& ic : tc.cols) { IndexCol c; c.col = t->colIndex(ic.name); c.collate = ic.collate.empty() && c.col >= 0 ? t->cols[c.col].collate : ic.collate; c.desc = ic.desc; ix->cols.push_back(c); } ix->isPk = true; ix->conflict = tc.conflict; break; }
              } else if (tc.kind == TableConstraint::Unique) {
                if (++cnt == n) { for (auto& ic : tc.cols) { IndexCol c; c.col = t->colIndex(ic.name); c.collate = ic.collate.empty() && c.col >= 0 ? t->cols[c.col].collate : ic.collate; c.desc = ic.desc; if (c.col < 0) c.expr = ic.e; ix->cols.push_back(c); } ix->conflict = tc.conflict; break; }
              }
            }
          }
        }
      } else {
        ix->sql = e.sql;
        try {
          auto stmts = parseSqlAll(e.sql);
          if (!stmts.empty() && stmts[0]->kind == Stmt::CreateIndex) {
            auto& st = *stmts[0];
            ix->unique = st.unique; ix->where = st.where;
            for (auto& ic : st.indexCols) {
              IndexCol c; c.collate = ic.collate; c.desc = ic.desc;
              Expr* x = ic.e.get();
              while (x->kind == Expr::Unary && x->op == "()") x = x->args[0].get();
              if (x->kind == Expr::Column && x->table.empty() && t) {
                int ci = t->colIndex(x->column);
                if (ci >= 0) { c.col = ci; if (c.collate.empty()) c.collate = t->cols[ci].collate; }
                else if (nameEq(x->column, "rowid") || nameEq(x->column, "oid") || nameEq(x->column, "_rowid_")) c.col = -2;
                else { c.col = -1; c.expr = ic.e; }
              } else { c.col = -1; c.expr = ic.e; }
              ix->cols.push_back(c);
            }
          }
        } catch (...) {}
      }
      main.indexes[lowerStr(ix->name)] = ix;
    } else if (e.type == "view") {
      auto t = std::make_shared<Table>();
      t->name = e.name; t->isView = true; t->sql = e.sql;
      try {
        auto stmts = parseSqlAll(e.sql);
        if (!stmts.empty() && stmts[0]->kind == Stmt::CreateView) {
          t->viewSelect = stmts[0]->select; t->viewCols = stmts[0]->viewCols;
          Engine eng(*this);
          std::vector<std::string> names;
          try { names = eng.selectColumnNames(t->viewSelect, nullptr); } catch (...) {}
          std::vector<std::string> fin = t->viewCols.empty() ? names : t->viewCols;
          for (auto& n : fin) { Column c; c.name = n; t->cols.push_back(c); }
        }
      } catch (...) {}
      main.tables[lowerStr(t->name)] = t;
    } else if (e.type == "trigger") {
      auto tr = std::make_shared<Trigger>();
      tr->name = e.name; tr->tableName = e.tblName; tr->sql = e.sql;
      try {
        auto stmts = parseSqlAll(e.sql);
        if (!stmts.empty() && stmts[0]->kind == Stmt::CreateTrigger) {
          auto& st = *stmts[0];
          tr->time = st.trigTime == 0 ? 1 : st.trigTime; tr->event = st.trigEvent; tr->cols = st.trigCols; tr->when = st.trigWhen; tr->body = st.trigBody;
        }
      } catch (...) {}
      main.triggers[lowerStr(tr->name)] = tr;
    }
  }
  return true;
}

// ---------- Writer ----------

struct PageBuilder {
  int pageSize, usable;
  std::vector<std::string> pages;  // index 0 = page 1
  PageBuilder(int ps, int us) : pageSize(ps), usable(us) {}
  uint32_t alloc() { pages.push_back(std::string(pageSize, '\0')); return (uint32_t)pages.size(); }
  void ensure(uint32_t pgno) { while (pages.size() < pgno) alloc(); }
  // Store payload with overflow; returns the local part + overflow pointer bytes
  std::string storePayload(const std::string& payload, bool isIndex) {
    int U = usable;
    int maxLocal = isIndex ? ((U - 12) * 64 / 255 - 23) : (U - 35);
    int minLocal = (U - 12) * 32 / 255 - 23;
    size_t P = payload.size();
    size_t local;
    if (P <= (size_t)maxLocal) return payload;
    size_t surplus = minLocal + (P - minLocal) % (U - 4);
    local = surplus <= (size_t)maxLocal ? surplus : (size_t)minLocal;
    std::string out = payload.substr(0, local);
    size_t pos = local;
    uint32_t first = 0; uint32_t prev = 0;
    while (pos < P) {
      uint32_t pg = alloc();
      if (!first) first = pg; else put32((unsigned char*)&pages[prev - 1][0], pg);
      size_t take = std::min<size_t>(P - pos, U - 4);
      memcpy(&pages[pg - 1][4], payload.data() + pos, take);
      pos += take; prev = pg;
    }
    unsigned char b[4]; put32(b, first);
    out.append((char*)b, 4);
    return out;
  }
  // write cells into a page (given page number). type: 0x0D,0x05,0x0A,0x02. rightChild for interior.
  void writePage(uint32_t pgno, int type, const std::vector<std::string>& cells, uint32_t rightChild) {
    ensure(pgno);
    std::string& pg = pages[pgno - 1];
    int hdrOff = pgno == 1 ? 100 : 0;
    unsigned char* h = (unsigned char*)&pg[hdrOff];
    int hdrSize = (type == 0x02 || type == 0x05) ? 12 : 8;
    h[0] = (unsigned char)type;
    put16(h + 1, 0);
    put16(h + 3, (uint16_t)cells.size());
    h[7] = 0;
    if (hdrSize == 12) put32(h + 8, rightChild);
    int ptr = hdrOff + hdrSize;
    int content = usable;
    for (auto& c : cells) {
      content -= (int)c.size();
      memcpy(&pg[content], c.data(), c.size());
      put16((unsigned char*)&pg[ptr], (uint16_t)content); ptr += 2;
    }
    put16(h + 5, (uint16_t)(content == 65536 ? 0 : content));
  }
  // Build a b-tree from leaf cells; returns root page number (root placed at rootPgno if nonzero)
  // keys: for table trees, the rowid per cell; for index trees, the full cell bytes serve as divider (moved up)
  uint32_t buildTree(uint32_t rootPgno, bool isIndex, std::vector<std::string>& cells, std::vector<int64_t>& rowids) {
    int hdrLeaf = 8, hdrInt = 12;
    int cap = usable - hdrLeaf;
    // pack leaves
    std::vector<std::vector<size_t>> leaves;  // indices of cells
    {
      std::vector<size_t> cur; int used = 0;
      for (size_t i = 0; i < cells.size(); i++) {
        int sz = (int)cells[i].size() + 2;
        if (!cur.empty() && used + sz > cap) { leaves.push_back(cur); cur.clear(); used = 0; }
        cur.push_back(i); used += sz;
      }
      leaves.push_back(cur);
    }
    if (leaves.size() == 1) {
      std::vector<std::string> cs; for (size_t i : leaves[0]) cs.push_back(cells[i]);
      uint32_t pg = rootPgno ? rootPgno : alloc();
      writePage(pg, isIndex ? 0x0A : 0x0D, cs, 0);
      return pg;
    }
    // ensure each leaf (for index trees) has >= 2 cells when it is followed by another (divider removal)
    struct Node { uint32_t pgno; std::string divider; int64_t maxKey; };
    std::vector<Node> level;
    for (size_t li = 0; li < leaves.size(); li++) {
      std::vector<std::string> cs; int64_t maxKey = 0;
      std::string divider;
      auto& idxs = leaves[li];
      size_t n = idxs.size();
      bool last = li + 1 == leaves.size();
      if (isIndex && !last) {
        // move last cell up as divider
        if (n >= 2) { divider = cells[idxs[n - 1]]; n--; }
        else { divider = cells[idxs[n - 1]]; n = 0; }
      }
      for (size_t k = 0; k < n; k++) cs.push_back(cells[idxs[k]]);
      if (!isIndex) maxKey = rowids[idxs[idxs.size() - 1]];
      uint32_t pg = alloc();
      writePage(pg, isIndex ? 0x0A : 0x0D, cs, 0);
      level.push_back({pg, divider, maxKey});
    }
    // build interior levels
    while (level.size() > 1) {
      std::vector<Node> next;
      std::vector<std::string> cs; std::vector<Node> children;
      int used = 0; int capI = usable - hdrInt;
      auto flush = [&](bool lastGroup) {
        // children: all but last become cells; last is right pointer
        std::vector<std::string> cellsI;
        for (size_t k = 0; k + 1 < children.size(); k++) {
          std::string c; unsigned char b[4]; put32(b, children[k].pgno); c.append((char*)b, 4);
          if (isIndex) { std::string pl; putVarint(pl, children[k].divider.size()); std::string stored = storePayload(children[k].divider, true); c += pl + stored; }
          else putVarint(c, (uint64_t)children[k].maxKey);
          cellsI.push_back(c);
        }
        uint32_t pg = alloc();
        writePage(pg, isIndex ? 0x02 : 0x05, cellsI, children.back().pgno);
        Node nn; nn.pgno = pg; nn.maxKey = children.back().maxKey; nn.divider = children.back().divider;
        next.push_back(nn);
        (void)lastGroup;
        children.clear(); used = 0;
      };
      for (size_t i = 0; i < level.size(); i++) {
        int sz = 4 + 9 + (isIndex ? (int)level[i].divider.size() + 9 : 0) + 2;
        if (children.size() >= 2 && used + sz > capI) flush(false);
        children.push_back(level[i]); used += sz;
      }
      if (!children.empty()) flush(true);
      level = next;
      (void)cs;
    }
    // level[0] is root; relocate to rootPgno if requested
    uint32_t rootNow = level[0].pgno;
    if (rootPgno && rootPgno != rootNow) {
      ensure(rootPgno);
      // copy page content with header offset adjust (page 1 never used for user tables here)
      pages[rootPgno - 1] = pages[rootNow - 1];
      pages[rootNow - 1] = std::string(pageSize, '\0');  // becomes free; mark for freelist
      freed.push_back(rootNow);
      return rootPgno;
    }
    return rootNow;
  }
  std::vector<uint32_t> freed;
};

static int collIdOfName(const std::string& n) { if (nameEq(n, "NOCASE")) return 1; if (nameEq(n, "RTRIM")) return 2; return 0; }

// Build all pages of the database image
static void buildDatabaseImage(Database& db, Schema& sch, PageBuilder& pb) {
  pb.alloc();  // page 1
  // Determine max rootpage
  uint32_t maxRoot = 1;
  for (auto& e : sch.entries) if (e.rootpage > (int)maxRoot) maxRoot = e.rootpage;
  pb.ensure(maxRoot);
  std::vector<bool> usedRoot(maxRoot + 1, false);
  usedRoot[1] = true;
  Engine eng(db);
  // tables
  for (auto& e : sch.entries) {
    if (e.type != "table") continue;
    TableP t = sch.findTable(e.name);
    if (!t || t->isView || t->isVirtual) continue;
    std::vector<std::string> cells; std::vector<int64_t> rowids;
    std::vector<int> storedIdx;
    for (size_t i = 0; i < t->cols.size(); i++) if (!(t->cols[i].isGenerated && !t->cols[i].genStored)) storedIdx.push_back((int)i);
    if (!t->withoutRowid) {
      for (auto& kv : t->rows) {
        std::vector<Value> vals;
        for (int ci : storedIdx) { if (ci == t->rowidCol) vals.push_back(Value::Null()); else vals.push_back(ci < (int)kv.second.size() ? kv.second[ci] : Value::Null()); }
        std::string rec = encodeRecord(vals);
        std::string cell; putVarint(cell, rec.size()); putVarint(cell, (uint64_t)kv.first);
        cell += pb.storePayload(rec, false);
        cells.push_back(cell); rowids.push_back(kv.first);
      }
      usedRoot[e.rootpage] = true;
      pb.buildTree(e.rootpage, false, cells, rowids);
    } else {
      // WITHOUT ROWID: index b-tree keyed by PK columns then others
      std::vector<int> order;
      for (int pk : t->pkCols) order.push_back(pk);
      for (int ci : storedIdx) if (std::find(order.begin(), order.end(), ci) == order.end()) order.push_back(ci);
      std::vector<std::pair<std::vector<Value>, std::string>> recs;
      for (auto& kv : t->rows) {
        std::vector<Value> vals; for (int ci : order) vals.push_back(ci < (int)kv.second.size() ? kv.second[ci] : Value::Null());
        recs.push_back({vals, encodeRecord(vals)});
      }
      std::vector<int> cids; std::vector<bool> desc;
      for (int pk : t->pkCols) { cids.push_back(collIdOfName(t->cols[pk].collate)); desc.push_back(false); }
      std::sort(recs.begin(), recs.end(), [&](const auto& a, const auto& b) {
        for (size_t k = 0; k < t->pkCols.size(); k++) { int c = compareValues(a.first[k], b.first[k], cids[k]); if (c) return c < 0; }
        return false;
      });
      for (auto& r : recs) { std::string cell; putVarint(cell, r.second.size()); cell += pb.storePayload(r.second, true); cells.push_back(cell); rowids.push_back(0); }
      usedRoot[e.rootpage] = true;
      pb.buildTree(e.rootpage, true, cells, rowids);
    }
  }
  // indexes
  for (auto& e : sch.entries) {
    if (e.type != "index") continue;
    IndexP ix = sch.findIndex(e.name);
    TableP t = ix ? sch.findTable(ix->tableName) : nullptr;
    if (!ix || !t) continue;
    if (t->withoutRowid && ix->isPk) continue;  // PK index is the table itself
    std::vector<std::pair<std::vector<Value>, std::string>> recs;
    Cursor cur; cur.table = t; cur.name = t->name;
    for (auto& c : t->cols) { cur.colNames.push_back(c.name); cur.affs.push_back(c.aff); cur.colls.push_back(c.collate); }
    cur.hiddenForStar.assign(t->cols.size(), false); cur.hasRowid = !t->withoutRowid; cur.rowidCol = t->rowidCol;
    Scope sc; sc.cursors.push_back(&cur);
    for (auto& kv : t->rows) {
      cur.row = &kv.second; cur.rowid = kv.first;
      if (ix->where) { try { Value w = eng.eval(ix->where, &sc); bool nul; if (!w.truthy(&nul) || nul) continue; } catch (...) { continue; } }
      std::vector<Value> vals;
      for (auto& c : ix->cols) {
        if (c.col >= 0) vals.push_back(kv.second[c.col]);
        else if (c.col == -2) vals.push_back(Value::Int(kv.first));
        else { try { vals.push_back(eng.eval(c.expr, &sc)); } catch (...) { vals.push_back(Value::Null()); } }
      }
      if (!t->withoutRowid) vals.push_back(Value::Int(kv.first));
      else for (int pk : t->pkCols) vals.push_back(kv.second[pk]);
      recs.push_back({vals, encodeRecord(vals)});
    }
    std::vector<int> cids; std::vector<bool> desc;
    for (auto& c : ix->cols) { cids.push_back(collIdOfName(c.collate)); desc.push_back(c.desc); }
    size_t nk = ix->cols.size();
    std::sort(recs.begin(), recs.end(), [&](const auto& a, const auto& b) {
      for (size_t k = 0; k < a.first.size(); k++) {
        int c = compareValues(a.first[k], b.first[k], k < nk ? cids[k] : 0);
        if (k < nk && desc[k]) c = -c;
        if (c) return c < 0;
      }
      return false;
    });
    std::vector<std::string> cells; std::vector<int64_t> rowids;
    for (auto& r : recs) { std::string cell; putVarint(cell, r.second.size()); cell += pb.storePayload(r.second, true); cells.push_back(cell); rowids.push_back(0); }
    if (e.rootpage > 0 && e.rootpage <= (int)maxRoot) { usedRoot[e.rootpage] = true; pb.buildTree(e.rootpage, true, cells, rowids); }
  }
  // schema table (page 1)
  {
    std::vector<std::string> cells; std::vector<int64_t> rowids;
    int64_t rid = 1;
    for (auto& e : sch.entries) {
      std::vector<Value> vals{Value::Text(e.type), Value::Text(e.name), Value::Text(e.tblName), Value::Int(e.rootpage), e.sqlNull ? Value::Null() : Value::Text(e.sql)};
      std::string rec = encodeRecord(vals);
      std::string cell; putVarint(cell, rec.size()); putVarint(cell, (uint64_t)rid);
      cell += pb.storePayload(rec, false);
      cells.push_back(cell); rowids.push_back(rid++);
    }
    pb.buildTree(1, false, cells, rowids);
  }
  // freelist: unused root slots + freed pages
  std::vector<uint32_t> freePages = pb.freed;
  for (uint32_t p = 2; p <= maxRoot; p++) if (!usedRoot[p]) freePages.push_back(p);
  std::sort(freePages.begin(), freePages.end());
  uint32_t firstTrunk = 0; uint32_t nFree = (uint32_t)freePages.size();
  if (!freePages.empty()) {
    firstTrunk = freePages[0];
    std::string& pg = pb.pages[firstTrunk - 1];
    pg.assign(pb.pageSize, '\0');
    put32((unsigned char*)&pg[0], 0);
    put32((unsigned char*)&pg[4], (uint32_t)(freePages.size() - 1));
    for (size_t i = 1; i < freePages.size(); i++) { put32((unsigned char*)&pg[8 + 4 * (i - 1)], freePages[i]); pb.pages[freePages[i] - 1].assign(pb.pageSize, '\0'); }
  }
  // header
  std::string& p1 = pb.pages[0];
  unsigned char* h = (unsigned char*)&p1[0];
  memcpy(h, "SQLite format 3", 16);
  put16(h + 16, pb.pageSize == 65536 ? 1 : pb.pageSize);
  h[18] = 1; h[19] = 1; h[20] = (unsigned char)(pb.pageSize - pb.usable); h[21] = 64; h[22] = 32; h[23] = 32;
  put32(h + 24, (uint32_t)db.fileChangeCounter);
  put32(h + 28, (uint32_t)pb.pages.size());
  put32(h + 32, firstTrunk);
  put32(h + 36, nFree);
  put32(h + 40, (uint32_t)sch.schemaCookie);
  put32(h + 44, 4);
  put32(h + 48, 0);
  put32(h + 52, 0);
  put32(h + 56, 1);
  put32(h + 60, (uint32_t)sch.userVersion);
  put32(h + 64, 0);
  put32(h + 68, (uint32_t)sch.applicationId);
  put32(h + 92, (uint32_t)db.fileChangeCounter);
  put32(h + 96, 3054000);
  db.freelistCount = (int)nFree;
  db.pageCount = (int)pb.pages.size();
}

int estimatePageCount(Database& db, Schema& sch) {
  if (sch.entries.empty() && db.isMemory) return 0;
  if (sch.entries.empty()) return db.fileExistedAtOpen || db.dirty ? 1 : (db.isMemory ? 0 : 0);
  PageBuilder pb(db.pageSize, db.pageSize);
  buildDatabaseImage(db, sch, pb);
  return (int)pb.pages.size();
}

bool Database::save(std::string& err) {
  if (isMemory || filename.empty()) return true;
  if (readOnly) { err = "attempt to write a readonly database"; return false; }
  fileChangeCounter++;
  PageBuilder pb(pageSize, pageSize);
  if (main.entries.empty()) {
    // empty database: sqlite leaves a zero-length file if nothing was ever written
    if (!fileExistedAtOpen || true) {
      // write empty file (0 bytes) to mimic sqlite for never-written DBs
      std::ofstream f(filename, std::ios::binary | std::ios::trunc);
      if (!f) { err = "unable to open database file"; return false; }
      return true;
    }
  }
  buildDatabaseImage(*this, main, pb);
  std::string tmp = filename + ".tmp-write";
  {
    std::ofstream f(tmp, std::ios::binary | std::ios::trunc);
    if (!f) { err = "unable to open database file"; return false; }
    for (auto& pg : pb.pages) f.write(pg.data(), pg.size());
  }
  if (rename(tmp.c_str(), filename.c_str()) != 0) { err = "disk I/O error"; unlink(tmp.c_str()); return false; }
  return true;
}
