std::vector<StmtP> parseSqlAll(const std::string& sql);

static uint32_t be32(const unsigned char* p) { return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; }
static uint16_t be16(const unsigned char* p) { return (uint16_t)((p[0] << 8) | p[1]); }
static void put32(unsigned char* p, uint32_t v) { p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = v; }
static void put16(unsigned char* p, uint16_t v) { p[0] = v >> 8; p[1] = v; }

static int getVarint(const unsigned char* p, const unsigned char* end, uint64_t& v) {
  v = 0;
  for (int i = 0; i < 8; i++) {
    if (p + i >= end) return 0;
    v = (v << 7) | (p[i] & 0x7f);
    if (!(p[i] & 0x80)) return i + 1;
  }
  if (p + 8 >= end) return 0;
  v = (v << 8) | p[8];
  return 9;
}
static void putVarint(std::string& out, uint64_t v) {
  if (v <= 0x7f) { out.push_back((char)v); return; }
  if (v > 0x00ffffffffffffffULL) {
    // 9 bytes
    unsigned char buf[9];
    buf[8] = (unsigned char)(v & 0xff); v >>= 8;
    for (int i = 7; i >= 0; i--) { buf[i] = (unsigned char)((v & 0x7f) | 0x80); v >>= 7; }
    out.append((char*)buf, 9); return;
  }
  unsigned char buf[10]; int n = 0;
  do { buf[n++] = (unsigned char)((v & 0x7f) | 0x80); v >>= 7; } while (v);
  buf[0] &= 0x7f;
  for (int i = n - 1; i >= 0; i--) out.push_back((char)buf[i]);
}

// ---------- Record encoding ----------

static std::string encodeRecord(const std::vector<Value>& vals) {
  std::string hdr, body;
  for (auto& v : vals) {
    switch (v.t) {
      case VT::Null: putVarint(hdr, 0); break;
      case VT::Int: {
        int64_t i = v.i;
        if (i == 0) { putVarint(hdr, 8); }
        else if (i == 1) { putVarint(hdr, 9); }
        else {
          int st; int n;
          if (i >= -128 && i <= 127) { st = 1; n = 1; }
          else if (i >= -32768 && i <= 32767) { st = 2; n = 2; }
          else if (i >= -8388608 && i <= 8388607) { st = 3; n = 3; }
          else if (i >= -2147483648LL && i <= 2147483647LL) { st = 4; n = 4; }
          else if (i >= -140737488355328LL && i <= 140737488355327LL) { st = 5; n = 6; }
          else { st = 6; n = 8; }
          putVarint(hdr, st);
          for (int k = n - 1; k >= 0; k--) body.push_back((char)((uint64_t)i >> (8 * k)));
        }
        break;
      }
      case VT::Real: {
        putVarint(hdr, 7);
        uint64_t u; memcpy(&u, &v.r, 8);
        for (int k = 7; k >= 0; k--) body.push_back((char)(u >> (8 * k)));
        break;
      }
      case VT::Text: putVarint(hdr, 13 + 2 * (uint64_t)v.s.size()); body += v.s; break;
      case VT::Blob: putVarint(hdr, 12 + 2 * (uint64_t)v.s.size()); body += v.s; break;
    }
  }
  std::string hl; putVarint(hl, hdr.size() + 1);
  if (hl.size() + hdr.size() != (size_t)(hdr.size() + 1)) { hl.clear(); putVarint(hl, hdr.size() + hl.size()); }
  // header length includes itself
  std::string out;
  std::string tmp; putVarint(tmp, hdr.size() + 1);
  if (tmp.size() > 1) { tmp.clear(); putVarint(tmp, hdr.size() + 2); if (tmp.size() == 1) { tmp.clear(); putVarint(tmp, hdr.size() + 1); } }
  out = tmp + hdr + body;
  return out;
}

static bool decodeRecord(const unsigned char* p, size_t n, std::vector<Value>& out) {
  const unsigned char* end = p + n;
  uint64_t hdrLen;
  int k = getVarint(p, end, hdrLen);
  if (!k || hdrLen > n) return false;
  const unsigned char* h = p + k;
  const unsigned char* hend = p + hdrLen;
  const unsigned char* d = hend;
  out.clear();
  while (h < hend) {
    uint64_t st; int kk = getVarint(h, hend, st);
    if (!kk) return false;
    h += kk;
    Value v;
    switch (st) {
      case 0: break;
      case 1: case 2: case 3: case 4: case 5: case 6: {
        int len = st <= 4 ? (int)st : (st == 5 ? 6 : 8);
        if (d + len > end) return false;
        int64_t iv = (d[0] & 0x80) ? -1 : 0;
        for (int i = 0; i < len; i++) iv = (iv << 8) | d[i];
        v = Value::Int(iv); d += len; break;
      }
      case 7: { if (d + 8 > end) return false; uint64_t u = 0; for (int i = 0; i < 8; i++) u = (u << 8) | d[i]; double r; memcpy(&r, &u, 8); v = Value::Real(r); d += 8; break; }
      case 8: v = Value::Int(0); break;
      case 9: v = Value::Int(1); break;
      case 10: case 11: return false;
      default: {
        uint64_t len = (st - 12) / 2;
        if (d + len > end) return false;
        if (st % 2) v = Value::Text(std::string((const char*)d, len)); else v = Value::Blob(std::string((const char*)d, len));
        d += len;
      }
    }
    out.push_back(v);
  }
  return true;
}

// ---------- Reader ----------

struct Reader {
  const std::string& data;
  int pageSize = 4096, usable = 4096;
  size_t nPages = 0;
  Reader(const std::string& d) : data(d) {}
  const unsigned char* page(uint32_t pgno) {
    if (pgno == 0 || (size_t)(pgno - 1) * pageSize + pageSize > data.size()) return nullptr;
    return (const unsigned char*)data.data() + (size_t)(pgno - 1) * pageSize;
  }
  std::string readPayload(const unsigned char* p, const unsigned char* pageEnd, uint64_t payloadLen, bool isIndex, size_t& cellBytes) {
    int U = usable;
    int maxLocal = isIndex ? ((U - 12) * 64 / 255 - 23) : (U - 35);
    int minLocal = (U - 12) * 32 / 255 - 23;
    uint64_t local;
    if (payloadLen <= (uint64_t)maxLocal) local = payloadLen;
    else {
      uint64_t surplus = minLocal + (payloadLen - minLocal) % (U - 4);
      local = surplus <= (uint64_t)maxLocal ? surplus : (uint64_t)minLocal;
    }
    std::string out;
    if (p + local > pageEnd) local = pageEnd > p ? pageEnd - p : 0;
    out.append((const char*)p, local);
    cellBytes = local;
    if (local < payloadLen) {
      if (p + local + 4 > pageEnd) return out;
      uint32_t ovfl = be32(p + local);
      cellBytes += 4;
      uint64_t remaining = payloadLen - local;
      int guard = 0;
      while (ovfl && remaining > 0 && guard++ < 1000000) {
        const unsigned char* op = page(ovfl);
        if (!op) break;
        uint32_t next = be32(op);
        uint64_t take = std::min<uint64_t>(remaining, U - 4);
        out.append((const char*)op + 4, take);
        remaining -= take;
        ovfl = next;
      }
    }
    return out;
  }
  // Walk a b-tree; callback(rowid, payload) for table trees; for index trees rowid=0
  void walk(uint32_t pgno, bool isIndex, const std::function<void(int64_t, const std::string&)>& cb, int depth = 0) {
    if (depth > 100) return;
    const unsigned char* pg = page(pgno);
    if (!pg) return;
    const unsigned char* hdr = pg + (pgno == 1 ? 100 : 0);
    const unsigned char* pageEnd = pg + pageSize;
    int type = hdr[0];
    int nCell = be16(hdr + 3);
    int hdrSize = (type == 0x02 || type == 0x05) ? 12 : 8;
    const unsigned char* ptrs = hdr + hdrSize;
    if (type == 0x05) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        if (c + 4 > pageEnd) continue;
        walk(be32(c), isIndex, cb, depth + 1);
      }
      walk(be32(hdr + 8), isIndex, cb, depth + 1);
      return;
    }
    if (type == 0x0D) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        uint64_t plen, rowid;
        int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        k = getVarint(c, pageEnd, rowid); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, false, cb2);
        cb((int64_t)rowid, payload);
      }
      return;
    }
    if (type == 0x02) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        if (c + 4 > pageEnd) continue;
        uint32_t child = be32(c); c += 4;
        walk(child, isIndex, cb, depth + 1);
        uint64_t plen; int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, true, cb2);
        cb(0, payload);
      }
      walk(be32(hdr + 8), isIndex, cb, depth + 1);
      return;
    }
    if (type == 0x0A) {
      for (int i = 0; i < nCell; i++) {
        const unsigned char* c = pg + be16(ptrs + 2 * i);
        uint64_t plen; int k = getVarint(c, pageEnd, plen); if (!k) continue; c += k;
        size_t cb2;
        std::string payload = readPayload(c, pageEnd, plen, true, cb2);
        cb(0, payload);
      }
    }
  }
};

static bool readFileAll(const std::string& fn, std::string& out) {
  std::ifstream f(fn, std::ios::binary);
  if (!f) return false;
  out.assign((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  return true;
}

