// Result output formatting for the shell
#include "shell.h"
#include <cmath>
#include <cstring>
#include <algorithm>
#include <sys/ioctl.h>
#include <unistd.h>

static int displayWidth(const std::string& s) {
  // count code points, treating control chars as width 1; wide chars approximated as 1
  int n = 0;
  size_t i = 0;
  while (i < s.size()) {
    unsigned char c = s[i];
    if (c < 0x80) { n++; i++; continue; }
    size_t p = i; int cp = utf8Decode(s, p);
    i = p;
    // East Asian wide ranges (approximate)
    if ((cp >= 0x1100 && cp <= 0x115F) || (cp >= 0x2E80 && cp <= 0xA4CF) || (cp >= 0xAC00 && cp <= 0xD7A3) || (cp >= 0xF900 && cp <= 0xFAFF) || (cp >= 0xFE30 && cp <= 0xFE4F) || (cp >= 0xFF00 && cp <= 0xFF60) || (cp >= 0xFFE0 && cp <= 0xFFE6) || (cp >= 0x1F300 && cp <= 0x1F64F) || (cp >= 0x1F900 && cp <= 0x1F9FF) || (cp >= 0x20000 && cp <= 0x3FFFD)) n += 2;
    else if (cp >= 0x300 && cp <= 0x36F) n += 0;
    else n++;
  }
  return n;
}

static std::string jsonEscapeText(const std::string& s, bool blobBytes) {
  std::string out = "\"";
  for (unsigned char c : s) {
    if (blobBytes) { char b[8]; snprintf(b, sizeof b, "\\u%04x", c); out += b; continue; }
    switch (c) {
      case '"': out += "\\\""; break;
      case '\\': out += "\\\\"; break;
      case '\n': out += "\\n"; break;
      case '\r': out += "\\r"; break;
      case '\t': out += "\\t"; break;
      case '\b': out += "\\b"; break;
      case '\f': out += "\\f"; break;
      default:
        if (c < 0x20) { char b[8]; snprintf(b, sizeof b, "\\u%04x", c); out += b; }
        else out.push_back((char)c);
    }
  }
  out += "\"";
  return out;
}

static std::string htmlEscape(const std::string& s) {
  std::string out;
  for (char c : s) {
    switch (c) {
      case '<': out += "&lt;"; break;
      case '>': out += "&gt;"; break;
      case '&': out += "&amp;"; break;
      case '"': out += "&quot;"; break;
      case '\'': out += "&#39;"; break;
      default: out.push_back(c);
    }
  }
  return out;
}

static std::string tclQuote(const std::string& s) {
  std::string out = "\"";
  for (unsigned char c : s) {
    if (c == '"' || c == '\\') { out.push_back('\\'); out.push_back((char)c); }
    else if (c == '\n') out += "\\n";
    else if (c == '\r') out += "\\r";
    else if (c == '\t') out += "\\t";
    else if (c < 0x20 || c == 0x7f) { char b[8]; snprintf(b, sizeof b, "\\%03o", c); out += b; }
    else out.push_back((char)c);
  }
  out += "\"";
  return out;
}

static bool needsCsvQuote(const std::string& s, const std::string& sep) {
  if (s.empty()) return true;
  for (unsigned char c : s) {
    if (c <= 0x20 || c == '"' || c == '\'' || c >= 0x7f) return true;
  }
  if (!sep.empty() && s.find(sep) != std::string::npos) return true;
  return false;
}

static std::string csvQuote(const std::string& s, const std::string& sep) {
  if (!needsCsvQuote(s, sep)) return s;
  std::string out = "\"";
  for (char c : s) { if (c == '"') out += "\"\""; else out.push_back(c); }
  out += "\"";
  return out;
}

// SQL-style quoting of a text value, using unistr() for control characters
static std::string sqlQuoteText(const std::string& s) {
  bool needs = false;
  for (unsigned char c : s) if (c < 0x20 || c == '\\') { needs = true; break; }
  bool hasCtrl = false;
  for (unsigned char c : s) if (c < 0x20) { hasCtrl = true; break; }
  if (!hasCtrl) return sqlQuoteString(s);
  (void)needs;
  std::string out = "unistr('";
  for (unsigned char c : s) {
    if (c == '\'') out += "''";
    else if (c == '\\') out += "\\\\";
    else if (c < 0x20) { char b[8]; snprintf(b, sizeof b, "\\u%04x", c); out += b; }
    else out.push_back((char)c);
  }
  out += "')";
  return out;
}

std::string shellQuoteValue(const Value& v, const std::string& nullValue) {
  switch (v.t) {
    case VT::Null: return nullValue;
    case VT::Int: return std::to_string(v.i);
    case VT::Real: return formatDouble(v.r);
    case VT::Text: return sqlQuoteText(v.s);
    case VT::Blob: { std::string h = blobToHex(v.s); for (auto& c : h) c = (char)tolower(c); return "x'" + h + "'"; }
  }
  return nullValue;
}

static std::string valueText(const Value& v, const std::string& nullValue) {
  if (v.isNull()) return nullValue;
  return v.toText();
}

static std::vector<std::string> splitLines(const std::string& s) {
  std::vector<std::string> out;
  size_t p = 0;
  while (true) {
    size_t q = s.find('\n', p);
    if (q == std::string::npos) { out.push_back(s.substr(p)); break; }
    out.push_back(s.substr(p, q - p)); p = q + 1;
  }
  return out;
}

// wrap text to width w using sqlite's rule (break at last space within first w+1 chars)
static std::vector<std::string> wrapText(const std::string& s, int w) {
  std::vector<std::string> out;
  for (auto& line : splitLines(s)) {
    std::string rest = line;
    // strip trailing CR
    while (true) {
      if (displayWidth(rest) <= w || w <= 0) { out.push_back(rest); break; }
      // collect code point boundaries
      std::vector<size_t> bounds; size_t i = 0;
      while (i < rest.size()) { bounds.push_back(i); utf8Decode(rest, i); }
      bounds.push_back(rest.size());
      int n = (int)bounds.size() - 1;
      int lastSpace = -1;
      for (int k = 0; k <= w && k < n; k++) if (rest[bounds[k]] == ' ') lastSpace = k;
      std::string chunk;
      if (lastSpace > 0) { chunk = rest.substr(0, bounds[lastSpace]); rest = rest.substr(bounds[lastSpace] + 1); }
      else if (lastSpace == 0) { chunk = ""; rest = rest.substr(bounds[1]); }
      else { chunk = rest.substr(0, bounds[w]); rest = rest.substr(bounds[w]); }
      out.push_back(chunk);
      if (rest.empty()) break;
    }
  }
  return out;
}

struct ColumnarRow { std::vector<std::string> cells; std::vector<bool> numeric; };

static void printColumnar(Shell& sh, const std::vector<std::string>& names, const std::vector<Row>& rows) {
  ModeSettings& ms = sh.ms;
  FILE* out = sh.out;
  size_t nCol = names.size();
  // render cell texts
  std::vector<std::vector<std::string>> texts(rows.size());
  std::vector<std::vector<bool>> numeric(rows.size());
  bool quoteMode = ms.mode == Mode::Qbox || ms.quote == "sql";
  for (size_t r = 0; r < rows.size(); r++) {
    texts[r].resize(nCol); numeric[r].resize(nCol);
    for (size_t c = 0; c < nCol && c < rows[r].size(); c++) {
      const Value& v = rows[r][c];
      if (quoteMode) texts[r][c] = shellQuoteValue(v, "NULL");
      else texts[r][c] = valueText(v, ms.nullValue);
      numeric[r][c] = v.isNum();
    }
  }
  // widths
  std::vector<int> width(nCol, 0);
  std::vector<bool> rightAlign(nCol, false);
  std::vector<bool> explicitW(nCol, false);
  for (size_t c = 0; c < nCol; c++) {
    int w = 0;
    if (c < ms.widths.size() && ms.widths[c] != 0) { w = std::abs(ms.widths[c]); explicitW[c] = true; if (ms.widths[c] < 0) rightAlign[c] = true; }
    else {
      if (ms.titles) w = displayWidth(names[c]);
      for (size_t r = 0; r < rows.size(); r++) {
        for (auto& ln : splitLines(texts[r][c])) {
          int dw = displayWidth(ln);
          if (ms.wrap > 0 && dw > ms.wrap) dw = ms.wrap;
          if (dw > w) w = dw;
        }
      }
      if (ms.wrap > 0 && w > ms.wrap) w = ms.wrap;
    }
    if (w < 1 && ms.titles) w = displayWidth(names[c]);
    if (w < 1) w = 1;
    width[c] = w;
  }
  // wrap cells into lines
  std::vector<std::vector<std::vector<std::string>>> lines(rows.size());
  bool multi = false;
  for (size_t r = 0; r < rows.size(); r++) {
    lines[r].resize(nCol);
    for (size_t c = 0; c < nCol; c++) {
      int w = width[c];
      std::vector<std::string> ls;
      if (explicitW[c] || ms.wrap > 0) ls = wrapText(texts[r][c], w);
      else ls = splitLines(texts[r][c]);
      if (ls.size() > 1) multi = true;
      lines[r][c] = ls;
    }
  }
  auto pad = [&](const std::string& s, int w, int align) {  // align: 0 left, 1 right, 2 center
    int dw = displayWidth(s);
    int n = w - dw; if (n < 0) n = 0;
    if (align == 1) return std::string(n, ' ') + s;
    if (align == 2) { int l = n / 2; return std::string(l, ' ') + s + std::string(n - l, ' '); }
    return s + std::string(n, ' ');
  };
  Mode m = ms.mode;
  if (m == Mode::Split) m = Mode::Column;
  if (m == Mode::Qbox) m = Mode::Box;
  bool border = ms.border;
  if (m == Mode::Psql) border = false;
  auto rowsep = [&](const char* left, const char* mid, const char* right, const char* fill) {
    std::string s;
    if (border) s += left;
    for (size_t c = 0; c < nCol; c++) {
      if (c > 0) s += mid;
      for (int k = 0; k < width[c] + 2; k++) s += fill;
    }
    if (border) s += right;
    fputs(s.c_str(), out); fputs("\n", out);
  };
  auto cellAlign = [&](size_t c, size_t r) -> int {
    if (c < ms.align.size()) { char a = ms.align[c]; if (a == 'R' || a == 'r') return 1; if (a == 'C' || a == 'c') return 2; return 0; }
    if (rightAlign[c]) return 1;
    if (r < rows.size() && numeric[r][c]) return 1;
    return 0;
  };
  auto printRowLines = [&](const std::vector<std::vector<std::string>>& cellLines, bool isHeader, size_t r) {
    size_t nLines = 1;
    for (auto& cl : cellLines) nLines = std::max(nLines, cl.size());
    for (size_t li = 0; li < nLines; li++) {
      std::string s;
      for (size_t c = 0; c < nCol; c++) {
        std::string cell = li < cellLines[c].size() ? cellLines[c][li] : "";
        int al = isHeader ? 2 : cellAlign(c, r);
        if (m == Mode::Column) {
          if (c > 0) s += "  ";
          std::string p = pad(cell, width[c], al);
          s += p;
        } else if (m == Mode::Markdown) {
          s += "| " + pad(cell, width[c], al) + " ";
        } else if (m == Mode::Box) {
          if (c == 0 && border) s += "\u2502";
          else if (c > 0) s += "\u2502";
          s += " " + pad(cell, width[c], al) + " ";
        } else {  // table / psql
          if (c == 0 && border) s += "|";
          else if (c > 0) s += "|";
          s += " " + pad(cell, width[c], al) + " ";
        }
      }
      if (m == Mode::Markdown) s += "|";
      else if (m == Mode::Box) { if (border) s += "\u2502"; }
      else if (m == Mode::Table || m == Mode::Psql) { if (border) s += "|"; }
      if (m == Mode::Column || m == Mode::Psql || (!border && (m == Mode::Box || m == Mode::Table))) {
        // trim trailing spaces
        while (!s.empty() && s.back() == ' ') s.pop_back();
      }
      fputs(s.c_str(), out); fputs("\n", out);
    }
  };
  std::vector<std::vector<std::string>> hdrLines(nCol);
  for (size_t c = 0; c < nCol; c++) hdrLines[c] = wrapText(names[c], width[c]);
  if (m == Mode::Column) {
    if (ms.titles) {
      printRowLines(hdrLines, true, 0);
      std::string s;
      for (size_t c = 0; c < nCol; c++) { if (c) s += "  "; s += std::string(width[c], '-'); }
      fputs(s.c_str(), out); fputs("\n", out);
    }
    for (size_t r = 0; r < rows.size(); r++) {
      if (multi && r > 0) fputs("\n", out);
      printRowLines(lines[r], false, r);
    }
  } else if (m == Mode::Markdown) {
    printRowLines(hdrLines, true, 0);
    std::string s;
    for (size_t c = 0; c < nCol; c++) { s += "|"; s += std::string(width[c] + 2, '-'); }
    s += "|";
    fputs(s.c_str(), out); fputs("\n", out);
    for (size_t r = 0; r < rows.size(); r++) printRowLines(lines[r], false, r);
  } else if (m == Mode::Box) {
    if (border) rowsep("\u256d", "\u252c", "\u256e", "\u2500");
    if (ms.titles) {
      printRowLines(hdrLines, true, 0);
      rowsep("\u255e", "\u256a", "\u2561", "\u2550");
    }
    for (size_t r = 0; r < rows.size(); r++) {
      if (multi && r > 0) rowsep("\u251c", "\u253c", "\u2524", "\u2500");
      printRowLines(lines[r], false, r);
    }
    if (border) rowsep("\u2570", "\u2534", "\u256f", "\u2500");
  } else if (m == Mode::Table) {
    if (border) rowsep("+", "+", "+", "-");
    if (ms.titles) {
      printRowLines(hdrLines, true, 0);
      rowsep("+", "+", "+", "-");
    }
    for (size_t r = 0; r < rows.size(); r++) {
      if (multi && r > 0) rowsep("+", "+", "+", "-");
      printRowLines(lines[r], false, r);
    }
    if (border) rowsep("+", "+", "+", "-");
  } else if (m == Mode::Psql) {
    if (ms.titles) {
      printRowLines(hdrLines, true, 0);
      rowsep("", "+", "", "-");
    }
    for (size_t r = 0; r < rows.size(); r++) {
      if (multi && r > 0) rowsep("", "+", "", "-");
      printRowLines(lines[r], false, r);
    }
  }
}

// Row-by-row output state
struct OutputState {
  Shell* sh;
  std::vector<std::string> names;
  bool first = true;
  int64_t nRow = 0;
  std::vector<Row> buffered;
  bool columnar = false;
  int lineLabelWidth = 0;
};

static void emitValueList(Shell& sh, const std::vector<std::string>& parts, const std::string& sep, const std::string& rowSep) {
  std::string s;
  for (size_t i = 0; i < parts.size(); i++) { if (i) s += sep; s += parts[i]; }
  s += rowSep;
  fputs(s.c_str(), sh.out);
}

static std::string quoteByMode(Shell& sh, const Value& v, bool isHeader, const std::string& hdrName) {
  ModeSettings& ms = sh.ms;
  const std::string& q = ms.quote;
  if (isHeader) {
    if (q == "sql") return sqlQuoteString(hdrName);
    if (q == "csv") return csvQuote(hdrName, ms.colSep);
    if (q == "html") return htmlEscape(hdrName);
    if (q == "tcl") return tclQuote(hdrName);
    if (q == "json") return jsonEscapeText(hdrName, false);
    return hdrName;
  }
  if (q == "sql" || q == "relaxed") {
    if (v.isNull()) return ms.nullValue;
    if (v.isReal() && std::isinf(v.r)) return v.r > 0 ? "Inf" : "-Inf";
    if (q == "relaxed" && v.isText()) return v.s;
    return shellQuoteValue(v, ms.nullValue);
  }
  if (q == "csv") {
    if (v.isNull()) return ms.nullValue;
    if (v.isNum()) return v.toText();
    return csvQuote(v.toText(), ms.colSep);
  }
  if (q == "html") { if (v.isNull()) return "null"; return htmlEscape(v.toText()); }
  if (q == "tcl") {
    if (v.isNull()) return ms.nullValue;
    if (v.isNum()) return v.toText();
    return tclQuote(v.s);
  }
  if (q == "json") {
    if (v.isNull()) return "null";
    if (v.isInt()) return std::to_string(v.i);
    if (v.isReal()) { if (std::isinf(v.r)) return v.r > 0 ? "9.0e+999" : "-9.0e+999"; if (std::isnan(v.r)) return "null"; return formatDouble(v.r); }
    if (v.isBlob()) return jsonEscapeText(v.s, true);
    if (v.sub == 'J' && !v.s.empty() && (v.s[0] == '{' || v.s[0] == '[')) return v.s;
    return jsonEscapeText(v.s, false);
  }
  return valueText(v, ms.nullValue);
}

// Called by the shell for each statement
struct ResultPrinter {
  Shell& sh;
  OutputState st;
  ResultPrinter(Shell& s) : sh(s) { st.sh = &s; }
  void header(const std::vector<std::string>& names) { st.names = names; }
  void row(const Row& r) {
    ModeSettings& ms = sh.ms;
    FILE* out = sh.out;
    st.nRow++;
    switch (ms.mode) {
      case Mode::Off: return;
      case Mode::Count: return;
      case Mode::Column: case Mode::Box: case Mode::Table: case Mode::Markdown: case Mode::Psql: case Mode::Qbox: case Mode::Split:
        st.buffered.push_back(r); return;
      case Mode::List: case Mode::Ascii: {
        if (st.first && ms.titles) {
          std::vector<std::string> h; for (auto& n : st.names) h.push_back(quoteByMode(sh, Value(), true, n));
          emitValueList(sh, h, ms.colSep, ms.rowSep);
        }
        std::vector<std::string> parts; for (auto& v : r) parts.push_back(quoteByMode(sh, v, false, ""));
        emitValueList(sh, parts, ms.colSep, ms.rowSep);
        break;
      }
      case Mode::Csv: case Mode::Tabs: {
        if (st.first && ms.titles) {
          std::vector<std::string> h; for (auto& n : st.names) h.push_back(csvQuote(n, ms.colSep));
          emitValueList(sh, h, ms.colSep, ms.rowSep);
        }
        std::vector<std::string> parts;
        for (auto& v : r) { if (v.isNull()) parts.push_back(ms.nullValue); else if (v.isNum()) parts.push_back(v.toText()); else parts.push_back(csvQuote(v.toText(), ms.colSep)); }
        emitValueList(sh, parts, ms.colSep, ms.rowSep);
        break;
      }
      case Mode::Quote: case Mode::C: case Mode::Tcl: case Mode::JAtom: {
        if (st.first && ms.titles) {
          std::vector<std::string> h; for (auto& n : st.names) h.push_back(quoteByMode(sh, Value(), true, n));
          emitValueList(sh, h, ms.colSep, ms.rowSep);
        }
        std::vector<std::string> parts; for (auto& v : r) parts.push_back(quoteByMode(sh, v, false, ""));
        emitValueList(sh, parts, ms.colSep, ms.rowSep);
        break;
      }
      case Mode::Html: {
        if (st.first && ms.titles) {
          fputs("<TR>", out); fputs("\n", out);
          for (auto& n : st.names) { fputs("<TH>", out); fputs(htmlEscape(n).c_str(), out); fputs("\n", out); }
          fputs("</TR>\n", out);
        }
        fputs("<TR>\n", out);
        for (auto& v : r) { fputs("<TD>", out); fputs(quoteByMode(sh, v, false, "").c_str(), out); fputs("\n", out); }
        fputs("</TR>\n", out);
        break;
      }
      case Mode::Insert: {
        std::string s = "INSERT INTO " + (ms.tableName.empty() ? std::string("tab") : ms.tableName);
        if (ms.titles) { s += "("; for (size_t i = 0; i < st.names.size(); i++) { if (i) s += ","; s += st.names[i]; } s += ")"; }
        s += " VALUES(";
        for (size_t i = 0; i < r.size(); i++) {
          if (i) s += ",";
          const Value& v = r[i];
          if (v.isReal() && std::isinf(v.r)) s += v.r > 0 ? "Inf" : "-Inf";
          else s += shellQuoteValue(v, "NULL");
        }
        s += ");\n";
        fputs(s.c_str(), out);
        break;
      }
      case Mode::Json: {
        std::string s = st.first ? "[{" : ",\n{";
        for (size_t i = 0; i < r.size(); i++) { if (i) s += ","; s += jsonEscapeText(i < st.names.size() ? st.names[i] : "", false); s += ":"; s += quoteByMode(sh, r[i], false, ""); }
        s += "}";
        fputs(s.c_str(), out);
        break;
      }
      case Mode::JObject: {
        std::string s = "{";
        for (size_t i = 0; i < r.size(); i++) { if (i) s += ","; s += jsonEscapeText(i < st.names.size() ? st.names[i] : "", false); s += ":"; s += quoteByMode(sh, r[i], false, ""); }
        s += "}\n";
        fputs(s.c_str(), out);
        break;
      }
      case Mode::Line: {
        if (st.first) { st.lineLabelWidth = 0; for (auto& n : st.names) st.lineLabelWidth = std::max(st.lineLabelWidth, displayWidth(n)); if (st.lineLabelWidth < 5) st.lineLabelWidth = 5; }
        if (!st.first) fputs("\n", out);
        for (size_t i = 0; i < r.size(); i++) {
          std::string val = valueText(r[i], ms.nullValue);
          std::string label = i < st.names.size() ? st.names[i] : "";
          int padn = st.lineLabelWidth - displayWidth(label); if (padn < 0) padn = 0;
          std::string s = std::string(padn, ' ') + label + ": ";
          // multi-line values are indented
          std::string indent(st.lineLabelWidth + 2, ' ');
          std::string v2; for (char c : val) { v2.push_back(c); if (c == '\n') v2 += indent; }
          s += v2 + "\n";
          fputs(s.c_str(), out);
        }
        break;
      }
    }
    st.first = false;
  }
  void finish() {
    ModeSettings& ms = sh.ms;
    if (ms.mode == Mode::Count) { fprintf(sh.out, "%lld\n", (long long)st.nRow); return; }
    if (st.nRow == 0) return;
    switch (ms.mode) {
      case Mode::Json: fputs("]\n", sh.out); break;
      case Mode::Column: case Mode::Box: case Mode::Table: case Mode::Markdown: case Mode::Psql: case Mode::Qbox: case Mode::Split:
        printColumnar(sh, st.names, st.buffered); break;
      default: break;
    }
  }
};

ResultPrinter* newPrinter(Shell& sh) { return new ResultPrinter(sh); }
void printerHeader(ResultPrinter* p, const std::vector<std::string>& n) { p->header(n); }
void printerRow(ResultPrinter* p, const Row& r) { p->row(r); }
void printerFinish(ResultPrinter* p) { p->finish(); }
void deletePrinter(ResultPrinter* p) { delete p; }
int shellDisplayWidth(const std::string& s) { return displayWidth(s); }
std::string shellCsvQuote(const std::string& s, const std::string& sep) { return csvQuote(s, sep); }
