// ---------- utilities ----------

static void resolveBackslashes(std::string& z) {
  std::string out;
  for (size_t i = 0; i < z.size(); i++) {
    char c = z[i];
    if (c == '\\' && i + 1 < z.size()) {
      c = z[++i];
      if (c == 'a') c = '\a'; else if (c == 'b') c = '\b'; else if (c == 't') c = '\t'; else if (c == 'n') c = '\n';
      else if (c == 'v') c = '\v'; else if (c == 'f') c = '\f'; else if (c == 'r') c = '\r'; else if (c == '"') c = '"';
      else if (c == '\'') c = '\''; else if (c == '\\') c = '\\';
      else if (c == 'x' && i + 1 < z.size() && isxdigit((unsigned char)z[i + 1])) {
        int v = 0; int k = 0;
        while (k < 2 && i + 1 < z.size() && isxdigit((unsigned char)z[i + 1])) { char h = z[++i]; v = v * 16 + (isdigit((unsigned char)h) ? h - '0' : (tolower(h) - 'a' + 10)); k++; }
        c = (char)v;
      } else if (c >= '0' && c <= '7') {
        int v = c - '0';
        if (i + 1 < z.size() && z[i + 1] >= '0' && z[i + 1] <= '7') { v = v * 8 + (z[++i] - '0'); if (i + 1 < z.size() && z[i + 1] >= '0' && z[i + 1] <= '7') v = v * 8 + (z[++i] - '0'); }
        c = (char)v;
      }
    }
    out.push_back(c);
  }
  z = out;
}

static std::vector<std::string> splitArgs(const std::string& line) {
  std::vector<std::string> args;
  size_t i = 0, n = line.size();
  while (i < n) {
    while (i < n && isspace((unsigned char)line[i])) i++;
    if (i >= n) break;
    if (line[i] == '\'' || line[i] == '"') {
      char delim = line[i++];
      std::string a;
      while (i < n && line[i] != delim) {
        if (line[i] == '\\' && delim == '"' && i + 1 < n) { a.push_back(line[i]); i++; }
        a.push_back(line[i]); i++;
      }
      if (i < n) i++;
      if (delim == '"') resolveBackslashes(a);
      args.push_back(a);
    } else {
      size_t s = i;
      while (i < n && !isspace((unsigned char)line[i])) i++;
      args.push_back(line.substr(s, i - s));
    }
  }
  return args;
}

static bool booleanValue(const std::string& s, bool& out) {
  std::string l = lowerStr(s);
  if (l == "on" || l == "yes" || l == "1" || l == "true") { out = true; return true; }
  if (l == "off" || l == "no" || l == "0" || l == "false") { out = false; return true; }
  // integer
  char* e; long v = strtol(s.c_str(), &e, 10);
  if (*e == 0 && !s.empty()) { out = v != 0; return true; }
  return false;
}

static std::string cEscape(const std::string& s) {
  std::string out;
  for (unsigned char c : s) {
    if (c == '\n') out += "\\n"; else if (c == '\r') out += "\\r"; else if (c == '\t') out += "\\t";
    else if (c == '\\') out += "\\\\"; else if (c == '"') out += "\\\"";
    else if (c < 0x20 || c == 0x7f) { char b[8]; snprintf(b, sizeof b, "\\%03o", c); out += b; }
    else out.push_back((char)c);
  }
  return out;
}

static std::string quoteIdentIfNeeded(const std::string& s) {
  bool need = s.empty();
  for (char c : s) if (!(isalnum((unsigned char)c) || c == '_')) need = true;
  if (!need && isdigit((unsigned char)s[0])) need = true;
  if (!need) { std::string up; for (char c : s) up.push_back(toupper((unsigned char)c)); if (isKeyword(up)) need = true; }
  if (!need) return s;
  std::string out = "\"";
  for (char c : s) { if (c == '"') out += "\"\""; else out.push_back(c); }
  return out + "\"";
}

