static std::string errorContext(const std::string& sql, int offset) {
  if (offset < 0 || offset >= (int)sql.size()) return "";
  std::string z = sql; int off = offset;
  size_t start = 0;
  while (off > 50) { off--; start++; while (start < z.size() && (z[start] & 0xC0) == 0x80) { start++; off--; } }
  std::string code = z.substr(start);
  size_t len = code.size();
  if (len > 78) { len = 78; while (len > 0 && (code[len] & 0xC0) == 0x80) len--; code = code.substr(0, len); }
  for (auto& c : code) if (isspace((unsigned char)c)) c = ' ';
  std::string out = "\n  " + code + "\n  ";
  if (off < 25) out += std::string(off, ' ') + "^--- error here";
  else out += std::string(off - 14, ' ') + "error here ---^";
  return out;
}

