void Shell::showHelp(const std::vector<std::string>& args) {
  if (args.size() <= 1) {
    for (int i = 0; kHelpSummary[i]; i++) fprintf(out, "%s\n", kHelpSummary[i]);
    return;
  }
  std::string pat = args[1];
  if (pat == "-all" || pat == "--all" || pat == "-a") {
    for (int i = 0; kHelpSummary[i]; i++) fprintf(out, "%s\n", kHelpSummary[i]);
    return;
  }
  if (!pat.empty() && pat[0] == '.') pat = pat.substr(1);
  // exact prefix match first
  int n = 0;
  for (int i = 0; kHelpEntries[i].name; i++) {
    std::string nm = kHelpEntries[i].name;
    if (nm.compare(0, pat.size(), pat) == 0) { fprintf(out, "%s\n", kHelpEntries[i].detail); n++; }
  }
  if (n == 0) {
    // substring match of summary lines
    for (int i = 0; kHelpEntries[i].name; i++) {
      std::string s = kHelpEntries[i].summary;
      std::string ls = lowerStr(s), lp = lowerStr(pat);
      if (ls.find(lp) != std::string::npos) { fprintf(out, "%s\n", kHelpEntries[i].summary); n++; }
    }
  }
  if (n == 0) fprintf(out, "Nothing matches '%s'\n", args[1].c_str());
}

// ---------- schema printing ----------

static std::string viewColumnComment(Shell& sh, TableP t) {
  std::string s = "\n/* " + t->name + "(";
  for (size_t i = 0; i < t->cols.size(); i++) { if (i) s += ","; s += t->cols[i].name; }
  s += ") */";
  (void)sh;
  return s;
}

void Shell::printSchema(const std::vector<std::string>& patterns, bool indent, bool nosys, bool full) {
  (void)indent; (void)full;
  struct Item { std::string sql; std::string schema; SchemaEntry e; };
  std::vector<Item> items;
  auto collect = [&](Schema& s, const std::string& sname) {
    for (auto& e : s.entries) {
      if (e.sqlNull) continue;
      if (nosys && lowerStr(e.name).compare(0, 7, "sqlite_") == 0) continue;
      bool match = patterns.empty();
      for (auto& p : patterns) {
        std::string pat = p;
        std::string schemaPat;
        size_t dot = pat.find('.');
        if (dot != std::string::npos && pat.find_first_of("%_") == std::string::npos) { schemaPat = pat.substr(0, dot); pat = pat.substr(dot + 1); }
        if (!schemaPat.empty() && !nameEq(schemaPat, sname)) continue;
        if (likeMatch(pat, e.tblName) || likeMatch(pat, e.name)) match = true;
      }
      if (!match) continue;
      Item it; it.e = e; it.schema = sname;
      std::string sql = e.sql;
      if (sname == "temp" && e.type == "table") {
        // CREATE TABLE temp.name
        size_t p = sql.find(e.name);
        if (sql.compare(0, 13, "CREATE TABLE ") == 0) sql = "CREATE TABLE temp." + sql.substr(13);
        (void)p;
      }
      if (e.type == "view") { TableP t = s.findTable(e.name); if (t) sql += viewColumnComment(*this, t); }
      if (e.type == "table" && e.name == "sqlite_sequence" && !patterns.empty()) {}
      it.sql = sql;
      items.push_back(it);
    }
  };
  collect(db.main, "main");
  collect(db.temp, "temp");
  for (auto& it : items) fprintf(out, "%s;\n", it.sql.c_str());
}

static std::string dumpValue(const Value& v) {
  if (v.isReal() && std::isinf(v.r)) return v.r > 0 ? "Inf" : "-Inf";
  return shellQuoteValue(v, "NULL");
}

void Shell::dump(const std::vector<std::string>& patterns, bool dataOnly, bool nosys, bool preserveRowids, bool newlines) {
  (void)newlines;
  auto matches = [&](const std::string& name) {
    if (patterns.empty()) return true;
    for (auto& p : patterns) if (likeMatch(p, name)) return true;
    return false;
  };
  if (!dataOnly) { fprintf(out, "PRAGMA foreign_keys=OFF;\n"); }
  fprintf(out, "BEGIN TRANSACTION;\n");
  bool writableSchema = false;
  std::vector<SchemaEntry> tables;
  for (auto& e : db.main.entries) if (e.type == "table" && !e.sqlNull && e.name != "sqlite_sequence") tables.push_back(e);
  for (auto& e : db.main.entries) if (e.type == "table" && !e.sqlNull && e.name == "sqlite_sequence") tables.push_back(e);
  for (auto& e : tables) {
    if (!matches(e.name)) continue;
    TableP t = db.main.findTable(e.name);
    if (!t) continue;
    bool isSys = lowerStr(e.name).compare(0, 7, "sqlite_") == 0;
    if (isSys && nosys) continue;
    if (!dataOnly) {
      if (e.name == "sqlite_sequence") {
        if (!writableSchema) { fprintf(out, "PRAGMA writable_schema=ON;\n"); writableSchema = true; }
        fprintf(out, "CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);\n");
        fprintf(out, "DELETE FROM sqlite_sequence;\n");
      } else if (isSys) {
        if (lowerStr(e.name).compare(0, 11, "sqlite_stat") == 0) fprintf(out, "ANALYZE sqlite_schema;\n");
        else continue;
      } else {
        std::string sql = e.sql;
        if (sql.size() > 13 && sql.compare(0, 13, "CREATE TABLE ") == 0 && (sql[13] == '"' || sql[13] == '\'' || sql[13] == '[' || sql[13] == '`'))
          fprintf(out, "CREATE TABLE IF NOT EXISTS %s;\n", sql.substr(13).c_str());
        else fprintf(out, "%s;\n", sql.c_str());
      }
    } else if (e.name == "sqlite_sequence") {
      fprintf(out, "DELETE FROM sqlite_sequence;\n");
    }
    if (t->isVirtual) continue;
    std::string qname = quoteIdentIfNeeded(t->name);
    for (auto& kv : t->rows) {
      std::string s = "INSERT INTO " + qname;
      if (preserveRowids && !t->withoutRowid && t->rowidCol < 0) {
        s += "(rowid";
        for (size_t i = 0; i < t->cols.size(); i++) { if (t->cols[i].isGenerated) continue; s += "," + quoteIdentIfNeeded(t->cols[i].name); }
        s += ") VALUES(" + std::to_string(kv.first);
        for (size_t i = 0; i < t->cols.size(); i++) { if (t->cols[i].isGenerated) continue; s += "," + dumpValue(kv.second[i]); }
      } else {
        s += " VALUES(";
        bool first = true;
        for (size_t i = 0; i < t->cols.size(); i++) {
          if (t->cols[i].isGenerated) continue;
          if (!first) s += ","; first = false;
          s += dumpValue(kv.second[i]);
        }
      }
      s += ");\n";
      fputs(s.c_str(), out);
    }
  }
  if (!dataOnly) {
    // views, triggers, indexes: ORDER BY type DESC (view, trigger, index)
    std::vector<SchemaEntry> others;
    for (const char* ty : {"view", "trigger", "index"})
      for (auto& e : db.main.entries) if (e.type == ty && !e.sqlNull && matches(e.tblName)) others.push_back(e);
    for (auto& e : others) {
      if (nosys && lowerStr(e.name).compare(0, 7, "sqlite_") == 0) continue;
      fprintf(out, "%s;\n", e.sql.c_str());
    }
    if (writableSchema) fprintf(out, "PRAGMA writable_schema=OFF;\n");
  }
  fprintf(out, "COMMIT;\n");
}

// ---------- import ----------

void Shell::importFile(const std::vector<std::string>& args) {
  std::string file, table, schema;
  bool useAscii = false, csv = false, verbose = false;
  int skip = 0;
  char colSep = 0, rowSep = 0;
  for (size_t i = 1; i < args.size(); i++) {
    const std::string& a = args[i];
    if (a.size() > 1 && a[0] == '-' && file.empty()) {
      std::string z = a; if (z.size() > 2 && z[1] == '-') z = z.substr(1);
      if (z == "-ascii") useAscii = true;
      else if (z == "-csv") csv = true;
      else if (z == "-skip" && i + 1 < args.size()) skip = atoi(args[++i].c_str());
      else if (z == "-schema" && i + 1 < args.size()) schema = args[++i];
      else if (z == "-colsep" && i + 1 < args.size()) colSep = args[++i][0];
      else if (z == "-rowsep" && i + 1 < args.size()) rowSep = args[++i][0];
      else if (z == "-v") verbose = true;
      else if (z == "-esc" || z == "-qesc") { i++; }
      else { fprintf(stderr, "ERROR: unknown option: %s.  Use --help for help\n", a.c_str()); errCnt++; return; }
    } else if (file.empty()) file = a;
    else if (table.empty()) table = a;
    else { fprintf(stderr, "ERROR: extra argument: \"%s\".  Usage:\n.import FILE TABLE\n", a.c_str()); errCnt++; return; }
  }
  if (file.empty() || table.empty()) { fprintf(stderr, "ERROR: missing %s argument. Usage:\n.import FILE TABLE\n", file.empty() ? "FILE" : "TABLE"); errCnt++; return; }
  bool isCsv = csv || (!useAscii && ms.mode != Mode::Ascii && ms.mode != Mode::Tabs);
  if (!colSep) colSep = useAscii || ms.mode == Mode::Ascii ? '\x1f' : (ms.mode == Mode::Tabs ? '\t' : (isCsv ? ',' : (ms.colSep.empty() ? ',' : ms.colSep[0])));
  if (!rowSep) rowSep = useAscii || ms.mode == Mode::Ascii ? '\x1e' : '\n';
  if (csv) { colSep = ','; rowSep = '\n'; }
  std::string data;
  if (!file.empty() && file[0] == '|') {
    FILE* p = popen(file.c_str() + 1, "r");
    if (!p) { fprintf(stderr, "Error: cannot open \"%s\"\n", file.c_str()); errCnt++; return; }
    char buf[4096]; size_t n; while ((n = fread(buf, 1, sizeof buf, p)) > 0) data.append(buf, n);
    pclose(p);
  } else {
    std::ifstream f(file, std::ios::binary);
    if (!f) { fprintf(stderr, "Error: cannot open \"%s\"\n", file.c_str()); errCnt++; return; }
    data.assign((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  }
  // parse rows
  std::vector<std::vector<std::string>> rows;
  {
    size_t i = 0; std::vector<std::string> cur; std::string field;
    while (i <= data.size()) {
      if (i == data.size()) { if (!cur.empty() || !field.empty()) { cur.push_back(field); rows.push_back(cur); } break; }
      char c = data[i];
      if (isCsv && c == '"' && field.empty()) {
        i++;
        while (i < data.size()) {
          if (data[i] == '"') { if (i + 1 < data.size() && data[i + 1] == '"') { field.push_back('"'); i += 2; continue; } i++; break; }
          field.push_back(data[i]); i++;
        }
        continue;
      }
      if (c == colSep) { cur.push_back(field); field.clear(); i++; continue; }
      if (c == rowSep || (rowSep == '\n' && c == '\r' && i + 1 < data.size() && data[i + 1] == '\n' && !useAscii)) {
        if (c == '\r') i++;
        cur.push_back(field); field.clear(); rows.push_back(cur); cur.clear(); i++; continue;
      }
      field.push_back(c); i++;
    }
  }
  if (rows.empty()) return;
  size_t start = 0;
  while (skip-- > 0 && start < rows.size()) start++;
  TableP t = db.findTable(schema, table);
  if (!t) {
    if (start >= rows.size()) { fprintf(stderr, "%s: empty file\n", file.c_str()); errCnt++; return; }
    std::string sql = "CREATE TABLE " + (schema.empty() ? "" : schema + ".") + quoteIdentIfNeeded(table) + "(";
    for (size_t i = 0; i < rows[start].size(); i++) { if (i) sql += ","; sql += quoteIdentIfNeeded(rows[start][i]); }
    sql += ")";
    if (verbose) fprintf(out, "%s\n", sql.c_str());
    try { auto st = parseSqlAll(sql); eng.execute(st[0], [](const std::vector<std::string>&) {}, [](const Row&) {}); }
    catch (SqlError& e) { fprintf(stderr, "%s\n", e.what()); errCnt++; return; }
    t = db.findTable(schema, table);
    start++;
  }
  if (!t) return;
  size_t nCol = 0; for (auto& c : t->cols) if (!c.isGenerated && !c.hidden) nCol++;
  if (nCol == 0) { fprintf(stderr, "Error: no such table: %s\n", table.c_str()); errCnt++; return; }
  int lineno = (int)start;
  int nErr = 0;
  for (size_t r = start; r < rows.size(); r++) {
    lineno++;
    auto& row = rows[r];
    if (row.size() != nCol) {
      if (row.size() > nCol) { fprintf(stderr, "%s:%d: expected %zu columns but found %zu - extras ignored\n", file.c_str(), lineno, nCol, row.size()); row.resize(nCol); }
      else { fprintf(stderr, "%s:%d: expected %zu columns but found %zu - filling the rest with NULL\n", file.c_str(), lineno, nCol, row.size()); }
    }
    std::string sql = "INSERT INTO " + (schema.empty() ? "" : schema + ".") + quoteIdentIfNeeded(table) + " VALUES(";
    size_t k = 0;
    for (size_t i = 0; i < nCol; i++) {
      if (i) sql += ",";
      if (i < row.size()) sql += sqlQuoteString(row[i]); else sql += "NULL";
      k++;
    }
    sql += ")";
    try { auto st = parseSqlAll(sql); eng.execute(st[0], [](const std::vector<std::string>&) {}, [](const Row&) {}); }
    catch (SqlError& e) { fprintf(stderr, "%s:%d: INSERT failed: %s\n", file.c_str(), lineno, e.what()); nErr++; }
  }
  if (verbose) fprintf(out, "Added %zu rows with %d errors using %d lines of input\n", rows.size() - start - nErr, nErr, lineno);
  if (nErr) errCnt++;
}

// ---------- mode handling ----------

static const char* kModeNames[] = {"ascii","box","c","column","count","csv","html","insert","jatom","jobject","json","line","list","markdown","off","psql","qbox","quote","split","table","tabs","tcl","batch","tty",nullptr};

static Mode modeFromName(const std::string& n, bool& ok) {
  ok = true;
  if (n == "ascii") return Mode::Ascii; if (n == "box") return Mode::Box; if (n == "c") return Mode::C; if (n == "column") return Mode::Column;
  if (n == "count") return Mode::Count; if (n == "csv") return Mode::Csv; if (n == "html") return Mode::Html; if (n == "insert") return Mode::Insert;
  if (n == "jatom") return Mode::JAtom; if (n == "jobject") return Mode::JObject; if (n == "json") return Mode::Json; if (n == "line") return Mode::Line;
  if (n == "list") return Mode::List; if (n == "markdown") return Mode::Markdown; if (n == "off") return Mode::Off; if (n == "psql") return Mode::Psql;
  if (n == "qbox") return Mode::Qbox; if (n == "quote") return Mode::Quote; if (n == "split") return Mode::Split; if (n == "table") return Mode::Table;
  if (n == "tabs") return Mode::Tabs; if (n == "tcl") return Mode::Tcl;
  ok = false; return Mode::List;
}
static const char* modeName(Mode m) {
  switch (m) {
    case Mode::Ascii: return "ascii"; case Mode::Box: return "box"; case Mode::C: return "c"; case Mode::Column: return "column"; case Mode::Count: return "count";
    case Mode::Csv: return "csv"; case Mode::Html: return "html"; case Mode::Insert: return "insert"; case Mode::JAtom: return "jatom"; case Mode::JObject: return "jobject";
    case Mode::Json: return "json"; case Mode::Line: return "line"; case Mode::List: return "list"; case Mode::Markdown: return "markdown"; case Mode::Off: return "off";
    case Mode::Psql: return "psql"; case Mode::Qbox: return "qbox"; case Mode::Quote: return "quote"; case Mode::Split: return "split"; case Mode::Table: return "table";
    case Mode::Tabs: return "tabs"; case Mode::Tcl: return "tcl";
  }
  return "list";
}

// Apply per-mode defaults onto settings
static void applyModeDefaults(ModeSettings& ms, Mode m) {
  ms.mode = m;
  ms.colSep = "|"; ms.rowSep = "\n"; ms.nullValue = ""; ms.quote = "off"; ms.blobQuote = "auto"; ms.border = true; ms.swAuto = false;
  switch (m) {
    case Mode::Ascii: ms.colSep = "\x1f"; ms.rowSep = "\x1e"; ms.titles = false; break;
    case Mode::List: ms.titles = false; break;
    case Mode::Box: case Mode::Column: case Mode::Table: case Mode::Markdown: ms.titles = true; break;
    case Mode::Psql: ms.titles = true; ms.border = false; break;
    case Mode::Qbox: ms.titles = true; ms.nullValue = "NULL"; ms.quote = "sql"; break;
    case Mode::C: ms.colSep = ","; ms.nullValue = "NULL"; ms.quote = "tcl"; ms.blobQuote = "tcl"; ms.titles = false; break;
    case Mode::Count: break;
    case Mode::Csv: ms.colSep = ","; ms.rowSep = "\r\n"; ms.quote = "csv"; ms.titles = false; break;
    case Mode::Html: ms.quote = "html"; ms.titles = true; break;
    case Mode::Insert: ms.nullValue = "NULL"; ms.quote = "sql"; ms.titles = false; break;
    case Mode::JAtom: ms.colSep = ","; ms.nullValue = "null"; ms.quote = "json"; ms.titles = false; break;
    case Mode::JObject: case Mode::Json: ms.nullValue = "null"; ms.quote = "json"; break;
    case Mode::Line: ms.colSep = ": "; break;
    case Mode::Off: break;
    case Mode::Quote: ms.colSep = ","; ms.nullValue = "NULL"; ms.quote = "sql"; ms.titles = false; break;
    case Mode::Split: ms.swAuto = true; ms.titles = false; break;
    case Mode::Tabs: ms.colSep = "\t"; ms.quote = "csv"; ms.titles = false; break;
    case Mode::Tcl: ms.colSep = " "; ms.nullValue = "\"\""; ms.quote = "tcl"; ms.blobQuote = "tcl"; ms.titles = false; break;
  }
}

static std::string modeSettingsString(const ModeSettings& ms, bool verbose) {
  ModeSettings d; applyModeDefaults(d, ms.mode); d.widths.clear(); d.wrap = 0; d.wordWrap = false; d.align = ""; d.screenWidth = 0; d.multiInsert = 0; d.tableName = ""; d.textJsonb = false; d.escape = "auto"; d.lineLimit = d.charLimit = d.titleLimit = 0;
  std::string s = std::string(".mode ") + modeName(ms.mode);
  auto q = [](const std::string& v) { return "\"" + cEscape(v) + "\""; };
  bool hasTitles = ms.mode != Mode::Count && ms.mode != Mode::JObject && ms.mode != Mode::Json && ms.mode != Mode::Line && ms.mode != Mode::Off;
  if (verbose || ms.align != d.align) s += " --align " + q(ms.align);
  if (verbose || ms.border != d.border) s += std::string(" --border ") + (ms.border ? "on" : "off");
  if (verbose || ms.blobQuote != d.blobQuote) s += " --blob-quote " + ms.blobQuote;
  if (verbose || ms.colSep != d.colSep) s += " --colsep " + q(ms.colSep);
  if (verbose || ms.escape != d.escape) s += " --escape " + ms.escape;
  if (verbose || ms.lineLimit || ms.charLimit || ms.titleLimit) {
    if (!ms.lineLimit && !ms.charLimit && !ms.titleLimit) s += " --limits off";
    else if (ms.lineLimit == 5 && ms.charLimit == 300 && ms.titleLimit == 20) s += " --limits on";
    else s += " --limits " + std::to_string(ms.lineLimit) + "," + std::to_string(ms.charLimit) + "," + std::to_string(ms.titleLimit);
  }
  if (verbose || ms.multiInsert != d.multiInsert) s += " --multiinsert " + std::to_string(ms.multiInsert);
  if (verbose || ms.nullValue != d.nullValue) s += " --null " + q(ms.nullValue);
  {
    std::string qn = ms.quote;
    if (qn == "csv") qn = "hex"; else if (qn == "html") qn = "csv";
    if (verbose || ms.quote != d.quote) s += " --quote " + qn;
  }
  if (verbose || ms.rowSep != d.rowSep) s += " --rowsep " + q(ms.rowSep);
  if (verbose || ms.swAuto != d.swAuto || ms.screenWidth != d.screenWidth) s += std::string(" --sw ") + (ms.swAuto ? "auto" : std::to_string(ms.screenWidth));
  if (verbose || ms.tableName != d.tableName) s += " --tablename " + q(ms.tableName);
  if (verbose || ms.textJsonb != d.textJsonb) s += std::string(" --textjsonb ") + (ms.textJsonb ? "on" : "off");
  if (hasTitles && (verbose || ms.titles != d.titles)) s += std::string(" --titles ") + (ms.titles ? "on" : "off");
  {
    std::string w; for (size_t i = 0; i < ms.widths.size(); i++) { if (i) w += ","; w += std::to_string(ms.widths[i]); }
    if (verbose || !ms.widths.empty()) s += " --widths " + q(w);
  }
  if (verbose || ms.wordWrap != d.wordWrap) s += std::string(" --wordwrap ") + (ms.wordWrap ? "on" : "off");
  if (ms.wrap) s += " --wrap " + std::to_string(ms.wrap);
  return s;
}

// ---------- dot commands ----------

static int usageErr(Shell& sh, const char* msg) { fprintf(stderr, "%s\n", msg); (void)sh; return 1; }

int Shell::doMetaCommand(const std::string& lineIn) {
  std::string line = lineIn;
  // strip trailing whitespace
  while (!line.empty() && isspace((unsigned char)line.back())) line.pop_back();
  std::vector<std::string> args = splitArgs(line.substr(1));
  if (args.empty()) return 0;
  std::string c = args[0];
  size_t n = args.size();
  int rc = 0;
  auto badArgs = [&]() { fprintf(stderr, "Error: unknown command or invalid arguments:  \"%s\". Enter \".help\" for help\n", c.c_str()); return 1; };
  // allow unambiguous prefixes? sqlite requires full-ish names; implement exact names with a few prefixes
  auto is = [&](const char* name, size_t minLen = 0) {
    std::string nm = name;
    if (c == nm) return true;
    if (minLen && c.size() >= minLen && c.size() < nm.size() && nm.compare(0, c.size(), c) == 0) return true;
    return false;
  };
  if (is("bail", 2)) {
    if (n != 2) return usageErr(*this, "Usage: .bail on|off");
    bool b; if (!booleanValue(args[1], b)) return usageErr(*this, "Usage: .bail on|off");
    bail = b; return 0;
  }
  if (is("cd")) {
    if (n != 2) return usageErr(*this, "Usage: .cd DIRECTORY");
    if (chdir(args[1].c_str()) != 0) { fprintf(stderr, "Error: cannot change to directory \"%s\"\n", args[1].c_str()); return 1; }
    return 0;
  }
  if (is("changes", 3)) {
    if (n != 2) return usageErr(*this, "Usage: .changes on|off");
    bool b; if (!booleanValue(args[1], b)) return usageErr(*this, "Usage: .changes on|off");
    showChanges = b; return 0;
  }
  if (is("crlf")) {
    if (n == 2) { bool b; if (booleanValue(args[1], b)) crlf = b; }
    fprintf(out, "crlf is %s\n", crlf ? "ON" : "OFF");
    return 0;
  }
  if (is("databases", 2)) {
    fprintf(out, "main: %s %s\n", db.isMemory ? "\"\"" : (dbFilename[0] == '/' ? dbFilename : [&]() { char buf[4096]; if (getcwd(buf, sizeof buf)) return std::string(buf) + "/" + dbFilename; return dbFilename; }()).c_str(), db.readOnly ? "r/o" : "r/w");
    for (auto& kv : db.attached) fprintf(out, "%s: \"\" r/w\n", kv.second.dbName.c_str());
    return 0;
  }
  if (is("dbinfo", 3)) {
    Schema& s = db.main;
    int nTab = 0, nIdx = 0, nTrg = 0, nView = 0; size_t schemaSize = 0;
    for (auto& e : s.entries) { if (e.type == "table") nTab++; else if (e.type == "index") nIdx++; else if (e.type == "trigger") nTrg++; else if (e.type == "view") nView++; if (!e.sqlNull) schemaSize += e.sql.size(); }
    fprintf(out, "database page size:  %d\n", db.pageSize);
    fprintf(out, "write format:        1\nread format:         1\nreserved bytes:      0\n");
    fprintf(out, "file change counter: %d\n", db.fileChangeCounter);
    fprintf(out, "database page count: %d\n", estimatePageCount(db, s));
    fprintf(out, "freelist page count: %d\n", db.freelistCount);
    fprintf(out, "schema cookie:       %d\n", s.schemaCookie);
    fprintf(out, "schema format:       4\ndefault cache size:  0\nautovacuum top root: 0\nincremental vacuum:  0\ntext encoding:       1 (utf8)\n");
    fprintf(out, "user version:        %d\n", s.userVersion);
    fprintf(out, "application id:      %d\n", s.applicationId);
    fprintf(out, "software version:    %d\n", db.isMemory ? 0 : 3054000);
    fprintf(out, "number of tables:    %d\nnumber of indexes:   %d\nnumber of triggers:  %d\nnumber of views:     %d\nschema size:         %zu\ndata version         %d\n", nTab, nIdx, nTrg, nView, schemaSize, db.isMemory ? 3 : 5);
    return 0;
  }
  if (is("dump", 2)) {
    bool dataOnly = false, nosys = false, preserve = false, newlines = false;
    std::vector<std::string> pats;
