static bool allWhitespace(const std::string& s) {
  for (size_t i = 0; i < s.size(); i++) {
    char c = s[i];
    if (isspace((unsigned char)c)) continue;
    if (c == '/' && i + 1 < s.size() && s[i + 1] == '*') {
      size_t e = s.find("*/", i + 2);
      if (e == std::string::npos) return true;
      i = e + 1; continue;
    }
    if (c == '-' && i + 1 < s.size() && s[i + 1] == '-') {
      size_t e = s.find('\n', i);
      if (e == std::string::npos) return true;
      i = e; continue;
    }
    return false;
  }
  return true;
}

static bool readLine(FILE* in, std::string& line) {
  line.clear();
  int c;
  bool any = false;
  while ((c = fgetc(in)) != EOF) {
    any = true;
    if (c == '\n') break;
    line.push_back((char)c);
  }
  if (!any) return false;
  if (!line.empty() && line.back() == '\r') line.pop_back();
  return true;
}

int Shell::processInput(FILE* in, bool isPrimary) {
  std::string sql;
  int startLine = 0;
  int errs = 0;
  std::string line;
  bool promptMode = interactive && isPrimary;
  while (true) {
    fflush(out);
    if (promptMode) { fputs(prompt(!sql.empty(), sql).c_str(), stdout); fflush(stdout); }
    if (!readLine(in, line)) break;
    if (promptMode && !stdinIsTty) { fputs(line.c_str(), stdout); fputs("\n", stdout); }
    lineno++;
    if (sql.empty() && allWhitespace(line)) { if (echo) fprintf(out, "%s\n", line.c_str()); continue; }
    if (!line.empty() && (line[0] == '.' || line[0] == '#') && sql.empty()) {
      if (echo) fprintf(out, "%s\n", line.c_str());
      if (line[0] == '.') {
        int rc = doMetaCommand(line);
        if (rc == 2) { return errs; }
        if (rc) { errs++; if (bail) { if (isPrimary) { db.flush(); exit(1); } return errs; } }
        if (onceOutput && (lineIn_once_check:true)) {}
      }
      continue;
    }
    // "go" / "/" terminators
    std::string trimmed = line; while (!trimmed.empty() && isspace((unsigned char)trimmed.back())) trimmed.pop_back();
    if ((trimmed == "/" || lowerStr(trimmed) == "go") && !sql.empty() && sqlIsComplete(sql + ";")) line = ";";
    if (sql.empty()) {
      size_t i = 0; while (i < line.size() && isspace((unsigned char)line[i])) i++;
      sql = line.substr(i);
      startLine = lineno;
    } else {
      sql += "\n"; sql += line;
    }
    bool endsSemi = false;
    { size_t k = sql.size(); while (k > 0 && isspace((unsigned char)sql[k - 1])) k--; endsSemi = k > 0 && sql[k - 1] == ';'; }
    if (endsSemi && sqlIsComplete(sql)) {
      if (echo) fprintf(out, "%s\n", sql.c_str());
      int rc = runSql(sql, startLine, nullptr);
      if (onceOutput) { onceOutput = false; if (out != stdout) { if (outIsPipe) pclose(out); else fclose(out); } out = stdout; outFile = ""; outIsPipe = false; }
      if (onceMode) { onceMode = false; ms = savedMs; }
