    }
    dump(pats, dataOnly, nosys, preserve, newlines);
    return 0;
  }
  if (is("echo", 2)) {
    if (n != 2) return usageErr(*this, "Usage: .echo on|off");
    bool b; if (!booleanValue(args[1], b)) return usageErr(*this, "Usage: .echo on|off");
    echo = b; return 0;
  }
  if (is("eqp", 2)) {
    if (n != 2) return usageErr(*this, "Usage: .eqp off|on|trace|trigger|full");
    std::string a = lowerStr(args[1]);
    if (a == "full") eqp = 2; else if (a == "trigger") eqp = 3; else if (a == "trace") eqp = 4; else { bool b; if (!booleanValue(a, b)) return usageErr(*this, "Usage: .eqp off|on|trace|trigger|full"); eqp = b ? 1 : 0; }
    return 0;
  }
  if (is("exit", 3) || is("quit", 1)) {
    db.flush();
    int code = 0;
    if (c == "exit" && n > 1) code = (int)strtol(args[1].c_str(), nullptr, 10);
    if (n > 1 && c == "exit") { fflush(out); exit(code & 0xff); }
    return 2;
  }
  if (is("explain", 3)) {
    if (n == 1) explainMode = "on";
    else { std::string a = lowerStr(args[1]); if (a == "auto") explainMode = "auto"; else { bool b; if (!booleanValue(a, b)) return usageErr(*this, "Usage: .explain ?on|off|auto?"); explainMode = b ? "on" : "off"; } }
    return 0;
  }
  if (is("fullschema", 5)) {
    bool indent = false;
    for (size_t i = 1; i < n; i++) if (args[i] == "--indent") indent = true;
    printSchema({}, indent, false, true);
    return 0;
  }
  if (is("headers", 3) || is("header", 3)) {
    if (n != 2) return usageErr(*this, "Usage: .headers on|off");
    bool b; if (!booleanValue(args[1], b)) return usageErr(*this, "Usage: .headers on|off");
    ms.titles = b; return 0;
  }
  if (is("help", 1)) { showHelp(args); return 0; }
  if (is("import", 3)) { importFile(args); return 0; }
