    for (size_t i = 1; i < n; i++) { std::string a = args[i]; if (a == "-a" || a == "--all") all = true; else if (a == "--expr") exprOnly = true; else if (a == "--sys") sysOnly = true; else pat = a; }
    std::vector<std::string> names;
    auto collect = [&](Schema& s) {
      for (auto& e : s.entries) {
        if (e.type != "index") continue;
        IndexP ix = s.findIndex(e.name); if (!ix) continue;
        bool sys = ix->autoIndex;
        if (sys && !all && !sysOnly) continue;
        if (sysOnly && !sys) continue;
        if (exprOnly) { bool hasExpr = false; for (auto& ic : ix->cols) if (ic.col == -1) hasExpr = true; if (!hasExpr) continue; }
