    collect(db.main); collect(db.temp);
    std::sort(names.begin(), names.end(), [](const std::string& a, const std::string& b) { return lowerStr(a) < lowerStr(b); });
    for (auto& nm : names) fprintf(out, "%s\n", nm.c_str());
    return 0;
  }
  if (is("limit", 3) || is("limits", 3)) {
    static const char* lim[] = {"length","sql_length","column","expr_depth","compound_select","vdbe_op","function_arg","attached","like_pattern_length","variable_number","trigger_depth","worker_threads",nullptr};
    static int vals[] = {1000000000,1000000000,2000,1000,500,250000000,1000,10,50000,32766,1000,0};
    if (n == 1) { for (int i = 0; lim[i]; i++) fprintf(out, "%20s %d\n", lim[i], vals[i]); return 0; }
    std::string a = lowerStr(args[1]); int found = -1;
    for (int i = 0; lim[i]; i++) if (std::string(lim[i]).compare(0, a.size(), a) == 0) { if (found >= 0) { fprintf(stderr, "ambiguous limit: \"%s\"\n", args[1].c_str()); return 1; } found = i; }
    if (found < 0) { fprintf(stderr, "unknown limit: \"%s\"\nenter \".limits\" with no arguments for a list\n", args[1].c_str()); return 1; }
    if (n == 3) vals[found] = atoi(args[2].c_str());
    fprintf(out, "%20s %d\n", lim[found], vals[found]);
    return 0;
  }
  if (is("log", 3)) { if (n != 2) return usageErr(*this, "Usage: .log FILENAME"); logFile = args[1]; return 0; }
  if (is("mode", 1)) {
    if (n == 1) { fprintf(out, "%s\n", modeSettingsString(ms, false).c_str()); return 0; }
    bool verbose = false;
    ModeSettings work = ms;
    bool onceFlag = false;
    for (size_t i = 1; i < n; i++) {
      std::string a = args[i];
      if (a.size() >= 2 && a[0] == '-') {
        std::string z = a; if (z.size() > 2 && z[1] == '-') z = z.substr(1);
        std::string opt = lowerStr(z.substr(1));
        auto need = [&](std::string& v) { if (i + 1 >= n) { fprintf(stderr, "argv[%zu]: %s\nargv[%zu]: missing argument\n", i, line.c_str(), i); return false; } v = args[++i]; return true; };
        std::string v;
        if (opt == "v" || opt == "verbose") verbose = true;
        else if (opt == "list") { fprintf(out, "available modes:"); for (int k = 0; kModeNames[k]; k++) fprintf(out, " %s", kModeNames[k]); fprintf(out, "\n"); return 0; }
        else if (opt == "once") onceFlag = true;
        else if (opt == "reset") { ModeSettings fresh; work = fresh; }
        else if (opt == "align") { if (!need(v)) return 1; work.align = v; }
        else if (opt == "blob-quote") { if (!need(v)) return 1; std::string lv = lowerStr(v); if (lv == "auto" || lv == "text" || lv == "sql" || lv == "hex" || lv == "tcl" || lv == "json" || lv == "size") work.blobQuote = lv; else { fprintf(stderr, "argv[%zu]: %s\nargv[%zu]: %*s---^\nargv[%zu]: should be auto, text, sql, hex, tcl, json, or size\n", i, line.c_str(), i, (int)line.find(v) + 1 - 3, "unknown", i); return 1; } }
        else if (opt == "border") { if (!need(v)) return 1; bool b; if (!booleanValue(v, b)) return badArgs(); work.border = b; }
        else if (opt == "charlimit") { if (!need(v)) return 1; work.charLimit = atoi(v.c_str()); }
        else if (opt == "colsep") { if (!need(v)) return 1; work.colSep = v; }
        else if (opt == "escape") { if (!need(v)) return 1; work.escape = lowerStr(v); }
        else if (opt == "linelimit") { if (!need(v)) return 1; work.lineLimit = atoi(v.c_str()); }
        else if (opt == "limits") { if (!need(v)) return 1; std::string lv = lowerStr(v); if (lv == "off") { work.lineLimit = work.charLimit = work.titleLimit = 0; } else if (lv == "on") { work.lineLimit = 5; work.charLimit = 300; work.titleLimit = 20; } else { int a1 = 0, a2 = 0, a3 = work.titleLimit; sscanf(v.c_str(), "%d,%d,%d", &a1, &a2, &a3); work.lineLimit = a1; work.charLimit = a2; work.titleLimit = a3; } }
        else if (opt == "multiinsert") { if (!need(v)) return 1; work.multiInsert = atoi(v.c_str()); }
        else if (opt == "null") { if (!need(v)) return 1; work.nullValue = v; }
        else if (opt == "quote") {
          if (!need(v)) return 1; std::string lv = lowerStr(v);
          if (lv == "off") work.quote = "off"; else if (lv == "on") { work.quote = "sql"; work.nullValue = "NULL"; } else if (lv == "sql" || lv == "relaxed" || lv == "csv" || lv == "html" || lv == "tcl" || lv == "json") work.quote = lv;
          else { size_t pos = line.find(v); fprintf(stderr, "argv[%zu]: %s\nargv[%zu]: %*s ---^\nargv[%zu]: should be off, on, sql, csv, html, tcl, json, or relaxed\n", i, line.c_str(), i, (int)pos + 1 + 3 - 4 + 7 - 3 + 2 - 1 - 1 - 1, "unknown", i); return 1; }
        }
        else if (opt == "rowsep") { if (!need(v)) return 1; work.rowSep = v; }
        else if (opt == "sw" || opt == "screenwidth") { if (!need(v)) return 1; if (lowerStr(v) == "auto") { work.swAuto = true; work.screenWidth = 0; } else { work.swAuto = false; work.screenWidth = atoi(v.c_str()); } }
        else if (opt == "tablename") { if (!need(v)) return 1; work.tableName = v; }
        else if (opt == "tag") { if (!need(v)) return 1; }
        else if (opt == "textjsonb") { if (!need(v)) return 1; bool b; booleanValue(v, b); work.textJsonb = b; }
        else if (opt == "title" || opt == "titles") { if (!need(v)) return 1; std::string lv = lowerStr(v); bool b; if (booleanValue(lv, b)) work.titles = b; else if (lv == "sql" || lv == "csv" || lv == "html" || lv == "tcl" || lv == "json") work.titles = true; else return badArgs(); }
        else if (opt == "titlelimit") { if (!need(v)) return 1; work.titleLimit = atoi(v.c_str()); }
        else if (opt == "widths") { if (!need(v)) return 1; work.widths.clear(); std::stringstream ss(v); std::string tok; while (std::getline(ss, tok, ',')) if (!tok.empty()) work.widths.push_back(atoi(tok.c_str())); }
        else if (opt == "wordwrap") { if (!need(v)) return 1; bool b; if (!booleanValue(v, b)) return badArgs(); work.wordWrap = b; }
        else if (opt == "wrap") { if (!need(v)) return 1; work.wrap = atoi(v.c_str()); }
        else if (opt == "ww") work.wordWrap = true;
        else { fprintf(stderr, "argv[%zu]: %s\nargv[%zu]: unknown option\n", i, line.c_str(), i); return 1; }
        continue;
      }
      std::string lm = lowerStr(a);
      if (lm == "batch") { bool ok; Mode m = modeFromName("list", ok); bool t = work.titles; applyModeDefaults(work, m); (void)t; continue; }
      if (lm == "tty") { bool ok; Mode m = modeFromName("qbox", ok); applyModeDefaults(work, m); work.colSep = ""; work.rowSep = ""; work.lineLimit = 5; work.charLimit = 300; work.titleLimit = 20; work.multiInsert = 3000; work.quote = "relaxed"; work.swAuto = true; work.textJsonb = true; continue; }
      bool ok; Mode m = modeFromName(lm, ok);
      if (!ok) {
        // prefix match
        int cnt = 0; std::string full;
        for (int k = 0; kModeNames[k]; k++) if (std::string(kModeNames[k]).compare(0, lm.size(), lm) == 0) { cnt++; full = kModeNames[k]; }
        if (cnt == 1) { m = modeFromName(full, ok); if (full == "batch") { m = modeFromName("list", ok); } }
        if (!ok) { fprintf(stderr, "Error: mode should be one of: ascii box c column count csv html insert jatom jobject json line list markdown off psql qbox quote split table tabs tcl batch tty\n"); return 1; }
      }
      bool keepTitles = work.titles;
      applyModeDefaults(work, m);
      if (m == Mode::Count || m == Mode::Line || m == Mode::Json || m == Mode::JObject || m == Mode::Off) work.titles = keepTitles;
      if ((m == Mode::Insert) && i + 1 < n && args[i + 1][0] != '-') { work.tableName = args[++i]; }
    }
    if (onceFlag) { savedMs = ms; onceMode = true; }
    ms = work;
    if (verbose) fprintf(out, "%s\n", modeSettingsString(ms, true).c_str());
    return 0;
  }
  if (is("nonce")) { return 0; }
  if (is("nullvalue", 4)) {
    if (n != 2) return usageErr(*this, "Usage: .nullvalue STRING");
    ms.nullValue = args[1]; return 0;
  }
  if (is("once", 3) || is("output", 3) || is("excel") || is("www")) {
    bool once = c == "once" || c == "excel" || c == "www";
    std::string fname;
    bool bom = false; bool plain = false;
    for (size_t i = 1; i < n; i++) {
      std::string a = args[i];
      if (a.size() > 1 && a[0] == '-' && fname.empty()) { std::string z = a; if (z.size() > 2 && z[1] == '-') z = z.substr(1); if (z == "-bom") bom = true; else if (z == "-plain") plain = true; else if (z == "-x" || z == "-e" || z == "-w") {} else { fprintf(stderr, "ERROR: unknown option: %s.  Use --help for help\n", a.c_str()); return 1; } }
      else if (fname.empty()) fname = a;
      else { fprintf(stderr, "ERROR: extra parameter: \"%s\".  Use --help for help\n", a.c_str()); return 1; }
    }
    (void)plain;
    // close current
    if (out != stdout) { if (outIsPipe) pclose(out); else fclose(out); out = stdout; outIsPipe = false; }
    onceOutput = false;
    if (fname.empty() || fname == "stdout") { out = stdout; outFile = ""; }
    else if (fname == "stderr") { out = stderr; outFile = "stderr"; }
    else if (fname[0] == '|') {
      out = popen(fname.c_str() + 1, "w");
