      outIsPipe = true; outFile = fname;
    } else {
      FILE* f = fopen(fname.c_str(), "wb");
      if (!f) { fprintf(stderr, "Error: cannot write to \"%s\"\n", fname.c_str()); return 1; }
      out = f; outFile = fname;
      if (bom) fputs("\xef\xbb\xbf", out);
    }
    if (once && out != stdout) onceOutput = true;
    return 0;
  }
  if (is("open", 2)) {
    std::string fname; bool newDb = false;
    for (size_t i = 1; i < n; i++) {
      std::string a = args[i];
      if (a.size() > 1 && a[0] == '-') { std::string z = a; if (z.size() > 2 && z[1] == '-') z = z.substr(1);
        if (z == "-new") newDb = true; else if (z == "-readonly") readOnlyOpt = true; else if (z == "-nofollow" || z == "-deserialize" || z == "-append" || z == "-zip" || z == "-hexdb") {}
        else if (z == "-maxsize") i++;
        else { fprintf(stderr, "unknown option: %s\n", a.c_str()); return 1; } }
      else fname = a;
    }
    db.flush();
    if (newDb && !fname.empty()) unlink(fname.c_str());
    openDb(fname, false);
    if (!openedOk) { openedOk = true; openDb("", false); return 1; }
