    else { in = fopen(f.c_str(), "rb"); if (!in) { fprintf(stderr, "Error: cannot open \"%s\"\n", f.c_str()); return 1; } }
    std::string savedName = inputFileName; int savedLine = lineno;
    inputFileName = pipe ? "" : f; lineno = 0;
    bool savedInteractive = interactive; interactive = false;
    int r = processInput(in, false);
    interactive = savedInteractive;
