    for (size_t i = 1; i < n; i++) { if (args[i][0] == '-') continue; pos.push_back(args[i]); }
    if (pos.empty()) { fprintf(stderr, "Usage: .%s ?DB? FILE\n", c.c_str()); return 1; }
    f = pos.back();
    if (c == "restore") {
      Database other; other.isMemory = false; other.filename = f;
      std::string err; if (!other.load(err)) { fprintf(stderr, "Error: %s\n", err.c_str()); return 1; }
      db.main = other.main; db.dirty = true; db.flush();
