    return 0;
  }
  if (is("scanstats", 4)) { if (n != 2) return usageErr(*this, "Usage: .scanstats on|off|est"); return 0; }
  if (is("schema", 3)) {
    bool indent = false, nosys = false; std::vector<std::string> pats;
    for (size_t i = 1; i < n; i++) {
      std::string a = args[i];
      if (a.size() > 1 && a[0] == '-') { std::string z = a; if (z.size() > 2 && z[1] == '-') z = z.substr(1); if (z == "-indent") indent = true; else if (z == "-nosys") nosys = true; else { fprintf(stderr, "Unknown option \"%s\" on \".schema\"\n", a.c_str()); return 1; } }
