  }
  if (is("tables", 2)) {
    std::string pat = n > 1 ? args[1] : "";
    std::vector<std::string> names;
    for (auto& e : db.main.entries) { if ((e.type == "table" || e.type == "view") && lowerStr(e.name).compare(0, 7, "sqlite_") != 0) { if (pat.empty() ? true : likeMatch(pat, e.name)) names.push_back(e.name); } }
