    for (auto& kv : db.attached) for (auto& e : kv.second.entries) if ((e.type == "table" || e.type == "view") && lowerStr(e.name).compare(0, 7, "sqlite_") != 0) { if (pat.empty() ? true : likeMatch(pat, e.name)) names.push_back(kv.second.dbName + "." + e.name); }
    std::sort(names.begin(), names.end());
    if (names.empty()) return 0;
    // layout: column-major, minimal rows such that width <= 80
    size_t nRow = 1;
    std::vector<int> colW;
    int screen = 80;
    while (true) {
      size_t nCol = (names.size() + nRow - 1) / nRow;
      colW.assign(nCol, 0);
      for (size_t i = 0; i < names.size(); i++) { size_t col = i / nRow; colW[col] = std::max(colW[col], shellDisplayWidth(names[i])); }
      int total = 0; for (size_t k = 0; k < nCol; k++) total += colW[k] + (k ? 3 : 0);
      if (total <= screen || nRow >= names.size()) break;
