    }
    for (size_t r = 0; r < nRow; r++) {
      std::string s;
      for (size_t i = r, col = 0; i < names.size(); i += nRow, col++) {
        if (col) s += "   ";
        s += names[i];
        if (i + nRow < names.size()) s += std::string(colW[col] - shellDisplayWidth(names[i]), ' ');
      }
      fprintf(out, "%s\n", s.c_str());
    }
    return 0;
  }
  if (is("testcase", 4)) { return 0; }
  if (is("check", 3)) { return 0; }
  if (is("timeout", 4)) { if (n != 2) return usageErr(*this, "Usage: .timeout MS"); db.busyTimeout = atoi(args[1].c_str()); return 0; }
  if (is("timer", 4)) {
    if (n != 2) return usageErr(*this, "Usage: .timer on|off|once");
    std::string a = lowerStr(args[1]);
    if (a == "once") timer = 2; else { bool b; if (!booleanValue(a, b)) return usageErr(*this, "Usage: .timer on|off|once"); timer = b ? 1 : 0; }
    return 0;
  }
  if (is("trace", 3)) return 0;
  if (is("version", 3)) {
    fprintf(out, "SQLite 3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b\n");
