  if (is("vfslist", 4)) { fprintf(out, "unix\nunix-none\nunix-dotfile\nunix-excl\n"); return 0; }
  if (is("vfsname", 4)) { fprintf(out, "unix\n"); return 0; }
  if (is("width", 2)) {
