static void usage(bool showDetail) {
  fprintf(stderr, "Usage: %s [OPTIONS] [FILENAME [SQL...]]\n", g_argv0.c_str());
  if (showDetail) fputs(kUsageText, stderr);
  else fprintf(stderr, "Use the -help option for additional information\n");
  exit(showDetail ? 0 : 1);
}

static std::string cmdlineOptionValue(int argc, char** argv, int i) {
  if (i >= argc) { fprintf(stderr, "%s: Error: missing argument to %s\n", g_argv0.c_str(), argv[argc - 1]); exit(1); }
  return argv[i];
}

