# 1. Add planner structures & functions before execCore
planner = r'''
// ---------- Simple index-aware scan planning ----------

struct ScanTerm { Expr* other; std::string op; int col; };  // col: table column index, or -2 rowid
struct ScanPlan {
  IndexP idx;               // chosen index (null = rowid/table order)
  bool useRowid = false;    // rowid equality / range
  std::vector<ScanTerm> eq; // equality terms, one per leading index column
  ScanTerm* in = nullptr;   // IN term on the column after eq prefix (or first)
  Expr* inExpr = nullptr;
  std::vector<ScanTerm> range;  // range terms on the next column
  bool reverse = false;
  bool valid = false;
  int orderMatch = 0;
};

struct IndexEntry { std::vector<Value> key; int64_t rowid; const Row* row; };
struct IndexCache {
  std::map<Index*, std::vector<IndexEntry>> byIndex;
};

static bool exprRefersToCursorAtOrAfter(Expr* e, int level) {
  bool found = false;
  std::function<void(Expr*)> walk = [&](Expr* x) {
    if (!x || found) return;
    if (x->kind == Expr::Column && x->resolved && !x->aliasTarget && x->depth == 0 && x->srcIdx >= level) { found = true; return; }
    if (x->kind == Expr::Column && x->aliasTarget) { walk(x->aliasTarget.get()); return; }
    if (x->kind == Expr::Subquery || x->kind == Expr::Exists || (x->kind == Expr::In && x->sub)) {
      // correlated subquery referencing this level: conservatively treat as dependent if it mentions depth>0 columns
      std::function<void(Select*)> ws = [&](Select* sel) {
        for (auto& core : sel->cores) {
          std::function<void(Expr*)> w2 = [&](Expr* y) {
            if (!y || found) return;
            if (y->kind == Expr::Column && y->resolved && y->depth >= 1) { found = true; return; }
            for (auto& a : y->args) w2(a.get());
            if (y->elseExpr) w2(y->elseExpr.get());
            if (y->sub) ws(y->sub.get());
          };
          for (auto& c : core->cols) w2(c.e.get());
          w2(core->where.get());
          for (auto& g : core->groupBy) w2(g.get());
          w2(core->having.get());
          for (auto& f : core->from) if (f.sub) ws(f.sub.get());
        }
      };
      ws(x->sub.get());
      return;
    }
    for (auto& a : x->args) walk(a.get());
    if (x->elseExpr) walk(x->elseExpr.get());
  };
  walk(e);
  return found;
}

static void flattenAnd(Expr* e, std::vector<Expr*>& out) {
  if (!e) return;
  if (e->kind == Expr::And) { flattenAnd(e->args[0].get(), out); flattenAnd(e->args[1].get(), out); return; }
  if (e->kind == Expr::Unary && e->op == "()") { flattenAnd(e->args[0].get(), out); return; }
  out.push_back(e);
}

static Expr* stripParens(Expr* e) { while (e && e->kind == Expr::Unary && e->op == "()") e = e->args[0].get(); return e; }

// Collect candidate constraint terms for cursor `ci` at join level `level`.
static void collectTerms(Engine* eng, Scope& sc, const std::vector<Expr*>& conj, int ci, int level, std::vector<ScanTerm>& eqs, std::vector<ScanTerm>& ranges, std::vector<std::pair<int, Expr*>>& ins) {
  (void)eng; (void)sc;
  for (Expr* t : conj) {
    Expr* x = stripParens(t);
    if (x->kind == Expr::Binary || x->kind == Expr::Is) {
      std::string op = x->kind == Expr::Is ? "=" : x->op;
      if (!(op == "=" || op == "==" || op == "<" || op == "<=" || op == ">" || op == ">=")) continue;
      Expr* l = stripParens(x->args[0].get()); Expr* r = stripParens(x->args[1].get());
      auto isCol = [&](Expr* c) { return c->kind == Expr::Column && c->resolved && !c->aliasTarget && c->depth == 0 && c->srcIdx == ci; };
      Expr* col = nullptr; Expr* other = nullptr; std::string eop = op;
      if (isCol(l) && !exprRefersToCursorAtOrAfter(r, level)) { col = l; other = r; }
      else if (isCol(r) && !exprRefersToCursorAtOrAfter(l, level)) { col = r; other = l; if (op == "<") eop = ">"; else if (op == "<=") eop = ">="; else if (op == ">") eop = "<"; else if (op == ">=") eop = "<="; }
      if (!col) continue;
      // collation: explicit COLLATE on either side must match the index collation (checked later); skip if explicit collate present
      if (x->args[0]->kind == Expr::Collate || x->args[1]->kind == Expr::Collate) continue;
      ScanTerm st; st.other = other; st.op = (eop == "==") ? "=" : eop; st.col = col->isRowid ? -2 : col->colIdx;
      if (st.op == "=") eqs.push_back(st); else ranges.push_back(st);
    } else if (x->kind == Expr::In && !x->negate) {
      Expr* l = stripParens(x->args[0].get());
      if (l->kind == Expr::Column && l->resolved && !l->aliasTarget && l->depth == 0 && l->srcIdx == ci) {
        bool dep = false;
        for (size_t k = 1; k < x->args.size(); k++) if (exprRefersToCursorAtOrAfter(x->args[k].get(), level)) dep = true;
        if (x->sub && exprRefersToCursorAtOrAfter(x, level)) dep = true;
        if (!dep) ins.push_back({l->isRowid ? -2 : l->colIdx, x});
      }
    } else if (x->kind == Expr::Between && !x->negate) {
      Expr* l = stripParens(x->args[0].get());
      if (l->kind == Expr::Column && l->resolved && !l->aliasTarget && l->depth == 0 && l->srcIdx == ci && !exprRefersToCursorAtOrAfter(x->args[1].get(), level) && !exprRefersToCursorAtOrAfter(x->args[2].get(), level)) {
        ScanTerm a; a.other = x->args[1].get(); a.op = ">="; a.col = l->isRowid ? -2 : l->colIdx; ranges.push_back(a);
        ScanTerm b; b.other = x->args[2].get(); b.op = "<="; b.col = a.col; ranges.push_back(b);
      }
    }
  }
}

static ScanPlan planScan(Engine* eng, Scope& sc, Cursor& c, int ci, int level, const std::vector<Expr*>& conj, const std::vector<OrderBy>* orderBy, bool singleTable) {
  ScanPlan plan;
  if (!c.table) return plan;
  std::vector<ScanTerm> eqs, ranges; std::vector<std::pair<int, Expr*>> ins;
  collectTerms(eng, sc, conj, ci, level, eqs, ranges, ins);
  TableP t = c.table;
  // rowid equality
  if (!t->withoutRowid) {
    for (auto& e : eqs) if (e.col == -2 || (e.col == t->rowidCol && t->rowidCol >= 0)) { plan.useRowid = true; plan.eq = {e}; plan.valid = true; return plan; }
  }
  // candidate indexes (newest first)
  std::vector<IndexP> idxs = eng->db.indexesOf(t->name);
  std::reverse(idxs.begin(), idxs.end());
  int bestScore = 0; IndexP best; ScanPlan bestPlan;
  for (auto& ix : idxs) {
    if (ix->where) continue;
    bool hasExpr = false; for (auto& icol : ix->cols) if (icol.col == -1) hasExpr = true;
    if (hasExpr) continue;
    ScanPlan p; p.idx = ix;
    size_t k = 0;
    for (; k < ix->cols.size(); k++) {
      int col = ix->cols[k].col;
      bool found = false;
      for (auto& e : eqs) if (e.col == col || (col == -2 && e.col == t->rowidCol && t->rowidCol >= 0)) { p.eq.push_back(e); found = true; break; }
      if (!found) break;
    }
    int score = (int)p.eq.size() * 100;
    if (k < ix->cols.size()) {
      int col = ix->cols[k].col;
      for (auto& in : ins) if (in.first == col) { p.inExpr = in.second; score += 60; break; }
      if (!p.inExpr) for (auto& r : ranges) if (r.col == col) { p.range.push_back(r); }
      if (!p.range.empty()) score += 30 + (p.range.size() > 1 ? 10 : 0);
    }
    if (p.eq.size() == ix->cols.size() && ix->unique) score += 50;
    // ORDER BY match
    if (orderBy && singleTable && !orderBy->empty() && score == 0) {
      bool fwd = true, bwd = true;
      size_t m = 0;
      for (; m < orderBy->size() && m < ix->cols.size(); m++) {
        Expr* oe = stripParens((*orderBy)[m].e.get());
        std::string coll;
        if (oe->kind == Expr::Collate) { coll = oe->collate; oe = stripParens(oe->args[0].get()); }
        if (!(oe->kind == Expr::Column && oe->resolved && !oe->aliasTarget && oe->depth == 0 && oe->srcIdx == ci && (oe->isRowid ? -2 : oe->colIdx) == ix->cols[m].col)) break;
        std::string icoll = ix->cols[m].collate; if (icoll.empty()) icoll = "BINARY";
        if (!coll.empty() && !nameEq(coll, icoll)) break;
        if (coll.empty() && ix->cols[m].col >= 0) { std::string cc = t->cols[ix->cols[m].col].collate; if (cc.empty()) cc = "BINARY"; if (!nameEq(cc, icoll)) break; }
        bool desc = (*orderBy)[m].desc != ix->cols[m].desc;
        if ((*orderBy)[m].nulls != 0) break;
        if (desc) fwd = false; else bwd = false;
      }
      if (m == orderBy->size() && (fwd || bwd)) { score += 20; p.reverse = bwd && !fwd; p.orderMatch = (int)m; }
    }
    if (score > bestScore) { bestScore = score; best = ix; bestPlan = p; }
  }
  if (!best) {
