    if (!t->withoutRowid) {
      for (auto& r : ranges) if (r.col == -2 || (r.col == t->rowidCol && t->rowidCol >= 0)) { plan.useRowid = true; plan.range.push_back(r); plan.valid = true; }
      if (plan.valid) return plan;
      for (auto& in : ins) if (in.first == -2 || (in.first == t->rowidCol && t->rowidCol >= 0)) { plan.useRowid = true; plan.inExpr = in.second; plan.valid = true; return plan; }
      if (orderBy && singleTable && orderBy->size() >= 1) {
        Expr* oe = stripParens((*orderBy)[0].e.get());
        if (oe->kind == Expr::Column && oe->resolved && !oe->aliasTarget && oe->depth == 0 && oe->srcIdx == ci && oe->isRowid) { plan.useRowid = true; plan.reverse = (*orderBy)[0].desc; plan.valid = true; return plan; }
      }
    }
    return plan;
  }
  bestPlan.valid = true;
  return bestPlan;
}

static int collIdName(const std::string& n) { if (nameEq(n, "NOCASE")) return 1; if (nameEq(n, "RTRIM")) return 2; return 0; }

// Build (or fetch) sorted index entries for a table
static std::vector<IndexEntry>& indexEntries(Engine* eng, IndexCache& cache, TableP t, IndexP ix, Cursor& c) {
  auto it = cache.byIndex.find(ix.get());
  if (it != cache.byIndex.end()) return it->second;
  std::vector<IndexEntry>& ents = cache.byIndex[ix.get()];
  Scope isc; Cursor tmp = c; tmp.isNullRow = false; isc.cursors.push_back(&tmp);
  for (auto& kv : t->rows) {
    IndexEntry e; e.rowid = kv.first; e.row = &kv.second;
    tmp.row = &kv.second; tmp.rowid = kv.first;
    for (auto& icol : ix->cols) {
      if (icol.col >= 0) e.key.push_back(kv.second[icol.col]);
      else if (icol.col == -2) e.key.push_back(Value::Int(kv.first));
      else e.key.push_back(eng->eval(icol.expr, &isc));
