  std::vector<int> cids; std::vector<bool> desc;
  for (auto& icol : ix->cols) { std::string coll = icol.collate; if (coll.empty() && icol.col >= 0) coll = t->cols[icol.col].collate; cids.push_back(collIdName(coll)); desc.push_back(icol.desc); }
  std::stable_sort(ents.begin(), ents.end(), [&](const IndexEntry& a, const IndexEntry& b) {
    for (size_t k = 0; k < a.key.size(); k++) { int cmp = compareValues(a.key[k], b.key[k], cids[k]); if (desc[k]) cmp = -cmp; if (cmp) return cmp < 0; }
    return a.rowid < b.rowid;
  });
  return ents;
}
