CREATE TABLE emp(id INTEGER PRIMARY KEY, name TEXT, dept INT, sal REAL);
INSERT INTO emp VALUES(1,'ann',10,100),(2,'bob',20,200),(3,'cat',10,150),(4,'dan',NULL,50);
CREATE TABLE dept(id INT, dname TEXT);
INSERT INTO dept VALUES(10,'eng'),(20,'ops'),(30,'hr');
SELECT e.name, d.dname FROM emp e JOIN dept d ON e.dept=d.id;
SELECT e.name, d.dname FROM emp e LEFT JOIN dept d ON e.dept=d.id;
SELECT e.name, d.dname FROM dept d LEFT JOIN emp e ON e.dept=d.id ORDER BY d.id;
SELECT d.dname, e.name FROM emp e RIGHT JOIN dept d ON e.dept=d.id;
SELECT d.dname, count(e.id) FROM dept d LEFT JOIN emp e ON e.dept=d.id GROUP BY d.id;
SELECT name, sal, rank() OVER (ORDER BY sal DESC) rk, sum(sal) OVER (PARTITION BY dept) ds, row_number() OVER () rn FROM emp;
SELECT name, lag(name) OVER (ORDER BY id), lead(name, 1, 'none') OVER (ORDER BY id) FROM emp;
SELECT name, sum(sal) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) FROM emp;
WITH RECURSIVE c(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM c WHERE n<5) SELECT group_concat(n) FROM c;
WITH t(x) AS (SELECT 1 UNION ALL SELECT 2) SELECT * FROM t a, t b;
SELECT (SELECT count(*) FROM emp WHERE dept=d.id) AS cnt, dname FROM dept d;
SELECT name FROM emp WHERE EXISTS (SELECT 1 FROM dept WHERE id=emp.dept);
SELECT name FROM emp WHERE dept IN (SELECT id FROM dept WHERE dname<>'ops');
SELECT * FROM emp WHERE (dept, sal) = (10, 150);
SELECT CASE WHEN sal>120 THEN 'high' WHEN sal>60 THEN 'mid' ELSE 'low' END, count(*) FROM emp GROUP BY 1 ORDER BY 2 DESC, 1;
SELECT name, sal*1.1 AS raised FROM emp WHERE raised > 160 ORDER BY raised;
SELECT typeof(sal), sal FROM emp LIMIT 1;
UPDATE emp SET sal = sal + 10 WHERE dept = 10 RETURNING id, sal;
DELETE FROM emp WHERE id = 4 RETURNING name;
SELECT count(*) FROM emp;
CREATE VIEW v AS SELECT name, sal FROM emp WHERE sal > 100;
SELECT * FROM v ORDER BY sal;
SELECT v.name FROM v JOIN emp USING(name) WHERE emp.dept=10;
ALTER TABLE emp ADD COLUMN note TEXT DEFAULT 'n/a';
SELECT * FROM emp WHERE id=1;
ALTER TABLE emp RENAME COLUMN note TO memo;
ALTER TABLE emp RENAME TO employees;
.schema employees
SELECT memo FROM employees LIMIT 1;
BEGIN; DELETE FROM employees; SELECT count(*) FROM employees; ROLLBACK; SELECT count(*) FROM employees;
BEGIN; INSERT INTO dept VALUES(40,'x'); SAVEPOINT s1; INSERT INTO dept VALUES(50,'y'); ROLLBACK TO s1; COMMIT; SELECT * FROM dept;
CREATE TRIGGER trg AFTER INSERT ON dept BEGIN UPDATE dept SET dname = upper(new.dname) WHERE id = new.id; END;
INSERT INTO dept VALUES(60,'zed'); SELECT * FROM dept WHERE id=60;
SELECT * FROM employees WHERE name LIKE 'A%';
SELECT * FROM employees WHERE name GLOB 'b*';
SELECT 1 WHERE 'abc' LIKE 'a_c' AND 'abc' NOT LIKE 'x%';
SELECT quote(zeroblob(2)), hex(randomblob(2)) <> '', length(hex(randomblob(16)));
EOF"}

