# helper to set up CTEs persistently
s=s.replace('''std::vector<std::string> Engine::selectColumnNames(const SelectP& sel, Scope* parent) {
  // Bind the select (all cores) and return column names of first core
  Scope cteScope; cteScope.parent = parent;
  std::map<std::string, CteDef*> ctes;
  std::vector<std::shared_ptr<CteDef>> defs;
  if (!sel->ctes.empty()) {
    for (auto& c : sel->ctes) {
      auto d = std::make_shared<CteDef>(); d->def = c; d->defScope = &cteScope;
      defs.push_back(d); ctes[lowerStr(c.name)] = d.get();
    }
    cteScope.ctes = &ctes;
  }
  Scope* p = sel->ctes.empty() ? parent : &cteScope;''','''// Set up persistent CTE definitions for a select; returns scope to use for binding/execution
Scope* setupCtes(const std::vector<Cte>& ctes, std::vector<std::shared_ptr<CteDef>>& defs, std::shared_ptr<std::map<std::string, CteDef*>>& cmap, Scope& cteScope, Scope* parent, bool resetState) {
  cteScope.parent = parent;
  if (ctes.empty()) return parent;
  if (defs.empty()) {
    cmap = std::make_shared<std::map<std::string, CteDef*>>();
    for (auto& c : ctes) {
      auto d = std::make_shared<CteDef>(); d->def = c;
