    std::string nm = c.table ? c.name : (subNames[i].empty() ? c.name : subNames[i]);
    if (!c.table) { out.push_back({nextId++, parentId, "SCAN " + nm}); continue; }
    std::vector<Expr*> conj = whereConj;
    if (c.on) flattenAnd(c.on.get(), conj);
    for (size_t j = i + 1; j < n; j++) if (b.cursors[j]->on && (b.cursors[j]->joinType & (4 | 8 | 32)) == 0) flattenAnd(b.cursors[j]->on.get(), conj);
    ScanPlan pl = planScan(eng, sc, c, (int)i, (int)i, conj, orderBy, n == 1 && !b.isAggregate);
    std::string d;
    TableP t = c.table;
    auto colName = [&](int col) { if (col == -2) return std::string("rowid"); return t->cols[col].name; };
    if (pl.valid && pl.useRowid) {
      std::string cond;
      if (!pl.eq.empty()) cond = "rowid=?";
      else if (pl.inExpr) cond = "rowid=?";
      else if (!pl.range.empty()) { bool lo = false, hi = false; for (auto& r : pl.range) { if (r.op == ">" || r.op == ">=") lo = true; else hi = true; } cond = lo && hi ? "rowid>? AND rowid<?" : (lo ? "rowid>?" : "rowid<?"); }
      if (cond.empty()) d = "SCAN " + nm; else d = "SEARCH " + nm + " USING INTEGER PRIMARY KEY (" + cond + ")";
    } else if (pl.valid && pl.idx) {
      std::string cond;
      for (auto& e : pl.eq) { if (!cond.empty()) cond += " AND "; cond += colName(e.col) + "=?"; }
      if (pl.inExpr) { if (!cond.empty()) cond += " AND "; cond += colName(pl.idx->cols[pl.eq.size()].col) + "=?"; }
      else if (!pl.range.empty()) {
        bool lo = false, hi = false; for (auto& r : pl.range) { if (r.op == ">" || r.op == ">=") lo = true; else hi = true; }
        std::string cn = colName(pl.idx->cols[pl.eq.size()].col);
        if (!cond.empty()) cond += " AND ";
        cond += lo && hi ? cn + ">? AND " + cn + "<?" : (lo ? cn + ">?" : cn + "<?");
      }
      // covering?
      bool covering = true;
      std::set<int> idxCols; for (auto& ic : pl.idx->cols) idxCols.insert(ic.col);
      std::function<void(Expr*)> walk = [&](Expr* x) { if (!x || !covering) return; if (x->kind == Expr::Column && x->resolved && x->depth == 0 && x->srcIdx == (int)i && !x->isRowid && !idxCols.count(x->colIdx)) covering = false; for (auto& a : x->args) walk(a.get()); if (x->elseExpr) walk(x->elseExpr.get()); };
      for (auto& rc : b.cols) walk(rc.e.get());
      walk(core->where.get()); for (auto& g : core->groupBy) walk(g.get()); walk(core->having.get());
      if (orderBy) for (auto& o : *orderBy) walk(o.e.get());
      std::string idxName = pl.idx->name;
      std::string using_ = (pl.idx->isPk && t->withoutRowid) ? (covering ? "COVERING PRIMARY KEY" : "PRIMARY KEY") : ((covering ? "COVERING INDEX " : "INDEX ") + idxName);
      if (pl.idx->isPk && t->withoutRowid) using_ = covering ? "PRIMARY KEY" : "PRIMARY KEY";
      if (cond.empty()) d = "SCAN " + nm + " USING " + using_;
      else d = "SEARCH " + nm + " USING " + using_ + " (" + cond + ")";
    } else d = "SCAN " + nm;
    out.push_back({nextId++, parentId, d});
  }
  if (!core->groupBy.empty()) out.push_back({nextId++, parentId, "USE TEMP B-TREE FOR GROUP BY"});
  if (core->distinct) out.push_back({nextId++, parentId, "USE TEMP B-TREE FOR DISTINCT"});
  (void)hasLimitOrder;
}

static void explainSelectInto(Engine* eng, const SelectP& sel, Scope* parent, std::vector<PlanLine>& out, int parentId, int& nextId, int& subqN) {
  Scope cteScope;
  Scope* p = setupCtes(sel->ctes, sel->cteDefs, sel->cteMap, cteScope, parent, false);
  eng->selectColumnNames(sel, parent);
  for (auto& d : sel->cteDefs) d->defScope = &cteScope;
  if (sel->cores.size() == 1) {
    explainCore(eng, sel->cores[0].get(), p, out, parentId, nextId, subqN, sel->orderBy.empty() ? nullptr : &sel->orderBy, false);
    if (!sel->orderBy.empty()) {
      // check whether the single table scan satisfies the ORDER BY via index
      bool satisfied = false;
      auto& core = sel->cores[0];
      if (core->from.size() == 1 && core->bind && core->bind->cursors[0]->table) {
        Scope sc; bindCore(eng, core.get(), p, sc, false);
        std::vector<Expr*> conj; flattenAnd(core->where.get(), conj);
        ScanPlan pl = planScan(eng, sc, *core->bind->cursors[0], 0, 0, conj, &sel->orderBy, !core->bind->isAggregate);
        if (pl.valid && pl.orderMatch == (int)sel->orderBy.size() && pl.eq.empty() && pl.range.empty() && !pl.inExpr) satisfied = true;
        if (pl.valid && pl.useRowid && pl.eq.empty() && pl.range.empty() && !pl.inExpr) satisfied = true;
      }
      if (!satisfied) out.push_back({nextId++, parentId, "USE TEMP B-TREE FOR ORDER BY"});
    }
    return;
  }
  int cid = nextId++;
  out.push_back({cid, parentId, "COMPOUND QUERY"});
  for (size_t i = 0; i < sel->cores.size(); i++) {
    std::string label;
    if (i == 0) label = "LEFT-MOST SUBQUERY";
    else { int op = sel->ops[i - 1]; label = std::string(op == 1 ? "UNION" : op == 2 ? "UNION ALL" : op == 3 ? "INTERSECT" : "EXCEPT") + " USING TEMP B-TREE"; if (op == 2) label = "UNION ALL"; }
    int id = nextId++;
    out.push_back({id, cid, label});
    explainCore(eng, sel->cores[i].get(), p, out, id, nextId, subqN, nullptr, false);
  }
  if (!sel->orderBy.empty()) out.push_back({nextId++, parentId, "USE TEMP B-TREE FOR ORDER BY"});
}

std::vector<std::tuple<int, int, std::string>> explainQueryPlan(Engine* eng, const StmtP& st) {
  std::vector<PlanLine> out; int nextId = 2; int subqN = 0;
  std::vector<std::tuple<int, int, std::string>> res;
  StmtP in = st;
  if (in->kind == Stmt::Select) explainSelectInto(eng, in->select, nullptr, out, 0, nextId, subqN);
  else if (in->kind == Stmt::Insert || in->kind == Stmt::Update || in->kind == Stmt::Delete) {
    TableP t = eng->db.findTable(in->schema, in->table);
    if (in->kind == Stmt::Insert && in->select) explainSelectInto(eng, in->select, nullptr, out, 0, nextId, subqN);
    else if (t) out.push_back({nextId++, 0, "SCAN " + t->name});
  }
  for (auto& l : out) res.push_back({l.id, l.parent, l.detail});
  return res;
}
