import sqlite3, subprocess
setup=open('/tmp/dt/setup.sql').read()
qs=[q for q in open('/tmp/dt/queries.txt').read().split('\n') if q.strip()]
def fmt(v):
    if v is None: return ''
    if isinstance(v,float):
        # use our binary's formatting via python? approximate with repr; compare loosely
        r=repr(v)
        if 'e' in r or 'inf' in r: return r
        if r.endswith('.0'): return r
        return r
    if isinstance(v,bytes): return v.decode('latin1')
    return str(v)
con=sqlite3.connect(':memory:')
con.executescript(setup)
fails=0
for q in qs:
    try:
        rows=con.execute(q).fetchall()
        exp='\n'.join('|'.join(fmt(v) for v in r) for r in rows)
    except Exception as e:
        exp='ERR '+str(e)
    p=subprocess.run(['/workspace/executable',':memory:','.read /tmp/dt/setup.sql',q],capture_output=True,text=True)
    got=p.stdout.rstrip('\n')
    if p.returncode!=0: got='ERR '+p.stderr.strip()
    if got!=exp:
        # tolerate float formatting differences by comparing numerically token-wise
        def norm(s):
            out=[]
            for line in s.split('\n'):
                toks=[]
                for t in line.split('|'):
                    try: toks.append('%.10g'%float(t))
                    except: toks.append(t)
                out.append('|'.join(toks))
            return '\n'.join(out)
        if norm(got)==norm(exp): continue
        fails+=1
        print('QUERY:',q); print(' EXP:',exp.replace('\n',' / ')); print(' GOT:',got.replace('\n',' / '))
print('fails',fails,'of',len(qs))
EOF"}

