import subprocess, random
random.seed(11)
# structured random SELECTs over t1/t2 to find crashes & compare with python sqlite3
import sqlite3
setup=open('/tmp/dt/setup.sql').read()
cols1=['a','b','c','d']; cols2=['id','t1a','name','qty']
funcs=['abs','length','upper','lower','typeof','quote','hex','round']
aggs=['count','sum','avg','min','max','total','group_concat']
def rexpr(depth=0, tbl='t1'):
    cols=cols1 if tbl=='t1' else cols2
    r=random.random()
    if depth>2 or r<0.3: return random.choice(cols+['1','2','0.5',"'x'","NULL","'alpha'"])
    if r<0.5: return '('+rexpr(depth+1,tbl)+' '+random.choice(['+','-','*','/','||','=','<','>','<=','>=','!=','AND','OR','IS','IS NOT'])+' '+rexpr(depth+1,tbl)+')'
    if r<0.6: return random.choice(funcs)+'('+rexpr(depth+1,tbl)+')'
    if r<0.7: return 'CASE WHEN '+rexpr(depth+1,tbl)+' THEN '+rexpr(depth+1,tbl)+' ELSE '+rexpr(depth+1,tbl)+' END'
    if r<0.8: return rexpr(depth+1,tbl)+' IN ('+rexpr(depth+1,tbl)+', '+rexpr(depth+1,tbl)+')'
    if r<0.9: return 'coalesce('+rexpr(depth+1,tbl)+', '+rexpr(depth+1,tbl)+')'
    return 'NOT '+rexpr(depth+1,tbl)
def rquery():
    tbl=random.choice(['t1','t2'])
    cols=cols1 if tbl=='t1' else cols2
    if random.random()<0.3:
        g=random.choice(cols)
        sel=g+', '+random.choice(aggs)+'('+random.choice(cols)+')'
        q='SELECT '+sel+' FROM '+tbl+' GROUP BY '+g
        if random.random()<0.5: q+=' HAVING '+rexpr(1,tbl)
        q+=' ORDER BY 1'
    else:
        sel=', '.join(rexpr(0,tbl) for _ in range(random.randint(1,3)))
        q='SELECT '+sel+' FROM '+tbl
        if random.random()<0.7: q+=' WHERE '+rexpr(0,tbl)
        q+=' ORDER BY '+random.choice(cols)+random.choice(['',' DESC'])+', '+random.choice(cols)
        if random.random()<0.3: q+=' LIMIT '+str(random.randint(0,4))
    return q+';'
con=sqlite3.connect(':memory:'); con.executescript(setup)
def fmt(v):
    if v is None: return ''
    if isinstance(v,bytes): return v.decode('latin1')
    if isinstance(v,float): return repr(v)
    return str(v)
def norm(s):
    out=[]
    for line in s.split('\n'):
        toks=[]
        for t in line.split('|'):
            try: toks.append('%.9g'%float(t))
            except: toks.append(t.replace('^@','\x00'))
        out.append('|'.join(toks))
    return '\n'.join(out)
fails=0; crashes=0
for i in range(300):
    q=rquery()
    try:
        rows=con.execute(q).fetchall(); exp='\n'.join('|'.join(fmt(v) for v in r) for r in rows)
    except Exception as e: exp='ERR'
    try:
        p=subprocess.run(['/workspace/executable',':memory:'],input=setup+q+'\n',capture_output=True,text=True,timeout=5)
    except subprocess.TimeoutExpired:
        crashes+=1; print('TIMEOUT',q); continue
    if p.returncode<0 or p.returncode>1: crashes+=1; print('CRASH',q); continue
    got=p.stdout.rstrip('\n')
    if p.returncode!=0 or p.stderr: got='ERR'
    if exp=='ERR' and got=='ERR': continue
    if norm(got)!=norm(exp):
        fails+=1
        if fails<=12: print('Q:',q); print(' EXP:',exp.replace('\n',' / ')[:300]); print(' GOT:',got.replace('\n',' / ')[:300]); 
print('fails',fails,'crashes',crashes)
EOF"}

