// ---------- Foreign key enforcement ----------

static bool fkParentCols(Engine* eng, const ForeignKey& fk, TableP parent, std::vector<int>& pcols) {
  pcols.clear();
  if (fk.parentCols.empty()) {
    if (parent->pkCols.empty()) { if (parent->rowidCol >= 0) pcols.push_back(parent->rowidCol); else return false; }
    else pcols = parent->pkCols;
  } else {
    for (auto& n : fk.parentCols) { int ci = parent->colIndex(n); if (ci < 0) return false; pcols.push_back(ci); }
