    for (int ci : fk.childCols) { if (ci < 0 || ci >= (int)row.size() || row[ci].isNull()) { anyNull = true; break; } key.push_back(row[ci]); }
    if (anyNull) continue;
    TableP parent = eng->db.findTable("", fk.parentTable);
    if (!parent) { bad++; continue; }
    std::vector<int> pcols;
    if (!fkParentCols(eng, fk, parent, pcols)) { bad++; continue; }
    bool found = false;
    if (parent == child) { /* self reference: also consider the row itself */ }
    for (auto& kv : parent->rows) {
      std::vector<Value> pk; for (int pc : pcols) pk.push_back(kv.second[pc]);
      if (keysEqual(key, pk, parent, pcols)) { found = true; break; }
    }
    if (!found) bad++;
  }
  return bad;
}

