  for (auto& kv : eng->db.main.tables) tables.push_back(kv.second);
  for (auto& kv : eng->db.temp.tables) tables.push_back(kv.second);
  for (auto& child : tables) {
    if (child->isView) continue;
    for (auto& fk : child->fks) {
