        bool same = true;
        for (size_t k = 0; k < pcols.size(); k++) if (compareValues(oldRow[pcols[k]], (*newRow)[pcols[k]]) != 0 || oldRow[pcols[k]].t != (*newRow)[pcols[k]].t) same = false;
        if (same) continue;
      }
      int action = isDelete ? fk.onDelete : fk.onUpdate;
